CREATE VIEW [dbo].[DownloadUnitsNotYetDoneSelfCertification] as
select CreatedDate [DateofSelfCertificationStarted]
	  ,EstablishmentName as [UnitName] 
	  ,[RegistrationNumber] [HotelCloudRegistrationNumber]
	  ,[Acommodationtype]
      ,[TotalRooms]
	  ,RestaurantType
	  ,Category
	  ,SelfCertificateNo
	  ,IsCertificateGenerated as [NoOfSelfCertification]
	  ,ResetDate [ResetOrRetakeDate]
	  ,[EstablishmentAddress]
	  ,[EstablishmentCity]
	  ,[DistrictName]
      ,[StateName]
      ,[EstablishmentPinCode]
	  ,[EstablishmentPhoneNo]
      ,[EstablishmentFaxNo]
      ,[RespondentName]
      ,[MobileNo]
      ,[EmailId] from SelfAssessments where IsCertificateGenerated =0 

