/****** Object:  StoredProcedure [dbo].[SP_API_FINANCE_GET_INVOICE_DETAILS]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
--[SP_API_FINANCE_GET_INVOICE_DETAILS] '<redacted>', '<redacted>'
CREATE PROCEDURE [dbo].[SP_API_FINANCE_GET_INVOICE_DETAILS] --'<redacted>', '<redacted>'
(
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL,
	@LatestMileStone varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;
	
	--DECLARE @Etag varchar(50) = NULL
	--SELECT @Etag = JSON_VALUE(SuccessResponse, '<redacted>') FROM ApiFinanceUnitDetailsResponse where ZedId=@ZedId and ApiType='<redacted>' and StatusCode='<redacted>'

	IF @LatestMileStone IS NULL OR @LatestMileStone=''
	BEGIN
		select top 1 @LatestMileStone=MileStoneNum from msmepaymentinfo where ZedId=@ZedId and Certification=@Certification order by Id Desc
	END
	print @LatestMileStone 
	IF NOT EXISTS (SELECT * FROM ZEDCS_V2_LIVE.dbo.ApiFinanceUnitDetailsResponse where ZedId=@ZedId AND Certification=@Certification and ApiType='InvoiceData' and StatusCode='Created' AND ModuleName='CONSULTANCY' and MileStoneNo=@LatestMileStone)

	AND EXISTS (SELECT * FROM MsmeBasicInformation WHERE ZedId=@ZedId and UdyogAadharNo not IN ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
	)
	BEGIN
		select top 1
		--convert(date,P.CreatedDate) AS Posting_Date,
		format(P.CreatedDate, 'yyyy-MM-dd') AS Posting_Date,
		NULL AS Error_Text,
		'ZED' AS Board,
		'NDIE' AS Portal,
		M.ZedId AS Login_Name,
		format(P.CreatedDate, 'yyyy-MM-dd') AS Voucher_Date,
		'NDIE' AS Location_Code,
		--CONCAT('<redacted>',P.Certification,'<redacted>',M.ZedId,'<redacted>') AS Line_Comments,
		--CASE WHEN P.Certification='<redacted>' then concat('<redacted>', P.MileStoneNum) 
		--WHEN P.Certification='<redacted>' then concat('<redacted>', P.MileStoneNum)
		--WHEN P.Certification='<redacted>' then concat('<redacted>', P.MileStoneNum) END AS Line_Comments,
		 CONCAT('ZED "',P.Certification,' Handholding Support Milestone ',P.MileStoneNum, '" (',M.ZedId,')')  AS Line_Comments,
		NULL [NABL4],
		1 AS Quantity,
		NULL AS Ledger_Name,
		0 AS Ledger_Amount,
		'ASSESSMENT FEE' AS TA_DA_LedgerName,
		NULL AS Assessor_Name,
		NULL AS Assessor_ID,
		NULL AS Assessor_Type,
		NULL AS Discipline_Name,
		CASE WHEN P.Certification='Bronze' then 'ZMS - HAND HOLDING THROUGH CONSULTANCY' 
		WHEN P.Certification='Silver' then 'ZMS - HAND HOLDING THROUGH CONSULTANCY'
		WHEN P.Certification='Gold' then 'ZMS - HAND HOLDING THROUGH CONSULTANCY' END  AS Sub_Discipline_Name,
		NULL AS Other_Discipline,
		NULL AS Assessment_Period_From,
		NULL AS Assessment_Period_To,
		NULL AS Due_Period_Start_From,
		NULL AS Due_Period_Period_To,
		NULL AS TADA_Amount,
		P.SubsidyAmount AS Other_Amount,
		NULL AS Overhead_Charges,
		NULL AS Invoice_No,
		P.TadaInvoiceNo AS TADA_Invoice_No,
		NULL AS Assessment_Type,
		NULL AS HONORARIUM_Yes_No,
		convert(varchar,P.Id) Entry_No,
		'' Etag

		from Msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
		inner join msmepaymentinfo P on (M.ZedId=P.ZedId) 
		inner join PaymentGateWayTransactions T on (P.ZedId=T.ZedId and P.Certification=T.Certification AND p.MileStoneNum=t.MileStoneNumber and T.PaymentStatus='SUCCESS') 
		where M.ZedId=@ZedId and P.Certification=@Certification and P.MileStoneNum=@LatestMileStone order by P.Id Desc
	END

	ELSE
	BEGIN
		SELECT 
		NULL AS Posting_Date,
		NULL AS Error_Text,
		NULL AS Board,
		NULL AS Portal,
		NULL AS Login_Name,
		NULL AS Voucher_Date,
		NULL AS Location_Code,
		NULL AS Line_Comments,
		NULL [NABL4],
		NULL AS Quantity,
		NULL AS Ledger_Name,
		NULL AS Ledger_Amount,
		NULL AS TA_DA_LedgerName,
		NULL AS Assessor_Name,
		NULL AS Assessor_ID,
		NULL AS Assessor_Type,
		NULL AS Discipline_Name,
		NULL AS Sub_Discipline_Name,
		NULL AS Other_Discipline,
		NULL AS Assessment_Period_From,
		NULL AS Assessment_Period_To,
		NULL AS Due_Period_Start_From,
		NULL AS Due_Period_Period_To,
		NULL AS TA_DA_Amount,
		NULL AS Other_Amount,
		NULL AS Overhead_Charges,
		NULL AS Invoice_No,
		NULL AS TADA_Invoice_No,
		NULL AS Assessment_Type,
		NULL AS HONORARIUM_Yes_No,
		NULL AS Entry_No,
		NULL AS Etag
		WHERE 
			1=2
	END
END

GO
