)
AS
BEGIN
	
	SET NOCOUNT ON;

    SELECT *, CASE WHEN SelfCertificateNo IS NOT NULL THEN  'SELF CERTIFIED ZEDCS_V2' ELSE NULL END AS SelfCertificationStatus, 
