-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_API_GET_UNIT_DETAILS_BY_WEEK] --'<redacted>'
(
	@SelfCertificationDate varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

    SELECT Category, CONVERT(Date,SelfCertificationDate) SelfCertificationDate,
		RegistrationNumber, 
		CASE WHEN SelfCertificateNo IS NOT NULL THEN  'SELF CERTIFIED ZEDCS_V2' ELSE NULL END AS SelfCertificationStatus, 
		CASE WHEN SaStatus=2 THEN 'SITE ASSESSED ZEDCS_V2' ELSE NULL END AS SiteAssessmentStatus 
	FROM SelfAssessments 
	WHERE CONVERT(Date,SelfCertificationDate + 7) >  @SelfCertificationDate 
	  and CONVERT(Date,SelfCertificationDate) <=  @SelfCertificationDate
	  order by SelfCertificationDate
END


