-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<enter client name in parameters and execute to get new API id >
-- =============================================
CREATE PROCEDURE [dbo].[SP_API_KEY_MAKER_delete] --'<redacted>'
(
	@ClientName varchar(50) = NULL
)
AS
BEGIN
	
	DECLARE @ApiKey varchar(100) = NULL

	SET NOCOUNT ON;

	SET @ApiKey=left(concat((REPLACE(NEWID(),'-','')),(REPLACE(NEWID(),'-','')),(REPLACE(NEWID(),'-',''))),75)

	IF(select count(*) from ApiClientTokens where token=@ApiKey)=0
	BEGIN
		insert into ApiClientTokens (Client,Token,CreatedDate,BaseUrl)
		values (@ClientName,@ApiKey,getdate(),concat('https://loginzed.msme.gov.in/msme/GetDetailsByUdyam?token=',@ApiKey,'&udyamNumber=UDYAM-MH-23-0006117&certificationNumber=02052022_002612'))
	END
	ELSE
	SELECT 'ID ALREADY EXISTS'
END

GO
/****** Object:  StoredProcedure [dbo].[SP_API_MSME_CONSULTANCY_RAMP_REPORT]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_API_MSME_CONSULTANCY_RAMP_REPORT]
AS
BEGIN

  SET NOCOUNT ON;

	TRUNCATE TABLE dbo.ConsultancyRampReport;

	INSERT INTO dbo.ConsultancyRampReport
(
ZedId,UnitName,StateName,DistrictName,EnterpriseType,UdyogAadharNo,SectorName,Gender,SocialCategoryName,HandholdingOptedDate,
HandholdingLevelCertification,Milestone1Process,DateofM1Completion,Milestone2Process,DateofM2Completion,Milestone3Process,FinalDateofCompletion)

    SELECT 
        m.zedid,
        m.pUnitName AS [UnitName],
        m.pStateName AS [StateName], 
        m.pDistrictName AS [DistrictName],
        m.EnterpriseType AS [EnterpriseType],
        b.UdyogAadharNo AS [UdyogAadharNo],
        m.TwoDigitActivity AS [Sectors Name],
        b.Gender AS [Gender],
        b.SocialCategoryName AS [SocialCategoryName],
        X.HandholdingOptedDate,
        X.[Handholding Level Certification],
        X.[Milestone 1 process (Applied/Completed)],
        X.[Date of M1 Completion],
        X.[Milestone 2 process (Applied/Completed)],
        X.[Date of M2 Completion],
        X.[Milestone 3 process (Applied/Completed)],
        X.[Final Date of Completion]
    FROM 
    (
        SELECT 
            zedid,
            MAX(CASE
                    WHEN certification IN ('Silver', 'Gold') AND nccount = 1 
                    THEN CONVERT(VARCHAR(10), createddate, 23)  -- yyyy-mm-dd
                END) AS HandholdingOptedDate,
            MAX(CASE WHEN nccount = 1 THEN certification END) AS [Handholding Level Certification],
            MAX(CASE
                    WHEN nccount = 1 THEN
                        CASE
                            WHEN certificationstatus = 100 AND sacertificateno IS NOT NULL THEN 'Completed'
                            WHEN certificationstatus BETWEEN 6 AND 99 THEN 'Applied'
                        END
                END) AS [Milestone 1 process (Applied/Completed)],
            MAX(CASE
                    WHEN nccount = 1 AND certificationstatus = 100 AND sacertificateno IS NOT NULL 
                    THEN CONVERT(VARCHAR(10), certificationstatusdate, 23)
                END) AS [Date of M1 Completion],
            MAX(CASE
                    WHEN nccount = 2 THEN
                        CASE
                            WHEN certificationstatus = 100 AND sacertificateno IS NOT NULL THEN 'Completed'
                            WHEN certificationstatus BETWEEN 6 AND 99 THEN 'Applied'
                        END
                END) AS [Milestone 2 process (Applied/Completed)],
            MAX(CASE
                    WHEN nccount = 2 AND certificationstatus = 100 AND sacertificateno IS NOT NULL 
                    THEN CONVERT(VARCHAR(10), certificationstatusdate, 23)
                END) AS [Date of M2 Completion],
            MAX(CASE
                    WHEN nccount = 3 THEN
                        CASE
                            WHEN certificationstatus = 100 AND sacertificateno IS NOT NULL THEN 'Completed'
                            WHEN certificationstatus BETWEEN 6 AND 99 THEN 'Applied'
                        END
                END) AS [Milestone 3 process (Applied/Completed)],
            MAX(CASE
                    WHEN nccount = 3 AND certificationstatus = 100 AND sacertificateno IS NOT NULL 
                    THEN CONVERT(VARCHAR(10), certificationstatusdate, 23)
                END) AS [Final Date of Completion]
        FROM msmecertifications
        GROUP BY zedid,Certification
    ) AS X
    INNER JOIN msme m ON m.zedid = X.zedid
    INNER JOIN MsmeBasicInformation b ON m.zedid = b.zedid
	WHERE B.UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915')
	--and m.ZedId = '<redacted>'
    ORDER BY m.ZedId ;
END
GO
