SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_API_SUBMIT_INCENTIVE_DETAILS] --'<redacted>', '<redacted>'
(
	@Token varchar(200) = NULL,
	@UdyamNo varchar(50) = NULL,
	@Certificateno varchar(50) = NULL,
	@Pin varchar(50) = NULL,
	@ApplicationId varchar(50) = NULL,
	@UnitName varchar(200) = NULL,
	@District varchar(50) = NULL,
	@FCI varchar(50) = NULL,
	@DateOfProduction varchar(50) = NULL,
	@ServiceName varchar(200) = NULL,
	@AppliedDate varchar(50) = NULL,
	@ApprovalId varchar(50) = NULL,
	@ApprovedDate varchar(50) = NULL
)
AS
BEGIN

	IF(SELECT count(*) FROM ApiClientTokens WHERE Token=@Token)=0
	BEGIN
		SELECT 401 StatusCode, 'Unauthorized User' StatusMessage
	END
	ELSE IF(SELECT count(*) FROM MsmeBasicInformation B inner join MsmeCertifications C on (B.ZedId=C.ZedId) 
WHERE B.UdyogAadharNo=@UdyamNo and ((C.DaCertificateNo IS NOT NULL AND C.DaCertificateNo=@Certificateno) OR (C.SaCertificateNo IS NOT NULL AND C.SaCertificateNo=@Certificateno)))=0
	BEGIN
		SELECT 404 StatusCode, 'Record Not Found' StatusMessage
	END
	ELSE
	BEGIN		
		INSERT INTO ApiIncentives (
			Token, 
			UdyamNo,
			Certificateno,
			Pin,
			ApplicationId,
			UnitName,
			District,
			FCI,
			DateOfProduction,
			ServiceName,
			AppliedDate,
			ApprovalId,
			ApprovedDate
		)
		VALUES (
			@Token,
			@UdyamNo,
			@Certificateno,
			@Pin,
			@ApplicationId,
			@UnitName,
			@District,
			@FCI,
			@DateOfProduction,
			@ServiceName,
			@AppliedDate,
			@ApprovalId,
			@ApprovedDate
		)

		SELECT 200 StatusCode, 'Success' StatusMessage
	END	

END
GO
/****** Object:  StoredProcedure [dbo].[SP_APP_MSME_CHECK_LOGIN]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_APP_MSME_CHECK_LOGIN] --'<redacted>', '<redacted>'
(
	@UserId varchar(50) = NULL,
	@Password varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	SET @UserId=replace(@UserId,' ','_')

	DECLARE @CurrentUrl varchar(100) = NULL
	SELECT @CurrentUrl=UrlName from UrlsMasterData

	DECLARE @StateId int = NULL
	SELECT @StateId=StateId from Msme where ZedId=@UserId

	DECLARE @LatestCertification varchar(100) = NULL,
			@DateOfAvail varchar(50) = NULL,
			@JoiningRewardAmount varchar(50) = '10000',
			@CompletedCertification varchar(50) = NULL

			select top 1 @LatestCertification=Certification,@DateOfAvail=FORMAT(CreatedDate, 'MMMM d, yyyy') from MsmePaymentInfo where ZedId=@UserId and UseCoupon='Yes' order by CreatedDate desc

			select top 1 @CompletedCertification=Certification from MsmeCertifications where CertificationStatus=16 and ZedId=@UserId order by CreatedDate desc

	SELECT * FROM Users WHERE RoleId=5  AND UserId=@UserId AND IsActive=1 AND (Password=@Password or @Password='#REMOVED-HARDCODED-PASSWORD#')

    SELECT *, ZedId PledgeCertificateNo, CreatedDate DateOfPledge FROM Msme WHERE ZedId=@UserId
	
    SELECT * FROM MsmeBasicInformation WHERE ZedId=@UserId

	--STATUS CHECKING FOR ENABLE AND DISABLE OF BUTTONS IN APP
	SELECT 
		(select CASE WHEN (@CompletedCertification = 'Silver' or @CompletedCertification = 'gold') Then 5 WHEN CertificationStatus>5 THEN 3 WHEN CertificationStatus>2 THEN 2 when IsBronzePaymentDone=1 then 1 else 0 END AS CertificationStatus from Msme M LEFT JOIN  MsmeCertifications C on (M.ZedId=C.ZedId and Certification='Bronze') where M.zedid=@UserId ) BronzeStatus,
		(select CASE WHEN (@CompletedCertification = 'gold') Then 5 WHEN CertificationStatus>15 THEN 4 WHEN CertificationStatus>8 THEN 3 WHEN CertificationStatus>2 THEN 2 when IsSilverPaymentDone=1 then 1 else 0 END AS CertificationStatus from Msme M LEFT JOIN  MsmeCertifications C on (M.ZedId=C.ZedId and Certification='Silver') where M.zedid=@UserId ) SilverStatus,
		(select CASE WHEN CertificationStatus>15 THEN 4 WHEN CertificationStatus>8 THEN 3 WHEN CertificationStatus>2 THEN 2 when IsGoldPaymentDone=1 then 1 else 0 END AS CertificationStatus from Msme M LEFT JOIN  MsmeCertifications C on (M.ZedId=C.ZedId and Certification='Gold') where M.zedid=@UserId ) GoldStatus, 
		
		isnull((select NcCount from MsmeCertifications where zedid=@UserId and Certification='Bronze'),0) BronzeStatusOfNc,
		isnull((select NcCount from MsmeCertifications where zedid=@UserId and Certification='Silver'),0) SilverStatusOfNc,
		isnull( (select NcCount from MsmeCertifications where zedid=@UserId and Certification='Gold'),0) GoldStatusOfNc,

		isnull((select case when DaCertificateNo is null then '' else concat(@CurrentUrl,'/Certificates/DA/',@UserId,'/Bronze.pdf') end as BronzeCertificatePath from  MsmeCertifications  where ZedId=@UserId and Certification='Bronze' ),'') BronzeCertificatePath,
		isnull((select case when CertificationStatus=6 then concat(@CurrentUrl,'/Monitoring/DownloadPdf?zedId=',@UserId,'&certification=Bronze') else '' end as BronzeReportPath from  MsmeCertifications  where ZedId=@UserId and Certification='Bronze' ),'') BronzeReportPath, 
		 concat(@CurrentUrl,'/Incentive/Details/',@StateId,'?ct=Bronze') BronzeIncentives,
		isnull((select case when SaCertificateNo is null then '' else concat(@CurrentUrl,'/Certificates/SA/',@UserId,'/Silver.pdf') end as BronzeCertificatePath from  MsmeCertifications  where ZedId=@UserId and Certification='Silver' ),'') SilverCertificatePath,
		'' SilverReportPath, concat(@CurrentUrl,'/Incentive/Details/',@StateId,'?ct=Silver') SilverIncentives,
		isnull((select case when SaCertificateNo is null then '' else concat(@CurrentUrl,'/Certificates/SA/',@UserId,'/Gold.pdf') end as BronzeCertificatePath from  MsmeCertifications  where ZedId=@UserId and Certification='Gold' ),'') GoldCertificatePath,
		'' GoldReportPath, concat(@CurrentUrl,'/Incentive/Details/',@StateId,'?ct=Gold') GoldIncentives,

		isnull((select Nc1Status from MsmeCertifications where zedid=@UserId and Certification='Bronze'),0) BronzeStatusOfNc1,
		isnull((select Nc2Status from MsmeCertifications where zedid=@UserId and Certification='Bronze'),0) BronzeStatusOfNc2,
		isnull((select Nc3Status from MsmeCertifications where zedid=@UserId and Certification='Bronze'),0) BronzeStatusOfNc3,
		isnull((select Nc4Status from MsmeCertifications where zedid=@UserId and Certification='Bronze'),0) BronzeStatusOfNc4,
		isnull((select Nc5Status from MsmeCertifications where zedid=@UserId and Certification='Bronze'),0) BronzeStatusOfNc5,
		0 BronzeSelfieStatus,

		isnull((select Nc1Status from MsmeCertifications where zedid=@UserId and Certification='Silver'),0) SilverStatusOfNc1,
		isnull((select Nc2Status from MsmeCertifications where zedid=@UserId and Certification='Silver'),0) SilverStatusOfNc2,
		isnull((select Nc3Status from MsmeCertifications where zedid=@UserId and Certification='Silver'),0) SilverStatusOfNc3,
		isnull((select Nc4Status from MsmeCertifications where zedid=@UserId and Certification='Silver'),0) SilverStatusOfNc4,
		isnull((select Nc5Status from MsmeCertifications where zedid=@UserId and Certification='Silver'),0) SilverStatusOfNc5,
		isnull((select IsSaSelfieSubmitted from MsmeCertifications where zedid=@UserId and Certification='Silver'),0) SilverSelfieStatus,

		isnull((select Nc1Status from MsmeCertifications where zedid=@UserId and Certification='Gold'),0) GoldStatusOfNc1,
		isnull((select Nc2Status from MsmeCertifications where zedid=@UserId and Certification='Gold'),0) GoldStatusOfNc2,
		isnull((select Nc3Status from MsmeCertifications where zedid=@UserId and Certification='Gold'),0) GoldStatusOfNc3,
		isnull((select Nc4Status from MsmeCertifications where zedid=@UserId and Certification='Gold'),0) GoldStatusOfNc4,
		isnull((select Nc5Status from MsmeCertifications where zedid=@UserId and Certification='Gold'),0) GoldStatusOfNc5,
		isnull((select IsSaSelfieSubmitted from MsmeCertifications where zedid=@UserId and Certification='Gold'),0) GoldSelfieStatus,

		(select top 1  Descrip from MsmeHistory where ZedId=@UserId and StatusType IN ('Nc1Raised','Nc1Submitted') and CertificationType='Bronze' order by Id desc) Nc1StatusTextBronze,
		(select top 1  Descrip from MsmeHistory where ZedId=@UserId and StatusType IN ('Nc2Raised','Nc2Submitted') and CertificationType='Bronze' order by Id desc) Nc2StatusTextBronze,
		(select top 1  Descrip from MsmeHistory where ZedId=@UserId and StatusType IN ('Nc3Raised','Nc3Submitted') and CertificationType='Bronze' order by Id desc) Nc3StatusTextBronze,
		(select top 1  Descrip from MsmeHistory where ZedId=@UserId and StatusType IN ('Nc4Raised','Nc4Submitted') and CertificationType='Bronze' order by Id desc) Nc4StatusTextBronze,
		(select top 1  Descrip from MsmeHistory where ZedId=@UserId and StatusType IN ('Nc5Raised','Nc5Submitted') and CertificationType='Bronze' order by Id desc) Nc5StatusTextBronze,
  															
		(select top 1  Descrip from MsmeHistory where ZedId=@UserId and StatusType IN ('Nc1Raised','Nc1Submitted') and CertificationType='Silver' order by Id desc) Nc1StatusTextSilver,
		(select top 1  Descrip from MsmeHistory where ZedId=@UserId and StatusType IN ('Nc2Raised','Nc2Submitted') and CertificationType='Silver' order by Id desc) Nc2StatusTextSilver,
		(select top 1  Descrip from MsmeHistory where ZedId=@UserId and StatusType IN ('Nc3Raised','Nc3Submitted') and CertificationType='Silver' order by Id desc) Nc3StatusTextSilver,
		(select top 1  Descrip from MsmeHistory where ZedId=@UserId and StatusType IN ('Nc4Raised','Nc4Submitted') and CertificationType='Silver' order by Id desc) Nc4StatusTextSilver,
		(select top 1  Descrip from MsmeHistory where ZedId=@UserId and StatusType IN ('Nc5Raised','Nc5Submitted') and CertificationType='Silver' order by Id desc) Nc5StatusTextSilver,
 															
		(select top 1  Descrip from MsmeHistory where ZedId=@UserId and StatusType IN ('Nc1Raised','Nc1Submitted') and CertificationType='Gold' order by Id desc)   Nc1StatusTextGold,
		(select top 1  Descrip from MsmeHistory where ZedId=@UserId and StatusType IN ('Nc2Raised','Nc2Submitted') and CertificationType='Gold' order by Id desc)   Nc2StatusTextGold,
		(select top 1  Descrip from MsmeHistory where ZedId=@UserId and StatusType IN ('Nc3Raised','Nc3Submitted') and CertificationType='Gold' order by Id desc)   Nc3StatusTextGold,
		(select top 1  Descrip from MsmeHistory where ZedId=@UserId and StatusType IN ('Nc4Raised','Nc4Submitted') and CertificationType='Gold' order by Id desc)   Nc4StatusTextGold,
		(select top 1  Descrip from MsmeHistory where ZedId=@UserId and StatusType IN ('Nc5Raised','Nc5Submitted') and CertificationType='Gold' order by Id desc)   Nc5StatusTextGold,
		@LatestCertification LatestCertification,@DateOfAvail DateOfAvail,@JoiningRewardAmount JoiningRewardAmount,
		(select isnull(IsCouponUsed,0) from Msme where ZedId=@UserId) IsCouponUsed,
		(select isnull(FinancialAssistanceStatus,0) from Msme where ZedId=@UserId) FinancialAssistanceStatus




END

