)
AS
BEGIN
	
	SET NOCOUNT ON;

	--select S.Id,S.SectionCode,S.SectionName,iButton,S.OrderNo,S.SectionType from Sections S
	--where S.SectionType=@CertificationType
	--order by S.OrderNo

	--SELECT ROW_NUMBER() OVER(ORDER BY SectionCode, RequirementCode) SNo, Id, SectionCode, SectionName,RequirementCode,RequirementName,Q.OrderNo,Q.SectionType
	--FROM Requirements Q
	--where Q.SectionType=@CertificationType
	--ORDER By cast(SectionCode as int), RequirementCode

	--SELECT ROW_NUMBER() OVER(ORDER BY SectionCode, RequirementCode, OptionCode) SNo, Id,SectionCode, RequirementCode,OptionCode,OptionName,OptionImage,Q.SectionType
	--FROM Options Q
	--where Q.SectionType=@CertificationType
	--ORDER By cast(SectionCode as int), RequirementCode, OptionCode

	--SELECT ROW_NUMBER() OVER(ORDER BY SectionCode, RequirementCode, OptionCode, SubOptionCode) SNo, Id, SectionCode,
	--	RequirementCode,OptionCode,SubOptionCode,SubOptionName,SubOptionImage,Q.SectionType
	--FROM SubOptions Q
	--where Q.SectionType=@CertificationType
	--ORDER By SectionCode, RequirementCode, OptionCode, SubOptionCode

	--SELECT ROW_NUMBER() OVER(ORDER BY SectionCode, RequirementCode, EvidenceCode) SNo, Id,SectionCode, RequirementCode,EvidenceCode,EvidenceName,E.SectionType,ValidationRequired
	--FROM Evidences E
	--where E.SectionType=@CertificationType
	--ORDER By cast(SectionCode as int), RequirementCode, EvidenceCode


	select S.SectionId Id,S.SectionCode,S.SectionName,iButton,S.OrderNo,S.SectionType from MsmeSections S
	where S.SectionType=@CertificationType and ZedId=@ZedId and NcCount=1
	order by S.OrderNo

	SELECT ROW_NUMBER() OVER(ORDER BY SectionCode, RequirementCode) SNo, RequirementId Id, SectionCode, SectionName,RequirementCode,RequirementName,Q.OrderNo,Q.SectionType
	FROM MsmeRequirements Q
	where Q.SectionType=@CertificationType and ZedId=@ZedId and NcCount=1
	ORDER By cast(SectionCode as int), RequirementCode

	SELECT ROW_NUMBER() OVER(ORDER BY SectionCode, RequirementCode, OptionCode) SNo, OptionId Id,SectionCode, RequirementCode,OptionCode,OptionName,OptionImage,Q.SectionType
	FROM MsmeOptions Q
	where Q.SectionType=@CertificationType and ZedId=@ZedId and NcCount=1
	ORDER By cast(SectionCode as int), RequirementCode, OptionCode

	SELECT ROW_NUMBER() OVER(ORDER BY SectionCode, RequirementCode, OptionCode, SubOptionCode) SNo, SubOptionId Id, SectionCode,
		RequirementCode,OptionCode,SubOptionCode,SubOptionName,SubOptionImage,Q.SectionType
	FROM MsmeSubOptions Q
	where Q.SectionType=@CertificationType and ZedId=@ZedId and NcCount=1
	ORDER By SectionCode, RequirementCode, OptionCode, SubOptionCode

	SELECT ROW_NUMBER() OVER(ORDER BY SectionCode, RequirementCode, EvidenceCode) SNo, EvidenceId Id,SectionCode, RequirementCode,EvidenceCode,EvidenceName,E.SectionType, ValidationRequired,EvidenceHelpText
	FROM MsmeEvidences E
	where E.SectionType=@CertificationType and ZedId=@ZedId and NcCount=1
	ORDER By cast(SectionCode as int), RequirementCode, EvidenceCode



END

