-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_APP_MSME_INSERT_BASIC_INFO] 
(
	@ZedId VarChar(50)						= NULL,
	@RefId VarChar(50)						= NULL,
	@CertificationType VarChar(50)			= NULL,
	@AuditsConducted VarChar(50)			= NULL,
	@DomesticCustomers VarChar(2000)		= NULL,	
	@InternationalCustomers varchar(2000)	= NULL, 
	@RawMaterialImported varchar(50)		= NULL, 
	@OutsourcedProcesses varchar(2000)		= NULL,
	@EnergySources varchar(2000)            = NULL,	

	@ProductList		ProductDetails2		READONLY,
	@RawMaterialList	RawMaterial			READONLY,

	@ProductDescriptionPhotos	DynamicPhotoList2	READONLY,
	@ProductPhotos				DynamicPhotoList2	READONLY,
	@SiteExteriorPhotos			DynamicPhotoList2	READONLY,
	@Selfie						DynamicPhotoList2	READONLY
)
AS
BEGIN

	DECLARE @ProductId varchar(50) = NULL
	
	IF EXISTS (select * from MsmeCertifications where ZedId=@ZedId and Certification=@CertificationType)
		BEGIN
			UPDATE MsmeCertifications SET AuditsConducted=@AuditsConducted, DomesticCustomers=@DomesticCustomers, InternationalCustomers=@InternationalCustomers, RawMaterialImported=@RawMaterialImported,
			OutsourcedProcesses=@OutsourcedProcesses, EnergySources=@EnergySources where ZedId=@ZedId and Certification=@CertificationType
		END
		ELSE
		BEGIN
			INSERT INTO MsmeCertifications (ZedId, Certification, AuditsConducted, DomesticCustomers, InternationalCustomers, RawMaterialImported, OutsourcedProcesses, EnergySources)
			VALUES (@ZedId, @CertificationType, @AuditsConducted, @DomesticCustomers, @InternationalCustomers, @RawMaterialImported, @OutsourcedProcesses, @EnergySources)
		END

	IF EXISTS(select * from @ProductList)
		BEGIN
			DELETE FROM MsmeProducts WHERE ZedId=@ZedId and Certification=@CertificationType
			INSERT INTO MsmeProducts (ZedId, Certification, ProductName, Exported, ProductPhoto, ProductDescriptionPhoto)
			SELECT @ZedId, @CertificationType, ProductName, Exported,ProductPhoto, ProductDescriptionPhoto FROM @ProductList

			UPDATE MsmeProducts SET ProductParentId=Id where ZedId=@ZedId and Certification=@CertificationType and NcCount=0
		END
	ELSE
		BEGIN
			INSERT INTO MsmeProducts (ZedId, Certification, ProductName, Exported, ProductPhoto, ProductDescriptionPhoto)
			SELECT @ZedId, @CertificationType, ProductName, Exported,ProductPhoto, ProductDescriptionPhoto FROM @ProductList

			UPDATE MsmeProducts SET ProductParentId=Id where ZedId=@ZedId and Certification=@CertificationType and NcCount=0
		END

	IF EXISTS(select * from @RawMaterialList)
		BEGIN
			DELETE FROM MsmeRawMaterials WHERE ZedId=@ZedId and Certification=@CertificationType
			INSERT INTO MsmeRawMaterials (ZedId, Certification, RawMaterialName, Percentage, CountryName)
			SELECT @ZedId, @CertificationType, Name, Percentage, CountryName FROM @RawMaterialList
		END
		ELSE
		BEGIN
			INSERT INTO MsmeRawMaterials (ZedId, Certification, RawMaterialName, Percentage, CountryName)
			SELECT @ZedId, @CertificationType, Name, Percentage, CountryName FROM @RawMaterialList
		END

	IF EXISTS(select * from @SiteExteriorPhotos)
		BEGIN
			DELETE FROM MsmePhotos WHERE ZedId=@ZedId and PhotoType='SiteExteriorPhotos'  and Certification=@CertificationType
			INSERT INTO MsmePhotos (ZedId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoExtension,PhotosOrder)
			SELECT @ZedId, @CertificationType, 'SiteExteriorPhotos', PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoType,1 FROM @SiteExteriorPhotos
		END
		ELSE
		BEGIN
			INSERT INTO MsmePhotos (ZedId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoExtension,PhotosOrder)
			SELECT @ZedId, @CertificationType, 'SiteExteriorPhotos', PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoType,1 FROM @SiteExteriorPhotos
		END


	IF EXISTS(select * from @Selfie)
		BEGIN
			DELETE FROM MsmePhotos WHERE ZedId=@ZedId and PhotoType='Selfie'  and Certification=@CertificationType
			INSERT INTO MsmePhotos (ZedId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoExtension,PhotosOrder)
			SELECT @ZedId, @CertificationType, 'Selfie', PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoType,2 FROM @Selfie
		END
		ELSE
		BEGIN
			INSERT INTO MsmePhotos (ZedId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoExtension,PhotosOrder)
			SELECT @ZedId, @CertificationType, 'Selfie', PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoType,2 FROM @Selfie
		END
	
	IF EXISTS(select * from @ProductPhotos)
		BEGIN									
			DELETE FROM MsmePhotos WHERE ZedId=@ZedId and PhotoType='ProductPhotos'  and Certification=@CertificationType
			INSERT INTO MsmePhotos (ZedId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoExtension,PhotosOrder)
			SELECT @ZedId, @CertificationType, 'ProductPhotos', PhotoId, 'ProductPhoto', TimeStamp, Latitude, Longitude, PhotoType,3 FROM @ProductPhotos

			update P set P.ProductId=M.Id from MsmeProducts M inner join MsmePhotos P on (M.ZedId=P.ZedId and M.Certification=P.Certification and M.ProductPhoto=concat(P.PhotoId,'.',PhotoExtension)) where m.zedid=@ZedId and M.Certification=@CertificationType and M.NcCount=0 


		END
		ELSE
		BEGIN			
			INSERT INTO MsmePhotos (ZedId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoExtension,PhotosOrder)
			SELECT @ZedId, @CertificationType, 'ProductPhotos', PhotoId, 'ProductPhoto', TimeStamp, Latitude, Longitude, PhotoType,3 FROM @ProductPhotos

			update P set P.ProductId=M.Id from MsmeProducts M inner join MsmePhotos P on (M.ZedId=P.ZedId and M.Certification=P.Certification and M.ProductPhoto=concat(P.PhotoId,'.',PhotoExtension)) where m.zedid=@ZedId and M.Certification=@CertificationType and M.NcCount=0 
		END

		IF EXISTS(select * from @ProductDescriptionPhotos)
		BEGIN		
			DELETE FROM MsmePhotos WHERE ZedId=@ZedId and PhotoType='ProductDescriptionPhotos'  and Certification=@CertificationType
			INSERT INTO MsmePhotos (ZedId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoExtension,ProductId,PhotosOrder)
			SELECT @ZedId, @CertificationType, 'ProductDescriptionPhotos', PhotoId, 'ProductDescriptionPhoto', TimeStamp, Latitude, Longitude, PhotoType,@ProductId,3 FROM @ProductDescriptionPhotos

			update P set P.ProductId=M.Id from MsmeProducts M inner join MsmePhotos P on (M.ZedId=P.ZedId and M.Certification=P.Certification and M.ProductDescriptionPhoto=concat(P.PhotoId,'.',PhotoExtension)) where m.zedid=@ZedId and M.Certification=@CertificationType and M.NcCount=0 
		END
		ELSE
		BEGIN			
			INSERT INTO MsmePhotos (ZedId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoExtension,ProductId,PhotosOrder)
			SELECT @ZedId, @CertificationType, 'ProductDescriptionPhotos', PhotoId, 'ProductDescriptionPhoto', TimeStamp, Latitude, Longitude, PhotoType,@ProductId,3 FROM @ProductDescriptionPhotos

			update P set P.ProductId=M.Id from MsmeProducts M inner join MsmePhotos P on (M.ZedId=P.ZedId and M.Certification=P.Certification and M.ProductDescriptionPhoto=concat(P.PhotoId,'.',PhotoExtension)) where m.zedid=@ZedId and M.Certification=@CertificationType and M.NcCount=0 
		END
END
GO
