-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_APP_MSME_INSERT_EVIDENCE] 
(
	@ZedId VarChar(50)			= NULL,
	@RefId VarChar(50)			= NULL,
	@EvidenceId VarChar(50)		= NULL,	
	@CertificationType VarChar(50)		= NULL,
	@IsFirst bit	 NULL,
	@PhotoList	DynamicPhotoList2	READONLY,
	@IsLast bit	 NULL

)
AS
BEGIN
	
	DECLARE @NcCount int = NULL
	SELECT @NcCount=NcCount FROM MsmeCertifications WHERE ZedId=@ZedId and Certification=@CertificationType

	IF @IsFirst = 1
	BEGIN
		DELETE FROM MsmePhotos WHERE ZedId=@ZedId and EvidenceId=@EvidenceId and Certification=@CertificationType and NcCount=@NcCount
	END

	INSERT INTO MsmePhotos (ZedId, EvidenceId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoExtension, NcCount)
	SELECT @ZedId, @EvidenceId, @CertificationType, 'EvidencePhotos', PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoType,@NcCount FROM @PhotoList
	
	IF @IsLast = 1
	BEGIN
		UPDATE MsmeEvidences set SyncedDate=GETDATE() WHERE ZedId=@ZedId and EvidenceId=@EvidenceId and SectionType=@CertificationType and NcCount=@NcCount
	END
END
GO
/****** Object:  StoredProcedure [dbo].[SP_APP_MSME_INSERT_FINANCIAL_ASSISTANCE_NOT_USING]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_APP_MSME_INSERT_FINANCIAL_ASSISTANCE_NOT_USING] 
(
	@RefId VarChar(50)						= NULL,
	@ZedId VarChar(50)						= NULL,

	@CategoryOfCertificate VarChar(50)		= NULL,
	@NameOfCertficate VarChar(200)			= NULL,
	@CertificationAgency VarChar(200)		= NULL,
	@CertficateNumber VarChar(50)			= NULL,
	@DateOfIssue VarChar(50)				= NULL,
	@ValidityOfCertificate VarChar(50)		= NULL,
	@AnyOtherInformation VarChar(5000)		= NULL,

	@ExpenditureCertficate VarChar(200)		= NULL,
	@AgencyOrSupplier VarChar(200)			= NULL,
	@InvoiceNo VarChar(50)					= NULL,
	@InvoiceBillDate VarChar(50)			= NULL,
	@AmountPaid VarChar(50)					= NULL,
	@EligibleAmount VarChar(50)				= NULL,
	@ModeOfPayment VarChar(50)				= NULL,

	@AccountNo VarChar(50)					= NULL,
	@IfscCode VarChar(50)					= NULL,
	@BranchAddress VarChar(2000)			= NULL,
	@BankName VarChar(200)					= NULL,

	@SubmittedFrom VarChar(50)				= NULL,
			
	@PhotoListWeb	DynamicPhotoList	READONLY,
	@PhotoListApp	DynamicPhotoList2	READONLY
)
AS
BEGIN

	DECLARE @FinancialAssistanceId varchar(200),
	@CertificationType varchar(50) = NULL

	SET @FinancialAssistanceId =Next Value For FinancialIdSequence
	

	IF EXISTS (SELECT Certification from MsmeCertifications where ZedId=@Zedid AND Certification='Gold' AND CertificationStatus=16 )
	BEGIN
		select @CertificationType='Gold'
	END
	ELSE
	IF EXISTS (SELECT Certification from MsmeCertifications where ZedId=@Zedid AND Certification='Silver' AND CertificationStatus=16 )
	BEGIN
		select @CertificationType='Silver'
	END
	ELSE
	IF EXISTS (SELECT Certification from MsmeCertifications where ZedId=@Zedid AND Certification='Bronze' AND CertificationStatus=6 )
	BEGIN
		select @CertificationType='Bronze' 
	END


	
	INSERT INTO FinancialAssistance (
		ZedId, CategoryOfCertificate, NameOfCertficate, CertificationAgency, CertficateNumber, DateOfIssue, ValidityOfCertificate, AnyOtherInformation,
		ExpenditureCertficate, AgencyOrSupplier, InvoiceNo, InvoiceBillDate, AmountPaid, EligibleAmount, ModeOfPayment, 
		AccountNo, IfscCode, BranchAddress, BankName, SubmittedFrom,CertificationType,FinancialAssistanceId
	)
	VALUES (
		@ZedId, @CategoryOfCertificate, @NameOfCertficate, @CertificationAgency, @CertficateNumber, @DateOfIssue, @ValidityOfCertificate, @AnyOtherInformation,
		@ExpenditureCertficate, @AgencyOrSupplier, @InvoiceNo, @InvoiceBillDate, @AmountPaid, @EligibleAmount, @ModeOfPayment, 
		@AccountNo, @IfscCode, @BranchAddress, @BankName, @SubmittedFrom,@CertificationType,@FinancialAssistanceId
	)

	INSERT INTO [FinancialAssistancePhotos] ([ZedId], [PhotoId], [Name], [TimeStamp], [Latitude], [Longitude], [PhotoType],FinancialAssistanceId,CertificationType)
	SELECT @ZedId, [PhotoId], [Name], [TimeStamp], [Latitude], [Longitude], [PhotoType],@FinancialAssistanceId,@CertificationType FROM @PhotoListApp

	INSERT INTO [FinancialAssistancePhotos] ([ZedId], [PhotoId], [Name], [TimeStamp], [Latitude], [Longitude], [PhotoType],FinancialAssistanceId,CertificationType)
	SELECT @ZedId, [PhotoId], [Name], [TimeStamp], [Latitude], [Longitude], [Name],@FinancialAssistanceId,@CertificationType FROM @PhotoListWeb

	UPDATE Msme SET FinancialAssistanceStatus=0 WHERE ZedId=@ZedId
END
GO
/****** Object:  StoredProcedure [dbo].[SP_APP_MSME_INSERT_PRODUCT_INFO]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
