SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_APP_MSME_INSERT_REQUIREMENT] 
(
	@ZedId VarChar(50)				= NULL,
	@Id VarChar(50)					= NULL,
	@CertificationType VarChar(50)	= NULL,
	@Code VarChar(50)				= NULL,
	@MsmeRemarks VarChar(2000)		= NULL,
	@IsFirst bit	 = NULL,
	@IsLast bit	 = NULL,
			
	@PhotoList	DynamicPhotoList2	READONLY
)
AS
BEGIN
	DECLARE @EvidenceId varchar(50) = NULL
	DECLARE @NcCount int = NULL
	SELECT @NcCount=NcCount FROM MsmeCertifications WHERE ZedId=@ZedId and Certification=@CertificationType

	SELECT @EvidenceId=EvidenceId From MsmeEvidences WHERE ZedId=@ZedId AND SectionType=@CertificationType AND RequirementId=@Id AND NcCount=@NcCount

	IF @CertificationType = 'Bronze'
	BEGIN

		IF @IsFirst = 1 
		BEGIN
			
			DELETE FROM MsmePhotos WHERE  ZedId=@ZedId and RequirementId=@Id AND NcCount=@NcCount and Certification=@CertificationType
		END

		update MsmeRequirements set MsmeRemarks=@MsmeRemarks,MsmeUpdatedDate=getdate(), AssessorRemarks=null,Conformance=null,OpenedFlag=null where ZedId=@ZedId and RequirementId=@Id AND NcCount=@NcCount and SectionType=@CertificationType

		INSERT INTO MsmePhotos (ZedId, RequirementId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoExtension, NcCount,EvidenceId)
		SELECT @ZedId, @Id, @CertificationType, 'EvidencePhotos', PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoType,@NcCount,@EvidenceId FROM @PhotoList

		IF @IsLast = 1 
		BEGIN
			UPDATE MsmeEvidences set SyncedDate=GETDATE(),DocumentOpenedTime=null WHERE ZedId=@ZedId and RequirementId=@Id AND NcCount=@NcCount and SectionType=@CertificationType

		END

	END

	ELSE
	BEGIN

	IF @IsFirst = 1 
		BEGIN
			
			DELETE FROM SaRequirementPhotos WHERE  ZedId=@ZedId and RequirementId=@Id AND NcCount=@NcCount and Certification=@CertificationType
		END

		update MsmeRequirements set MsmeRemarks=@MsmeRemarks,MsmeUpdatedDate=getdate(),SaAssessorRemarks=null,SaConformance=null,OpenedFlag=null where ZedId=@ZedId and RequirementId=@Id AND NcCount=@NcCount and SectionType=@CertificationType

		INSERT INTO SaRequirementPhotos (ZedId, RequirementId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude,SaPhotoExtension, NcCount)
		SELECT @ZedId, @Id, @CertificationType, 'EvidencePhotos', PhotoId, Name, TimeStamp, Latitude, Longitude,PhotoType, @NcCount FROM @PhotoList

		IF @IsLast = 1 
		BEGIN
			UPDATE MsmeEvidences set SyncedDate=GETDATE(),DocumentOpenedTime=null WHERE ZedId=@ZedId and RequirementId=@Id AND NcCount=@NcCount and SectionType=@CertificationType

		END
	END
END
GO
