-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_APP_MSME_REMOTE_INSERT_SELFIE] 
(
	@ZedId              VarChar(50)		= NULL,
	@CertificationType	VarChar(200)	= NULL,
	@Timestamp          VarChar(200)	= NULL,
	@PhotoPath          VarChar(2000)	= NULL,
	@Longitude          VarChar(50)		= NULL,
	@Latitude           VarChar(50)		= NULL,
	@RepresentativeName varchar(200)    = NULL,
	@Designation		varchar(200)	= NULL
)
AS
BEGIN
	      
	SET NOCOUNT ON;
	
	INSERT INTO MsmeSelfies(ZedId,Certification,Timestamp,PhotoPath,Latitude,Longitude,CreatedDate,RepresentativeName,Designation)
	VALUES (@ZedId,@CertificationType,@Timestamp,@PhotoPath,@Latitude,@Longitude,Getdate(),@RepresentativeName,@Designation)

	INSERT INTO MsmeLocations(ZedId,Certification,Timestamp,Latitude,Longitude,CreatedDate)
	VALUES (@ZedId,@CertificationType,@Timestamp,@Latitude,@Longitude,Getdate())
END



