/****** Object:  StoredProcedure [dbo].[SP_APP_MSME_STATUS]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
-- [SP_APP_MSME_STATUS] '<redacted>'
CREATE PROCEDURE [dbo].[SP_APP_MSME_STATUS] --'<redacted>'
(
	@ZedId varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	DECLARE @StateId int = NULL
	SELECT @StateId=StateId from Msme where ZedId=@ZedId

	DECLARE @CurrentUrl varchar(100) = NULL
	SELECT @CurrentUrl=UrlName from UrlsMasterData

	DECLARE @LatestCertification varchar(100) = NULL,
			@DateOfAvail varchar(50) = NULL,
			@JoiningRewardAmount varchar(50) = '10000',
			@CompletedCertification varchar(50) = NULL

			select top 1 @LatestCertification=Certification,@DateOfAvail=FORMAT(CreatedDate, 'MMMM d, yyyy') from MsmePaymentInfo where ZedId=@ZedId and UseCoupon='Yes' order by CreatedDate desc

			select top 1 @CompletedCertification=Certification from MsmeCertifications where CertificationStatus=16 and ZedId=@ZedId order by CreatedDate desc

	--STATUS CHECKING FOR ENABLE AND DISABLE OF BUTTONS IN APP
	SELECT 
		(select CASE WHEN (@CompletedCertification = 'Silver' or @CompletedCertification = 'gold') Then 5 WHEN CertificationStatus>5 THEN 3 WHEN CertificationStatus>2 THEN 2 when IsBronzePaymentDone=1 then 1 else 0 END AS CertificationStatus from Msme M LEFT JOIN  MsmeCertifications C on (M.ZedId=C.ZedId and Certification='Bronze') where M.zedid=@ZedId ) BronzeStatus,
		(select CASE WHEN (@CompletedCertification = 'gold') Then 5 WHEN CertificationStatus>15 THEN 4 WHEN CertificationStatus>8 THEN 3 WHEN CertificationStatus>2 THEN 2 when IsSilverPaymentDone=1 then 1 else 0 END AS CertificationStatus from Msme M LEFT JOIN  MsmeCertifications C on (M.ZedId=C.ZedId and Certification='Silver') where M.zedid=@ZedId ) SilverStatus,
		(select CASE WHEN CertificationStatus>15 THEN 4 WHEN CertificationStatus>8 THEN 3 WHEN CertificationStatus>2 THEN 2 when IsGoldPaymentDone=1 then 1 else 0 END AS CertificationStatus from Msme M LEFT JOIN  MsmeCertifications C on (M.ZedId=C.ZedId and Certification='Gold') where M.zedid=@ZedId ) GoldStatus, 
		
		isnull((select NcCount from MsmeCertifications where zedid=@ZedId and Certification='Bronze'),0) BronzeStatusOfNc,
		isnull((select NcCount from MsmeCertifications where zedid=@ZedId and Certification='Silver'),0) SilverStatusOfNc,
		isnull( (select NcCount from MsmeCertifications where zedid=@ZedId and Certification='Gold'),0) GoldStatusOfNc,
		

		isnull((select case when DaCertificateNo is null then '' else concat(@CurrentUrl,'/Certificates/DA/',@ZedId,'/Bronze.pdf') end as BronzeCertificatePath from  MsmeCertifications  where ZedId=@ZedId and Certification='Bronze' ),'') BronzeCertificatePath,
		 '' BronzeReportPath, concat(@CurrentUrl,'/Incentive/Details/',@StateId,'?ct=Bronze') BronzeIncentives,
		isnull((select case when SaCertificateNo is null then '' else concat(@CurrentUrl,'/Certificates/SA/',@ZedId,'/Silver.pdf') end as BronzeCertificatePath from  MsmeCertifications  where ZedId=@ZedId and Certification='Silver' ),'') SilverCertificatePath,
		'' SilverReportPath, concat(@CurrentUrl,'/Incentive/Details/',@StateId,'?ct=Silver') SilverIncentives,
		isnull((select case when SaCertificateNo is null then '' else concat(@CurrentUrl,'/Certificates/SA/',@ZedId,'/Gold.pdf') end as BronzeCertificatePath from  MsmeCertifications  where ZedId=@ZedId and Certification='Gold' ),'') GoldCertificatePath,
		'' GoldReportPath, concat(@CurrentUrl,'/Incentive/Details/',@StateId,'?ct=Gold') GoldIncentives,
		

		isnull((select Nc1Status from MsmeCertifications where zedid=@ZedId and Certification='Bronze'),0) BronzeStatusOfNc1,
		isnull((select Nc2Status from MsmeCertifications where zedid=@ZedId and Certification='Bronze'),0) BronzeStatusOfNc2,
		isnull((select Nc3Status from MsmeCertifications where zedid=@ZedId and Certification='Bronze'),0) BronzeStatusOfNc3,
		isnull((select Nc4Status from MsmeCertifications where zedid=@ZedId and Certification='Bronze'),0) BronzeStatusOfNc4,
		isnull((select Nc5Status from MsmeCertifications where zedid=@ZedId and Certification='Bronze'),0) BronzeStatusOfNc5,
		0 BronzeSelfieStatus,
		0 BronzeRemoteStatus,

		isnull((select Nc1Status from MsmeCertifications where zedid=@ZedId and Certification='Silver'),0) SilverStatusOfNc1,
		isnull((select Nc2Status from MsmeCertifications where zedid=@ZedId and Certification='Silver'),0) SilverStatusOfNc2,
		isnull((select Nc3Status from MsmeCertifications where zedid=@ZedId and Certification='Silver'),0) SilverStatusOfNc3,
		isnull((select Nc4Status from MsmeCertifications where zedid=@ZedId and Certification='Silver'),0) SilverStatusOfNc4,
		isnull((select Nc5Status from MsmeCertifications where zedid=@ZedId and Certification='Silver'),0) SilverStatusOfNc5,
		isnull((select IsSaSelfieSubmitted from MsmeCertifications where zedid=@ZedId and Certification='Silver'),0) SilverSelfieStatus,
		isnull((select case when ModeOfAssessment='Remote Assessment' and CertificationStatus>9 then 2  when ModeOfAssessment='Remote Assessment' and CertificationStatus=9 then 1 else 0 end as RemoteStatus from MsmeCertifications where zedid=@ZedId and Certification='Silver'),0) SilverRemoteStatus,

		isnull((select Nc1Status from MsmeCertifications where zedid=@ZedId and Certification='Gold'),0) GoldStatusOfNc1,
		isnull((select Nc2Status from MsmeCertifications where zedid=@ZedId and Certification='Gold'),0) GoldStatusOfNc2,
		isnull((select Nc3Status from MsmeCertifications where zedid=@ZedId and Certification='Gold'),0) GoldStatusOfNc3,
		isnull((select Nc4Status from MsmeCertifications where zedid=@ZedId and Certification='Gold'),0) GoldStatusOfNc4,
		isnull((select Nc5Status from MsmeCertifications where zedid=@ZedId and Certification='Gold'),0) GoldStatusOfNc5,
		isnull((select IsSaSelfieSubmitted from MsmeCertifications where zedid=@ZedId and Certification='Gold'),0) GoldSelfieStatus,
		0 GoldRemoteStatus,

		(select top 1  Descrip from MsmeHistory where ZedId=@ZedId and StatusType IN ('Nc1Raised','Nc1Submitted') and CertificationType='Bronze' order by Id desc) Nc1StatusTextBronze,
		(select top 1  Descrip from MsmeHistory where ZedId=@ZedId and StatusType IN ('Nc2Raised','Nc2Submitted') and CertificationType='Bronze' order by Id desc) Nc2StatusTextBronze,
		(select top 1  Descrip from MsmeHistory where ZedId=@ZedId and StatusType IN ('Nc3Raised','Nc3Submitted') and CertificationType='Bronze' order by Id desc) Nc3StatusTextBronze,
		(select top 1  Descrip from MsmeHistory where ZedId=@ZedId and StatusType IN ('Nc4Raised','Nc4Submitted') and CertificationType='Bronze' order by Id desc) Nc4StatusTextBronze,
		(select top 1  Descrip from MsmeHistory where ZedId=@ZedId and StatusType IN ('Nc5Raised','Nc5Submitted') and CertificationType='Bronze' order by Id desc) Nc5StatusTextBronze,
  
		(select top 1  Descrip from MsmeHistory where ZedId=@ZedId and StatusType IN ('Nc1Raised','Nc1Submitted') and CertificationType='Silver' order by Id desc) Nc1StatusTextSilver,
		(select top 1  Descrip from MsmeHistory where ZedId=@ZedId and StatusType IN ('Nc2Raised','Nc2Submitted') and CertificationType='Silver' order by Id desc) Nc2StatusTextSilver,
		(select top 1  Descrip from MsmeHistory where ZedId=@ZedId and StatusType IN ('Nc3Raised','Nc3Submitted') and CertificationType='Silver' order by Id desc) Nc3StatusTextSilver,
		(select top 1  Descrip from MsmeHistory where ZedId=@ZedId and StatusType IN ('Nc4Raised','Nc4Submitted') and CertificationType='Silver' order by Id desc) Nc4StatusTextSilver,
		(select top 1  Descrip from MsmeHistory where ZedId=@ZedId and StatusType IN ('Nc5Raised','Nc5Submitted') and CertificationType='Silver' order by Id desc) Nc5StatusTextSilver,
 
		(select top 1  Descrip from MsmeHistory where ZedId=@ZedId and StatusType IN ('Nc1Raised','Nc1Submitted') and CertificationType='Gold' order by Id desc)   Nc1StatusTextGold,
		(select top 1  Descrip from MsmeHistory where ZedId=@ZedId and StatusType IN ('Nc2Raised','Nc2Submitted') and CertificationType='Gold' order by Id desc)   Nc2StatusTextGold,
		(select top 1  Descrip from MsmeHistory where ZedId=@ZedId and StatusType IN ('Nc3Raised','Nc3Submitted') and CertificationType='Gold' order by Id desc)   Nc3StatusTextGold,
		(select top 1  Descrip from MsmeHistory where ZedId=@ZedId and StatusType IN ('Nc4Raised','Nc4Submitted') and CertificationType='Gold' order by Id desc)   Nc4StatusTextGold,
		(select top 1  Descrip from MsmeHistory where ZedId=@ZedId and StatusType IN ('Nc5Raised','Nc5Submitted') and CertificationType='Gold' order by Id desc)   Nc5StatusTextGold,

		(select FinancialAssistanceStatus from Msme where ZedId=@ZedId)  FinancialAssistanceStatus,
		@LatestCertification LatestCertification,@DateOfAvail DateOfAvail,@JoiningRewardAmount JoiningRewardAmount,
		(select isnull(IsCouponUsed,0) from Msme where ZedId=@ZedId) IsCouponUsed


END

GO
/****** Object:  StoredProcedure [dbo].[SP_APP_SA_ALLOT_SECTIONS_TO_COASSESSOR]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_APP_SA_ALLOT_SECTIONS_TO_COASSESSOR]
(
	@ZedId varchar(50) = NULL,
	@CertificationType VarChar(50)	= NULL,

	@AllotList	DynamicSectionAllot	READONLY
)
AS
BEGIN

	DECLARE @NcCount int = NULL
	SELECT @NcCount=NcCount FROM MsmeCertifications WHERE ZedId=@ZedId and Certification=@CertificationType and  SiteAssessorId is not null and SaCertificateNo is null
	
	update S set S.AssessorId=A.AssessorId from MsmeSections S inner join @AllotList A 
	on ( S.SectionId=A.SectionId and S.SectionCode=A.SectionCode) where ZedId=@ZedId and SectionType=@CertificationType and NcCount=@NcCount

	Update MsmeCertifications set CertificationStatus=9 where ZedId=@ZedId and Certification=@CertificationType and NcCount=@NcCount

	insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
	values (@ZedId,'Sections allocation done by Lead assessor to Co assessor',getdate(),@CertificationType,NULL)

END



GO
/****** Object:  StoredProcedure [dbo].[SP_APP_SA_CHECK_LOGIN]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
--[SP_APP_SA_CHECK_LOGIN] '<redacted>', '<redacted>', '<redacted>'
CREATE PROCEDURE [dbo].[SP_APP_SA_CHECK_LOGIN] --'<redacted>', '<redacted>', '<redacted>'
(
	@UserId varchar(50) = NULL,
	@Password varchar(50) = NULL,
	@ZedId varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	SET @UserId=replace(@UserId,' ','_')
	SET @ZedId=replace(@ZedId,' ','_')

	DECLARE @CertificationStatus int = NULL,
			@CertificationType varchar(50) = NULL,
			@NcCount int = NULL
	SELECT @CertificationStatus=CertificationStatus,@CertificationType=Certification,@NcCount=NcCount FROM MsmeCertifications where ZedId=@ZedId and  SiteAssessorId is not null and SaCertificateNo is null

	DECLARE @CertificationStatusTu int = NULL,
			@CertificationTypeTu varchar(50) = NULL,
			@NcCountTu int = NULL

	SELECT TOP 1 @CertificationStatusTu=CertificationStatus,@CertificationTypeTu=Certification,@NcCountTu=NcCount FROM MsmeCertifications where ZedId=@ZedId and  SiteAssessorId is not null and SaCertificateNo is not null ORDER BY ID DESC


	SELECT * FROM Users WHERE RoleId=3  AND UserId=@UserId AND Password=@Password and (SiteVerification=1 OR FinancialVerification=1) AND IsActive=1


	IF @CertificationType is null and @CertificationStatusTu=100 AND @NcCountTu=3 AND 
	(SELECT COUNT(*) FROM FinancialAssistance where ZedId=@ZedId and  FinancialAssessorId=@UserId and VerificationStatus=2)>0
	BEGIN
			
			EXEC [SP_APP_TU_CHECK_LOGIN] @UserId, @Password, @ZedId
	END
	

	ELSE
	BEGIN

		--SELECT * FROM Users WHERE RoleId=3  AND UserId=@UserId AND Password=@Password and SiteVerification=1 AND IsActive=1  --type of assessor to be load
		
		SELECT TOP 1 @CertificationStatus=CertificationStatus,@CertificationType=Certification,@NcCount=NcCount FROM MsmeCertifications where ZedId=@ZedId ORDER BY ID DESC

		IF @CertificationType is null and @CertificationStatusTu=100 AND @NcCountTu=3 AND 
	    (SELECT COUNT(*) FROM FinancialAssistance where ZedId=@ZedId and CertificationType=@CertificationTypeTu AND FinancialAssessorId=@UserId and VerificationStatus>2)>0
		BEGIN

		SELECT NULL AssessmentDate, NULL EnterpriseName, NULL Sector, NULL UnitAddress, NULL Email, NULL PhoneNumber, NULL UserType, 20 CertificationStatus,
		NULL LeadAssessorId, NULL LeadAssessorName, NULL CoAssessorId, NULL CoAssessorName, NULL ZedId, 
		NULL CertificationType, NULL AuditsConducted, NULL DomesticCustomers, NULL InternationalCustomers,
		NULL RawMaterialImported, NULL OutsourcedProcesses, NULL EnergySources, 4 Milestone, NULL BdsFromDate, NULL BdsToDate, NULL HapFromDate, NULL HapToDate, 
		NULL PAddress, NULL PDistrictName, NULL PStateName, NULL PPincode		

		END
		ELSE
		BEGIN
			SELECT FORMAT(AssessmentDate,'MM/dd/yyyy hh:mm:ss tt') AssessmentDate, B.EnterpriseName, TwoDigitActivity Sector, concat(E.PAddress,E.PDistrictName,E.PStateName,e.PPin) UnitAddress, 
				B.EmailId Email, E.MobileNo PhoneNumber,
				case when SiteAssessorId=@UserId then 1 when AC.CoAssessorId=@UserId then 2 end as UserType, CertificationStatus,
				SiteAssessorId LeadAssessorId, U.UserName LeadAssessorName,AC.CoAssessorId, US.UserName CoAssessorName, B.ZedId, M.Certification CertificationType,
				M.AuditsConducted, M.DomesticCustomers, M.InternationalCustomers, M.RawMaterialImported, M.OutsourcedProcesses, M.EnergySources,
				@NcCount as Milestone,
				BdsFromDate,BdsToDate,HapFromDate,HapToDate,
				E.PAddress,E.PDistrictName,E.PStateName,e.PPin as PPincode

			FROM MsmeBasicInformation B 
			inner join Msme E on (B.ZedId=E.ZedId)
			inner join MsmeCertifications M on (B.ZedId=m.ZedId) 
			left join Users U on (M.SiteAssessorId=U.UserId)
			left join AllotedCoAssessors AC on (M.ZedId=AC.ZedId and M.Certification=AC.Certification and M.NcCount=AC.NcCount)
			left join Users US on (AC.CoAssessorId=US.UserId)
			WHERE M.ZedId=@ZedId and M.Certification=@CertificationType and M.NcCount=@NcCount
				and (SiteAssessorId=@UserId or AC.CoAssessorId=@UserId) and CertificationStatus>=8	
		END



		IF @CertificationStatus = 8
			SELECT * FROM MsmeSections where ZedId=@ZedId and SectionType=@CertificationType and NcCount=@NcCount order by cast(SectionId as int)
		ELSE 
			SELECT * FROM MsmeSections where ZedId=@ZedId and SectionType=@CertificationType and NcCount=@NcCount and AssessorId=@UserId order by cast(SectionId as int)

		SELECT * FROM msmeProducts WHERE ZedId=@ZedId and Certification=@CertificationType

		SELECT Id, ZedId, Certification, RawMaterialName, Percentage RawMaterialPercentage, CountryName FROM MsmeRawMaterials WHERE ZedId=@ZedId and Certification=@CertificationType

		IF @CertificationStatus = 9
		BEGIN

			select R.Id,R.ZedId,R.SectionType Certification,R.SectionCode,R.SectionName,R.QuestionCode,R.QuestionName,R.RequirementCode,R.RequirementName,
			R.OrderNo,R.SectionType,R.Conformance,R.AssessorRemarks,'MsmeRequirements' TableName,R.OpenedFlag
			, isnull(R1.Id,0) as PrevReqId,
			R1.SaConformance,R1.BaselineRemarks,R1.EstimatedTimeInDays,R1.HActionPlanRemarks,R1.IntConformance,R1.InterventionRemarks,R1.Intervention,
			R1.IsProposedActivityCompleted, R1.ProgressReviewRemarks
			from MsmeSections S 
			inner join MsmeRequirements R on (S.SectionCode=R.SectionCode and S.ZedId=R.ZedId and S.SectionType=R.SectionType and S.NcCount=R.NcCount)
			left join MsmeRequirements R1 on (R.RequirementId=R1.RequirementId AND S.SectionCode=R1.SectionCode and S.ZedId=R1.ZedId and S.SectionType=R1.SectionType and R1.NcCount=1 )
			where R.ZedId=@ZedId  and R.SectionType=@CertificationType and R.NcCount=@NcCount and AssessorId=@UserId order by cast(SectionId as int),cast(R.RequirementId as int)

			select R.Id,R.ZedId,R.SectionType Certification,R.SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,R.SectionType from MsmeSections S inner join MsmeOptions R on (S.SectionCode=R.SectionCode and S.ZedId=R.ZedId and S.SectionType=R.SectionType and S.NcCount=R.NcCount)
			where R.ZedId=@ZedId  and R.SectionType=@CertificationType and R.NcCount=@NcCount and AssessorId=@UserId order by cast(SectionId as int)

			select R.Id,R.ZedId,R.SectionType Certification,R.SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,R.SectionType from MsmeSections S inner join MsmeSubOptions R on (S.SectionCode=R.SectionCode and S.ZedId=R.ZedId and S.SectionType=R.SectionType and S.NcCount=R.NcCount)
			where R.ZedId=@ZedId  and R.SectionType=@CertificationType and R.NcCount=@NcCount and AssessorId=@UserId order by cast(SectionId as int)
		 
		END
		ELSE
		BEGIN
			select  NULL Id,NULL ZedId,NULL Certification,NULL SectionCode,NULL SectionName,NULL QuestionCode,NULL QuestionName,NULL RequirementCode,NULL RequirementName,NULL OrderNo,NULL SectionType,
			NULL Conformance,NULL AssessorRemarks,NULL TableName,NULL OpenedFlag 
			where 1=2

			select NULL Id,NULL ZedId,NULL Certification,NULL SectionCode,NULL QuestionCode,NULL OptionCode,NULL OptionName,NULL OptionImage,NULL RequirementCode,NULL SectionType 
			where 1=2

			select NULL Id,NULL ZedId,NULL Certification,NULL SectionCode,NULL QuestionCode,NULL OptionCode,NULL SubOptionCode,NULL SubOptionName,NULL RequirementCode,NULL SubOptionImage,NULL SectionType 
			where 1=2
		END



		DECLARE @LeadAssessor varchar(50) = NULL,
				@CoAssessor   varchar(50) = NULL,
				@True bit = 1,
				@False bit = 0

		SELECT @LeadAssessor=SiteAssessorId,@CoAssessor=CoAssessorId FROM MsmeCertifications WHERE ZedId=@ZedId and Certification=@CertificationType and NcCount=@NcCount

		SELECT 		
			CASE WHEN 
			(select count(*) from Meetings where zedid=@ZedId and certificationtype=@CertificationType and AssessorId=@LeadAssessor and MeetingType='Open Meeting' and NcCount=@NcCount)>0 THEN @True ELSE @False end as OpenMeetingSubmitted, 
		
			CASE WHEN
			(SELECT count(*) FROM SaPhotos WHERE ZedId=@ZedId and Certification=@CertificationType and AssessorId=@UserId and PhotoType='Selfie' and NcCount=@NcCount)>0 THEN @True ELSE @False end as SelfieSubmitted


		SELECT Id,RefId,ZedId,CertificationType,convert(int,RequirementId) RequirementId,BulletPoints,ReqType,NcCount
		from MsmeRequirementBullets where ZedId=@ZedId and CertificationType=@CertificationType and NcCount=1 order by Id
	END

END

GO
/****** Object:  StoredProcedure [dbo].[SP_APP_SA_CHECK_LOGIN_V2]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
--[SP_APP_SA_CHECK_LOGIN_V2] '<redacted>', '<redacted>', '<redacted>'
--[SP_APP_SA_CHECK_LOGIN_V2] '<redacted>', '<redacted>', '<redacted>'
CREATE PROCEDURE [dbo].[SP_APP_SA_CHECK_LOGIN_V2] --'<redacted>', '<redacted>', '<redacted>'
(
	@UserId varchar(50) = NULL,
	@Password varchar(50) = NULL,
	@ZedId varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	SET @UserId=replace(@UserId,' ','_')
	SET @ZedId=replace(@ZedId,' ','_')


	IF EXISTS (SELECT * FROM Users WHERE RoleId=3  AND UserId=@UserId AND Password=@Password and SiteVerification=1 AND IsActive=1)
	BEGIN
		
			-- Check if finalsubmit is completed
		 IF EXISTS (SELECT top 1 * FROM MsmeCertifications WHERE ZedId=@ZedId AND CertificationStatus in (8,9) AND (SiteAssessorId=@UserId OR CoAssessorId like '%'+@UserId+'%') order by Id desc)
			BEGIN
				SELECT *, '1' StatusCode, '' ErrorMessage  FROM Users WHERE RoleId=3  AND UserId=@UserId AND Password=@Password and SiteVerification=1 AND IsActive=1
		        EXEC [SP_APP_SA_CONSULTANCY_CHECK_LOGIN] @UserId, @Password, @ZedId
			END
		ELSE IF EXISTS (SELECT top 1 * FROM MsmeCertifications WHERE ZedId=@ZedId AND CertificationStatus>9 order by Id Desc)
			BEGIN				
				SELECT '0' AS StatusCode, concat('Handholding Closing Meeting Submitted for the ZEDID: ',@ZedId) AS ErrorMessage
			END
		ELSE
		BEGIN
			SELECT '0' AS StatusCode,  concat('Handholding Consultant not yet allocated for the ZEDID: ',@ZedId) AS ErrorMessage
		END
	END 
		


	ELSE IF EXISTS (SELECT * FROM Users WHERE RoleId=3 AND UserId=@UserId AND Password=@Password and FinancialVerification=1 AND IsActive=1)
	BEGIN
		
			-- Check if final submission is done from mobile app
		IF EXISTS (SELECT top 1 * FROM FinancialAssistance WHERE ZedId=@ZedId AND TechUpgradeStatus in (4,5,10) order by Id desc)
		BEGIN
			SELECT *, '1' StatusCode,'' ErrorMessage FROM Users WHERE RoleId=3  AND UserId=@UserId AND Password=@Password and FinancialVerification=1 AND IsActive=1
			EXEC [SP_APP_TU_CHECK_LOGIN] @UserId, @Password, @ZedId	
		END
		ELSE IF EXISTS (SELECT top 1 * FROM FinancialAssistance WHERE ZedId=@ZedId AND TechUpgradeStatus>5 order by Id desc)
			BEGIN
				SELECT '0' AS StatusCode, concat('Final submission done from the mobile app for the ZEDID: ',@ZedId) AS ErrorMessage
			END
		ELSE
		BEGIN
			SELECT '0' AS StatusCode,  concat('DFO not yet allocated for the ZEDID: ',@ZedId) AS ErrorMessage
		END
	END

	ELSE
	BEGIN
		
		SELECT '0' StatusCode, 'Invalid Credentials. Please check' AS ErrorMessage  
	END
	
END

GO
/****** Object:  StoredProcedure [dbo].[SP_APP_SA_CHECK_STATUS_old]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_APP_SA_CHECK_STATUS_old] --'<redacted>', '<redacted>', '<redacted>'
(
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL,
	@AssessorId varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	DECLARE @LeadAssessor varchar(50) = NULL,
			@CoAssessor   varchar(50) = NULL

			SELECT @LeadAssessor=SiteAssessorId,@CoAssessor=CoAssessorId FROM MsmeCertifications WHERE ZedId=@ZedId and Certification=@Certification

	--SELECT 
	--	1 SaStatus,
	--	CASE WHEN 
	--	(select count(*) from Meetings  where zedid=@ZedId and certificationtype=@Certification and AssessorId=@LeadAssessor and MeetingType='<redacted>')>0 THEN 1 ELSE 0 end as OpenMeetingSubmitted, 

	--	CASE WHEN
	--	(select  count(*) from MsmeEvidences E inner join MsmeSections S on (S.SectionCode=E.SectionCode and S.ZedId=E.ZedId and E.NcCount=0)
	--	left join MsmePhotos P on (E.EvidenceId=P.EvidenceId and E.ZedId=P.ZedId and E.NcCount=0)
	--	where E.zedid=@ZedId and E.sectiontype=@Certification and (IsAssessmentExcempted='<redacted>' OR IsAssessmentExcempted IS NULL) 
	--	and AssessorId=@LeadAssessor and P.EvidenceId is null)=0 THEN 1 ELSE 0 end as AllParametersSyncedByLead,

	--	CASE WHEN
	--	(select count(*) from MsmeEvidences E inner join MsmeSections S on (S.SectionCode=E.SectionCode and S.ZedId=E.ZedId and E.NcCount=0)
	--	left join MsmePhotos P on (E.EvidenceId=P.EvidenceId and E.ZedId=P.ZedId and E.NcCount=0)
	--	where E.zedid=@ZedId and E.sectiontype=@Certification and (IsAssessmentExcempted='<redacted>' OR IsAssessmentExcempted IS NULL) 
	--	and AssessorId=@CoAssessor and P.EvidenceId is null)=0 THEN 1 ELSE 0 end as AllParametersSyncedByCo,

	--	CASE WHEN
	--	(select count(*) from Meetings  where zedid=@ZedId and certificationtype=@Certification and AssessorId=@CoAssessor and MeetingType='<redacted>')>0 THEN 1 ELSE 0 end as FinalSubmissionDone,

	--	CASE WHEN
	--	(select count(*) from Meetings  where zedid=@ZedId and certificationtype=@Certification and AssessorId=@LeadAssessor and MeetingType='<redacted>')>0 THEN 1 ELSE 0 end as ClosingMeetingSubmitted,

	--	CASE WHEN
	--	(SELECT count(*) FROM MsmeCertifications WHERE ZedId=@ZedId and Certification=@Certification and SiteAssessorId=@AssessorId)>0 THEN 1 ELSE 0 end as LeadAssessor



	select 1 SaStatus, 
		1 OpenMeetingSubmitted, 
		1 AllParametersSyncedByLead, 
		1 AllParametersSyncedByCo,
		1 FinalSubmissionDone, 
		1 ClosingMeetingSubmitted,
		1 LeadAssessor

	from MsmeCertifications 
	where ZedId=@ZedId 
		and Certification=@Certification
	
END



