/****** Object:  StoredProcedure [dbo].[SP_APP_SA_CONSULTANCY_CHECK_LOGIN]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
--[SP_APP_SA_CHECK_LOGIN] '<redacted>', '<redacted>', '<redacted>'
CREATE PROCEDURE [dbo].[SP_APP_SA_CONSULTANCY_CHECK_LOGIN] --'<redacted>', '<redacted>', '<redacted>'
(
	@UserId varchar(50) = NULL,
	@Password varchar(50) = NULL,
	@ZedId varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	SET @UserId=replace(@UserId,' ','_')
	SET @ZedId=replace(@ZedId,' ','_')

	DECLARE @CertificationStatus int = NULL,
			@CertificationType varchar(50) = NULL,
			@NcCount int = NULL
	SELECT @CertificationStatus=CertificationStatus,@CertificationType=Certification,@NcCount=NcCount FROM MsmeCertifications where ZedId=@ZedId and  SiteAssessorId is not null and SaCertificateNo is null


	BEGIN

		IF @CertificationType is null
		BEGIN

		SELECT NULL AssessmentDate, NULL EnterpriseName, NULL Sector, NULL UnitAddress, NULL Email, NULL PhoneNumber, NULL UserType, 20 CertificationStatus,
		NULL LeadAssessorId, NULL LeadAssessorName, NULL CoAssessorId, NULL CoAssessorName, NULL ZedId, 
		NULL CertificationType, NULL AuditsConducted, NULL DomesticCustomers, NULL InternationalCustomers,
		NULL RawMaterialImported, NULL OutsourcedProcesses, NULL EnergySources, 4 Milestone, NULL BdsFromDate, NULL BdsToDate, NULL HapFromDate, NULL HapToDate, 
		NULL PAddress, NULL PDistrictName, NULL PStateName, NULL PPincode		

		END
		ELSE
		BEGIN
			SELECT FORMAT(AssessmentDate,'MM/dd/yyyy hh:mm:ss tt') AssessmentDate, PUnitName EnterpriseName, TwoDigitActivity Sector, concat(E.PAddress,E.PDistrictName,E.PStateName,e.PPin) UnitAddress, 
				B.EmailId Email, E.MobileNo PhoneNumber,
				case when SiteAssessorId=@UserId then 1 when AC.CoAssessorId=@UserId then 2 end as UserType, CertificationStatus,
				SiteAssessorId LeadAssessorId, U.UserName LeadAssessorName,AC.CoAssessorId, US.UserName CoAssessorName, B.ZedId, M.Certification CertificationType,
				M.AuditsConducted, M.DomesticCustomers, M.InternationalCustomers, M.RawMaterialImported, M.OutsourcedProcesses, M.EnergySources,
				@NcCount as Milestone,
				BdsFromDate,BdsToDate,HapFromDate,HapToDate,
				E.PAddress,E.PDistrictName,E.PStateName,e.PPin as PPincode

			FROM MsmeBasicInformation B 
			inner join Msme E on (B.ZedId=E.ZedId)
			inner join MsmeCertifications M on (B.ZedId=m.ZedId) 
			left join Users U on (M.SiteAssessorId=U.UserId)
			left join AllotedCoAssessors AC on (M.ZedId=AC.ZedId and M.Certification=AC.Certification and M.NcCount=AC.NcCount)
			left join Users US on (AC.CoAssessorId=US.UserId)
			WHERE M.ZedId=@ZedId and M.Certification=@CertificationType and M.NcCount=@NcCount
				and (SiteAssessorId=@UserId or AC.CoAssessorId=@UserId) and CertificationStatus>=8	
		END



		IF @CertificationStatus = 8
			SELECT * FROM MsmeSections where ZedId=@ZedId and SectionType=@CertificationType and NcCount=@NcCount order by cast(SectionId as int)
		ELSE 
			SELECT * FROM MsmeSections where ZedId=@ZedId and SectionType=@CertificationType and NcCount=@NcCount and AssessorId=@UserId order by cast(SectionId as int)

		SELECT * FROM msmeProducts WHERE ZedId=@ZedId and Certification=@CertificationType

		SELECT Id, ZedId, Certification, RawMaterialName, Percentage RawMaterialPercentage, CountryName FROM MsmeRawMaterials WHERE ZedId=@ZedId and Certification=@CertificationType

		IF @CertificationStatus = 9
		BEGIN

			select R.Id,R.ZedId,R.SectionType Certification,R.SectionCode,R.SectionName,R.QuestionCode,R.QuestionName,R.RequirementCode,R.RequirementName,
			R.OrderNo,R.SectionType,R.Conformance,R.AssessorRemarks,'MsmeRequirements' TableName,R.OpenedFlag
			, isnull(R1.Id,0) as PrevReqId,
			R1.SaConformance,R1.BaselineRemarks,R1.EstimatedTimeInDays,R1.HActionPlanRemarks,R1.IntConformance,R1.InterventionRemarks,R1.Intervention,
			R1.IsProposedActivityCompleted, R1.ProgressReviewRemarks
			from MsmeSections S 
			inner join MsmeRequirements R on (S.SectionCode=R.SectionCode and S.ZedId=R.ZedId and S.SectionType=R.SectionType and S.NcCount=R.NcCount)
			left join MsmeRequirements R1 on (R.RequirementId=R1.RequirementId AND S.SectionCode=R1.SectionCode and S.ZedId=R1.ZedId and S.SectionType=R1.SectionType and R1.NcCount=1 )
			where R.ZedId=@ZedId  and R.SectionType=@CertificationType and R.NcCount=@NcCount and AssessorId=@UserId order by cast(SectionId as int),cast(R.RequirementId as int)

			select R.Id,R.ZedId,R.SectionType Certification,R.SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,R.SectionType from MsmeSections S inner join MsmeOptions R on (S.SectionCode=R.SectionCode and S.ZedId=R.ZedId and S.SectionType=R.SectionType and S.NcCount=R.NcCount)
			where R.ZedId=@ZedId  and R.SectionType=@CertificationType and R.NcCount=@NcCount and AssessorId=@UserId order by cast(SectionId as int)

			select R.Id,R.ZedId,R.SectionType Certification,R.SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,R.SectionType from MsmeSections S inner join MsmeSubOptions R on (S.SectionCode=R.SectionCode and S.ZedId=R.ZedId and S.SectionType=R.SectionType and S.NcCount=R.NcCount)
			where R.ZedId=@ZedId  and R.SectionType=@CertificationType and R.NcCount=@NcCount and AssessorId=@UserId order by cast(SectionId as int)
		 
		END
		ELSE
		BEGIN
			select  NULL Id,NULL ZedId,NULL Certification,NULL SectionCode,NULL SectionName,NULL QuestionCode,NULL QuestionName,NULL RequirementCode,NULL RequirementName,NULL OrderNo,NULL SectionType,
			NULL Conformance,NULL AssessorRemarks,NULL TableName,NULL OpenedFlag 
			where 1=2

			select NULL Id,NULL ZedId,NULL Certification,NULL SectionCode,NULL QuestionCode,NULL OptionCode,NULL OptionName,NULL OptionImage,NULL RequirementCode,NULL SectionType 
			where 1=2

			select NULL Id,NULL ZedId,NULL Certification,NULL SectionCode,NULL QuestionCode,NULL OptionCode,NULL SubOptionCode,NULL SubOptionName,NULL RequirementCode,NULL SubOptionImage,NULL SectionType 
			where 1=2
		END



		DECLARE @LeadAssessor varchar(50) = NULL,
				@CoAssessor   varchar(50) = NULL,
				@True bit = 1,
				@False bit = 0

		SELECT @LeadAssessor=SiteAssessorId,@CoAssessor=CoAssessorId FROM MsmeCertifications WHERE ZedId=@ZedId and Certification=@CertificationType and NcCount=@NcCount

		SELECT 		
			CASE WHEN 
			(select count(*) from Meetings where zedid=@ZedId and certificationtype=@CertificationType and AssessorId=@LeadAssessor and MeetingType='Open Meeting' and NcCount=@NcCount)>0 THEN @True ELSE @False end as OpenMeetingSubmitted, 
		
			CASE WHEN
			(SELECT count(*) FROM SaPhotos WHERE ZedId=@ZedId and Certification=@CertificationType and AssessorId=@UserId and PhotoType='Selfie' and NcCount=@NcCount)>0 THEN @True ELSE @False end as SelfieSubmitted


		SELECT Id,RefId,ZedId,CertificationType,convert(int,RequirementId) RequirementId,BulletPoints,ReqType,NcCount
		from MsmeRequirementBullets where ZedId=@ZedId and CertificationType=@CertificationType and NcCount=1 order by Id
	END

END

GO
