CREATE PROCEDURE [dbo].[SP_APP_SA_CONSULTANCY_INSERT_BASIC_INFO] 
(
	 @RefId VARCHAR(50) = NULL
    ,@ZedId VARCHAR(50) = NULL
    ,@CertificationType VARCHAR(50) = NULL
	
	,@NumOfAccidents VARCHAR(50) = NULL
    ,@NumOfNearMisses VARCHAR(50) = NULL
    ,@ManHoursLast VARCHAR(50) = NULL
    ,@LostTimeInjuryFrequencyRate VARCHAR(50) = NULL
	
    ,@NumOfDeliveries VARCHAR(50) = NULL
    ,@NumOfDeliveriesOnTimeInFull VARCHAR(50) = NULL
	
    ,@MeanTimeToRepair VARCHAR(50) = NULL
    ,@MeanTimeBetweenFailure VARCHAR(50) = NULL
	
    ,@Electrical_Unit VARCHAR(50) = NULL
    ,@Electrical_TotalConsumptionPercentage VARCHAR(50) = NULL
	
    ,@Solar_Unit VARCHAR(50) = NULL
    ,@Solar_TotalConsumptionPercentage VARCHAR(50) = NULL
	
    ,@Wind_Unit VARCHAR(50) = NULL
    ,@Wind_TotalConsumptionPercentage VARCHAR(50) = NULL
	
    ,@FossilFuel_Unit VARCHAR(50) = NULL
    ,@FossilFuel_TotalConsumptionPercentage VARCHAR(50) = NULL
	
    ,@Gas_Unit VARCHAR(50) = NULL
    ,@Gas_TotalConsumptionPercentage VARCHAR(50) = NULL
	
    ,@Others_unit VARCHAR(50) = NULL
    ,@Others_TotalConsumptionPercentage VARCHAR(50) = NULL
	
    ,@TotalCost VARCHAR(50) = NULL
    ,@EnergyMgmtMeasuresTaken VARCHAR(50) = NULL
	
    ,@Cox VARCHAR(50) = NULL
    ,@Nox VARCHAR(50) = NULL
    ,@Sox VARCHAR(50) = NULL
    ,@SuspendedParticulateMaterial VARCHAR(50) = NULL
	
    ,@TotalSuspendedSolid VARCHAR(50) = NULL
    ,@BiochemicalOxygenDemand VARCHAR(50) = NULL
    
    ,@SolidWaste VARCHAR(50) = NULL
    ,@PlasticWaste VARCHAR(50) = NULL
    ,@EWaste VARCHAR(50) = NULL
    ,@HazardousWaste VARCHAR(50) = NULL
	
    ,@NoiseLevel VARCHAR(50) = NULL
    ,@EnviMgmtMeasuresTaken VARCHAR(50) = NULL
	
    ,@EmployeesEngagedInActivities VARCHAR(50) = NULL
    ,@NoOfSuggestions VARCHAR(50) = NULL
    ,@HrmMeasuresTaken VARCHAR(50) = NULL
	
    ,@Defects VARCHAR(50) = NULL
    ,@Rework VARCHAR(50) = NULL
    ,@CustomerRejections VARCHAR(50) = NULL
    ,@NumberOfCustomerComplaints VARCHAR(50) = NULL
    ,@NumberOfComplaintsResolved VARCHAR(50) = NULL
    ,@CustomerSatisfactionLevel VARCHAR(50) = NULL
    ,@CostOfPoorQuality VARCHAR(50) = NULL
	
    ,@Water VARCHAR(50) = NULL
    ,@Minerals VARCHAR(50) = NULL
    ,@Wood VARCHAR(50) = NULL
    ,@Others VARCHAR(50) = NULL
    
    ,@WaterRecycling VARCHAR(50) = NULL
    ,@WaterReuse VARCHAR(50) = NULL
    ,@RainWaterHarvesting VARCHAR(50) = NULL
    ,@NoOfTreePlanted VARCHAR(50) = NULL
    ,@NrmMeasuresTaken VARCHAR(50) = NULL
	
    ,@Turnover VARCHAR(50) = NULL
    ,@GrossProfit VARCHAR(50) = NULL
)
AS
BEGIN

	DECLARE @NcCount int = NULL
	SELECT @NcCount=NcCount FROM MsmeCertifications WHERE ZedId=@ZedId and Certification=@CertificationType and  SiteAssessorId is not null and SaCertificateNo is null
	

	DELETE FROM ConsultancyBasicInformation WHERE ZedId=@ZedId AND CertificationType=@CertificationType AND NcCount=@NcCount

	INSERT INTO ConsultancyBasicInformation (
		RefId, ZedId, CertificationType,NcCount, NumOfAccedents, NumOfNearMisses, ManHoursLast, LosttimeInjuryfreqRate, 
		NumOfDeliveries, NumOfDeliveriesOntimeFull,	MeanTimeToRepair, MeanTimeBetweenFailure, ElectriUnit, ElectriTotConsumpPer, SolarUnit, SolarTotConsumpPer,
		WindUnit, WindTotConsumpPer, FossilUnit, FossilTotConsumpPer, GasUnit, GasTotConsumpPer, OthersUnit, OthersTotConsumpPer, TotalCost, EnergyMgmtMeasuresTaken,
		Cox, Nox, Sox, SuspPertiMaterial, TotSuspenSolid, BioChemOxyDemand, SolidWaste, PlasticWaste, Ewaste, hazardWaste, NoiseLevel, EnviMgmtMeasuresTaken,
		EmpEngagedInActivities, NumOfSuggestions, HrmMeasuresTaken, Defects, ReWork, CustRejections, NumOfCustComplaints, NumOfComplaintsResolved, CustSatisLevel,
		CostOfPoorQuality, Water, Minarals, Wood, NrmOthers, WaterRecycling, Waterreuse, RainWaterHarvest, NumofTreesPlanted, NrmMeasuresTaken, TurnOver, GrossProfit
	)

	VALUES(
		@RefId, @ZedId, @CertificationType,@NcCount, @NumOfAccidents, @NumOfNearMisses, @ManHoursLast, @LostTimeInjuryFrequencyRate, @NumOfDeliveries,
		@NumOfDeliveriesOnTimeInFull, @MeanTimeToRepair, @MeanTimeBetweenFailure, @Electrical_Unit, @Electrical_TotalConsumptionPercentage, @Solar_Unit,
		@Solar_TotalConsumptionPercentage, @Wind_Unit, @Wind_TotalConsumptionPercentage, @FossilFuel_Unit, @FossilFuel_TotalConsumptionPercentage,
		@Gas_Unit, @Gas_TotalConsumptionPercentage, @Others_unit, @Others_TotalConsumptionPercentage, @TotalCost,
		@EnergyMgmtMeasuresTaken, @Cox, @Nox, @Sox, @SuspendedParticulateMaterial, @TotalSuspendedSolid, @BiochemicalOxygenDemand,
		@SolidWaste, @PlasticWaste, @EWaste, @HazardousWaste, @NoiseLevel, @EnviMgmtMeasuresTaken, @EmployeesEngagedInActivities,
		@NoOfSuggestions, @HrmMeasuresTaken, @Defects, @Rework, @CustomerRejections, @NumberOfCustomerComplaints,
		@NumberOfComplaintsResolved, @CustomerSatisfactionLevel, @CostOfPoorQuality	, @Water, @Minerals, @Wood, @Others,  
		@WaterRecycling, @WaterReuse, @RainWaterHarvesting, @NoOfTreePlanted, @NrmMeasuresTaken	, @Turnover, @GrossProfit
	)
		

		
	
END
