-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================

CREATE PROCEDURE [dbo].[SP_APP_SA_CONSULTANCY_TRAINING_INFO] 
(
	@RefId varchar(50) = NULL,
	@ZedId varchar(50) = NULL,
	@CertificationType varchar(50) = NULL,
	@TrainingTopic varchar(500) = NULL,
	@TrainingDate varchar(500) = NULL,	
	@TrainingTime varchar(50) = NULL,	
	@Remarks varchar(2000) = NULL,
	@TrainingType varchar(50) = NULL,
	@AssessorId varchar(50) = NULL,
	@TrainingPhotos DynamicPhotoList2	READONLY
)
AS
BEGIN
	
	SET NOCOUNT ON;

	DECLARE @NcCount int = NULL
	SELECT @NcCount=NcCount FROM MsmeCertifications WHERE ZedId=@ZedId and Certification=@CertificationType and  SiteAssessorId is not null and SaCertificateNo is null

	DELETE FROM TrainingInfo where ZedId=@ZedId and CertificationType=@CertificationType and TrainingType=@TrainingType and AssessorId=@AssessorId and NcCount=@NcCount
	
	INSERT INTO TrainingInfo (RefId, ZedId, CertificationType, TrainingType, TrainingTopic, TrainingDate, TrainingTime, Remarks, NcCount,AssessorId)
	VALUES (@RefId, @ZedId, @CertificationType, @TrainingType, @TrainingTopic, @TrainingDate, @TrainingTime, @Remarks, @NcCount,@AssessorId)



	DELETE FROM TrainingPhotos where ZedId=@ZedId and Certification=@CertificationType and PhotoType=@TrainingType and AssessorId=@AssessorId and NcCount=@NcCount

	INSERT INTO TrainingPhotos (ZedId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoExtension,NcCount,AssessorId)
	SELECT @ZedId, @CertificationType, @TrainingType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoType, @NcCount,@AssessorId FROM @TrainingPhotos

	


END

	
	
	
