/****** Object:  StoredProcedure [dbo].[SP_APP_SA_SAVE_PARAMETER]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_APP_SA_SAVE_PARAMETER] 
(
	@ZedId VarChar(50)				= NULL,
	@AssessorId VarChar(50)			= NULL,
	@ParameterId VarChar(50)		= NULL,
	@ParameterCode VarChar(50)		= NULL,
	@CertificationType VarChar(50)	= NULL,
	@Phototype VarChar(50)			= NULL,
			
	@PhotoList	DynamicPhotoList2	READONLY,
	@RequirementsList DynamicRequirementsList1 READONLY,
	@BulletList DynamicParticipants  READONLY
)
AS
BEGIN
	
	DECLARE @NcCount int = NULL
	SELECT @NcCount=NcCount FROM MsmeCertifications WHERE ZedId=@ZedId and Certification=@CertificationType and  SiteAssessorId is not null and SaCertificateNo is null


	IF @Phototype='BaselineDiagnostic'
	BEGIN
		update M set M.SaConformance=replace(replace(R.Conformance,'True','Yes'),'False','No'),
			M.BaselineRemarks=R.AssessorRemarks,
			BaselineDate=getdate()
		from MsmeRequirements M 
		inner join @RequirementsList R on (M.Id=R.RequirementId) 
		where M.ZedId=@ZedId and M.SectionCode=@ParameterCode and M.SectionType=@CertificationType and NcCount=@NcCount


	END

	IF @Phototype='HandholdingActionPlan'
	BEGIN
		update M set M.EstimatedTimeInDays=R.Conformance,
			M.HActionPlanRemarks=R.AssessorRemarks,
			HActionPlanDate=getdate()
		from MsmeRequirements M 
		inner join @RequirementsList R on (M.Id=R.RequirementId) 
		where M.ZedId=@ZedId and M.SectionCode=@ParameterCode and M.SectionType=@CertificationType and NcCount=@NcCount

	END

	IF @Phototype='TechnologyIntervention'
	BEGIN
		update M set M.IntConformance=R.Conformance,
			M.InterventionRemarks=R.AssessorRemarks,
			InterventionDate=getdate(),
			Intervention=R.RequirementCode 
		from MsmeRequirements M 
		inner join @RequirementsList R on (M.Id=R.RequirementId) 
		where M.ZedId=@ZedId and M.SectionCode=@ParameterCode and M.SectionType=@CertificationType and NcCount=@NcCount

	END

	IF @Phototype='ProgressReview'
	BEGIN
		IF @NcCount=2
		BEGIN
			update M set M.IsProposedActivityCompleted=R.Conformance,
				M.ProgressReviewRemarks=R.AssessorRemarks,
				ProgressReviewDate=getdate() 
			from MsmeRequirements M 
			inner join MsmeRequirements J on (M.ZedId=J.ZedId and M.SectionCode=j.SectionCode and m.SectionType=J.SectionType and M.RequirementId=J.RequirementId and M.NcCount=1 and J.NcCount=2)
			inner join @RequirementsList R on (J.Id=R.RequirementId) 
			--inner join @RequirementsList R on (M.Id=R.RequirementId) 
			where M.ZedId=@ZedId and M.SectionCode=@ParameterCode and M.SectionType=@CertificationType and M.NcCount=1
		END
		ELSE
		BEGIN
			update M set M.IsProposedActivityCompleted2=R.Conformance,
				M.ProgressReviewRemarks2=R.AssessorRemarks,
				ProgressReviewDate2=getdate() 
			from MsmeRequirements M 
			inner join MsmeRequirements J on (M.ZedId=J.ZedId and M.SectionCode=j.SectionCode and m.SectionType=J.SectionType and M.RequirementId=J.RequirementId and M.NcCount=1 and J.NcCount=3)
			inner join @RequirementsList R on (J.Id=R.RequirementId) 
			--inner join @RequirementsList R on (M.Id=R.RequirementId) 
			where M.ZedId=@ZedId and M.SectionCode=@ParameterCode and M.SectionType=@CertificationType and M.NcCount=1
		END

		

	END


	DELETE from SaRequirementPhotos WHERE ZedId=@ZedId and Certification=@CertificationType and NcCount=@NcCount and RequirementId in (select PhotoType from @PhotoList) and PhotoType=@Phototype

	INSERT INTO SaRequirementPhotos(ZedId, RequirementId, Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, NcCount)
	SELECT @ZedId, Phototype, @CertificationType, @Phototype, PhotoId, Name, TimeStamp, Latitude, Longitude,@NcCount FROM @PhotoList


	IF EXISTS (SELECT * FROM @BulletList)
	BEGIN

		DELETE from MsmeRequirementBullets WHERE ZedId=@ZedId and CertificationType=@CertificationType and NcCount=@NcCount and RequirementId in (select Name from @BulletList) and ReqType=@Phototype

		INSERT INTO MsmeRequirementBullets (ZedId,RequirementId,BulletPoints,ReqType,CertificationType,NcCount)
		select @ZedId,Name,Designation,@PhotoType,@CertificationType, @NcCount from @BulletList 
	END
	
END
GO
