/****** Object:  StoredProcedure [dbo].[SP_APP_TU_CHECK_LOGIN]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_APP_TU_CHECK_LOGIN] --'<redacted>', '<redacted>', '<redacted>'
(
	@UserId varchar(50) = NULL,
	@Password varchar(50) = NULL,
	@ZedId varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	SET @UserId=replace(@UserId,' ','_')
	SET @ZedId=replace(@ZedId,' ','_')

	DECLARE @CertificationStatus int = NULL,
			@CertificationType varchar(50) = NULL
			--,NcCount int = NULL

	DECLARE @FinancialAssistanceId int = NULL
	DECLARE @CertId int = NULL

	SELECT @CertificationType=CertificationType, @FinancialAssistanceId=Id, @CertId=CertId FROM FinancialAssistance where ZedId=@ZedId and  FinancialAssessorId=@UserId and VerificationStatus=2


	--SELECT * FROM Users WHERE RoleId=3  AND UserId=@UserId AND Password=@Password and FinancialVerification=1 AND IsActive=1  --type of assessor to be load

	select top 1
	FORMAT(getdate(),'MM/dd/yyyy hh:mm:ss tt') AssessmentDate, PUnitName EnterpriseName, TwoDigitActivity Sector, concat(E.PAddress,E.PDistrictName,E.PStateName,e.PPin) UnitAddress, 
			B.EmailId Email, E.MobileNo PhoneNumber,
			1 as UserType, 2 CertificationStatus,
			FinancialAssessorId LeadAssessorId, U.UserName LeadAssessorName, NULL  CoAssessorId, NULL CoAssessorName, B.ZedId, M.CertificationType,
			0 AuditsConducted, null DomesticCustomers, null InternationalCustomers, null RawMaterialImported, null OutsourcedProcesses, null EnergySources,
			4 as Milestone,
			FORMAT(getdate(),'MM/dd/yyyy hh:mm:ss tt') BdsFromDate,FORMAT(getdate(),'MM/dd/yyyy hh:mm:ss tt') BdsToDate, FORMAT(getdate(),'MM/dd/yyyy hh:mm:ss tt') HapFromDate, FORMAT(getdate(),'MM/dd/yyyy hh:mm:ss tt') HapToDate,
			E.PAddress,E.PDistrictName,E.PStateName,e.PPin as PPincode
	from MsmeBasicInformation B 
	inner join Msme E on (B.ZedId=E.ZedId)
	inner join financialAssistance M on (B.ZedId=m.ZedId) 
	left join Users U on (M.FinancialAssessorId=U.UserId)
	WHERE M.ZedId=@ZedId and M.CertificationType=@CertificationType 
	and (FinancialAssessorId=@UserId) order by m.id desc



	SELECT * FROM MsmeSections S 	
	inner join FinancialAssistance C on (S.ZedId=C.ZedId and S.SectionType=C.CertificationType and S.SectionCode=C.CategoryOfCertificate) --and S.NcCount=C.NcCount)
	inner join Users U on (c.FinancialAssessorId=U.UserId) 
	WHERE SectionType=@CertificationType AND S.ZedId=@ZedId  
	ORDER BY cast(SectionCode as int), S.NcCount

	SELECT * FROM msmeProducts WHERE 1=2

	SELECT Id, ZedId, Certification, RawMaterialName, Percentage RawMaterialPercentage, CountryName FROM MsmeRawMaterials WHERE 1=2


	select R.Id,R.ZedId,R.SectionType Certification,R.SectionCode,R.SectionName,R.QuestionCode,R.QuestionName,R.RequirementCode,R.RequirementName,
	R.OrderNo,R.SectionType,R.Conformance,R.AssessorRemarks,'MsmeRequirements' TableName,R.OpenedFlag
	, isnull(R1.Id,0) as PrevReqId,
	R1.SaConformance,R1.BaselineRemarks,R1.EstimatedTimeInDays,R1.HActionPlanRemarks,R1.IntConformance,R1.InterventionRemarks,R1.Intervention,
	R1.IsProposedActivityCompleted, R1.ProgressReviewRemarks
	from MsmeSections S 
	inner join MsmeRequirements R on (S.SectionCode=R.SectionCode and S.ZedId=R.ZedId and S.SectionType=R.SectionType and S.NcCount=R.NcCount)
	inner join FinancialAssistance C on (S.ZedId=C.ZedId and S.SectionType=C.CertificationType and S.SectionCode=C.CategoryOfCertificate)
	left join MsmeRequirements R1 on (R.RequirementId=R1.RequirementId AND S.SectionCode=R1.SectionCode and S.ZedId=R1.ZedId and S.SectionType=R1.SectionType and R1.NcCount=1 )
	where R.ZedId=@ZedId  and R.SectionType=@CertificationType and R.NcCount=3 and AssessorId=@UserId order by cast(SectionId as int),cast(R.RequirementId as int)

	select R.Id,R.ZedId,R.SectionType Certification,R.SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,R.SectionType from MsmeSections S inner join MsmeOptions R on (S.SectionCode=R.SectionCode and S.ZedId=R.ZedId and S.SectionType=R.SectionType and S.NcCount=R.NcCount)
	inner join FinancialAssistance C on (S.ZedId=C.ZedId and S.SectionType=C.CertificationType and S.SectionCode=C.CategoryOfCertificate)
	where R.ZedId=@ZedId  and R.SectionType=@CertificationType and R.NcCount=3 and AssessorId=@UserId order by cast(SectionId as int)

	select R.Id,R.ZedId,R.SectionType Certification,R.SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,R.SectionType from MsmeSections S inner join MsmeSubOptions R on (S.SectionCode=R.SectionCode and S.ZedId=R.ZedId and S.SectionType=R.SectionType and S.NcCount=R.NcCount)
	inner join FinancialAssistance C on (S.ZedId=C.ZedId and S.SectionType=C.CertificationType and S.SectionCode=C.CategoryOfCertificate)
	where R.ZedId=@ZedId  and R.SectionType=@CertificationType and R.NcCount=3 and AssessorId=@UserId order by cast(SectionId as int)


	
	
	SELECT 
	CASE WHEN 
	(select count(*) from TuMeetings where zedid=@ZedId and certificationtype=@CertificationType AND FinancialAssistanceId=@FinancialAssistanceId and CertId=@CertId)>0 THEN convert(bit, 1) ELSE convert(bit, 0) end as OpenMeetingSubmitted, 
	convert(bit, 1) SelfieSubmitted

	SELECT *
	FROM MsmeRequirementBullets 
	WHERE CertificationType=@CertificationType AND ZedId=@ZedId  

	
END

GO
