CREATE PROC [dbo].[SP_ASSESSMENT_ACCEPT_UNIT_FOR_DA]
(
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL,
	@DesktopAssessorId varchar(100) = NULL
)
AS
BEGIN
	
	UPDATE MsmeCertifications
	SET  AcceptOrRejectDate=null, DesktopReasonForRejection=null
	where ZedId=@ZedId AND Certification=@Certification
	
	UPDATE MsmeCertifications
	SET DesktopAssessorId = @DesktopAssessorId, AcceptOrRejectDate=getdate()
	where ZedId=@ZedId AND Certification=@Certification

	insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
	values (@ZedId,concat('DA for ',@Certification, ' Alotted to Desktop Assessor ',@DesktopAssessorId),getdate(),@Certification,'DocVerifiAllot')

END



