/****** Object:  StoredProcedure [dbo].[SP_ASSESSMENT_ACCEPT_UNIT_FOR_SA]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_ASSESSMENT_ACCEPT_UNIT_FOR_SA]
(
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL,
	@SiteAssessorId varchar(100) = NULL,
	@AssessmentDate varchar(50) = NULL,
	@BdsFromDate varchar(50) = NULL,
	@BdsToDate varchar(50) = NULL,
	@HapFromDate varchar(50) = NULL,
	@HapToDate varchar(50) = NULL,
	@ModeOfAssessment varchar(100) = NULL,
	@CoAssessorId varchar(1000) = NULL,
	@TechnicalExperts varchar(1000) = NULL
)
AS
BEGIN

	IF @CoAssessorId=''
	BEGIN
		SET @CoAssessorId=NULL
	END

	IF @TechnicalExperts=''
	BEGIN
		SET @TechnicalExperts=NULL
	END

	DECLARE @NcCount int = NULL
	SELECT @NcCount=isnull(max(NcCount),0) FROM MsmeCertifications where ZedId=@ZedId and Certification= @Certification

	IF @NcCount>1
	BEGIN
		set @AssessmentDate=@BdsFromDate
	END
	ELSE
	BEGIN
		--set @AssessmentDate=case when @HapFromDate is null or @BdsFromDate<@HapFromDate then @BdsFromDate else @HapFromDate end
		set @AssessmentDate=@BdsFromDate
	END

	UPDATE MsmeCertifications
	SET SiteAssessorId = @SiteAssessorId,CoAssessorId = @CoAssessorId, TechExpert=@TechnicalExperts, AssessmentDate=@AssessmentDate, ModeOfAssessment=@ModeOfAssessment, CertificationStatus=8,
	BdsFromDate=@BdsFromDate, BdsToDate=@BdsToDate, HapFromDate=@HapFromDate, HapToDate=@HapToDate
	where ZedId=@ZedId AND Certification=@Certification and NcCount=@NcCount

	--INSERT INTO AllotedCoAssessors (ZedId,Certification,NcCount,CoAssessorId)
	--select @ZedId, @Certification, @NcCount, value from string_split(@CoAssessorId,'<redacted>')

		
		update AllotedCoAssessors set ZedId=concat(zedid,'_del') WHERE ZedId=@ZedId AND Certification=@Certification AND NcCount=@NcCount

		INSERT INTO AllotedCoAssessors (ZedId,Certification,NcCount,CoAssessorId)
		select @ZedId, @Certification, @NcCount, value from string_split(@CoAssessorId,',')

		update AllotedTechExperts set ZedId=concat(zedid,'_del') WHERE ZedId=@ZedId AND Certification=@Certification AND NcCount=@NcCount

		INSERT INTO AllotedTechExperts (ZedId,Certification,NcCount,TechExpertId)
		select @ZedId, @Certification, @NcCount, value from string_split(@TechnicalExperts,',')

	
	
	insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType,NcCount)
	values (@ZedId,concat('Scheduled on  ',@AssessmentDate),getdate(),@Certification,'ScheduledOn',@NcCount)

	insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType,NcCount)
	values (@ZedId,concat('Completed On  ',@AssessmentDate),getdate(),@Certification,'AllocationCompleted',@NcCount)

	IF @NcCount>1
	BEGIN
		insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType,NcCount)
		values (@ZedId,concat('PR ',@NcCount-1, ' Date: ',@BdsFromDate),getdate(),@Certification,'BdsScheduledOn',@NcCount)
	END
	ELSE 
	BEGIN
		insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType,NcCount)
		values (@ZedId,concat('BDS Start Date: ',@BdsFromDate),getdate(),@Certification,'BdsScheduledOn',@NcCount)
	END
	

	insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType,NcCount)
	values (@ZedId,concat('HAP Start Date: ',@HapFromDate),getdate(),@Certification,'HapScheduledOn',@NcCount)


	insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType,NcCount)
	values (@ZedId,concat('SA for ',@Certification, ' Alotted to',@SiteAssessorId,' and ',@CoAssessorId, ' and ',@TechnicalExperts ),getdate(),@Certification,NULL,@NcCount)





	--insert into MsmeEvidences(EvidenceId, ZedId,SectionCode,RequirementCode,EvidenceCode,SectionType,EvidenceName,NcCount,RequirementId)
	--select (next value for EvidenceIdSequence),M.ZedId,M.SectionCode,RequirementCode,concat('<redacted>',@NcCount),M.SectionType,
	--concat('<redacted>',@NcCount),@NcCount,RequirementId from MsmeRequirements M inner join  MsmeSections S on (M.ZedId=S.ZedId and M.SectionType=S.SectionType and M.SectionCode=S.SectionCode and M.NcCount=S.NcCount) 
	--where M.zedid=@ZedId  and M.NcCount=@NcCount and (IsAssessmentExcempted is null or IsAssessmentExcempted='<redacted>')
		
	IF @ModeOfAssessment='Remote Assessment'
		BEGIN
			update MsmeSections set AssessorId=@SiteAssessorId where ZedId=@ZedId and SectionType=@Certification and NcCount=0 and (IsAssessmentExcempted='No' or IsAssessmentExcempted is null)

			UPDATE MsmeCertifications SET  CertificationStatus=9 where ZedId=@ZedId AND Certification=@Certification

			INSERT INTO Meetings (ZedId,CertificationType,AssessorId,MeetingType)
			VALUES (@ZedId,@Certification,@SiteAssessorId,'Open Meeting')

			INSERT INTO Meetings (ZedId,CertificationType,AssessorId,MeetingType)
			VALUES (@ZedId,@Certification,@SiteAssessorId,'Close Meeting')

			insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			values (@ZedId,concat('Scheduled on  ',@AssessmentDate),getdate(),@Certification,'ScheduledOn')

		END

END



GO
/****** Object:  StoredProcedure [dbo].[SP_ASSESSMENT_AGENCIES_TO_ALLOT]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_ASSESSMENT_AGENCIES_TO_ALLOT] --'<redacted>'
(
	@ZedId varchar(50) = NULL
)
AS
BEGIN
	
	declare @UnitState int
	select @UnitState=StateId from Msme where ZedId=@ZedId

	SELECT UserId,UserName,DesktopVerification, SiteVerification, convert(bit,case when TuPreferredState=@UnitState then 1 else 0 end) as FinancialVerification from 
	(SELECT UserId, UserName,DesktopVerification, SiteVerification, FinancialVerification,TuPreferredState FROM Users WHERE RoleId=2 AND IsActive = 1 and UserId not in (select distinct UserId from AgencyUserStates where RoleId=2) 
	UNION
	select U.UserId,UserName,DesktopVerification, SiteVerification, FinancialVerification,TuPreferredState from AgencyUserStates A inner join Users U on (A.UserId=U.UserId) where A.RoleId=2 AND U.IsActive=1 AND States in (SELECT PStateName FROM Msme WHERE ZedId=@ZedId)) A

	INTERSECT

	SELECT UserId,UserName,DesktopVerification, SiteVerification, convert(bit,case when TuPreferredState=@UnitState then 1 else 0 end) as FinancialVerification from
	(SELECT UserId, UserName,DesktopVerification, SiteVerification, FinancialVerification, TuPreferredState FROM Users WHERE RoleId=2 AND IsActive = 1 and UserId not in (select distinct UserId from UserNicSectors where RoleId=2) 
	UNION
	select U.UserId,UserName,DesktopVerification, SiteVerification, FinancialVerification, TuPreferredState from UserNicSectors A inner join Users U on (A.UserId=U.UserId) where A.RoleId=2 AND U.IsActive=1 AND NicSectorCode in (SELECT SUBSTRING(TwoDigitActivity,1,2) FROM Msme WHERE ZedId=@ZedId))B
	order by UserName
END



GO
/****** Object:  StoredProcedure [dbo].[SP_ASSESSMENT_ALLOT_LIST]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
--[SP_ASSESSMENT_ALLOT_LIST] '<redacted>','<redacted>',null,null,'<redacted>'
CREATE PROCEDURE [dbo].[SP_ASSESSMENT_ALLOT_LIST] --'<redacted>','<redacted>','<redacted>','<redacted>','<redacted>'
(
	@UserId varchar(50) = NULL,
	@RoleId varchar(50) = NULL,
	@State varchar(50) = NULL,
	@CertificationType varchar(50) = NULL,
	@AllotmentType varchar(50) = NULL,
	@ZedId varchar(50) = NULL,
	@Status varchar(50) =null,
	@Gender varchar(50) = NULL,
	@MsmeSize varchar(50) = NULL,
	@PageNo int = 1,
	@NoOfRecords int = 25000,
	@Milestone int = 1

)
AS
BEGIN
	
	SET NOCOUNT ON;

	IF @State='' 
	SET @State = NULL

	IF @CertificationType='' 
	SET @CertificationType = NULL

	IF @Gender='' 
	SET @Gender = NULL

	IF @MsmeSize='' 
	SET @MsmeSize = NULL

	DECLARE @TimeDifference varchar(50) = NULL

	IF @RoleId = 7
	BEGIN
		SELECT 
		P.Id CertId,M.MsmeId, M.ZedId, M.StateId, M.StateName, M.DistrictId, M.DistrictName, M.OwnerName, M.EnterpriseName,
		M.OrganisationType, M.OrganisationTypeName, M.EnterpriseType, M.EnterpriseTypee, M.MobileNo, M.EmailId,
		M.ApplicationId, M.UamNumber, M.PFlat, M.PBuilding, M.PRoad, M.PArea, M.PCity, M.PAddress, M.PPin,
		M.PStateId, M.PStateName, M.PLgDistrictCode, M.PDistrictName, M.PPlantDetailId, M.Activity,
		M.TwoDigitActivity, M.FourDigitActivity, M.FiveDigitActivity, M.ActivityDetailId, M.PledgeEmailId,
		M.IsBronzePaymentDone, M.IsSilverPaymentDone, M.IsGoldPaymentDone, M.IsCouponUsed, M.PledgeCertificateNo,
		M.RegistrationType, M.IncorporationDate, M.WhetherProdCommenced, M.PlantIdNo, M.PUnitName, M.PUnitIdNo,
		M.CreatedDate, M.RegistrationFrom, M.FinancialAssistanceStatus, M.WashWebinarCertificateNo, M.WashCertificateNo, M.QrCodeNo,
		CONCAT(PAddress, ', ', PPin, ', ', PDistrictName, ', ', PStateName) UnitAddress, 
			P.Certification, P.CertificationBodyUserId,P.ReasonForRejection,P.DesktopReasonForRejection, P.ZedId, DesktopAssessorId,
			case when (P.DesktopAssessorId is null and DesktopAccepted is null and DATEDIFF(hour, AcceptOrRejectDate,GETDATE())>=72)
			or (P.DesktopAssessorId is not null and P.ReasonForRejection is not null and DesktopAccepted is null and DATEDIFF(hour, DesktopAcceptOrRejectDate,GETDATE())>=72)
			then 'Reallot' else NULL end as TimeDuration,DesktopAccepted,
			U.UserName AgencyName,SpocName,U.Email AgencyEmail,U.MobileNo AgencyMobileNo,U.Address AgencyAddress,
			M.OwnerName as UnitSpocName, M.EmailId as UnitSpocEmailId, M.MobileNo as UnitSpocMobileNo,
			ROW_NUMBER() OVER (order by p.Id desc) as RowNumber,NcStatus,CertificationStatus,NcCount,
			FORMAT(BdsFromDate, 'MMMM d, yyyy') BdsFromDate,FORMAT(BdsToDate, 'MMMM d, yyyy') BdsToDate,
			FORMAT(HapFromDate, 'MMMM d, yyyy') HapFromDate,FORMAT(HapToDate, 'MMMM d, yyyy') HapToDate

		FROM MsmeCertifications P INNER JOIN Msme M ON (P.ZedId=M.ZedId)
		LEFT JOIN Users U ON (P.CertificationBodyUserId=U.UserId)
		LEFT JOIN MsmeBasicInformation B on (M.ZedId=B.ZedId)
		WHERE P.ZedId=M.ZedId --AND Certification=ISNULL(@Certification,'<redacted>')
		AND (@ZedId IS NULL OR p.ZedId=@ZedId)
		AND CertificationStatus in (6) and IdDisabled IS NULL
		--AND DesktopAccepted IS NULL 
		AND (@State is null or M.StateId=@State) AND (@CertificationType IS NULL OR P.Certification=@CertificationType ) AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize) AND (@Gender IS NULL OR Gender=@Gender)
		AND (@AllotmentType is null or (@AllotmentType='ALLOT' and P.CertificationBodyUserId is null) or (@AllotmentType='REALLOT' and P.CertificationBodyUserId is not null))
		ORDER By MsmeId desc

		SELECT UserId, UserName FROM Users WHERE RoleId=2 AND IsActive = 1 ORDER BY UserName
	END
	ELSE IF @RoleId = 2
	BEGIN
		IF @AllotmentType = 'DA'
		BEGIN
			SELECT P.Id CertId,M.*, CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress, 
				P.Certification, P.DesktopAssessorId,P.ReasonForRejection,P.DesktopReasonForRejection, P.ZedId, DesktopAssessorId, NULL TimeDuration, DesktopAccepted,
			U.UserName AgencyName,U.SpocName,U.Email AgencyEmail,U.MobileNo AgencyMobileNo,U.Address AgencyAddress,
			UD.UserName DaAssessorName,UD.SpocName,UD.Email DaAssessorEmail,UD.MobileNo DaAssessorMobileNo,UD.Address DaAssessorAddress,
			M.OwnerName as UnitSpocName, M.EmailId as UnitSpocEmailId, M.MobileNo as UnitSpocMobileNo,
			ROW_NUMBER() OVER (order by p.Id desc) as RowNumber,NcStatus,CertificationStatus,NcCount,
			FORMAT(BdsFromDate, 'MMMM d, yyyy') BdsFromDate,FORMAT(BdsToDate, 'MMMM d, yyyy') BdsToDate,
			FORMAT(HapFromDate, 'MMMM d, yyyy') HapFromDate,FORMAT(HapToDate, 'MMMM d, yyyy') HapToDate

		FROM MsmeCertifications P INNER JOIN Msme M ON (P.ZedId=M.ZedId)
		LEFT JOIN Users U ON (P.CertificationBodyUserId=U.UserId)
		LEFT JOIN Users UD ON (P.DesktopAssessorId=UD.UserId)
		LEFT JOIN MsmeBasicInformation B on (M.ZedId=B.ZedId)
			WHERE P.ZedId=M.ZedId AND CertificationBodyUserId=@UserId AND P.ReasonForRejection is null AND DesktopAccepted IS NULL
			AND (@ZedId IS NULL OR p.ZedId=@ZedId)  and CertificationStatus<3 and IdDisabled IS NULL
			--AND Certification=ISNULL(@Certification,'<redacted>')
			AND (@State is null or M.StateId=@State) AND (@CertificationType  IS NULL OR P.Certification=@CertificationType ) AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize) AND (@Gender IS NULL OR Gender=@Gender)
			ORDER By P.Id desc

			SELECT UserId, UserName FROM Users WHERE RoleId=3 AND IsActive = 1 AND CREATEDBY=@UserId AND DesktopVerification=1  ORDER BY UserName

			SELECT UserId, UserName FROM Users WHERE RoleId=33 AND IsActive = 1 AND CREATEDBY=@UserId AND DesktopVerification=1  ORDER BY UserName
		END
		ELSE
		BEGIN

			WITH CoAssessorCTE AS (
			SELECT P.Id, value AS CoAssessorIdSplit
			FROM MsmeCertifications P
			CROSS APPLY STRING_SPLIT(P.CoAssessorId, ',')
		),
		TechExpertCTE AS (
			SELECT P.Id, value AS TechExpertIdSplit
			FROM MsmeCertifications P
			CROSS APPLY STRING_SPLIT(P.TechExpert, ',')
		)

			SELECT 
			P.Id CertId,M.MsmeId, M.ZedId, M.StateId, M.StateName, M.DistrictId, M.DistrictName, M.OwnerName, M.EnterpriseName,
			M.OrganisationType, M.OrganisationTypeName, M.EnterpriseType, M.EnterpriseTypee, M.MobileNo, M.EmailId,
			M.ApplicationId, M.UamNumber, M.PFlat, M.PBuilding, M.PRoad, M.PArea, M.PCity, M.PAddress, M.PPin,
			M.PStateId, M.PStateName, M.PLgDistrictCode, M.PDistrictName, M.PPlantDetailId, M.Activity,
			M.TwoDigitActivity, M.FourDigitActivity, M.FiveDigitActivity, M.ActivityDetailId, M.PledgeEmailId,
			M.IsBronzePaymentDone, M.IsSilverPaymentDone, M.IsGoldPaymentDone, M.IsCouponUsed, M.PledgeCertificateNo,
			M.RegistrationType, M.IncorporationDate, M.WhetherProdCommenced, M.PlantIdNo, M.PUnitName, M.PUnitIdNo,
			M.CreatedDate, M.RegistrationFrom, M.FinancialAssistanceStatus, M.WashWebinarCertificateNo, M.WashCertificateNo, M.QrCodeNo,
			CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress, 
				P.Certification, P.SiteAssessorId,P.CoAssessorId,P.CoAssessorId CoAssessors,P.TechExpert, P.TechExpert TechnicalExperts,
				P.ReasonForRejection,P.DesktopReasonForRejection, P.ZedId, DesktopAssessorId, NULL TimeDuration,
			U.UserName AgencyName,U.SpocName,U.Email AgencyEmail,U.MobileNo AgencyMobileNo,U.Address AgencyAddress,
			UD.UserName SaAssessorName,UD.SpocName,UD.Email SaAssessorEmail,UD.MobileNo SaAssessorMobileNo,UD.Address SaAssessorAddress,
			UC.UserName CoAssessorName,UC.SpocName,UC.Email CoAssessorEmail,UC.MobileNo CoAssessorMobileNo,UC.Address CoAssessorAddress,
			UT.UserName TechExpertName,UT.SpocName,UT.Email TechExpertEmail,UT.MobileNo TechExpertMobileNo,UT.Address TechExpertAddress,
			M.OwnerName as UnitSpocName, M.EmailId as UnitSpocEmailId, M.MobileNo as UnitSpocMobileNo,
			ROW_NUMBER() OVER (order by p.Id desc) as RowNumber,NcStatus,CertificationStatus,NcCount,
			FORMAT(BdsFromDate, 'MMMM d, yyyy') BdsFromDate,FORMAT(BdsToDate, 'MMMM d, yyyy') BdsToDate,
			FORMAT(HapFromDate, 'MMMM d, yyyy') HapFromDate,FORMAT(HapToDate, 'MMMM d, yyyy') HapToDate

		FROM MsmeCertifications P INNER JOIN Msme M ON (P.ZedId=M.ZedId)
		LEFT JOIN Users U ON (P.CertificationBodyUserId=U.UserId)
		LEFT JOIN Users UD ON (P.SiteAssessorId=UD.UserId)
		LEFT JOIN Users UC ON (P.CoAssessorId=UC.UserId)
		LEFT JOIN Users UT ON (P.TechExpert=UT.UserId)
		LEFT JOIN MsmeBasicInformation B on (M.ZedId=B.ZedId)
			WHERE P.ZedId=M.ZedId AND CertificationBodyUserId=@UserId AND Certification!='Bronze' --AND Certification=ISNULL(@Certification,'<redacted>')
			AND (@ZedId IS NULL OR p.ZedId=@ZedId) and CertificationStatus<9 and IdDisabled IS NULL
			AND (@State is null or M.StateId=@State) AND (@CertificationType  IS NULL OR P.Certification=@CertificationType ) AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize) AND (@Gender IS NULL OR Gender=@Gender)
			ORDER By P.Id desc

			SELECT UserId, UserName FROM Users WHERE RoleId=3 AND IsActive = 1 AND CREATEDBY=@UserId AND SiteVerification=1  ORDER BY UserName

			SELECT UserId, UserName FROM Users WHERE RoleId=33 AND IsActive = 1 AND CREATEDBY=@UserId AND SiteVerification=1  ORDER BY UserName

		END
	END
	ELSE IF @RoleId = 3
	BEGIN
		IF @AllotmentType = 'SA'
		BEGIN
			SELECT 
			P.Id CertId,M.MsmeId, M.ZedId, M.StateId, M.StateName, M.DistrictId, M.DistrictName, M.OwnerName, M.EnterpriseName,
			M.OrganisationType, M.OrganisationTypeName, M.EnterpriseType, M.EnterpriseTypee, M.MobileNo, M.EmailId,
			M.ApplicationId, M.UamNumber, M.PFlat, M.PBuilding, M.PRoad, M.PArea, M.PCity, M.PAddress, M.PPin,
			M.PStateId, M.PStateName, M.PLgDistrictCode, M.PDistrictName, M.PPlantDetailId, M.Activity,
			M.TwoDigitActivity, M.FourDigitActivity, M.FiveDigitActivity, M.ActivityDetailId, M.PledgeEmailId,
			M.IsBronzePaymentDone, M.IsSilverPaymentDone, M.IsGoldPaymentDone, M.IsCouponUsed, M.PledgeCertificateNo,
			M.RegistrationType, M.IncorporationDate, M.WhetherProdCommenced, M.PlantIdNo, M.PUnitName, M.PUnitIdNo,
			M.CreatedDate, M.RegistrationFrom, M.FinancialAssistanceStatus, M.WashWebinarCertificateNo, M.WashCertificateNo, M.QrCodeNo,
			CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress, P.Certification,DesktopAccepted,DesktopReasonForRejection,P.ZedId, DesktopAssessorId, NULL TimeDuration, DesktopAccepted,CertificationBodyUserId,ModeOfAssessment,
			M.OwnerName as UnitSpocName, M.EmailId as UnitSpocEmailId, M.MobileNo as UnitSpocMobileNo,
			ROW_NUMBER() OVER (order by P.CertificationStatusDate desc) as RowNumber,NcStatus,CertificationStatus,NcCount,
			FORMAT(BdsFromDate, 'MMMM d, yyyy') BdsFromDate,FORMAT(BdsToDate, 'MMMM d, yyyy') BdsToDate,
			FORMAT(HapFromDate, 'MMMM d, yyyy') HapFromDate,FORMAT(HapToDate, 'MMMM d, yyyy') HapToDate

			FROM MsmeCertifications P INNER JOIN Msme M ON (P.ZedId=M.ZedId)
			LEFT JOIN MsmeBasicInformation B on (M.ZedId=B.ZedId)
			WHERE P.ZedId=M.ZedId AND SiteAssessorId=@UserId and CertificationStatus in ('14','15') and IdDisabled IS NULL
			AND (@ZedId IS NULL OR p.ZedId=@ZedId)
			AND (@State is null or M.StateId=@State) AND (@CertificationType  IS NULL OR P.Certification=@CertificationType ) AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize) AND (@Gender IS NULL OR Gender=@Gender)
			ORDER By P.CertificationStatusDate desc
		END
		ELSE IF @AllotmentType = 'RA'
		BEGIN
			SELECT 
			P.Id CertId,M.MsmeId, M.ZedId, M.StateId, M.StateName, M.DistrictId, M.DistrictName, M.OwnerName, M.EnterpriseName,
			M.OrganisationType, M.OrganisationTypeName, M.EnterpriseType, M.EnterpriseTypee, M.MobileNo, M.EmailId,
			M.ApplicationId, M.UamNumber, M.PFlat, M.PBuilding, M.PRoad, M.PArea, M.PCity, M.PAddress, M.PPin,
			M.PStateId, M.PStateName, M.PLgDistrictCode, M.PDistrictName, M.PPlantDetailId, M.Activity,
			M.TwoDigitActivity, M.FourDigitActivity, M.FiveDigitActivity, M.ActivityDetailId, M.PledgeEmailId,
			M.IsBronzePaymentDone, M.IsSilverPaymentDone, M.IsGoldPaymentDone, M.IsCouponUsed, M.PledgeCertificateNo,
			M.RegistrationType, M.IncorporationDate, M.WhetherProdCommenced, M.PlantIdNo, M.PUnitName, M.PUnitIdNo,
			M.CreatedDate, M.RegistrationFrom, M.FinancialAssistanceStatus, M.WashWebinarCertificateNo, M.WashCertificateNo, M.QrCodeNo,
			CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress, P.Certification,DesktopAccepted,DesktopReasonForRejection,P.ZedId, DesktopAssessorId, NULL TimeDuration, DesktopAccepted,CertificationBodyUserId,ModeOfAssessment,FORMAT(AssessmentDate, 'MMMM dd, yyyy') AssessmentDate,
			U.UserName AgencyName,U.SpocName,U.Email AgencyEmail,U.MobileNo AgencyMobileNo,U.Address AgencyAddress,
			UD.UserName SaAssessorName,UD.SpocName,UD.Email SaAssessorEmail,UD.MobileNo SaAssessorMobileNo,UD.Address SaAssessorAddress,
			M.OwnerName as UnitSpocName, M.EmailId as UnitSpocEmailId, M.MobileNo as UnitSpocMobileNo,
			ROW_NUMBER() OVER (order by p.CertificationStatusDate desc) as RowNumber,NcStatus,CertificationStatus,NcCount,
			FORMAT(BdsFromDate, 'MMMM d, yyyy') BdsFromDate,FORMAT(BdsToDate, 'MMMM d, yyyy') BdsToDate,
			FORMAT(HapFromDate, 'MMMM d, yyyy') HapFromDate,FORMAT(HapToDate, 'MMMM d, yyyy') HapToDate

			FROM MsmeCertifications P INNER JOIN Msme M ON (P.ZedId=M.ZedId)
			LEFT JOIN Users U ON (P.CertificationBodyUserId=U.UserId)
			LEFT JOIN Users UD ON (P.SiteAssessorId=UD.UserId)
			LEFT JOIN MsmeBasicInformation B on (M.ZedId=B.ZedId)
			WHERE P.ZedId=M.ZedId AND (SiteAssessorId=@UserId OR CoAssessorId like '%'+@UserId+'%') --AND Certification=ISNULL(@Certification,'<redacted>')
			AND (@ZedId IS NULL OR p.ZedId=@ZedId) and ModeOfAssessment in ('Remote Assessment','Onsite Assessment') and CertificationStatus<15
			AND P.NcCount=@Milestone
			AND (@State is null or M.StateId=@State) AND (@CertificationType  IS NULL OR P.Certification=@CertificationType ) AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize) AND (@Gender IS NULL OR Gender=@Gender)
			ORDER By P.CertificationStatusDate desc
		END
		ELSE IF @AllotmentType = 'NC'
		BEGIN
			SELECT 
			P.Id CertId,M.MsmeId, M.ZedId, M.StateId, M.StateName, M.DistrictId, M.DistrictName, M.OwnerName, M.EnterpriseName,
			M.OrganisationType, M.OrganisationTypeName, M.EnterpriseType, M.EnterpriseTypee, M.MobileNo, M.EmailId,
			M.ApplicationId, M.UamNumber, M.PFlat, M.PBuilding, M.PRoad, M.PArea, M.PCity, M.PAddress, M.PPin,
			M.PStateId, M.PStateName, M.PLgDistrictCode, M.PDistrictName, M.PPlantDetailId, M.Activity,
			M.TwoDigitActivity, M.FourDigitActivity, M.FiveDigitActivity, M.ActivityDetailId, M.PledgeEmailId,
			M.IsBronzePaymentDone, M.IsSilverPaymentDone, M.IsGoldPaymentDone, M.IsCouponUsed, M.PledgeCertificateNo,
			M.RegistrationType, M.IncorporationDate, M.WhetherProdCommenced, M.PlantIdNo, M.PUnitName, M.PUnitIdNo,
			M.CreatedDate, M.RegistrationFrom, M.FinancialAssistanceStatus, M.WashWebinarCertificateNo, M.WashCertificateNo, M.QrCodeNo,
			CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress, P.Certification,DesktopAccepted,DesktopReasonForRejection,P.ZedId, DesktopAssessorId, NULL TimeDuration, DesktopAccepted,CertificationBodyUserId,ModeOfAssessment,
			U.UserName AgencyName,U.SpocName,U.Email AgencyEmail,U.MobileNo AgencyMobileNo,U.Address AgencyAddress,
			UD.UserName SaAssessorName,UD.SpocName,UD.Email SaAssessorEmail,UD.MobileNo SaAssessorMobileNo,UD.Address SaAssessorAddress,
			UC.UserName CoAssessorName,UC.SpocName,UC.Email CoAssessorEmail,UC.MobileNo CoAssessorMobileNo,UC.Address CoAssessorAddress,
			M.OwnerName as UnitSpocName, M.EmailId as UnitSpocEmailId, M.MobileNo as UnitSpocMobileNo,
			ROW_NUMBER() OVER (order by P.CertificationStatusDate desc) as RowNumber,NcStatus,CertificationStatus,NcCount

			FROM MsmeCertifications P INNER JOIN Msme M ON (P.ZedId=M.ZedId)
			LEFT JOIN Users U ON (P.CertificationBodyUserId=U.UserId)
			LEFT JOIN Users UD ON (P.SiteAssessorId=UD.UserId)
			LEFT JOIN Users UC ON (P.CoAssessorId=UC.UserId)
			LEFT JOIN MsmeBasicInformation B on (M.ZedId=B.ZedId)
			WHERE P.ZedId=M.ZedId AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId OR CoAssessorId=@UserId) --AND Certification=ISNULL(@Certification,'<redacted>')
			AND (@ZedId IS NULL OR p.ZedId=@ZedId) and CertificationStatus in ('4','14') and IdDisabled IS NULL
			AND (@State is null or M.StateId=@State) AND (@CertificationType  IS NULL OR P.Certification=@CertificationType ) AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize) AND (@Gender IS NULL OR Gender=@Gender)
			ORDER By p.CertificationStatusDate desc
		END
		ELSE
		BEGIN
			SELECT 
			P.Id CertId,M.MsmeId, M.ZedId, M.StateId, M.StateName, M.DistrictId, M.DistrictName, M.OwnerName, M.EnterpriseName,
			M.OrganisationType, M.OrganisationTypeName, M.EnterpriseType, M.EnterpriseTypee, M.MobileNo, M.EmailId,
			M.ApplicationId, M.UamNumber, M.PFlat, M.PBuilding, M.PRoad, M.PArea, M.PCity, M.PAddress, M.PPin,
			M.PStateId, M.PStateName, M.PLgDistrictCode, M.PDistrictName, M.PPlantDetailId, M.Activity,
			M.TwoDigitActivity, M.FourDigitActivity, M.FiveDigitActivity, M.ActivityDetailId, M.PledgeEmailId,
			M.IsBronzePaymentDone, M.IsSilverPaymentDone, M.IsGoldPaymentDone, M.IsCouponUsed, M.PledgeCertificateNo,
			M.RegistrationType, M.IncorporationDate, M.WhetherProdCommenced, M.PlantIdNo, M.PUnitName, M.PUnitIdNo,
			M.CreatedDate, M.RegistrationFrom, M.FinancialAssistanceStatus, M.WashWebinarCertificateNo, M.WashCertificateNo, M.QrCodeNo,
			CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress, P.Certification,DesktopAccepted,DesktopReasonForRejection,P.ZedId, DesktopAssessorId, NULL TimeDuration, DesktopAccepted,CertificationBodyUserId,ModeOfAssessment,
			U.UserName AgencyName,U.SpocName,U.Email AgencyEmail,U.MobileNo AgencyMobileNo,U.Address AgencyAddress,
			M.OwnerName as UnitSpocName, M.EmailId as UnitSpocEmailId, M.MobileNo as UnitSpocMobileNo,
			ROW_NUMBER() OVER (order by p.Id desc) as RowNumber,NcStatus,CertificationStatus,NcCount

			FROM MsmeCertifications P INNER JOIN Msme M ON (P.ZedId=M.ZedId)
			LEFT JOIN Users U ON (P.CertificationBodyUserId=U.UserId)
			LEFT JOIN Users UD ON (P.DesktopAssessorId=UD.UserId)
			LEFT JOIN MsmeBasicInformation B on (M.ZedId=B.ZedId)
			WHERE P.ZedId=M.ZedId AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) AND DesktopReasonForRejection IS NULL --AND Certification=ISNULL(@Certification,'<redacted>')
			AND (@ZedId IS NULL OR p.ZedId=@ZedId)
			AND CertificationStatus < 4 and IdDisabled IS NULL
			AND (@State is null or M.StateId=@State) AND (@CertificationType  IS NULL OR P.Certification=@CertificationType ) AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize) AND (@Gender IS NULL OR Gender=@Gender)
			ORDER By P.Id desc
		END
	END

END

	
