/****** Object:  StoredProcedure [dbo].[SP_ASSESSMENT_ALLOT_TO_AGENCY]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_ASSESSMENT_ALLOT_TO_AGENCY]
(
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL,
	@CertificationBodyUserId varchar(100) = NULL
)
AS
BEGIN

	DECLARE @NcCount int = NULL
	SELECT @NcCount=isnull(max(NcCount),0) FROM MsmeCertifications where ZedId=@ZedId and Certification= @Certification
	
	update MsmeHistory set ZedId=concat(ZedId,'_DEL') WHERE ZedId=@ZedId and CertificationType=@Certification and NcCount=@NcCount and StatusType='CoAlloted'

	UPDATE [MsmeCertifications] 
	SET CertificationBodyUserId=@CertificationBodyUserId,AcceptOrRejectDate=NULL,ReasonForRejection=NULL 
	where  ZedId=@ZedId AND Certification=@Certification and NcCount=@NcCount

	insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType,NcCount)
	values (@ZedId,concat('DA for ',@Certification, ' Alotted to Agency ',@CertificationBodyUserId),getdate(),@Certification,'CoAlloted',@NcCount)

END



