/****** Object:  StoredProcedure [dbo].[SP_ASSESSMENT_DA_AUTO_REJECT]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_ASSESSMENT_DA_AUTO_REJECT] 
(
	@ZedId VarChar(50)						= NULL,
	@CertificationType VarChar(50)			= NULL,
	@AssessorRemarks VarChar(5000)			= NULL
)
AS
BEGIN
	
	Declare @NcCount int  = NULL
	Declare @ErrorStatus bit = 0

	Declare @EvidenceId varchar(50) = NULL
	

	--Select @NcCount=NcCount from MsmeCertifications where ZedId=@ZedId AND Certification=@CertificationType

			
			insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			select ZedId,concat('Auto Rejected On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),Certification,'Certification auto Rejected due to NC closure time is exceeded' from MsmeCertifications where certificationstatus=4 and NcFinalClosureDt<GETDATE() and Certification='Bronze' 
			UPDATE MsmeCertifications set NcCount=6, CertificationStatus=7,CertificationStatusDate=getdate(),IsAutoReject=1 where certificationstatus=4 and NcFinalClosureDt<GETDATE() and Certification='Bronze'
			

			insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			select ZedId,concat('Auto Rejected On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),Certification,'Certification auto Rejected due to NC closure time is exceeded' from MsmeCertifications where certificationstatus=4 and NcFinalClosureDt<GETDATE() and Certification in ('Silver','Gold') 
			UPDATE MsmeCertifications set NcCount=6, CertificationStatus=17,CertificationStatusDate=getdate(),IsAutoReject=1 where certificationstatus=14 and NcFinalClosureDt<GETDATE() and Certification in ('Silver','Gold')


END
