/****** Object:  StoredProcedure [dbo].[SP_ASSESSMENT_DA_CONFIRM_FINAL_SUBMIT]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_ASSESSMENT_DA_CONFIRM_FINAL_SUBMIT] --'<redacted>','<redacted>'
(
	@ZedId VarChar(50)				= NULL,
	@CertificationType VarChar(50)	= NULL
)
AS
BEGIN

	Declare @NcCount int  = NULL

	Select @NcCount=NcCount from MsmeCertifications where ZedId=@ZedId AND Certification=@CertificationType

	IF
	(select count(*) from MsmePhotos where PhotoType='SiteExteriorPhotos' and Certification=@CertificationType and ZedId=@ZedId and IsVerified IS NULL and NcCount=@NcCount)>0
	select 0 AllowFinalSubmit, 'You may have missed assessment of one or more Exterior Photos. Please review.' ErrorMessage
	ELSE IF
	(select count(*) from MsmeProducts where Certification=@CertificationType and ZedId=@ZedId and IsVerified IS NULL and NcCount=@NcCount)>0
	select 0 AllowFinalSubmit, 'You may have missed assessment of one or more products. Please review.' ErrorMessage
	ELSE IF
	(select count(*) from MsmeRequirements where SectionType=@CertificationType and ZedId=@ZedId and Conformance IS NULL and NcCount=@NcCount)>0
	select 0 AllowFinalSubmit, 'You may have missed assessment of one or more parameters. Please review.' ErrorMessage
	ELSE IF
	(select count(*) from MsmeSections S inner join MsmeEvidences E on (S.SectionCode=E.SectionCode ) where E.zedid=@ZedId and S.zedid=@ZedId and ValidationRequired=1 and E.SectionType=s.SectionType and S.SectionType=@CertificationType and IsAssessmentExcempted IS NULL and S.NcCount=@NcCount)>0
	select 0 AllowFinalSubmit, 'You may have missed assessment of one or more Exemptions. Please review.' ErrorMessage

	ELSE 
	select 1 AllowFinalSubmit, '' ErrorMessage

	IF @NcCount>=5
	SELECT 0 RaisedForNc
	
	ELSE IF @CertificationType='Bronze' and (select count(*) from MsmePhotos where PhotoType='SiteExteriorPhotos' and Certification=@CertificationType and ZedId=@ZedId and IsVerified='No' and NcCount=@NcCount)>0
		SELECT 1 RaisedForNc

	ELSE IF @CertificationType='Bronze' and (select count(*) from MsmeProducts where Certification=@CertificationType and ZedId=@ZedId and IsVerified='No' and NcCount=@NcCount)>0
		SELECT 1 RaisedForNc
	
	ELSE IF @CertificationType='Bronze' and (select count(*) from MsmeRequirements where SectionType=@CertificationType and ZedId=@ZedId and Conformance='No' and NcCount=@NcCount)>0
		SELECT 1 RaisedForNc

	ELSE 
		SELECT 0 RaisedForNc
	

END
GO
/****** Object:  StoredProcedure [dbo].[SP_ASSESSMENT_DA_DETAILS]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
--[SP_ASSESSMENT_DA_DETAILS] '<redacted>','<redacted>','<redacted>','<redacted>'
--[SP_ASSESSMENT_DA_DETAILS] '<redacted>','<redacted>','<redacted>','<redacted>'
CREATE PROCEDURE [dbo].[SP_ASSESSMENT_DA_DETAILS] --'<redacted>','<redacted>','<redacted>','<redacted>','<redacted>'
(
	@UserId varchar(50) = NULL,
	@RoleId varchar(50) = NULL,
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL,
	@Milestone int = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	DECLARE @CurrentUrl varchar(100) = NULL,
	@ModeOfAssessment varchar(50) = NULL,
	@TargetCertification VARCHAR(50)

	select @TargetCertification=LastestCertification from MsmeBasicinformation where ZedId=@ZedId

	--IF @Certification='<redacted>'
	--BEGIN
	--	SET @TargetCertification='<redacted>';

	--	select @TargetCertification=LastestCertification from msmebasicinformation where zedid=@ZedId
	--END
	--ELSE IF @Certification='<redacted>'
	--BEGIN
	--	SET @TargetCertification='<redacted>';
	--END



	DECLARE @NcCount int = NULL
	SELECT @NcCount=isnull(max(NcCount),0) FROM MsmeCertifications where ZedId=@ZedId and Certification= @Certification

	IF(select count(*) from MsmeCertifications where zedid=@ZedId and Certification=@Certification and ((SiteAssessorId=@UserId and @RoleId=3) OR (DesktopAssessorId=@UserId and @RoleId=3) OR (CoAssessorId like '%'+@UserId+'%' and @RoleId=3) OR (CertificationBodyUserId=@UserId AND @RoleId=2) OR (@RoleId=10) OR (@RoleId=7) OR (@RoleId=8) OR (ZedId=@ZedId AND (@RoleId is null OR @RoleId=5))))=0
	BEGIN
		SET @ZedId='000'
	END

	SELECT @CurrentUrl=UrlName from UrlsMasterData
	SELECT @ModeOfAssessment=ModeOfAssessment from MsmeCertifications WHERE ZedId=@ZedId and Certification=@Certification

	SELECT C.Id, C.ZedId, C.Certification, M.EnterpriseName,M.PUnitName, UdyogAadharNo, CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) PlantAddress,
		CertificationBodyUserId,UB.UserName AgencyName,
		SiteAssessorId ,UL.UserName SiteAssessorName,CoAssessorId,UC.UserName CoAssessorName, C.CertificationStatus,SendBackStatus,IsAutoReject,
		
		UT.TechExpertName AS TechExpertName, 
    TechExpert,
		 (select top 1 AssessorRemarks from AssessorComments ASSC where NcCount=0 and ZedId=@ZedId and Assc.Certification=@Certification and AssessmentType='DA') AssessorRemarks,
		 (select top 1 AssessorRemarks from AssessorComments ASSC where NcCount=6 and ZedId=@ZedId and Assc.Certification=@Certification and AssessmentType='RJ') SendBackRemarks,
		 'MsmeCertifications' TableName, C.NcCount, FORMAT(CertificationStatusDate, 'MMMM d, yyyy') DaVerificationDate,
		 C.IsSaVerified,
		 (select top 1 SaAssessorRemarks from AssessorComments ASSC where NcCount=C.NcCount and ZedId=@ZedId and Assc.Certification=@Certification and AssessmentType='SA' order by id desc) SaAssessorRemarks,
		 C.CertificationBodyUserId, UB.UserName,
		 FORMAT(BdsFromDate, 'MMMM d, yyyy') BdsFromDate,FORMAT(BdsToDate, 'MMMM d, yyyy') BdsToDate,
		 FORMAT(HapFromDate, 'MMMM d, yyyy') HapFromDate,FORMAT(HapToDate, 'MMMM d, yyyy') HapToDate, ModeOfAssessment, 
		 LastestCertification, FORMAT(C.CertificationStatusDate, 'MMMM d, yyyy')  CertificationStatusDate,
		  
		 
		case when CoAssessorId like '%'+@UserId+'%' then 0 else 1 end as IsCoAssessorLogin,
		(select top 1 WebFinalSubmitStatus from AllotedCoAssessors where ZedId=@ZedId and Certification=@Certification and NcCount=C.NcCount and CoAssessorId=@UserId and NcCount=@NcCount order by id desc) WebFinalSubmitStatus


		FROM MsmeCertifications C 
		INNER JOIN Msme M ON (C.ZedId=M.ZedId)
		INNER JOIN MsmeBasicInformation B ON (M.ZedId=B.ZedId )
		LEFT JOIN Users UB ON (C.CertificationBodyUserId=UB.UserId)
		LEFT JOIN Users UL ON (C.SiteAssessorId=UL.UserId)
		LEFT JOIN Users UC ON (C.CoAssessorId=UC.UserId)
		-- Join to parse comma-separated TechExpert User IDs and aggregate Names
		OUTER APPLY (
			SELECT STRING_AGG(U_TE.UserName, ', ') AS TechExpertName
			FROM STRING_SPLIT(C.TechExpert, ',') s
			INNER JOIN Users U_TE ON LTRIM(RTRIM(s.value)) = U_TE.UserId
		) UT

	WHERE c.Certification=@Certification 
		AND C.ZedId=@ZedId
		order by NcCount 
	
	SELECT *,'MsmeProducts' TableName FROM MsmeProducts WHERE Certification=@Certification AND ZedId=@ZedId	AND NcCount=@NcCount

	--IF @ModeOfAssessment='<redacted>'
	--BEGIN
	--SELECT * FROM SaRawMaterials WHERE Certification=@Certification AND ZedId=@ZedId
	--END
	--ELSE
	--BEGIN
	--SELECT * FROM MsmeRawMaterials WHERE Certification=@Certification AND ZedId=@ZedId
	--END

	SELECT 'DA' ModeOfAssessment,Id,ZedId,Certification,RawMaterialName,Percentage,CountryName,NcCount FROM MsmeRawMaterials WHERE Certification=@Certification AND ZedId=@ZedId
	UNION
	SELECT 'SA' ModeOfAssessment,Id,ZedId,Certification,RawMaterialName,Percentage,CountryName,NcCount FROM SaRawMaterials WHERE Certification=@Certification AND ZedId=@ZedId


	IF (SELECT count(*) from MsmeCertifications where ZedId=@ZedId and Certification=@Certification and CoAssessorId like '%'+@UserId+'%')>0
	BEGIN
		SELECT row_number() over(order by  cast(SectionCode as int)) as SectionsOrder, s.Id,s.ZedId,SectionType Certification,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType,
		(select count(*) ValidationRequired from MsmeEvidences E where ZedId=@ZedId and SectionType=@Certification and validationrequired=1 and E.SectionCode=S.SectionCode group by sectioncode) ValidationRequired,
		IsAssessmentExcempted,'MsmeSections' TableName, OfiComments,
		--isnull(S.AssessorId,'<redacted>') AllotedAssessorId,UPPER(U.UserName) AllotedAssessorName,
		--case when C.SiteAssessorId=S.AssessorId then '<redacted>' when C.CoAssessorId like '<redacted>'+S.AssessorId+'<redacted>' then '<redacted>' end as AssessorRank,
		S.NcCount
		FROM MsmeSections S 
		--left join Users U on (S.AssessorId=U.UserId) 
		inner join MsmeCertifications C on (S.ZedId=C.ZedId and S.SectionType=C.Certification  and S.NcCount=C.NcCount)
		WHERE SectionType=@Certification AND s.ZedId=@ZedId and AssessorId=@UserId AND s.NcCount=@NcCount 
		ORDER BY cast(SectionCode as int)
	END
	ELSE
	BEGIN
		SELECT row_number() over(order by cast(SectionCode as int)) as SectionsOrder, s.Id,S.ZedId,SectionType Certification,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType,
		(select count(*) ValidationRequired from MsmeEvidences E where ZedId=@ZedId and SectionType=@Certification and validationrequired=1 and E.SectionCode=S.SectionCode group by sectioncode) ValidationRequired,
		IsAssessmentExcempted,'MsmeSections' TableName, OfiComments,
		--isnull(S.AssessorId,'<redacted>') AllotedAssessorId,UPPER(U.UserName) AllotedAssessorName,
		--case when C.SiteAssessorId=S.AssessorId then '<redacted>' when C.CoAssessorId like '<redacted>'+S.AssessorId+'<redacted>' then '<redacted>' end as AssessorRank,
		S.NcCount
		FROM MsmeSections S 
		--left join Users U on (S.AssessorId=U.UserId) 
		inner join MsmeCertifications C on (S.ZedId=C.ZedId and S.SectionType=C.Certification  and S.NcCount=C.NcCount)
		WHERE SectionType=@Certification AND S.ZedId=@ZedId AND S.NcCount=@NcCount  
		ORDER BY cast(SectionCode as int)
	END
	
	SELECT 'C_'+convert(varchar,Id) IdP, Id,ZedId,SectionType Certification,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode, RequirementId,RequirementName,OrderNo,SectionType,Conformance,AssessorRemarks,'MsmeRequirements' TableName,OpenedFlag, SaConformance,SaAssessorRemarks,FORMAT(UpdatedDate, 'MMMM dd, yyyy HH:mm tt') UpdatedDate,FORMAT(SaUpdatedDate, 'MMMM dd, yyyy HH:mm tt') SaUpdatedDate,
	EstimatedTimeInDays,Intervention,BaselineDate,InterventionDate,HActionPlanDate,
	BaselineRemarks,InterventionRemarks,HActionPlanRemarks,IntConformance, IsProposedActivityCompleted, ProgressReviewRemarks, ProgressReviewDate, IsProposedActivityCompleted2, ProgressReviewRemarks2, ProgressReviewDate2
	FROM MsmeRequirements WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=1 ORDER BY cast(SectionCode as int), cast(RequirementCode as int)
	
	SELECT 'C_'+convert(varchar,Id) IdP, Id,ZedId,SectionType Certification,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType FROM MsmeOptions WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=@NcCount ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(OptionCode as int)
	
	SELECT 'C_'+convert(varchar,Id) IdP, Id,ZedId,SectionType Certification,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType FROM MsmeSubOptions WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=@NcCount ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(OptionCode as int), cast(SubOptionCode as int)
	
	SELECT 'C_'+convert(varchar,Id) IdP, Id,ZedId,SectionType Certification,SectionCode,RequirementCode,EvidenceId,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired, IsVerified, SourceOfValidation, AssessorRemarks, 'MsmeEvidences' TableName, DocumentOpenedTime,FORMAT(SyncedDate, 'MMMM dd, yyyy HH:mm tt')  SyncedDate,FORMAT(SyncedDate, 'MMMM dd, yyyy HH:mm tt') GeneratedTime FROM MsmeEvidences WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=@NcCount ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(EvidenceCode as int)

		
	SELECT Id,ZedId,Certification,PhotoId,Name,CONVERT(varchar,TimeStamp,100) TimeStamp,Latitude,Longitude,PhotoType,EvidenceId,IsVerified,AssessorRemarks,FORMAT(UpdatedDate,  'MMMM dd, yyyy HH:mm tt') UpdatedDate,NcCount,PhotoExtension,RequirementId,FORMAT(CreatedDate, 'MMMM dd, yyyy HH:mm tt') CreatedDate, ProductId,
	'MsmePhotos' TableName,(SELECT count(*) DocumentOpenedTime from MsmePhotos WHERE Certification=@Certification AND ZedId=@ZedId AND PhotoType in ('SiteExteriorPhotos') AND NcCount=@NcCount and DocumentOpenedTime is null)  DocumentOpenedTime  FROM MsmePhotos 
	WHERE Certification=@Certification AND ZedId=@ZedId AND PhotoType in ('SiteExteriorPhotos','Selfie', 'ProductPhotos', 'ProductDescriptionPhotos') AND NcCount=@NcCount order by PhotosOrder

	--SELECT *,'<redacted>' TableName,CONCAT(@CurrentUrl,'<redacted>','<redacted>',AssessorId,'<redacted>') as PhotoPath  FROM SaPhotos WHERE Name in ('<redacted>','<redacted>') AND ZedId=@ZedId --AND Certification=@Certification
	
	-- Lat Longs
	IF @ModeOfAssessment='Remote Assessment'
	BEGIN
		SELECT TOP 1 Latitude, Longitude,Latitude SaLatitude, Longitude SaLongitude FROM 
		SaPhotos
		WHERE Certification=@Certification AND ZedId=@ZedId AND PhotoType='Open Meeting' AND NcCount=@NcCount
	END
	ELSE
	BEGIN

			--SELECT TOP 1 M.Latitude, M.Longitude,S.Latitude SaLatitude, S.Longitude SaLongitude, 0 NcCount FROM ZEDCS_V2_LIVE.DBO.MsmePhotos M 
			--left join ZEDCS_V2_LIVE.DBO.SaPhotos S on (M.ZedId=S.ZedId and M.Certification=S.Certification and S.NcCount=0 and S.Name='<redacted>')	
			--WHERE M.Certification=@Certification AND M.ZedId=@ZedId AND M.PhotoType='<redacted>' AND M.NcCount=0

			--UNION ALL

		SELECT TOP 1 Latitude, Longitude,Latitude SaLatitude, Longitude SaLongitude, NcCount FROM SaPhotos WHERE Certification=@Certification AND ZedId=@ZedId AND PhotoType='Open Meeting' AND NcCount=1
		UNION ALL
		SELECT TOP 1 Latitude, Longitude,Latitude SaLatitude, Longitude SaLongitude, NcCount FROM SaPhotos WHERE Certification=@Certification AND ZedId=@ZedId AND PhotoType='Open Meeting' AND NcCount=2
		UNION ALL
		SELECT TOP 1 Latitude, Longitude,Latitude SaLatitude, Longitude SaLongitude, NcCount FROM SaPhotos WHERE Certification=@Certification AND ZedId=@ZedId AND PhotoType='Open Meeting' AND NcCount=3
		order by NcCount
	END




	IF @Certification!='Bronze'
	BEGIN

		SELECT 
		Id,	ZedId,	Certification,	PhotoId,	Name,	TimeStamp,	Latitude,	Longitude,	PhotoType,	EvidenceId,IsVerified,	AssessorId,	AssessorRemarks,	UpdatedDate,	NcCount,	PhotoExtension,	RequirementId,	
		isnull(Photo,CONCAT(@CurrentUrl,'/mobileapi/','SA/SaPhotos/',@ZedId,'/',Name,'.jpg')) Photo,CreatedDate	
		,'SaPhotos' TableName
		FROM SaPhotos WHERE (name in ('Site Exterior Photo','Site Interior Photo') or (PhotoType='SiteExteriorPhotos')) and Certification=@Certification AND ZedId=@ZedId	AND NcCount=@NcCount

		SELECT *,'Meetings' TableName FROM Meetings WHERE MeetingType='Open Meeting' AND ZedId=@ZedId --AND Certification=@Certification
		SELECT *,'MeetingParticipants' TableName FROM MeetingParticipants WHERE MeetingType='Open Meeting' AND ZedId=@ZedId --AND Certification=@Certification
		SELECT *,'Meetings' TableName FROM Meetings WHERE MeetingType='Close Meeting' AND ZedId=@ZedId --AND Certification=@Certification
		SELECT *,'MeetingParticipants' TableName FROM MeetingParticipants WHERE MeetingType='Close Meeting' AND ZedId=@ZedId --AND Certification=@Certification

	
		SELECT *,'SaPhotos' TableName,CONCAT(@CurrentUrl,'/mobileapi/','SA/SaPhotos/',@ZedId,'/',AssessorId,'.jpg') as PhotoPath  FROM SaPhotos WHERE Name in ('Selfie on Site') AND ZedId=@ZedId AND Certification=@Certification
		union
		SELECT *,'SaPhotos' TableName,CONCAT(@CurrentUrl,'/mobileapi/','SA/SaPhotos/',@ZedId,'/Opening Meeting Photo.jpg') as PhotoPath  FROM SaPhotos WHERE Name in ('Opening Meeting Photo') AND ZedId=@ZedId AND Certification=@Certification
	
		SELECT *,'SaPhotos' TableName,CONCAT(@CurrentUrl,'/mobileapi/','SA/SaPhotos/',@ZedId,'/SiteTour/',PhotoId,'.jpg') as PhotoPath  FROM SaPhotos WHERE PhotoType='SiteTour' AND ZedId=@ZedId AND Certification=@Certification


		SELECT 
		Id,	ZedId,	Certification,	PhotoId,	Name,	TimeStamp,	Latitude,	Longitude,	PhotoType,	EvidenceId,IsVerified,	AssessorId,	AssessorRemarks,FORMAT(UpdatedDate,  'MMMM dd, yyyy HH:mm tt')	UpdatedDate,	NcCount,	PhotoExtension,	RequirementId, null RequirementCode, null SectionCode,	
		Photo,CreatedDate	
		,'SaPhotos' TableName
		FROM SaPhotos WHERE  (PhotoType='Evidence Photos') and Certification=@Certification AND ZedId=@ZedId	--AND NcCount=@NcCount
		union
		SELECT 
		S.Id,	S.ZedId,	S.Certification,	S.PhotoId,	S.Name,	S.TimeStamp,	S.Latitude,	S.Longitude,	S.PhotoType,	EvidenceId,IsVerified,	AssessorId,	S.AssessorRemarks,	S.UpdatedDate,	S.NcCount,	PhotoExtension,	M.RequirementId, M.RequirementCode, M.SectionCode,	
		case when S.PhotoType='Evidences' then isnull(S.Photo,CONCAT(@CurrentUrl,'/mobileapi/','SA/SaPhotos/',@ZedId,'/',@Certification,'/Evidences/',S.PhotoId,'.jpg')) else
		isnull(S.Photo,CONCAT(@CurrentUrl,'/mobileapi/','SA/SaPhotos/',@ZedId,'/SiteTour/',S.PhotoId,'.jpg')) end as Photo,S.CreatedDate	
		,'SaPhotos' TableName
		FROM SaPhotos S
		inner join SaRequirementPhotos R on (S.ZedId=R.ZedId and S.Certification=R.Certification and S.PhotoId=R.PhotoId)
		inner join MsmeRequirements M on (R.RequirementId=M.Id)
		WHERE  S.Certification=@Certification AND S.ZedId=@ZedId	--AND S.NcCount=@NcCount

		SELECT *,'SaPhotos' TableName,CONCAT(@CurrentUrl,'/mobileapi/','SA/SaPhotos/',@ZedId,'/Closing Meeting Photo.jpg') as PhotoPath  FROM SaPhotos WHERE Name in ('Closing Meeting Photo') AND ZedId=@ZedId AND Certification=@Certification

		IF @Certification='Gold'
		BEGIN
			select Id,	ZedId, Certification, ProductName, Exported, 
			CONCAT(@CurrentUrl,'/mobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/BasicInfo/',ProductPhoto) ProductPhoto,
			CONCAT(@CurrentUrl,'/mobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/BasicInfo/',ProductDescriptionPhoto) ProductDescriptionPhoto, 
			IsVerified, AssessorRemarks, UpdatedDate,	NcCount, MsmeRemarks, MsmeUpdatedDate, ProductOpenedTime, ProductDescOpenedTime,'SaProducts' TableName 
			from SaProducts where ZedId=@ZedId AND Certification=@Certification
		END
		ELSE
		BEGIN
			select *,'SaProducts' TableName from SaProducts where ZedId=@ZedId AND Certification=@Certification
		END

		--select *,'<redacted>' TableName from SaRawMaterials where ZedId=@ZedId AND Certification=@Certification
		------WE ARE USING THIS BELOW QUERY TO DISPLAY TO ATTENDANCE DETAILS-------------
	
--	SELECT 
--    A.ZedId,
--    A.Certification,
--    A.ConsultantId, -- Added to identify each assessor separately
--    A.MileStoneNo,
--    CONVERT(DATE, A.Timestamp) AS TimeStamps,
--    CONVERT(TIME, MAX(CASE WHEN A.AttendanceType = '<redacted>' THEN A.Timestamp END)) AS LoginTime,
--    CONVERT(TIME, MAX(CASE WHEN A.AttendanceType = '<redacted>' THEN A.Timestamp END)) AS LogoutTime,
--    MAX(CASE WHEN A.AttendanceType = '<redacted>' THEN A.PhotoId END) AS LoginPhotoId1,
--    MAX(CASE WHEN A.AttendanceType = '<redacted>' THEN A.PhotoId END) AS LogoutPhotoId1,
--    CONCAT(@CurrentUrl, '<redacted>', @ZedId, '<redacted>', A.Certification, '<redacted>', MAX(CASE WHEN A.AttendanceType = '<redacted>' THEN A.PhotoId END), '<redacted>') AS LoginPhotoId,
--    CONCAT(@CurrentUrl, '<redacted>', @ZedId, '<redacted>', A.Certification, '<redacted>', MAX(CASE WHEN A.AttendanceType = '<redacted>' THEN A.PhotoId END), '<redacted>') AS LogoutPhotoId,
--    DATEDIFF(MINUTE, MAX(CASE WHEN A.AttendanceType = '<redacted>' THEN A.Timestamp END), MAX(CASE WHEN A.AttendanceType = '<redacted>' THEN A.Timestamp END)) / 60 AS NoOfHours,
--    DATEDIFF(MINUTE, MAX(CASE WHEN A.AttendanceType = '<redacted>' THEN A.Timestamp END), MAX(CASE WHEN A.AttendanceType = '<redacted>' THEN A.Timestamp END)) % 60 AS NoOfMinutes,
--    DATEDIFF(DAY, CONVERT(DATE, C.AssessmentDate), CONVERT(DATE, A.Timestamp)) + 1 AS RowNumber
--FROM ConsultantDailyAttendance A 
--INNER JOIN MsmeCertifications C 
--    ON (A.ZedId = C.ZedId 
--    AND A.Certification = C.Certification 
--    AND A.MileStoneNo = C.NcCount) 
--WHERE A.ZedId = @ZedId 
--  AND A.Certification = @Certification
--GROUP BY 
--    A.ZedId,
--    A.Certification,
--    A.ConsultantId, -- Crucial: This prevents merging Lead and Co-Assessor records
--    A.MileStoneNo,
--    CONVERT(DATE, A.Timestamp),
--    C.AssessmentDate
--	order by ConsultantId,milestoneNo,CONVERT(DATE, A.Timestamp)


------WE ARE USING THIS BELOW QUERY TO DISPLAY ATTENDANCE DETAILS-------------
	;WITH DailyCounts AS (
		SELECT 
			ZedId, 
			Certification, 
			ConsultantId,
			MileStoneNo,
			CONVERT(DATE, CONVERT(DATETIME, Timestamp)) AS AttendanceDate,
			SUM(CASE WHEN AttendanceType = 'LOGIN' THEN 1 ELSE 0 END) AS TotalLogins,
			SUM(CASE WHEN AttendanceType = 'LOGOUT' THEN 1 ELSE 0 END) AS TotalLogouts
		FROM ConsultantDailyAttendance
		WHERE ZedId = @ZedId AND Certification = @Certification
		GROUP BY ZedId, Certification, ConsultantId, MileStoneNo, CONVERT(DATE, CONVERT(DATETIME, Timestamp))
	),
	LoginRecords AS (
		SELECT 
			A.ZedId,
			A.Certification,
			A.ConsultantId,
			A.MileStoneNo,
			CONVERT(DATE, CONVERT(DATETIME, A.Timestamp)) AS AttendanceDate,
			CONVERT(DATETIME, A.Timestamp) AS LoginTimestamp,
			A.PhotoId AS LoginPhotoId,
			ROW_NUMBER() OVER (
				PARTITION BY A.ZedId, A.Certification, A.ConsultantId, A.MileStoneNo, CONVERT(DATE, CONVERT(DATETIME, A.Timestamp))
				ORDER BY CONVERT(DATETIME, A.Timestamp)
			) AS LoginSeq,
			DC.TotalLogins,
			DC.TotalLogouts
		FROM ConsultantDailyAttendance A
		INNER JOIN DailyCounts DC ON 
			A.ZedId = DC.ZedId AND 
			A.Certification = DC.Certification AND 
			A.ConsultantId = DC.ConsultantId AND
			A.MileStoneNo = DC.MileStoneNo AND
			CONVERT(DATE, CONVERT(DATETIME, A.Timestamp)) = DC.AttendanceDate
		WHERE A.AttendanceType = 'LOGIN'
		  AND A.ZedId = @ZedId AND A.Certification = @Certification
	),
	LogoutRecords AS (
		SELECT 
			A.ZedId,
			A.Certification,
			A.ConsultantId,
			A.MileStoneNo,
			CONVERT(DATE, CONVERT(DATETIME, A.Timestamp)) AS AttendanceDate,
			CONVERT(DATETIME, A.Timestamp) AS LogoutTimestamp,
			A.PhotoId AS LogoutPhotoId,
			ROW_NUMBER() OVER (
				PARTITION BY A.ZedId, A.Certification, A.ConsultantId, A.MileStoneNo, CONVERT(DATE, CONVERT(DATETIME, A.Timestamp))
				ORDER BY CONVERT(DATETIME, A.Timestamp)
			) AS LogoutSeq,
			DC.TotalLogins,
			DC.TotalLogouts
		FROM ConsultantDailyAttendance A
		INNER JOIN DailyCounts DC ON 
			A.ZedId = DC.ZedId AND 
			A.Certification = DC.Certification AND 
			A.ConsultantId = DC.ConsultantId AND
			A.MileStoneNo = DC.MileStoneNo AND
			CONVERT(DATE, CONVERT(DATETIME, A.Timestamp)) = DC.AttendanceDate
		WHERE A.AttendanceType = 'LOGOUT'
		  AND A.ZedId = @ZedId AND A.Certification = @Certification
	),
	Sessions AS (
		SELECT
			COALESCE(L.ZedId, O.ZedId) AS ZedId,
			COALESCE(L.Certification, O.Certification) AS Certification,
			COALESCE(L.ConsultantId, O.ConsultantId) AS ConsultantId,
			COALESCE(L.MileStoneNo, O.MileStoneNo) AS MileStoneNo,
			COALESCE(L.AttendanceDate, O.AttendanceDate) AS AttendanceDate,
			L.LoginTimestamp,
			L.LoginPhotoId,
			O.LogoutTimestamp,
			O.LogoutPhotoId,
			COALESCE(L.LoginSeq, O.LogoutSeq + (COALESCE(L.TotalLogins, O.TotalLogins) - COALESCE(L.TotalLogouts, O.TotalLogouts))) AS SessionNo
		FROM LoginRecords L
		FULL OUTER JOIN LogoutRecords O ON
			L.ZedId = O.ZedId AND
			L.Certification = O.Certification AND
			L.ConsultantId = O.ConsultantId AND
			L.MileStoneNo = O.MileStoneNo AND
			L.AttendanceDate = O.AttendanceDate AND
			L.LoginSeq = O.LogoutSeq + (COALESCE(L.TotalLogins, O.TotalLogins) - COALESCE(L.TotalLogouts, O.TotalLogouts))
	)
	SELECT
		S.ZedId,
		S.Certification,
		S.ConsultantId,
		S.MileStoneNo,
		S.AttendanceDate AS TimeStamps,
		CONVERT(TIME, S.LoginTimestamp) AS LoginTime,
		CONVERT(TIME, S.LogoutTimestamp) AS LogoutTime,
		S.LoginPhotoId AS LoginPhotoId1,
		S.LogoutPhotoId AS LogoutPhotoId1,
		CONCAT(@CurrentUrl, '/consultancymobileapi/Attendance/', S.ZedId, '/', S.Certification, '/', S.LoginPhotoId, '.jpg') AS LoginPhotoId,
		CONCAT(@CurrentUrl, '/consultancymobileapi/Attendance/', S.ZedId, '/', S.Certification, '/', S.LogoutPhotoId, '.jpg') AS LogoutPhotoId,
		DATEDIFF(MINUTE, S.LoginTimestamp, S.LogoutTimestamp) / 60 AS NoOfHours,
		DATEDIFF(MINUTE, S.LoginTimestamp, S.LogoutTimestamp) % 60 AS NoOfMinutes,
		DATEDIFF(DAY, CONVERT(DATE, C.AssessmentDate), S.AttendanceDate) + 1 AS RowNumber,
		S.SessionNo
	FROM Sessions S
	LEFT JOIN MsmeCertifications C ON
		S.ZedId = C.ZedId AND S.Certification = C.Certification AND S.MileStoneNo = C.NcCount
	ORDER BY S.ConsultantId, S.MileStoneNo, S.AttendanceDate, S.SessionNo;



		END

	--select * from screenshotphotos where ZedId=@ZedId AND Certification=@Certification order by id
	select Distinct SiteAssessorId ConsultantId, 'Consultant' AssessorType from MsmeCertifications where ZedId=@ZedId AND Certification=@Certification and SiteAssessorId is not null
	UNION ALL
	select Distinct CoAssessorId ConsultantId, 'CoConsultant' AssessorType from AllotedCoAssessors where ZedId=@ZedId AND Certification=@Certification 

	-----------LOADING LATLONGS OF ZED ASSESSMENT------------------------
		SELECT TOP 1 M.Latitude AS ZedLatitude, M.Longitude AS ZedLongitude,  ISNULL(S.Latitude, M.Latitude) AS ZedSaLatitude, ISNULL(S.Longitude, M.Longitude) AS ZedSaLongitude, 0 AS NcCount 
        FROM ZEDCS_V2_LIVE.DBO.MsmePhotos M LEFT JOIN ZEDCS_V2_LIVE.DBO.SaPhotos S ON M.ZedId = S.ZedId AND M.Certification = S.Certification AND S.NcCount = 0 AND S.Name = 'Site Exterior Photo'
		WHERE M.Certification = @TargetCertification AND M.ZedId = @ZedId AND M.PhotoType = 'SiteExteriorPhotos' AND M.NcCount = 0

END



GO
/****** Object:  StoredProcedure [dbo].[SP_ASSESSMENT_DA_DETAILS_NC]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
--[SP_ASSESSMENT_DA_DETAILS_NC] null,null,'<redacted>','<redacted>',1
CREATE PROCEDURE [dbo].[SP_ASSESSMENT_DA_DETAILS_NC] --'<redacted>','<redacted>','<redacted>','<redacted>','<redacted>'
(
	@UserId varchar(50) = NULL,
	@RoleId varchar(50) = NULL,
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL,
	@NcCount int = 0
)
AS
BEGIN
	
	SET NOCOUNT ON;

	IF(select count(*) from MsmeCertifications where zedid=@ZedId and Certification=@Certification and ((DesktopAssessorId=@UserId and @RoleId=3) OR (SiteAssessorId=@UserId and @RoleId=3) OR (CoAssessorId=@UserId and @RoleId=3) OR (CertificationBodyUserId=@UserId AND @RoleId=2) OR (@RoleId=10) OR (@RoleId=7) OR (@RoleId=8) OR (ZedId=@ZedId AND (@RoleId is null OR @RoleId=5))))=0
	BEGIN
		SET @ZedId='000'
	END

	IF @Certification='Bronze'
	BEGIN
	
		SELECT Id,ZedId,Certification,ProductName,Exported,ProductPhoto,ProductDescriptionPhoto,IsVerified,AssessorRemarks,FORMAT(UpdatedDate,  'MMMM dd, yyyy HH:mm tt') UpdatedDate,NcCount,MsmeRemarks,SaProductPhoto,SaProductDescriptionPhoto,
		IsSaVerified,SaAssessorRemarks,SaUpdatedDate,ProductOpenedTime,ProductDescOpenedTime,ProductParentId,PreviousAssessorRemarks,FORMAT(PreviousAssessorUpdatedDate,  'MMMM dd, yyyy HH:mm tt') PreviousAssessorUpdatedDate,FORMAT(MsmeUpdatedDate,  'MMMM dd, yyyy HH:mm tt') MsmeUpdatedDate,'MsmeProducts' TableName 
		FROM MsmeProducts WHERE Certification=@Certification AND ZedId=@ZedId	AND NcCount = @NcCount


		SELECT Id,ZedId,SectionType Certification,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType,
		(select count(*) ValidationRequired from MsmeEvidences E where ZedId=@ZedId and SectionType=@Certification and validationrequired=1 and E.SectionCode=S.SectionCode group by sectioncode) ValidationRequired,
		IsAssessmentExcempted
		FROM MsmeSections S 	WHERE SectionType=@Certification AND ZedId=@ZedId AND NcCount = @NcCount ORDER BY SectionCode

		SELECT Id,ZedId,SectionType Certification,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode,RequirementName,OrderNo,SectionType,Conformance,AssessorRemarks, PreviousAssessorRemarks,MsmeRemarks MsmeComments, FORMAT(PreviousAssessorUpdatedDate, 'MMMM dd, yyyy HH:mm tt') PreviousAssessorUpdatedDate, FORMAT(MsmeUpdatedDate, 'MMMM dd, yyyy HH:mm tt') MsmeUpdatedDate, 'MsmeRequirements' TableName, OpenedFlag,SaConformance,SaAssessorRemarks FROM MsmeRequirements WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount = @NcCount ORDER BY SectionCode, RequirementCode
	
		SELECT Id,ZedId,SectionType Certification,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType FROM MsmeOptions WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount = @NcCount ORDER BY SectionCode, RequirementCode, OptionCode
	
		SELECT Id,ZedId,SectionType Certification,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType FROM MsmeSubOptions WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount = @NcCount ORDER BY SectionCode, RequirementCode, OptionCode, SubOptionCode
	
		
		IF @RoleId=5
		BEGIN
			SELECT E.Id,E.ZedId,E.SectionType Certification,E.SectionCode,E.RequirementCode,EvidenceId,EvidenceCode,EvidenceName,E.SectionType,EvidenceType,ValidationRequired, IsVerified, SourceOfValidation, E.AssessorRemarks, 'MsmeEvidences' TableName,E.NcCount, DocumentOpenedTime, SyncedDate,FORMAT(SyncedDate, 'MMMM dd, yyyy HH:mm tt') GeneratedTime, '' RequirementRemarks, '' RequirementMsmeRemarks
			FROM MsmeEvidences E 
			WHERE E.SectionType=@Certification AND E.ZedId=@ZedId  AND E.NcCount>0  AND E.NcCount = @NcCount 
			ORDER BY SectionCode, RequirementCode, NcCount
		END
		ELSE
		BEGIN
			SELECT E.Id,E.ZedId,E.SectionType Certification,E.SectionCode,E.RequirementCode,EvidenceId,EvidenceCode,EvidenceName,E.SectionType,EvidenceType,ValidationRequired, IsVerified, SourceOfValidation, E.AssessorRemarks, 'MsmeEvidences' TableName,E.NcCount, DocumentOpenedTime, SyncedDate,FORMAT(SyncedDate, 'MMMM dd, yyyy HH:mm tt') GeneratedTime, R1.Conformance, R1.AssessorRemarks RequirementRemarks, R1.MsmeRemarks RequirementMsmeRemarks
			FROM MsmeEvidences E 
			INNER JOIN MsmeRequirements R1 ON (E.SectionType=R1.SectionType AND E.ZedId=R1.ZedId  AND E.NcCount = R1.NcCount AND E.SectionCode=R1.SectionCode AND E.RequirementCode=R1.RequirementCode)
			WHERE E.SectionType=@Certification AND E.ZedId=@ZedId  AND E.NcCount>0  AND E.NcCount <= @NcCount 
			ORDER BY SectionCode, RequirementCode, NcCount
		END


		--SELECT Id,ZedId,Certification,PhotoId,Name,CONVERT(varchar,TimeStamp,100) TimeStamp,Latitude,Longitude,PhotoType,EvidenceId,IsVerified,AssessorRemarks,UpdatedDate,NcCount,PhotoExtension,RequirementId,FORMAT(CreatedDate,  '<redacted>') CreatedDate, ProductId,
		--'<redacted>' TableName,MsmeRemarks, (SELECT count(*) DocumentOpenedTime from MsmePhotos WHERE Certification=@Certification AND ZedId=@ZedId AND PhotoType in ('<redacted>') AND NcCount=@NcCount and DocumentOpenedTime is null)  DocumentOpenedTime  FROM MsmePhotos WHERE Certification=@Certification AND ZedId=@ZedId AND PhotoType in ('<redacted>', '<redacted>', '<redacted>') AND NcCount = @NcCount

		
		SELECT Id,ZedId,Certification,PhotoId,Name,CONVERT(varchar,TimeStamp,100) TimeStamp,Latitude,Longitude,PhotoType,EvidenceId,IsVerified,AssessorRemarks,UpdatedDate,NcCount,PhotoExtension,RequirementId,FORMAT(CreatedDate,  'MMMM dd, yyyy HH:mm tt') CreatedDate, ProductId,
		'MsmePhotos' TableName,MsmeRemarks, (SELECT count(*) DocumentOpenedTime from MsmePhotos WHERE Certification=@Certification AND ZedId=@ZedId AND PhotoType in ('SiteExteriorPhotos') AND NcCount=@NcCount and DocumentOpenedTime is null)  DocumentOpenedTime  FROM MsmePhotos WHERE Certification=@Certification AND ZedId=@ZedId AND PhotoType in ('SiteExteriorPhotos') AND NcCount = @NcCount

		---ASSESSOR REMARKS
		select AssessorRemarks AssessorRemarksNc from AssessorComments where ZedId=@ZedId  and Certification=@Certification and NcCount=@NcCount

		--SELECT ZedId,[0] as Nc0AsComments,[1] as Nc1AsComments,[2] as Nc2AsComments,[3] as Nc3AsComments,[4] as Nc4AsComments,[5] as Nc5AsComments  from 
		--(select ZedId,NcCount,AssessorRemarks from AssessorComments where ZedId=@ZedId  and Certification=@Certification AND NcCount=@NcCount) SRC
		--PIVOT
		--(max(AssessorRemarks) for NcCount in ([0],[1],[2],[3],[4],[5])) pvt

		SELECT *,'MsmeProducts' TableName FROM MsmeProducts WHERE Certification=@Certification AND ZedId=@ZedId	AND NcCount < @NcCount order by NcCount
	END

	ELSE

	BEGIN
	
		SELECT *,'MsmeProducts' TableName FROM MsmeProducts WHERE Certification=@Certification AND ZedId=@ZedId	AND NcCount = @NcCount

		IF (SELECT count(*) from MsmeCertifications where ZedId=@ZedId and Certification=@Certification and CoAssessorId=@UserId)>0
		BEGIN
			SELECT Id,ZedId,SectionType Certification,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType,
			(select count(*) ValidationRequired from MsmeEvidences E where ZedId=@ZedId and SectionType=@Certification and validationrequired=1 and E.SectionCode=S.SectionCode group by sectioncode) ValidationRequired,
			IsAssessmentExcempted
			FROM MsmeSections S 	WHERE SectionType=@Certification AND ZedId=@ZedId AND NcCount = @NcCount and AssessorId=@UserId  ORDER BY convert(int,SectionCode)
		END

		ELSE
		BEGIN
			SELECT Id,ZedId,SectionType Certification,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType,
			(select count(*) ValidationRequired from MsmeEvidences E where ZedId=@ZedId and SectionType=@Certification and validationrequired=1 and E.SectionCode=S.SectionCode group by sectioncode) ValidationRequired,
			IsAssessmentExcempted
			FROM MsmeSections S 	WHERE SectionType=@Certification AND ZedId=@ZedId AND NcCount = @NcCount ORDER BY convert(int,SectionCode)
		END

		SELECT Id,ZedId,SectionType Certification,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode,RequirementName,OrderNo,SectionType,Conformance,AssessorRemarks,PreviousAssessorRemarks, MsmeRemarks MsmeComments, FORMAT(PreviousAssessorUpdatedDate, 'MMMM dd, yyyy HH:mm tt') PreviousAssessorUpdatedDate, FORMAT(MsmeUpdatedDate, 'MMMM dd, yyyy HH:mm tt') MsmeUpdatedDate, 'MsmeRequirements' TableName, OpenedFlag,SaConformance,SaAssessorRemarks FROM MsmeRequirements WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount = @NcCount ORDER BY convert(int,SectionCode), convert(int,RequirementCode)
	
	
		SELECT Id,ZedId,SectionType Certification,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType FROM MsmeOptions WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount = @NcCount ORDER BY SectionCode, RequirementCode, OptionCode
	
		SELECT Id,ZedId,SectionType Certification,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType FROM MsmeSubOptions WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount = @NcCount ORDER BY SectionCode, RequirementCode, OptionCode, SubOptionCode

		IF @RoleId=5
		BEGIN
			SELECT Id,ZedId,SectionType Certification,SectionCode,RequirementCode,EvidenceId,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired, IsVerified, SourceOfValidation, AssessorRemarks, 'MsmeEvidences' TableName,NcCount, DocumentOpenedTime, SyncedDate,FORMAT(SyncedDate, 'MMMM dd, yyyy HH:mm tt') GeneratedTime FROM MsmeEvidences WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount>0  AND NcCount = @NcCount ORDER BY SectionCode, RequirementCode, NcCount
		END
		ELSE
		BEGIN
			SELECT Id,ZedId,SectionType Certification,SectionCode,RequirementCode,EvidenceId,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired, IsVerified, SourceOfValidation, AssessorRemarks, 'MsmeEvidences' TableName,NcCount, DocumentOpenedTime, SyncedDate,FORMAT(SyncedDate, 'MMMM dd, yyyy HH:mm tt') GeneratedTime FROM MsmeEvidences WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount>0  AND NcCount <= @NcCount ORDER BY SectionCode, RequirementCode, NcCount

		END
	
		--SELECT Id,ZedId,SectionType Certification,SectionCode,SectionName,QuestionCode,QuestionName,RequirementId,RequirementCode,RequirementName,OrderNo,SectionType,Conformance,AssessorRemarks,MsmeRemarks, '<redacted>' TableName, NcCount, OpenedFlag FROM MsmeRequirements WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount>0  AND NcCount <= @NcCount ORDER BY SectionCode, RequirementCode, NcCount
		---SELECT Id,ZedId,SectionType Certification,SectionCode,RequirementCode,EvidenceId,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired, IsVerified, SourceOfValidation, AssessorRemarks, '<redacted>' TableName,NcCount, DocumentOpenedTime, SyncedDate,FORMAT(SyncedDate, '<redacted>') GeneratedTime FROM MsmeEvidences WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount>0  AND NcCount <= @NcCount ORDER BY SectionCode, RequirementCode, NcCount
		--SELECT Id,ZedId,SectionType Certification,SectionCode,RequirementCode,EvidenceId,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired, IsVerified, SourceOfValidation, AssessorRemarks, '<redacted>' TableName,NcCount, DocumentOpenedTime, SyncedDate,FORMAT(SyncedDate, '<redacted>') GeneratedTime FROM MsmeEvidences WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount>0  AND NcCount <= @NcCount ORDER BY SectionCode, RequirementCode, NcCount

		SELECT Id,ZedId,Certification,PhotoId,Name,TimeStamp,Latitude,Longitude,PhotoType,EvidenceId,IsVerified,AssessorId,AssessorRemarks, UpdatedDate,NcCount,PhotoExtension,RequirementId,Photo,FORMAT(CreatedDate, 'MMMM dd, yyyy HH:mm tt') CreatedDate,ProductId,DocumentOpenedTime,MsmeRemarks,'SaPhotos' TableName  FROM SaPhotos WHERE Certification=@Certification AND ZedId=@ZedId AND name in ('Site Exterior Photo','Site Interior Photo','SiteExteriorPhotos') AND NcCount = @NcCount

		---ASSESSOR REMARKS
		select 'AssessorComments' TableName,Id, SaAssessorRemarks from AssessorComments where ZedId=@ZedId  and Certification=@Certification and NcCount=@NcCount

		SELECT *,'MsmeProducts' TableName FROM MsmeProducts WHERE Certification=@Certification AND ZedId=@ZedId	AND NcCount < @NcCount order by NcCount

		SELECT P.*,'SaPhotos' TableName, P2.ProductParentId FROM SaPhotos P inner join MsmeProducts P2 on (P.ProductId=P2.Id AND P.NcCount=P2.NcCount AND P.ZedId=P2.ZedId and P.Certification=P2.Certification) 
		WHERE P.Certification=@Certification AND P.ZedId=@ZedId AND PhotoType in ('ProductPhotos','ProductDescriptionPhotos') AND P.NcCount = @NcCount

	END

END



GO
/****** Object:  StoredProcedure [dbo].[SP_ASSESSMENT_DA_FINAL_SUBMIT]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_ASSESSMENT_DA_FINAL_SUBMIT] 
(
	@ZedId VarChar(50)						= NULL,
	@CertificationType VarChar(50)			= NULL,
	@AssessorRemarks VarChar(5000)			= NULL
)
AS
BEGIN
	
	Declare @NcCount int  = NULL
	Declare @ErrorStatus bit = 0

	Declare @EvidenceId varchar(50) = NULL
	

	Select @NcCount=NcCount from MsmeCertifications where ZedId=@ZedId AND Certification=@CertificationType

	IF @CertificationType='Bronze'
	BEGIN
		--CHECKING FOR ERRORS IN SITE EXTERIOR PHOTOS
		IF(select count(*) from MsmePhotos where PhotoType='SiteExteriorPhotos' and Certification=@CertificationType and ZedId=@ZedId and IsVerified='No' and NcCount=@NcCount)>0
		SET @ErrorStatus=1

		--CHECKING FOR ERRORS IN PRODUCTS
		IF(select count(*) from MsmeProducts where Certification=@CertificationType and ZedId=@ZedId and IsVerified='No' and NcCount=@NcCount)>0
		SET @ErrorStatus=1
	
		--CHECKING FOR ERRORS IN EVIDENCES
		IF(select count(*) from MsmeRequirements where SectionType=@CertificationType and ZedId=@ZedId and Conformance='No' and NcCount=@NcCount)>0
		BEGIN		
			SET @ErrorStatus=1
			IF @NcCount<5
			BEGIN
				insert into MsmeSections(SectionId,ZedId,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType,NcCount,IsAssessmentExcempted)
				select Distinct SectionId,S.ZedId,S.SectionCode,S.SectionName,S.OrderNo,iButton,SectionImage,S.SectionType,@NcCount+1,IsAssessmentExcempted from MsmeRequirements R  inner join MsmeSections S on (R.SectionCode=S.SectionCode and R.NcCount=S.NcCount) where R.zedid=@ZedId and S.zedid=@ZedId and Conformance='No'  and S.NcCount=@NcCount
		
				insert into MsmeRequirements(RequirementId,ZedId,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode,RequirementName,OrderNo,SectionType,NcCount,PreviousAssessorRemarks,PreviousAssessorUpdatedDate)
				select RequirementId,ZedId,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode,RequirementName,OrderNo,SectionType,@NcCount+1,AssessorRemarks,UpdatedDate from MsmeRequirements where zedid=@ZedId and Conformance='No' and NcCount=@NcCount
		
				insert into MsmeOptions(OptionId,ZedId,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType,NcCount)
				select OptionId,O.ZedId,O.SectionCode,O.QuestionCode,OptionCode,OptionName,OptionImage,O.RequirementCode,O.SectionType,@NcCount+1 from MsmeRequirements R  inner join MsmeOptions O on (R.SectionCode=O.SectionCode and R.RequirementCode=O.RequirementCode and R.NcCount=O.NcCount) where R.zedid=@ZedId and O.zedid=@ZedId and Conformance='No' and O.NcCount=@NcCount
		
				insert into MsmeSubOptions(SubOptionId,ZedId,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType,NcCount)
				select O.SubOptionId,O.ZedId,O.SectionCode,O.QuestionCode,OptionCode,SubOptionCode,SubOptionName,O.RequirementCode,SubOptionImage,O.SectionType,@NcCount+1 from MsmeRequirements R  inner join MsmeSubOptions O on (R.SectionCode=O.SectionCode and R.RequirementCode=O.RequirementCode  and R.NcCount=O.NcCount ) where R.zedid=@ZedId and O.zedid=@ZedId and Conformance='No' and O.NcCount=@NcCount
		
				insert into MsmeEvidences(EvidenceId, ZedId,SectionCode,RequirementCode,EvidenceCode,SectionType,EvidenceName,NcCount,RequirementId)
				select (next value for EvidenceIdSequence),ZedId,SectionCode,RequirementCode,concat('9',@NcCount+1),SectionType,concat('NC',@NcCount+1),@NcCount+1,RequirementId from MsmeRequirements where zedid=@ZedId and Conformance='No' and NcCount=@NcCount
			END
		END

		IF(select count(*) from MsmeProducts where Certification=@CertificationType and ZedId=@ZedId and IsVerified='No' and NcCount=@NcCount)>0
		BEGIN		
			SET @ErrorStatus=1

			IF @NcCount<5
			BEGIN
				INSERT INTO MsmeProducts (ZedId, Certification, ProductName, Exported, NcCount, PreviousAssessorRemarks,ProductParentId,PreviousAssessorUpdatedDate)
				SELECT ZedId, Certification, ProductName, Exported,  @NcCount+1, AssessorRemarks, ProductParentId,UpdatedDate FROM MsmeProducts WHERE zedid=@ZedId and IsVerified='No' and NcCount=@NcCount
			END
		END

		IF (@ErrorStatus=1 and @NcCount=0)
		BEGIN

			insert into AssessorComments (ZedId,Certification,NcCount,AssessorRemarks,CertificationStatusDate,AssessmentType)
			Values(@ZedId,@CertificationType,@NcCount,@AssessorRemarks,getdate(),'DA')

			UPDATE MsmeCertifications set CertificationStatus=4,NcCount=@NcCount+1,CertificationStatusDate=getdate(),AssessorRemarks=@AssessorRemarks,NcStatus=1,Nc1Status=1,NcFinalClosureDt=DATEADD(MONTH, 1, GETDATE())  where ZedId=@ZedId AND Certification=@CertificationType

			insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			values (@ZedId,concat('NC ',@NcCount+1,' Raised On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,concat('Nc',@NcCount+1,'Raised' ))

			insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			values (@ZedId,concat('Final Closure Date: ',FORMAT(DATEADD(MONTH, 1, getdate()), 'MMMM d, yyyy')),getdate(),@CertificationType,'NcFinalClosureDate')

			insert into NcClosureDateHistory (ZedId,Certification,NoOfDays,FnNcCloseDt)
			values (@ZedId,@CertificationType,0,getdate())


		END

		IF (@ErrorStatus=1 and @NcCount>0)
		BEGIN

			insert into AssessorComments (ZedId,Certification,NcCount,AssessorRemarks,CertificationStatusDate,AssessmentType)
			Values(@ZedId,@CertificationType,@NcCount,@AssessorRemarks,getdate(),'DA')

			SET @NcCount=@NcCount+1

			UPDATE MsmeCertifications set NcStatus=1,NcCount=@NcCount,CertificationStatusDate=getdate(),AssessorRemarks=@AssessorRemarks  where ZedId=@ZedId AND Certification=@CertificationType

			IF @NcCount = 1
			UPDATE MsmeCertifications set Nc1Status=1 where ZedId=@ZedId and Certification=@CertificationType
			IF @NcCount = 2
			UPDATE MsmeCertifications set Nc2Status=1 where ZedId=@ZedId and Certification=@CertificationType
			IF @NcCount = 3
			UPDATE MsmeCertifications set Nc3Status=1 where ZedId=@ZedId and Certification=@CertificationType
			IF @NcCount = 4
			UPDATE MsmeCertifications set Nc4Status=1 where ZedId=@ZedId and Certification=@CertificationType
			IF @NcCount = 5
			UPDATE MsmeCertifications set Nc5Status=1 where ZedId=@ZedId and Certification=@CertificationType
			IF @NcCount > 5
			UPDATE MsmeCertifications set CertificationStatus=7 where ZedId=@ZedId and Certification=@CertificationType

			IF @NcCount<6
			BEGIN
				insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
				values (@ZedId,concat('NC ',@NcCount,' Raised On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,concat('Nc',@NcCount,'Raised' ))
			END
			ELSE
			BEGIN
				insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
				values (@ZedId,concat('Assessor Rejected On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'Assessor Rejected in NC 5' )
			END
		END

		IF @ErrorStatus=0
		BEGIN
		
			insert into AssessorComments (ZedId,Certification,NcCount,AssessorRemarks,CertificationStatusDate,AssessmentType)
			Values(@ZedId,@CertificationType,@NcCount,@AssessorRemarks,getdate(),'DA')

			UPDATE MsmeCertifications set CertificationStatus=5,CertificationStatusDate=getdate(),AssessorRemarks=@AssessorRemarks  where ZedId=@ZedId AND Certification=@CertificationType

			insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			values (@ZedId,concat('NC(s) Closed On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'NcClosed')
		END
	END

	ELSE 
	BEGIN
		------- if it is not bronze, we are sending directly to agency for approval

			insert into AssessorComments (ZedId,Certification,NcCount,AssessorRemarks,CertificationStatusDate,AssessmentType)
			Values(@ZedId,@CertificationType,@NcCount,@AssessorRemarks,getdate(),'DA')

			UPDATE MsmeCertifications set CertificationStatus=5,CertificationStatusDate=getdate(),AssessorRemarks=@AssessorRemarks  where ZedId=@ZedId AND Certification=@CertificationType

			--insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			--values (@ZedId,concat('<redacted>',FORMAT(getdate(), '<redacted>')),getdate(),@CertificationType,'<redacted>')

			insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			values (@ZedId,concat('DA Final submit has Done for ','NcCount ',@NcCount, ' and send to Agency for QC'),getdate(),@CertificationType,NULL)
			
		END

	

END
GO
/****** Object:  StoredProcedure [dbo].[SP_ASSESSMENT_DA_UPDATE_EVIDENCES]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_ASSESSMENT_DA_UPDATE_EVIDENCES] 
(
	@Id VarChar(50)						= NULL,
	@ZedId VarChar(50)					= NULL,
	@CertificationType VarChar(50)		= NULL,
	@IsVerified VarChar(50)				= NULL,
	@SourceOfValidation VarChar(2000)	= NULL,
	@Remark VarChar(2000)				= NULL,
	@Screenshots FileDetails READONLY
)
AS
BEGIN

		DECLARE 
		@SectionCode varchar(50) = NULL,
		@RequirementCode varchar(50) = NULL,
		@SectionType varchar(50) = NULL

	DECLARE @NcCount int = NULL
	SELECT @NcCount=NcCount FROM MsmeCertifications WHERE ZedId=@ZedId and Certification=@CertificationType

	
	DECLARE @NewFileName varchar(2000) = NULL
	select @NewFileName=FileName from @Screenshots

	
	IF @IsVerified='No'
	BEGIN
		UPDATE MsmeEvidences set IsVerified=@IsVerified,SourceOfValidation=@SourceOfValidation,AssessorRemarks=@Remark, UpdatedDate=getdate() 
		where Id=@Id --AND ZedId=@ZedId AND SectionType=@CertificationType

		UPDATE MsmeRequirements SET Conformance='No',AssessorRemarks=@Remark where ZedId=@ZedId and SectionType=@CertificationType and NcCount=0 and concat(sectioncode,'_',RequirementCode)  in 
		(SELECT DISTINCT CONCAT(SectionCode,'_',RequirementCode)  from MsmeEvidences where ZedId=@ZedId and SectionType=@CertificationType and ValidationRequired=1 and NcCount=0 and Id=@Id)
	END
	ELSE 
	BEGIN
		UPDATE MsmeEvidences set IsVerified=@IsVerified,SourceOfValidation=@SourceOfValidation,AssessorRemarks=@Remark, UpdatedDate=getdate() 
		where Id=@Id --AND ZedId=@ZedId AND SectionType=@CertificationType
	END
	

	IF EXISTS (select * from ScreenshotPhotos where ZedId=@ZedId and Certification=@CertificationType and RefEvidenceId=@Id and NcCount=@NcCount)
		BEGIN
			update ScreenshotPhotos set FileName=@NewFileName where RefEvidenceId=@Id and  ZedId=@ZedId and Certification=@CertificationType and NcCount=@NcCount
		END
		ELSE
		BEGIN
			INSERT INTO ScreenshotPhotos (RefEvidenceId,ZedId,Certification,FileName,NcCount)
			SELECT @Id,@ZedId,@CertificationType,FileName,@NcCount from @Screenshots
		END


	

	IF @NcCount=0
	BEGIN
	UPDATE MsmeCertifications SET CertificationStatus=3 where ZedId=@ZedId AND Certification=@CertificationType
	END

	IF @NcCount>0
	BEGIN
	UPDATE MsmeCertifications SET NcStatus=3 where ZedId=@ZedId AND Certification=@CertificationType
	END



		select @ZedId=ZedId,@SectionCode=SectionCode,@RequirementCode=RequirementCode,@SectionType=SectionType from MsmeEvidences where Id=@Id

		IF (
		select count(*) from MsmeEvidences where ZedId=@ZedId and SectionCode=@SectionCode and RequirementCode=@RequirementCode and SectionType=@SectionType and DocumentOpenedTime is null)=0
			BEGIN
				IF (select count(*) from MsmeEvidences where ZedId=@ZedId and SectionCode=@SectionCode and RequirementCode=@RequirementCode and SectionType=@SectionType and ValidationRequired =1 and IsVerified is null)=0
				UPDATE MsmeRequirements set OpenedFlag=1 where ZedId=@ZedId and SectionCode=@SectionCode and RequirementCode=@RequirementCode and SectionType=@SectionType
			END


END
GO
