)
AS
BEGIN


	IF @ColumnName='SaAuditsConducted'
	BEGIN
		UPDATE MsmeCertifications 
		SET SaAuditsConducted=@Response
		where  Id=@Id AND ZedId=@ZedId AND Certification=@CertificationType
	END
	ELSE IF @ColumnName='SaDomesticCustomers'
	BEGIN
		UPDATE MsmeCertifications 
		SET SaDomesticCustomers=@Response
		where  Id=@Id AND ZedId=@ZedId AND Certification=@CertificationType
	END

	ELSE IF @ColumnName='SaInternationalCustomers'
	BEGIN
		UPDATE MsmeCertifications 
		SET SaInternationalCustomers=@Response
		where  Id=@Id AND ZedId=@ZedId AND Certification=@CertificationType
	END

	ELSE IF @ColumnName='SaRawMaterialImported'
	BEGIN
		UPDATE MsmeCertifications 
		SET SaRawMaterialImported=@Response
		where  Id=@Id AND ZedId=@ZedId AND Certification=@CertificationType
	END

	ELSE IF @ColumnName='SaOutsourcedProcesses'
	BEGIN
		UPDATE MsmeCertifications 
		SET SaOutsourcedProcesses=@Response
		where  Id=@Id AND ZedId=@ZedId AND Certification=@CertificationType
	END

	ELSE IF @ColumnName='SaEnergySources'
	BEGIN
		UPDATE MsmeCertifications 
		SET SaEnergySources=@Response
		where  Id=@Id AND ZedId=@ZedId AND Certification=@CertificationType
	END

END

