/****** Object:  StoredProcedure [dbo].[SP_ASSESSMENT_SA_DETAILS]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
--[SP_ASSESSMENT_SA_DETAILS]  '<redacted>','<redacted>','<redacted>','<redacted>'
--[SP_ASSESSMENT_SA_DETAILS]  '<redacted>','<redacted>','<redacted>','<redacted>'
CREATE PROCEDURE [dbo].[SP_ASSESSMENT_SA_DETAILS] --'<redacted>','<redacted>','<redacted>','<redacted>','<redacted>'
(
	@UserId varchar(50) = NULL,
	@RoleId varchar(50) = NULL,
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL,
	@MileStone int = NULL
)
AS
BEGIN
	
		SET NOCOUNT ON;

		DECLARE @CurrentUrl varchar(100) = NULL,
		@ModeOfAssessment varchar(50) = NULL

		DECLARE @NcCount int = NULL,
		@CertificationStatus int = NULL
	SELECT @NcCount=isnull(max(NcCount),0),@CertificationStatus=min(CertificationStatus) FROM MsmeCertifications where ZedId=@ZedId and Certification= @Certification

		IF(select count(*) from MsmeCertifications where zedid=@ZedId and Certification=@Certification and ((SiteAssessorId=@UserId and @RoleId=3) OR (CoAssessorId like '%'+@UserId+'%' and @RoleId=3) OR (CertificationBodyUserId=@UserId AND @RoleId=2) OR (@RoleId=7) OR (@RoleId=8) OR (@RoleId=10) OR (ZedId=@ZedId AND (@RoleId is null OR @RoleId=5))))=0
		BEGIN
			SET @ZedId='000'
		END

		SELECT @CurrentUrl=UrlName from UrlsMasterData
		SELECT @ModeOfAssessment=ModeOfAssessment from MsmeCertifications WHERE ZedId=@ZedId and Certification=@Certification

		--IF @ModeOfAssessment='<redacted>'
		BEGIN
			SELECT 
			Id,	ZedId,	Certification,	PhotoId,	Name name,	TimeStamp,	Latitude,	Longitude,	PhotoType,	EvidenceId,IsVerified,	AssessorId,	AssessorRemarks,	UpdatedDate,	NcCount,	PhotoExtension,	RequirementId,	
			isnull(Photo,CONCAT(@CurrentUrl,'/consultancymobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/',Name,'_',PhotoId,'.jpg')) src,CreatedDate	
			,'SaPhotos' TableName
			FROM SaPhotos WHERE (name in ('Site Exterior Photo','Site Interior Photo') or (PhotoType='SiteExteriorPhotos')) and Certification=@Certification AND ZedId=@ZedId	--AND NcCount=@NcCount

			SELECT *,'Meetings' TableName FROM Meetings WHERE MeetingType='Open Meeting' AND ZedId=@ZedId AND CertificationType=@Certification ORDER BY NcCount
			SELECT *,'MeetingParticipants' TableName FROM MeetingParticipants WHERE MeetingType='Open Meeting' AND ZedId=@ZedId AND CertificationType=@Certification ORDER BY NcCount
			SELECT *,'Meetings' TableName FROM Meetings WHERE MeetingType='Close Meeting' AND ZedId=@ZedId AND CertificationType=@Certification ORDER BY NcCount
			SELECT *,'MeetingParticipants' TableName FROM MeetingParticipants WHERE MeetingType='Close Meeting' AND ZedId=@ZedId AND CertificationType=@Certification ORDER BY NcCount

			--SELECT Id,ZedId,Certification,PhotoId,TimeStamp,Latitude,Longitude,PhotoType,EvidenceId,IsVerified,AssessorId,AssessorRemarks,UpdatedDate,NcCount,PhotoExtension,RequirementId,Photo,CreatedDate,'<redacted>' TableName,CONCAT(@CurrentUrl,'<redacted>','<redacted>',@ZedId,'<redacted>',AssessorId,'<redacted>') as PhotoPath,Photo src,name  FROM SaPhotos WHERE PhotoType in ('<redacted>') AND ZedId=@ZedId AND Certification=@Certification
			--union
			SELECT Id,ZedId,Certification,PhotoId,TimeStamp,Latitude,Longitude,PhotoType,EvidenceId,IsVerified,AssessorId,AssessorRemarks,UpdatedDate,NcCount,PhotoExtension,RequirementId,Photo,CreatedDate,'SaPhotos' TableName,CONCAT(@CurrentUrl,'/consultancymobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/Opening Meeting Photo_',PhotoId,'.jpg') as PhotoPath,CONCAT(@CurrentUrl,'/consultancymobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/Opening Meeting Photo_',PhotoId,'.jpg') src,name  FROM SaPhotos WHERE Name in ('Opening Meeting Photo') AND ZedId=@ZedId AND Certification=@Certification
	
			SELECT Id,ZedId,Certification,PhotoId,TimeStamp,Latitude,Longitude,PhotoType,EvidenceId,IsVerified,AssessorId,AssessorRemarks,UpdatedDate,NcCount,PhotoExtension,RequirementId,Photo,CreatedDate,'SaPhotos' TableName,CONCAT(@CurrentUrl,'/consultancymobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/SiteTour/',PhotoId,'.jpg') as PhotoPath,CONCAT(@CurrentUrl,'/consultancymobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/SiteTour/',PhotoId,'.jpg') src,name  FROM SaPhotos WHERE PhotoType in ('SiteTour') AND ZedId=@ZedId AND Certification=@Certification
			
			SELECT 
			Id,	ZedId,	Certification,	PhotoId,	Name name,	TimeStamp,	Latitude,	Longitude,	PhotoType,	EvidenceId,IsVerified,	AssessorId,	AssessorRemarks,	UpdatedDate,	NcCount,	PhotoExtension,	RequirementId, null RequirementCode, null SectionCode,	
			Photo,FORMAT(CreatedDate, 'MMMM dd, yyyy HH:mm tt') CreatedDate	
			,'SaPhotos' TableName,Photo src
			FROM SaPhotos WHERE  (PhotoType in ('BaselineDiagnosticStudy')) and Certification=@Certification AND ZedId=@ZedId	--AND NcCount=@NcCount
			union
			SELECT 
			R.Id,	R.ZedId,	R.Certification,	R.PhotoId,	R.Name name,	R.TimeStamp,	R.Latitude,	R.Longitude,	R.PhotoType, null EvidenceId,null IsVerified,null 	AssessorId,	null AssessorRemarks,	R.UpdatedDate,	R.NcCount,	null PhotoExtension,	M.RequirementId, M.RequirementCode, M.SectionCode,	
			case when R.PhotoType='Evidences' then isnull(R.Photo,CONCAT(@CurrentUrl,'/consultancymobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/SiteTour/',R.PhotoId,'.jpg')) else
			isnull(R.Photo,CONCAT(@CurrentUrl,'/consultancymobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/BaselineDiagnosticStudy/',R.PhotoId,'.jpg')) end as Photo,FORMAT(R.CreatedDate, 'MMMM dd, yyyy HH:mm tt') CreatedDate	
			,'SaPhotos' TableName,isnull(R.Photo,CONCAT(@CurrentUrl,'/consultancymobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/BaselineDiagnosticStudy/',R.PhotoId,'.jpg')) src
			FROM  SaRequirementPhotos R	inner join MsmeRequirements M on (R.RequirementId=M.Id)
			WHERE  R.Certification=@Certification AND R.ZedId=@ZedId and (R.PhotoType='BaselineDiagnostic') --	AND R.NcCount=@NcCount
			union
			SELECT 
			R.Id,	R.ZedId,	R.Certification,	R.PhotoId,	R.Name name,	R.TimeStamp,	R.Latitude,	R.Longitude,	R.PhotoType, null EvidenceId,null IsVerified,null 	AssessorId,	null AssessorRemarks,	R.UpdatedDate,	R.NcCount,	null PhotoExtension,	M.RequirementId, M.RequirementCode, M.SectionCode,	
			case when R.PhotoType='Evidences' then isnull(R.Photo,CONCAT(@CurrentUrl,'/consultancymobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/SiteTour/',R.PhotoId,'.jpg')) else
			isnull(R.Photo,CONCAT(@CurrentUrl,'/consultancymobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/BaselineDiagnosticStudy/',R.PhotoId,'.jpg')) end as Photo,FORMAT(R.CreatedDate, 'MMMM dd, yyyy HH:mm tt') CreatedDate	
			,'SaPhotos' TableName,isnull(R.Photo,CONCAT(@CurrentUrl,'/consultancymobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/ProgressReview/',R.PhotoId,'.jpg')) src
			FROM  SaRequirementPhotos R	inner join MsmeRequirements M on (R.RequirementId=M.Id)
			WHERE  R.Certification=@Certification AND R.ZedId=@ZedId and (R.PhotoType='ProgressReview') --	AND R.NcCount=@NcCount

			SELECT Id,ZedId,Certification,PhotoId,TimeStamp,Latitude,Longitude,PhotoType,EvidenceId,IsVerified,AssessorId,AssessorRemarks,UpdatedDate,NcCount,PhotoExtension,RequirementId,Photo,CreatedDate,'SaPhotos' TableName,CONCAT(@CurrentUrl,'/consultancymobileapi/','SaPhotos/',@ZedId,'/Closing Meeting Photo_',PhotoId,'.jpg') as PhotoPath,CONCAT(@CurrentUrl,'/consultancymobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/Closing Meeting Photo_',PhotoId,'.jpg') src,name  FROM SaPhotos WHERE Name in ('Closing Meeting Photo') AND ZedId=@ZedId AND Certification=@Certification

			select *,'SaProducts' TableName from SaProducts where ZedId=@ZedId AND Certification=@Certification

			select *,'SaRawMaterials' TableName from SaRawMaterials where ZedId=@ZedId AND Certification=@Certification

			SELECT Id,ZedId,Certification,PhotoId,TimeStamp,Latitude,Longitude,PhotoType,EvidenceId,IsVerified,AssessorId,AssessorRemarks,UpdatedDate,NcCount,PhotoExtension,RequirementId, CONCAT(@CurrentUrl,'/consultancymobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/BasicInfo/', PhotoId,'.',PhotoExtension) Photo,CreatedDate,'SaPhotos' TableName, CONCAT(@CurrentUrl,'/consultancymobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/BasicInfo/', PhotoId,'.',PhotoExtension) src,name,ProductId  FROM SaPhotos WHERE PhotoType in ('ProductPhotos','ProductDescriptionPhotos') AND ZedId=@ZedId AND Certification=@Certification order by PhotoType desc

			--SELECT TOP 1 Id,	ZedId,	Certification,	Timestamp,	CONCAT(@CurrentUrl,'<redacted>',PhotoPath) PhotoPath,	Latitude,	Longitude,	CreatedDate,	RepresentativeName,	Designation FROM MsmeSelfies WHERE ZedId=@ZedId AND Certification=@Certification ORDER BY ID DESC
			SELECT Id, ZedId, Certification, PhotoId, TimeStamp, Latitude, Longitude, PhotoType, EvidenceId, IsVerified, AssessorId, AssessorRemarks, UpdatedDate, NcCount, PhotoExtension,RequirementId, Photo, CreatedDate, 'SaPhotos' TableName, 
			CASE WHEN NcCount=1 THEN CONCAT(@CurrentUrl,'/consultancymobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/Baseline Diagnostic Selfie/',PhotoId,'.jpg') 
			WHEN NcCount>1 THEN CONCAT(@CurrentUrl,'/consultancymobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/Progress Review/',PhotoId,'.jpg') END
			as PhotoPath,Photo src,name  FROM SaPhotos WHERE PhotoType in ('Selfie') AND ZedId=@ZedId AND Certification=@Certification ORDER By NcCount

			select *, 'TrainingInfo' TableName from TrainingInfo where ZedId=@ZedId AND CertificationType=@Certification AND NcCount=1 and TrainingType='ZedTraining' order by id desc
			select *,CONCAT(@CurrentUrl,'/consultancymobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/Training on ZED/',PhotoId,'.jpg') src,
			 'trainingphotos' TableName
			from trainingphotos  where ZedId=@ZedId AND Certification=@Certification AND NcCount=1  and PhotoType='ZedTraining'

			select *, 'TrainingInfo' TableName,
			case when C.SiteAssessorId=T.AssessorId then 'Lead Consultant' when C.CoAssessorId=T.AssessorId then 'Co Consultant' end as AssessorRank
			from TrainingInfo T left join Users U on (T.AssessorId=U.UserId) left join MsmeCertifications C on (T.ZedId=C.ZedId and T.CertificationType=C.Certification and T.NcCount=C.NcCount) 
			where T.ZedId=@ZedId AND CertificationType=@Certification and TrainingType='HouseholdingTraining' -- AND T.NcCount=@NcCount
			order by T.id
			
			select *,CONCAT(@CurrentUrl,'/consultancymobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/Training on Handholding Implementation Plan/',PhotoId,'.jpg') src,
			'trainingphotos' TableName
			from trainingphotos  where ZedId=@ZedId AND Certification=@Certification and PhotoType='HouseholdingTraining'--AND NcCount=@NcCount

			select * from ConsultancyBasicInformation where ZedId=@ZedId AND CertificationType=@Certification --AND NcCount=@NcCount
			ORDER BY NcCount

			--SELECT '<redacted>'+convert(varchar,B.Id) IdP, B.Id,B.ZedId,SectionType Certification,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode, B.RequirementId,RequirementName,OrderNo,SectionType,Conformance,AssessorRemarks,'<redacted>' TableName,
			--EstimatedTimeInDays,Intervention,BaselineDate,InterventionDate,HActionPlanDate,
			--BaselineRemarks,InterventionRemarks,HActionPlanRemarks,IntConformance
			--FROM MsmeRequirementBullets B inner join MsmeRequirements R on (B.ZedId=R.ZedId and B.RequirementId=R.Id) 
			--WHERE SectionType=@Certification AND B.ZedId=@ZedId  AND B.NcCount=@NcCount ORDER BY cast(SectionCode as int), cast(RequirementCode as int)

			
			IF (@RoleId=2 and @CertificationStatus=15) OR (@RoleId=3 and (@CertificationStatus=13 or @CertificationStatus=9))
			BEGIN
				SELECT *, 'MsmeRequirementBullets' TableName
				FROM MsmeRequirementBullets 
				WHERE CertificationType=@Certification AND ZedId=@ZedId  --AND NcCount=@NcCount 
				UNION
				select 999999999 Id, NULL RefId, ZedId, SectionType CertificationType,Id RequirementId, NULL BulletPoints,'BaselineDiagnostic' ReqType, NcCount
				, 'MsmeRequirementBullets' TableName from MsmeRequirements WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=@NcCount 
				UNION
				select 999999999 Id, NULL RefId, ZedId, SectionType CertificationType,Id RequirementId, NULL BulletPoints,'HandholdingActionPlan' ReqType, NcCount
				, 'MsmeRequirementBullets' TableName from MsmeRequirements WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=@NcCount 
				UNION
				select 999999999 Id, NULL RefId, ZedId, SectionType CertificationType, Id RequirementId, NULL BulletPoints,'TechnologyIntervention' ReqType, NcCount
				, 'MsmeRequirementBullets' TableName from MsmeRequirements WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=@NcCount  			
				order by RequirementId,Id 
			END
			ELSE
			BEGIN
				SELECT *, 'MsmeRequirementBullets' TableName
				FROM MsmeRequirementBullets 
				WHERE CertificationType=@Certification AND ZedId=@ZedId  --AND NcCount=@NcCount
			END

			--IF (SELECT count(*) from MsmeCertifications where ZedId=@ZedId and Certification=@Certification and CoAssessorId like '<redacted>'+@UserId+'<redacted>')>0
			--BEGIN
			--	SELECT A.CoAssessorId as LoginUserId, WebFinalSubmitStatus, '<redacted>' TableName
			--	from MsmeSections S 
			--	inner join AllotedCoAssessors A on (S.AssessorId=A.CoAssessorId and S.NcCount=A.NcCount and S.ZedId=A.ZedId and s.SectionType=a.Certification)  
			--	where
			--	 Certification=@Certification AND S.ZedId=@ZedId  AND S.NcCount=@NcCount and CoAssessorId=@UserId order by A.Id
			--END
			--ELSE
			--BEGIN
			--	SELECT @UserId as LoginUserId, 1 WebFinalSubmitStatus, '<redacted>' TableName
				
			--END

			SELECT SectionCode, isnull(S.AssessorId,'Exempted from Asssessment') AllotedAssessorId,UPPER(U.UserName) AllotedAssessorName, S.NcCount,
			case when C.SiteAssessorId=S.AssessorId then 'Lead Consultant' when C.CoAssessorId like '%'+S.AssessorId+'%' then 'Co consultant' end as AssessorRank
			FROM MsmeSections S 
			inner join Users U on (S.AssessorId=U.UserId) 
			inner join MsmeCertifications C on (S.ZedId=C.ZedId and S.SectionType=C.Certification and S.NcCount=C.NcCount)
			WHERE SectionType=@Certification AND S.ZedId=@ZedId  
			ORDER BY cast(SectionCode as int), S.NcCount


			SELECT 'C_'+convert(varchar,Id) IdP, Id,ZedId,SectionType Certification,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode, 
				RequirementId,RequirementName,OrderNo,SectionType,Conformance,AssessorRemarks,'MsmeRequirements' TableName,OpenedFlag, SaConformance,
				SaAssessorRemarks,FORMAT(UpdatedDate, 'MMMM dd, yyyy HH:mm tt') UpdatedDate,FORMAT(SaUpdatedDate, 'MMMM dd, yyyy HH:mm tt') SaUpdatedDate,
				EstimatedTimeInDays,Intervention,BaselineDate,InterventionDate,HActionPlanDate,
				BaselineRemarks,InterventionRemarks,HActionPlanRemarks,IntConformance, IsProposedActivityCompleted, ProgressReviewRemarks, ProgressReviewDate
			FROM MsmeRequirements 
			WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=@NcCount 
			ORDER BY cast(SectionCode as int), cast(RequirementCode as int)
	

		END

		
END



GO
/****** Object:  StoredProcedure [dbo].[SP_ASSESSMENT_VIEW_PROFILE]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================

CREATE PROCEDURE [dbo].[SP_ASSESSMENT_VIEW_PROFILE] --'<redacted>', '<redacted>', '<redacted>'
(
	
	@ZedId varchar(50) = NULL,
	@UserId varchar(50) = NULL,
	@RoleId varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	DECLARE @CurrentUrl varchar(100) = NULL
	SELECT @CurrentUrl=UrlName from UrlsMasterData

	IF @RoleId IN ('2','3')
	BEGIN
	IF(select count(*) from MsmeCertifications where ZedId=@ZedId AND ((@RoleId=2 AND CertificationBodyUserId=@UserId) OR (@RoleId=3 AND DesktopAssessorId=@UserId) OR (@RoleId=3 AND SiteAssessorId=@UserId) OR (@RoleId=3 AND CoAssessorId=@UserId) )   )=0
		SET @ZedId='000'
	END
						

    SELECT 
	M.MsmeId, M.ZedId, M.StateId, M.StateName, M.DistrictId, M.DistrictName, M.OwnerName, M.EnterpriseName,
	M.OrganisationType, M.OrganisationTypeName, M.EnterpriseType, M.EnterpriseTypee, M.MobileNo, M.EmailId,
	M.ApplicationId, M.UamNumber, M.PFlat, M.PBuilding, M.PRoad, M.PArea, M.PCity, M.PAddress, M.PPin,
	M.PStateId, M.PStateName, M.PLgDistrictCode, M.PDistrictName, M.PPlantDetailId, M.Activity,
	M.TwoDigitActivity, M.FourDigitActivity, M.FiveDigitActivity, M.ActivityDetailId, M.PledgeEmailId,
	M.IsBronzePaymentDone, M.IsSilverPaymentDone, M.IsGoldPaymentDone, M.IsCouponUsed, M.PledgeCertificateNo,
	M.RegistrationType, M.IncorporationDate, M.WhetherProdCommenced, M.PlantIdNo, M.PUnitName, M.PUnitIdNo,
	M.CreatedDate, M.RegistrationFrom, M.FinancialAssistanceStatus, M.WashWebinarCertificateNo, M.WashCertificateNo, M.QrCodeNo,	
	FORMAT(CreatedDate, 'MMMM d, yyyy') as PledgeOn FROM Msme M Where ZedId=@ZedId


    SELECT Id, MsmeId, ApplicationId, UdyogAadharNo, OwnerName, EnterpriseName, OrganisationType, OrganisationTypeName, SocialCategory, SocialCategoryName,
	Gender, PH, PanNo, Address, StateId, StateName, DistrictId, DistrictName, LgDistrictCode, Pincode, MobileNo, EmailId, MajorActivity, MajorActivityName,
	EnterpriseType, EnterpriseTypee, CommmenceDate, PreviousEMType, PreviousEMNumber, TotalEmp, InvestmentCost, DicName, AppliedDate, ZedId, LastestCertification FROM MsmeBasicInformation Where ZedId=@ZedId


	END

GO
/****** Object:  StoredProcedure [dbo].[SP_CLEARING_MILESTONE_1_DATA_INCLUDING_PAYMENTS_UPDATES_PAYMENTS]    Script Date: 9/19/2026 4:28:40 AM ******/
