CREATE PROCEDURE [dbo].[SP_CLEARING_MILESTONE_1_DATA_INCLUDING_PAYMENTS_UPDATES_PAYMENTS]  --'<redacted>','<redacted>',1
(
	@ZedId varchar(100) = NULL,
	@Certification varchar(50) = NULL,
	@NcCount int = NULL
)
AS
BEGIN			

	DECLARE @NewZedId VARCHAR(60) = CONCAT(@ZedId, '_RESET')
	
	UPDATE ZED_CONSULTANT.dbo.SaRequirementPhotos SET ZedId = @NewZedId WHERE ZedId = @ZedId AND certification = @Certification AND NcCount = @NcCount
	UPDATE ZED_CONSULTANT.dbo.MsmeCertifications SET ZedId = @NewZedId WHERE ZedId = @ZedId AND certification = @Certification AND NcCount = @NcCount
	UPDATE ZED_CONSULTANT.dbo.SaRawMaterials SET ZedId = @NewZedId WHERE ZedId = @ZedId AND certification = @Certification AND NcCount = @NcCount
	UPDATE ZED_CONSULTANT.dbo.AssessorComments SET ZedId = @NewZedId WHERE ZedId = @ZedId AND certification = @Certification AND NcCount = @NcCount
	UPDATE ZED_CONSULTANT.dbo.ScreenshotPhotos SET ZedId = @NewZedId WHERE ZedId = @ZedId AND certification = @Certification AND NcCount = @NcCount
	UPDATE ZED_CONSULTANT.dbo.MsmeRawMaterials SET ZedId = @NewZedId WHERE ZedId = @ZedId AND certification = @Certification AND NcCount = @NcCount
	UPDATE ZED_CONSULTANT.dbo.PaymentGateWayTransactions SET ZedId = @NewZedId WHERE ZedId = @ZedId AND certification = @Certification AND MileStoneNumber = @NcCount
	UPDATE ZED_CONSULTANT.dbo.MsmePaymentInfo SET ZedId = @NewZedId WHERE ZedId = @ZedId AND certification = @Certification AND MileStoneNum = @NcCount
	UPDATE ZED_CONSULTANT.dbo.MsmeSections SET ZedId = @NewZedId WHERE ZedId = @ZedId AND SectionType = @Certification AND NcCount = @NcCount
	UPDATE ZED_CONSULTANT.dbo.MsmeRequirements SET ZedId = @NewZedId WHERE ZedId = @ZedId AND SectionType = @Certification AND NcCount = @NcCount
	UPDATE ZED_CONSULTANT.dbo.MsmeOptions SET ZedId = @NewZedId WHERE ZedId = @ZedId AND SectionType = @Certification AND NcCount = @NcCount
	UPDATE ZED_CONSULTANT.dbo.MsmeSubOptions SET ZedId = @NewZedId WHERE ZedId = @ZedId AND SectionType = @Certification AND NcCount = @NcCount
	UPDATE ZED_CONSULTANT.dbo.MsmeEvidences SET ZedId = @NewZedId WHERE ZedId = @ZedId AND SectionType = @Certification AND NcCount = @NcCount
	UPDATE ZED_CONSULTANT.dbo.MsmePhotos SET ZedId = @NewZedId WHERE ZedId = @ZedId AND certification = @Certification AND NcCount = @NcCount
	UPDATE ZED_CONSULTANT.dbo.MsmeProducts SET ZedId = @NewZedId WHERE ZedId = @ZedId AND certification = @Certification AND NcCount = @NcCount
	UPDATE ZED_CONSULTANT.dbo.SaPhotos SET ZedId = @NewZedId WHERE ZedId = @ZedId AND certification = @Certification AND NcCount = @NcCount
	UPDATE ZED_CONSULTANT.dbo.SaProducts SET ZedId = @NewZedId WHERE ZedId = @ZedId AND certification = @Certification AND NcCount = @NcCount
	UPDATE ZED_CONSULTANT.dbo.MsmeHistory SET ZedId = @NewZedId WHERE ZedId = @ZedId AND CertificationType = @Certification AND NcCount = @NcCount
	UPDATE ZED_CONSULTANT.dbo.MeetingParticipants SET ZedId = @NewZedId WHERE ZedId = @ZedId AND CertificationType = @Certification AND NcCount = @NcCount
	UPDATE ZED_CONSULTANT.dbo.Meetings SET ZedId = @NewZedId WHERE ZedId = @ZedId AND CertificationType = @Certification AND NcCount = @NcCount
	UPDATE ZED_CONSULTANT.dbo.msmerequirementbullets SET ZedId = @NewZedId WHERE ZedId = @ZedId AND CertificationType = @Certification AND NcCount = @NcCount

	--New added table---
	UPDATE ZED_CONSULTANT.dbo.MsmeHistory SET ZedId = @NewZedId WHERE ZedId = @ZedId AND CertificationType = @Certification AND NcCount = @NcCount


	IF @NcCount = 1
	BEGIN
		IF @Certification = 'Bronze'
		BEGIN
			UPDATE ZED_CONSULTANT.dbo.msme SET isBronzePaymentDone = NULL  WHERE ZedId = @ZedId AND isBronzePaymentDone IS NOT NULL;
		END
		ELSE IF @Certification = 'Silver'
		BEGIN
			UPDATE ZED_CONSULTANT.dbo.msme SET isSilverPaymentDone = NULL WHERE ZedId = @ZedId AND isSilverPaymentDone IS NOT NULL;
		END
		ELSE IF @Certification = 'Gold'
		BEGIN
			UPDATE ZED_CONSULTANT.dbo.msme SET isGoldPaymentDone = NULL WHERE ZedId = @ZedId AND isGoldPaymentDone IS NOT NULL;
		END
	END

	INSERT INTO MsmeHistory(ZedId, Descrip, CreatedDate, CertificationType, StatusType, NcCount)
	VALUES (@ZedId, 'Data reset on request of QCI', GETDATE(), @Certification, NULL, @NcCount)
	
	PRINT 'Clearing milestone 1 data and updated payment.'


END
GO
