CREATE PROC [dbo].[SP_CONSULTANCY_INSERT_BULLETS]  --'<redacted>','<redacted>','<redacted>','<redacted>'
(
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL,
	@RequirementId varchar(50) = NULL,
	@ReqType varchar(200) = NULL,
	@BulletPoints varchar(2000) = NULL,
	@NcCount varchar(2000) = NULL,
	@UserId varchar(50) = NULL
	
	
)
AS
BEGIN

	SELECT @NcCount=isnull(max(NcCount),0) FROM MsmeCertifications where ZedId=@ZedId and Certification= @Certification

