GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_CONSULTANCY_UPDATE_COLUMN_VALUE]  --'<redacted>','<redacted>','<redacted>','<redacted>'
(
	@Id varchar(50) = NULL,
	@TableName varchar(200) = NULL,
	@ColumnName varchar(200) = NULL,
	@ColumnValue varchar(2000) = NULL,
	@UserId varchar(50) = NULL
	
)
AS
BEGIN
	
	SET NOCOUNT ON;

	declare @sql nvarchar (max);
	
	IF @ColumnName='Delete' AND @TableName='MsmeRequirementBullets'
	BEGIN
		--delete from MsmeRequirementBullets where Id=@Id
		update MsmeRequirementBullets set ZedId=CONCAT(ZedId,'DELETED'),RequirementId=CONCAT(RequirementId,'DELETED') where Id=@Id

	END

	ELSE
	BEGIN
        -- Secured with QUOTENAME and REPLACE to prevent SQL injection
		SET @sql = CONCAT('UPDATE ', QUOTENAME(@TableName), ' SET ', QUOTENAME(@ColumnName), ' = ''', REPLACE(@ColumnValue, '''', ''''''), ''' WHERE Id = ', @Id);
		EXEC sp_executesql @sql;
	END

    -- THE FIX: Only return the specific row that was updated.
    -- (If your application doesn't actually use this data, you can delete this line entirely)
	SELECT * FROM MsmeRequirementBullets WHERE Id = @Id;
	
	
END


