/****** Object:  StoredProcedure [dbo].[SP_DASHBOARD_GET_DETAILS]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_DASHBOARD_GET_DETAILS] --'<redacted>','<redacted>'
(
	@UserId varchar(100) = NULL,
	@RoleId varchar(100) = NULL
)
AS
BEGIN
	SET NOCOUNT ON; -- Prevents extra network overhead from DONEINPROC messages

	DECLARE @State varchar(100) = NULL

	IF @State IS NULL OR @State=''
	BEGIN
		SELECT @State = StateCode FROM USERS WHERE UserId = @UserId and RoleId = 8
	END

	-- Define local variables to cache performance-heavy counts
	DECLARE 
		@AssessmentAgencies INT = 0, @DesktopAssessors INT = 0, @SiteAssessors INT = 0, @FinancialAssessors INT = 0,
		@BronzeCompleted INT = 0, @FaBronzeCompleted INT = 0, @BronzePending INT = 0,
		@SilverCompleted INT = 0, @FaSilverCompleted INT = 0, @SilverPending INT = 0,
		@GoldCompleted INT = 0, @FaGoldCompleted INT = 0, @GoldPending INT = 0,
		@BronzeTotal INT = 0, @SilverTotal INT = 0, @GoldTotal INT = 0,
		@FaTotal INT = 0, @FaPending INT = 0, @FaCompleted INT = 0,
		@SaSilverCompleted INT = 0, @SaGoldCompleted INT = 0, @SaSilverPending INT = 0, @SaGoldPending INT = 0,
		@BronzeRejected INT = 0, @SilverRejected INT = 0, @GoldRejected INT = 0,
		@SilverM1PaymentDone INT = 0, @SilverM2PaymentDone INT = 0, @SilverM3PaymentDone INT = 0,
		@GoldM1PaymentDone INT = 0, @GoldM2PaymentDone INT = 0, @GoldM3PaymentDone INT = 0;

	---------------------------------------------------------------------------------------------------------
	-- BRANCH 1: ROLE ID 7, 10, or 8
	---------------------------------------------------------------------------------------------------------
	IF @RoleId = 7 OR @RoleId = 10 OR @RoleId = 8
	BEGIN
		SELECT @AssessmentAgencies = COUNT(*) from Users where RoleId = 2;
		SELECT @DesktopAssessors = COUNT(*) from Users where RoleId = 3 and DesktopVerification = 1;
		SELECT @SiteAssessors = COUNT(*) from Users where RoleId = 3 and SiteVerification = 1;
		SELECT @FinancialAssessors = COUNT(*) from Users where RoleId = 3 and FinancialVerification = 1;

		SELECT @SilverCompleted = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver' and CertificationStatus=100 AND NcCount=1 AND (@State is null or M.StateId=@State);
		SELECT @SilverPending = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver' and CertificationStatus=100 AND NcCount=2 AND (@State is null or M.StateId=@State);
		SELECT @GoldCompleted = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Gold' and CertificationStatus=100 AND NcCount=1 AND (@State is null or M.StateId=@State);
		SELECT @FaGoldCompleted = count(*) from FinancialAssistance where CertificationType='Gold' and IsApproved=1;
		SELECT @GoldPending = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Gold' and CertificationStatus=100 AND NcCount=2 AND (@State is null or M.StateId=@State);

		SELECT @BronzeTotal = count(*) from Msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (B.ZedId=replace(P.ZedId,'_D','')) where P.Certification='Bronze' AND (@State is null or M.StateId=@State) and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476');
		SELECT @SilverTotal = count(*) from Msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (B.ZedId=replace(P.ZedId,'_D','')) where P.Certification='Silver' AND (@State is null or M.StateId=@State) and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476');
		SELECT @GoldTotal = count(*) from Msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (B.ZedId=replace(P.ZedId,'_D','')) where P.Certification='Gold' AND (@State is null or M.StateId=@State) and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476');

		SELECT @FaTotal = count(*) from FinancialAssistance where TechUpgradeStatus not in (0,1,7) and VerificationStatus!=5;
		SELECT @FaPending = count(*) from FinancialAssistance where TechUpgradeStatus in (2,3,4,5,6,8,9,10);
		SELECT @FaCompleted = count(*) from FinancialAssistance where TechUpgradeStatus=16 and VerificationStatus=6;

		SELECT @SaSilverCompleted = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver' and (CertificationStatus=100 OR CertificationStatus=16) AND NcCount=3 AND (@State is null or M.StateId=@State);
		SELECT @SaGoldCompleted = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Gold' and (CertificationStatus=100 OR CertificationStatus=16) AND NcCount=3 AND (@State is null or M.StateId=@State);
		SELECT @SaSilverPending = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver' and CertificationStatus in (8,9,13,14,15) AND (@State is null or M.StateId=@State);
		SELECT @SaGoldPending = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Gold' and CertificationStatus in (8,9,13,14,15) AND (@State is null or M.StateId=@State);

		SELECT @BronzeRejected = count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Bronze' and CertificationStatus=99 AND (@State is null or M.StateId=@State);
		SELECT @SilverRejected = count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Silver' and CertificationStatus=99 AND (@State is null or M.StateId=@State);
		SELECT @GoldRejected = count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Gold' and CertificationStatus=99 AND (@State is null or M.StateId=@State);

		SELECT @SilverM1PaymentDone = count(*) from MsmePaymentInfo C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Silver' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=1 AND (@State is null or M.StateId=@State);
		SELECT @SilverM2PaymentDone = count(*) from MsmePaymentInfo C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Silver' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=2 AND (@State is null or M.StateId=@State);
		SELECT @SilverM3PaymentDone = count(*) from MsmePaymentInfo C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Silver' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=3 AND (@State is null or M.StateId=@State);
		SELECT @GoldM1PaymentDone = count(*) from MsmePaymentInfo C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Gold' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=1 AND (@State is null or M.StateId=@State);
		SELECT @GoldM2PaymentDone = count(*) from MsmePaymentInfo C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Gold' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=2 AND (@State is null or M.StateId=@State);
		SELECT @GoldM3PaymentDone = count(*) from MsmePaymentInfo C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Gold' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=3 AND (@State is null or M.StateId=@State);
	END

	---------------------------------------------------------------------------------------------------------
	-- BRANCH 2: ROLE ID 2
	---------------------------------------------------------------------------------------------------------
	ELSE IF @RoleId = 2
	BEGIN
		SELECT @DesktopAssessors = count(*) from Users where RoleId=3 and DesktopVerification=1 and CreatedBy=@UserId;
		SELECT @SiteAssessors = count(*) from Users where RoleId=3 and SiteVerification=1 and CreatedBy=@UserId;
		SELECT @BronzeCompleted = count(*) from MsmeCertifications where Certification='Bronze' and CertificationBodyUserId=@UserId and DaCertificateNo is not null;
		SELECT @BronzePending = count(*) from MsmeCertifications where Certification='Bronze' and CertificationBodyUserId=@UserId and DaCertificateNo is null and CertificationStatus<6 and CertificationStatus>1;

		SELECT @SilverCompleted = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver' and CertificationStatus=100 AND NcCount=1 and CertificationBodyUserId=@UserId;
		SELECT @SilverPending = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver' and CertificationStatus=100 AND NcCount=2 and CertificationBodyUserId=@UserId;
		SELECT @GoldCompleted = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Gold' and CertificationStatus=100 AND NcCount=1 and CertificationBodyUserId=@UserId;
		SELECT @GoldPending = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Gold' and CertificationStatus=100 AND NcCount=2 and CertificationBodyUserId=@UserId;

		SELECT @SaSilverCompleted = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver' and CertificationStatus=100 AND NcCount=3 and CertificationBodyUserId=@UserId;
		SELECT @SaSilverPending = count(*) from MsmeCertifications where Certification='Silver' and ModeOfAssessment is not null and CertificationBodyUserId=@UserId and SaCertificateNo is null;
		SELECT @SaGoldCompleted = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Gold' and CertificationStatus=100 AND NcCount=3 and CertificationBodyUserId=@UserId;
		SELECT @SaGoldPending = count(*) from MsmeCertifications where Certification='Gold' and ModeOfAssessment is not null and CertificationBodyUserId=@UserId and SaCertificateNo is null;

		SELECT @BronzeTotal = SUM(counts) FROM (SELECT count(*) counts from MsmeCertifications where Certification='Bronze' and CertificationBodyUserId=@UserId and DaCertificateNo is not null UNION ALL SELECT count(*) counts from MsmeCertifications where Certification='Bronze' and CertificationBodyUserId=@UserId and DaCertificateNo is null) A;
		SELECT @SilverTotal = SUM(counts) FROM (SELECT count(*) counts from Msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmeCertifications C on (M.ZedId=C.ZedId) where Certification='Silver' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and CertificationBodyUserId=@UserId and NcCount=1) A;
		SELECT @GoldTotal = SUM(counts) FROM (SELECT count(*) counts from Msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmeCertifications C on (M.ZedId=C.ZedId) where Certification='Gold' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and CertificationBodyUserId=@UserId and NcCount=1) A;
		
		SELECT @FinancialAssessors = count(*) from Users where RoleId=3 and FinancialVerification=1 and CreatedBy=@UserId;
		SELECT @FaTotal = count(*) from FinancialAssistance where TechUpgradeStatus not in (0,1,7) and CertificationBodyUserId=@UserId;
		SELECT @FaPending = count(*) from FinancialAssistance where TechUpgradeStatus in (2,3,4,5,6,8,9,10) and CertificationBodyUserId=@UserId;
		SELECT @FaCompleted = count(*) from FinancialAssistance where TechUpgradeStatus=16 and VerificationStatus=6 and CertificationBodyUserId=@UserId;

		SELECT @BronzeRejected = count(*) from MsmeCertifications C inner join Msme M on (REPLACE(C.ZedId,'_D','')=M.ZedId) where Certification='Bronze' and CertificationStatus=99 AND (@State is null or StateId=@State);
		SELECT @SilverRejected = count(*) from MsmeCertifications C inner join Msme M on (REPLACE(C.ZedId,'_D','')=M.ZedId) where Certification='Silver' and CertificationStatus=99 AND (@State is null or StateId=@State);
		SELECT @GoldRejected = count(*) from MsmeCertifications C inner join Msme M on (REPLACE(C.ZedId,'_D','')=M.ZedId) where Certification='Gold' and CertificationStatus=99 AND (@State is null or StateId=@State);

		SELECT @SilverM1PaymentDone = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification and C.NcCount=P.MileStoneNum) where C.Certification='Silver' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=1 AND CertificationBodyUserId=@UserId;
		SELECT @SilverM2PaymentDone = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification and C.NcCount=P.MileStoneNum) where C.Certification='Silver' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=2 AND CertificationBodyUserId=@UserId;
		SELECT @SilverM3PaymentDone = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification and C.NcCount=P.MileStoneNum) where C.Certification='Silver' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=3 AND CertificationBodyUserId=@UserId;
		SELECT @GoldM1PaymentDone = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification and C.NcCount=P.MileStoneNum) where C.Certification='Gold' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=1 AND CertificationBodyUserId=@UserId;
		SELECT @GoldM2PaymentDone = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification and C.NcCount=P.MileStoneNum) where C.Certification='Gold' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=2 AND CertificationBodyUserId=@UserId;
		SELECT @GoldM3PaymentDone = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification and C.NcCount=P.MileStoneNum) where C.Certification='Gold' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=3 AND CertificationBodyUserId=@UserId;
	END

	---------------------------------------------------------------------------------------------------------
	-- BRANCH 3: ROLE ID 3
	---------------------------------------------------------------------------------------------------------
	ELSE IF @RoleId = 3
	BEGIN
		SELECT @BronzeCompleted = count(*) from MsmeCertifications where Certification='Bronze' and DesktopAssessorId=@UserId and DaCertificateNo is not null;
		SELECT @BronzePending = count(*) from MsmeCertifications where Certification='Bronze' and DesktopAssessorId=@UserId and DaCertificateNo is null;
		SELECT @SilverCompleted = count(*) from MsmeCertifications where Certification='Silver' and DesktopAssessorId=@UserId and DaCertificateNo is not null;
		SELECT @SilverPending = count(*) from MsmeCertifications where Certification='Silver' and DesktopAssessorId=@UserId and DaCertificateNo is null;
		SELECT @GoldCompleted = count(*) from MsmeCertifications where Certification='Gold' and DesktopAssessorId=@UserId and DaCertificateNo is not null;
		SELECT @GoldPending = count(*) from MsmeCertifications where Certification='Gold' and DesktopAssessorId=@UserId and DaCertificateNo is null;

		SELECT @SaSilverCompleted = count(*) from MsmeCertifications where Certification='Silver' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and SaCertificateNo is not null;
		SELECT @SaSilverPending = count(*) from MsmeCertifications where Certification='Silver' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and SaCertificateNo is null;
		SELECT @SaGoldCompleted = count(*) from MsmeCertifications where Certification='Gold' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and SaCertificateNo is not null;
		SELECT @SaGoldPending = count(*) from MsmeCertifications where Certification='Gold' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and SaCertificateNo is null;

		SELECT @BronzeTotal = SUM(counts) FROM (SELECT count(*) counts from MsmeCertifications where Certification='Bronze' and DesktopAssessorId=@UserId and DaCertificateNo is not null UNION ALL SELECT count(*) counts from MsmeCertifications where Certification='Bronze' and DesktopAssessorId=@UserId and DaCertificateNo is null) A;
		SELECT @SilverTotal = SUM(counts) FROM (SELECT count(*) counts from MsmeCertifications where Certification='Silver' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and DaCertificateNo is not null UNION ALL SELECT count(*) counts from MsmeCertifications where Certification='Silver' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and DaCertificateNo is null) A;
		SELECT @GoldTotal = SUM(counts) FROM (SELECT count(*) counts from MsmeCertifications where Certification='Gold' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and DaCertificateNo is not null UNION ALL SELECT count(*) counts from MsmeCertifications where Certification='Gold' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and DaCertificateNo is null) A;

		SELECT @FaTotal = count(*) from FinancialAssistance where TechUpgradeStatus=2 and VerificationStatus!=5 and FinancialAssessorId=@UserId;
		SELECT @FaPending = count(*) from FinancialAssistance where TechUpgradeStatus in (4,5,6,8) and VerificationStatus<5 and FinancialAssessorId=@UserId;
		SELECT @FaCompleted = count(*) from FinancialAssistance where TechUpgradeStatus=16 and VerificationStatus=6 and FinancialAssessorId=@UserId;

		SELECT @BronzeRejected = count(*) from MsmeCertifications C inner join Msme M on (REPLACE(C.ZedId,'_D','')=M.ZedId) where Certification='Bronze' and CertificationStatus=99 and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId);
		SELECT @SilverRejected = count(*) from MsmeCertifications C inner join Msme M on (REPLACE(C.ZedId,'_D','')=M.ZedId) where Certification='Silver' and CertificationStatus=99 and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId);
		SELECT @GoldRejected = count(*) from MsmeCertifications C inner join Msme M on (REPLACE(C.ZedId,'_D','')=M.ZedId) where Certification='Gold' and CertificationStatus=99 and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId);

		SELECT @SilverM1PaymentDone = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification) where C.Certification='Silver' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=1 AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId);
		SELECT @SilverM2PaymentDone = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification) where C.Certification='Silver' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=2 AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId);
		SELECT @SilverM3PaymentDone = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification) where C.Certification='Silver' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=3 AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId);
		SELECT @GoldM1PaymentDone = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification) where C.Certification='Gold' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=1 AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId);
		SELECT @GoldM2PaymentDone = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification) where C.Certification='Gold' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=2 AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId);
		SELECT @GoldM3PaymentDone = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification) where C.Certification='Gold' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=3 AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId);
	END

	---------------------------------------------------------------------------------------------------------
	-- FINAL OUTPUT RETRIEVAL (Instant Response)
	---------------------------------------------------------------------------------------------------------
	SELECT 
		@AssessmentAgencies AS AssessmentAgencies,
		@DesktopAssessors AS DesktopAssessors, 
		@SiteAssessors AS SiteAssessors,  
		@FinancialAssessors AS FinancialAssessors,
		@BronzeCompleted AS BronzeCompleted,
		@FaBronzeCompleted AS FaBronzeCompleted,		
		@BronzePending AS BronzePending,
		@SilverCompleted AS SilverCompleted, 
		@FaSilverCompleted AS FaSilverCompleted,
		@SilverPending AS SilverPending, 
		@GoldCompleted AS GoldCompleted,
		@FaGoldCompleted AS FaGoldCompleted,
		@GoldPending AS GoldPending,
		@BronzeTotal AS BronzeTotal,
		@SilverTotal AS SilverTotal,
		@GoldTotal AS GoldTotal,
		@FaTotal AS FaTotal,
		@FaPending AS FaPending,
		@FaCompleted AS FaCompleted,
		@SaSilverCompleted AS SaSilverCompleted, 
		@SaGoldCompleted AS SaGoldCompleted,
		@SaSilverPending AS SaSilverPending, 
		@SaGoldPending AS SaGoldPending,
		@BronzeRejected AS BronzeRejected,
		@SilverRejected AS SilverRejected,
		@GoldRejected AS GoldRejected,
		@SilverM1PaymentDone AS SilverM1PaymentDone,
		@SilverM2PaymentDone AS SilverM2PaymentDone,
		@SilverM3PaymentDone AS SilverM3PaymentDone,
		@GoldM1PaymentDone AS GoldM1PaymentDone,
		@GoldM2PaymentDone AS GoldM2PaymentDone,
		@GoldM3PaymentDone AS GoldM3PaymentDone;

END
GO
/****** Object:  StoredProcedure [dbo].[SP_DASHBOARD_GET_DETAILS_backup]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

--[SP_DASHBOARD_GET_DETAILS] '<redacted>','<redacted>'
create PROC [dbo].[SP_DASHBOARD_GET_DETAILS_backup] --'<redacted>','<redacted>'
(
	@UserId varchar(100) = NULL,
	@RoleId varchar(100) = NULL
)
AS
BEGIN
	
		DECLARE @State varchar(100) =NULL

		IF @State IS NULL OR @State=''
		BEGIN
		SELECT @State=StateCode FROM USERS WHERE UserId=@UserId and RoleId=8
		END

		IF @RoleId=7 OR @RoleId=10 OR @RoleId=8
		BEGIN
				SELECT (select count(*) from Users where RoleId=2) AssessmentAgencies,
			   (select count(*) from Users where RoleId=3 and DesktopVerification=1) DesktopAssessors, (select count(*) from Users where RoleId=3 and SiteVerification=1) SiteAssessors,  
			   (select count(*) from Users where RoleId=3 and FinancialVerification=1) FinancialAssessors,
			   0 BronzeCompleted,
			   0 FaBronzeCompleted,		
			   0 BronzePending,
				
			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) 
			    inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
			   where  UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver' and CertificationStatus=100 AND NcCount=1 AND (@State is null or M.StateId=@State)) SilverCompleted, 
			   0 FaSilverCompleted,

			   
				(select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) 
				inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
			   where  UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
				and Certification='Silver' and CertificationStatus=100 AND NcCount=2  AND (@State is null or M.StateId=@State)) SilverPending, 

			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) 
			   inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
			   where  UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
			   and Certification='Gold' and CertificationStatus=100 AND NcCount=1 AND (@State is null or M.StateId=@State)) GoldCompleted,
			   (select count(*) from FinancialAssistance where CertificationType='Gold' and IsApproved=1) FaGoldCompleted,

			   
				(select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) 
				inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
			   where  UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
				and Certification='Gold' and CertificationStatus=100 AND NcCount=2 AND (@State is null or M.StateId=@State)) GoldPending,

		


				 (select count(*) from Msme M inner join MsmeBasicInformation B  on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (B.ZedId=replace(P.ZedId,'_D',''))
				where P.Certification='Bronze' AND (@State is null or M.StateId=@State) and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')) BronzeTotal,

				(select count(*) from Msme M inner join MsmeBasicInformation B  on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (B.ZedId=replace(P.ZedId,'_D',''))
				where P.Certification='Silver' AND (@State is null or M.StateId=@State) and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')) SilverTotal,

				(select count(*) from Msme M inner join MsmeBasicInformation B  on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (B.ZedId=replace(P.ZedId,'_D',''))
				where P.Certification='Gold' AND (@State is null or M.StateId=@State) and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')) GoldTotal,




			   (select count(*) from FinancialAssistance where TechUpgradeStatus not in (0,1,7) and VerificationStatus!=5) FaTotal,
			   (select count(*) from FinancialAssistance where TechUpgradeStatus in (2,3,4,5,6,8,9,10)) FaPending,
			   (select count(*) from FinancialAssistance where TechUpgradeStatus=16 and VerificationStatus=6) FaCompleted,

			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) 
			   inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
			   where  UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
			   and Certification='Silver' 
			   and (CertificationStatus=100 OR  CertificationStatus=16) AND NcCount=3 AND (@State is null or M.StateId=@State)) SaSilverCompleted, 

			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) 
			   inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
			   where  UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
			   and Certification='Gold' and (CertificationStatus=100 OR CertificationStatus=16) AND NcCount=3 AND (@State is null or M.StateId=@State)) SaGoldCompleted,

			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) 
			   inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
			   where  UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
			   and Certification='Silver' and CertificationStatus in (8,9,13,14,15) AND (@State is null or M.StateId=@State)) SaSilverPending, 

			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) 
			   inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
			   where  UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
			   and Certification='Gold' and CertificationStatus in (8,9,13,14,15) AND (@State is null or M.StateId=@State)) SaGoldPending,

			    (select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Bronze' and CertificationStatus=99 AND (@State is null or M.StateId=@State)) BronzeRejected,

			    (select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Silver' and CertificationStatus=99 AND (@State is null or M.StateId=@State)) SilverRejected,

			    (select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Gold' and CertificationStatus=99 AND (@State is null or M.StateId=@State)) GoldRejected,

			   (select count(*) from MsmePaymentInfo C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Silver' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=1 AND (@State is null or M.StateId=@State)) SilverM1PaymentDone,

			   (select count(*) from MsmePaymentInfo C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Silver' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=2 AND (@State is null or M.StateId=@State)) SilverM2PaymentDone,

			   (select count(*) from MsmePaymentInfo C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Silver' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=3 AND (@State is null or M.StateId=@State)) SilverM3PaymentDone,

			   (select count(*) from MsmePaymentInfo C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Gold' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=1 AND (@State is null or M.StateId=@State)) GoldM1PaymentDone,

			   (select count(*) from MsmePaymentInfo C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Gold' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=2 AND (@State is null or M.StateId=@State)) GoldM2PaymentDone,

			   (select count(*) from MsmePaymentInfo C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Gold' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=3 AND (@State is null or M.StateId=@State)) GoldM3PaymentDone
		END

		ELSE IF @RoleId=2
		BEGIN
		SELECT 0 AssessmentAgencies,
			   (select count(*) from Users where RoleId=3 and DesktopVerification=1 and CreatedBy=@UserId) DesktopAssessors, 
			   (select count(*) from Users where RoleId=3 and SiteVerification=1 and  CreatedBy=@UserId) SiteAssessors,
			   (select count(*) from MsmeCertifications where Certification='Bronze' and CertificationBodyUserId=@UserId and DaCertificateNo is not null ) BronzeCompleted,
			   (select count(*) from MsmeCertifications where Certification='Bronze' and CertificationBodyUserId=@UserId and DaCertificateNo is null and CertificationStatus<6 and CertificationStatus>1) BronzePending, 

			
			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) 
			    inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
			   where  UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver' and CertificationStatus=100 AND NcCount=1 and CertificationBodyUserId=@UserId) SilverCompleted, 
			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) 
			    inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
			   where  UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver' and CertificationStatus=100 AND NcCount=2 and CertificationBodyUserId=@UserId) SilverPending, 
			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) 
			    inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
			   where  UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Gold' and CertificationStatus=100 AND NcCount=1 and CertificationBodyUserId=@UserId) GoldCompleted,
			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) 
			    inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
			   where  UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Gold' and CertificationStatus=100 AND NcCount=2 and CertificationBodyUserId=@UserId) GoldPending,

			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) 
			    inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
			   where  UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver' and CertificationStatus=100 AND NcCount=3 and CertificationBodyUserId=@UserId) SaSilverCompleted, 
			   (select count(*) from MsmeCertifications where Certification='Silver' and ModeOfAssessment is not null and CertificationBodyUserId=@UserId and SaCertificateNo is null) SaSilverPending, 
			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) 
			    inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
			   where  UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Gold' and CertificationStatus=100 AND NcCount=3 and CertificationBodyUserId=@UserId) SaGoldCompleted,
			   (select count(*) from MsmeCertifications where Certification='Gold' and ModeOfAssessment is not null and CertificationBodyUserId=@UserId and SaCertificateNo is null) SaGoldPending,

			   (select sum(counts) from (
			   (select count(*) counts from MsmeCertifications where Certification='Bronze' and CertificationBodyUserId=@UserId and DaCertificateNo is not null) union all
			   (select count(*) counts from MsmeCertifications where Certification='Bronze' and CertificationBodyUserId=@UserId and DaCertificateNo is null))A) BronzeTotal, 
			   (select sum(counts) from (
			   (select count(*) counts from Msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join  MsmeCertifications C on (M.ZedId=C.ZedId) where Certification='Silver' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and CertificationBodyUserId=@UserId and NcCount=1))A) SilverTotal, 
			    (select sum(counts) from (
			   (select count(*) counts from Msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join  MsmeCertifications C on (M.ZedId=C.ZedId) where Certification='Gold' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and CertificationBodyUserId=@UserId and NcCount=1))A) GoldTotal,
			   --(select sum(counts) from (
			   --(select count(*) counts from MsmeCertifications where Certification='<redacted>' and CertificationBodyUserId=@UserId and DaCertificateNo is not null) union all
			   --(select count(*) counts from MsmeCertifications where Certification='<redacted>' and CertificationBodyUserId=@UserId and DaCertificateNo is null))A) GoldTotal,
			   (select count(*) from Users where RoleId=3 and FinancialVerification=1 and  CreatedBy=@UserId) FinancialAssessors,

			   (select count(*) from FinancialAssistance where TechUpgradeStatus not in (0,1,7) and CertificationBodyUserId=@UserId) FaTotal,
			   (select count(*) from FinancialAssistance where TechUpgradeStatus in (2,3,4,5,6,8,9,10)  and CertificationBodyUserId=@UserId) FaPending,
			   (select count(*) from FinancialAssistance where TechUpgradeStatus=16 and VerificationStatus=6  and CertificationBodyUserId=@UserId) FaCompleted,


			   --(select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('<redacted>', C.ZedId + '<redacted>') - 1)=M.ZedId) where Certification='<redacted>' and CertificationStatus=99 and CertificationBodyUserId=@UserId) BronzeRejected,

			   --(select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('<redacted>', C.ZedId + '<redacted>') - 1)=M.ZedId) where Certification='<redacted>' and CertificationStatus=99 and  CertificationBodyUserId=@UserId) SilverRejected,

			   --(select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('<redacted>', C.ZedId + '<redacted>') - 1)=M.ZedId) where Certification='<redacted>' and CertificationStatus=99 and CertificationBodyUserId=@UserId) GoldRejected,

			   	(select count(*) from MsmeCertifications C inner join Msme M on (REPLACE(C.ZedId,'_D','')=M.ZedId) where Certification='Bronze' and CertificationStatus=99 AND (@State is null or StateId=@State)) BronzeRejected,

			   (select count(*) from MsmeCertifications C inner join Msme M on (REPLACE(C.ZedId,'_D','')=M.ZedId) where Certification='Silver' and CertificationStatus=99 AND (@State is null or StateId=@State)) SilverRejected,

			   (select count(*) from MsmeCertifications C inner join Msme M on (REPLACE(C.ZedId,'_D','')=M.ZedId) where Certification='Gold' and CertificationStatus=99 AND (@State is null or StateId=@State)) GoldRejected,

			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification and C.NcCount=P.MileStoneNum) where C.Certification='Silver' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=1 AND CertificationBodyUserId=@UserId ) SilverM1PaymentDone,
																								 																																											 																							
			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification and C.NcCount=P.MileStoneNum) where C.Certification='Silver' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=2 AND CertificationBodyUserId=@UserId) SilverM2PaymentDone,
																																																																			 																							
			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification and C.NcCount=P.MileStoneNum) where C.Certification='Silver' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=3 AND CertificationBodyUserId=@UserId) SilverM3PaymentDone,
																								 																																											 																							
			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification and C.NcCount=P.MileStoneNum) where C.Certification='Gold'   and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=1 AND CertificationBodyUserId=@UserId) GoldM1PaymentDone,
																								 																																																																		
			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification and C.NcCount=P.MileStoneNum) where C.Certification='Gold'   and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=2 AND CertificationBodyUserId=@UserId) GoldM2PaymentDone,
																																																																			 																							
			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification and C.NcCount=P.MileStoneNum) where C.Certification='Gold'   and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=3 AND CertificationBodyUserId=@UserId) GoldM3PaymentDone
		END

		ELSE IF @RoleId=3
		BEGIN
		SELECT 0 AssessmentAgencies,
			   0 DesktopAssessors,	
			   0 SiteAssessors,
			   (select count(*) from MsmeCertifications where Certification='Bronze' and DesktopAssessorId=@UserId and DaCertificateNo is not null) BronzeCompleted,
			   (select count(*) from MsmeCertifications where Certification='Bronze' and DesktopAssessorId=@UserId and DaCertificateNo is null) BronzePending, 
			   (select count(*) from MsmeCertifications where Certification='Silver' and DesktopAssessorId=@UserId and DaCertificateNo is not null) SilverCompleted, 
			   (select count(*) from MsmeCertifications where Certification='Silver' and DesktopAssessorId=@UserId and DaCertificateNo is null) SilverPending, 
			   (select count(*) from MsmeCertifications where Certification='Gold' and DesktopAssessorId=@UserId and DaCertificateNo is not null) GoldCompleted,
			   (select count(*) from MsmeCertifications where Certification='Gold' and DesktopAssessorId=@UserId and DaCertificateNo is null) GoldPending,

			   (select count(*) from MsmeCertifications where Certification='Silver' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and SaCertificateNo is not null) SaSilverCompleted, 
			   (select count(*) from MsmeCertifications where Certification='Silver' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and SaCertificateNo is null) SaSilverPending, 
			   (select count(*) from MsmeCertifications where Certification='Gold' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and SaCertificateNo is not null) SaGoldCompleted,
			   (select count(*) from MsmeCertifications where Certification='Gold' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and SaCertificateNo is null) SaGoldPending,

			   (select sum(counts) from (
			   (select count(*) counts from MsmeCertifications where Certification='Bronze' and DesktopAssessorId=@UserId and DaCertificateNo is not null) union all
			   (select count(*) counts from MsmeCertifications where Certification='Bronze' and DesktopAssessorId=@UserId and DaCertificateNo is null))A) BronzeTotal, 
			   (select sum(counts) from (
			   (select count(*) counts from MsmeCertifications where Certification='Silver' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and DaCertificateNo is not null) union all
			   (select count(*) counts from MsmeCertifications where Certification='Silver' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and DaCertificateNo is null))A) SilverTotal, 
			   (select sum(counts) from (
			   (select count(*) counts from MsmeCertifications where Certification='Gold' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and DaCertificateNo is not null) union all
			   (select count(*) counts from MsmeCertifications where Certification='Gold' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and DaCertificateNo is null))A) GoldTotal,

			
			   (select count(*) from FinancialAssistance where TechUpgradeStatus=2 and VerificationStatus!=5 and FinancialAssessorId=@UserId) FaTotal,
			   (select count(*) from FinancialAssistance where TechUpgradeStatus in (4,5,6,8) and VerificationStatus<5 and FinancialAssessorId=@UserId) FaPending,
			   (select count(*) from FinancialAssistance where TechUpgradeStatus=16 and VerificationStatus=6 and FinancialAssessorId=@UserId) FaCompleted,

			    (select count(*) from MsmeCertifications C inner join Msme M on (REPLACE(C.ZedId,'_D','')=M.ZedId) where Certification='Bronze' and CertificationStatus=99 and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId)) BronzeRejected,

			   (select count(*) from MsmeCertifications C inner join Msme M on (REPLACE(C.ZedId,'_D','')=M.ZedId) where Certification='Silver' and CertificationStatus=99 and  (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId)) SilverRejected,

			   (select count(*) from MsmeCertifications C inner join Msme M on (REPLACE(C.ZedId,'_D','')=M.ZedId) where Certification='Gold' and CertificationStatus=99 and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId)) GoldRejected,

			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId)inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification) where C.Certification='Silver' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=1 AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) ) SilverM1PaymentDone,
																								 																																										
			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId)inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification) where C.Certification='Silver' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=2 AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId)) SilverM2PaymentDone,
																								 																																											
			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId)inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification) where C.Certification='Silver' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=3 AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId)) SilverM3PaymentDone,
																								 																																											
			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId)inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification) where C.Certification='Gold'   and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=1 AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId)) GoldM1PaymentDone,
																																																																			 
			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId)inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification) where C.Certification='Gold'   and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=2 AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId)) GoldM2PaymentDone,
																																																																		
			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId)inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification) where C.Certification='Gold'   and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=3 AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId)) GoldM3PaymentDone

		END
		

END





GO
/****** Object:  StoredProcedure [dbo].[SP_DASHBOARD_GET_DETAILS_optimized]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

create PROC [dbo].[SP_DASHBOARD_GET_DETAILS_optimized] --'<redacted>','<redacted>'
(
	@UserId varchar(100) = NULL,
	@RoleId varchar(100) = NULL
)
AS
BEGIN
	SET NOCOUNT ON; -- Prevents extra network overhead from DONEINPROC messages

	DECLARE @State varchar(100) = NULL

	IF @State IS NULL OR @State=''
	BEGIN
		SELECT @State = StateCode FROM USERS WHERE UserId = @UserId and RoleId = 8
	END

	-- Define local variables to cache performance-heavy counts
	DECLARE 
		@AssessmentAgencies INT = 0, @DesktopAssessors INT = 0, @SiteAssessors INT = 0, @FinancialAssessors INT = 0,
		@BronzeCompleted INT = 0, @FaBronzeCompleted INT = 0, @BronzePending INT = 0,
		@SilverCompleted INT = 0, @FaSilverCompleted INT = 0, @SilverPending INT = 0,
		@GoldCompleted INT = 0, @FaGoldCompleted INT = 0, @GoldPending INT = 0,
		@BronzeTotal INT = 0, @SilverTotal INT = 0, @GoldTotal INT = 0,
		@FaTotal INT = 0, @FaPending INT = 0, @FaCompleted INT = 0,
		@SaSilverCompleted INT = 0, @SaGoldCompleted INT = 0, @SaSilverPending INT = 0, @SaGoldPending INT = 0,
		@BronzeRejected INT = 0, @SilverRejected INT = 0, @GoldRejected INT = 0,
		@SilverM1PaymentDone INT = 0, @SilverM2PaymentDone INT = 0, @SilverM3PaymentDone INT = 0,
		@GoldM1PaymentDone INT = 0, @GoldM2PaymentDone INT = 0, @GoldM3PaymentDone INT = 0;

	---------------------------------------------------------------------------------------------------------
	-- BRANCH 1: ROLE ID 7, 10, or 8
	---------------------------------------------------------------------------------------------------------
	IF @RoleId = 7 OR @RoleId = 10 OR @RoleId = 8
	BEGIN
		SELECT @AssessmentAgencies = COUNT(*) from Users where RoleId = 2;
		SELECT @DesktopAssessors = COUNT(*) from Users where RoleId = 3 and DesktopVerification = 1;
		SELECT @SiteAssessors = COUNT(*) from Users where RoleId = 3 and SiteVerification = 1;
		SELECT @FinancialAssessors = COUNT(*) from Users where RoleId = 3 and FinancialVerification = 1;

		SELECT @SilverCompleted = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver' and CertificationStatus=100 AND NcCount=1 AND (@State is null or M.StateId=@State);
		SELECT @SilverPending = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver' and CertificationStatus=100 AND NcCount=2 AND (@State is null or M.StateId=@State);
		SELECT @GoldCompleted = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Gold' and CertificationStatus=100 AND NcCount=1 AND (@State is null or M.StateId=@State);
		SELECT @FaGoldCompleted = count(*) from FinancialAssistance where CertificationType='Gold' and IsApproved=1;
		SELECT @GoldPending = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Gold' and CertificationStatus=100 AND NcCount=2 AND (@State is null or M.StateId=@State);

		SELECT @BronzeTotal = count(*) from Msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (B.ZedId=replace(P.ZedId,'_D','')) where P.Certification='Bronze' AND (@State is null or M.StateId=@State) and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476');
		SELECT @SilverTotal = count(*) from Msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (B.ZedId=replace(P.ZedId,'_D','')) where P.Certification='Silver' AND (@State is null or M.StateId=@State) and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476');
		SELECT @GoldTotal = count(*) from Msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (B.ZedId=replace(P.ZedId,'_D','')) where P.Certification='Gold' AND (@State is null or M.StateId=@State) and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476');

		SELECT @FaTotal = count(*) from FinancialAssistance where TechUpgradeStatus not in (0,1,7) and VerificationStatus!=5;
		SELECT @FaPending = count(*) from FinancialAssistance where TechUpgradeStatus in (2,3,4,5,6,8,9,10);
		SELECT @FaCompleted = count(*) from FinancialAssistance where TechUpgradeStatus=16 and VerificationStatus=6;

		SELECT @SaSilverCompleted = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver' and (CertificationStatus=100 OR CertificationStatus=16) AND NcCount=3 AND (@State is null or M.StateId=@State);
		SELECT @SaGoldCompleted = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Gold' and (CertificationStatus=100 OR CertificationStatus=16) AND NcCount=3 AND (@State is null or M.StateId=@State);
		SELECT @SaSilverPending = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver' and CertificationStatus in (8,9,13,14,15) AND (@State is null or M.StateId=@State);
		SELECT @SaGoldPending = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Gold' and CertificationStatus in (8,9,13,14,15) AND (@State is null or M.StateId=@State);

		SELECT @BronzeRejected = count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Bronze' and CertificationStatus=99 AND (@State is null or M.StateId=@State);
		SELECT @SilverRejected = count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Silver' and CertificationStatus=99 AND (@State is null or M.StateId=@State);
		SELECT @GoldRejected = count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Gold' and CertificationStatus=99 AND (@State is null or M.StateId=@State);

		SELECT @SilverM1PaymentDone = count(*) from MsmePaymentInfo C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Silver' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=1 AND (@State is null or M.StateId=@State);
		SELECT @SilverM2PaymentDone = count(*) from MsmePaymentInfo C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Silver' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=2 AND (@State is null or M.StateId=@State);
		SELECT @SilverM3PaymentDone = count(*) from MsmePaymentInfo C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Silver' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=3 AND (@State is null or M.StateId=@State);
		SELECT @GoldM1PaymentDone = count(*) from MsmePaymentInfo C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Gold' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=1 AND (@State is null or M.StateId=@State);
		SELECT @GoldM2PaymentDone = count(*) from MsmePaymentInfo C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Gold' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=2 AND (@State is null or M.StateId=@State);
		SELECT @GoldM3PaymentDone = count(*) from MsmePaymentInfo C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Gold' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=3 AND (@State is null or M.StateId=@State);
	END

	---------------------------------------------------------------------------------------------------------
	-- BRANCH 2: ROLE ID 2
	---------------------------------------------------------------------------------------------------------
	ELSE IF @RoleId = 2
	BEGIN
		SELECT @DesktopAssessors = count(*) from Users where RoleId=3 and DesktopVerification=1 and CreatedBy=@UserId;
		SELECT @SiteAssessors = count(*) from Users where RoleId=3 and SiteVerification=1 and CreatedBy=@UserId;
		SELECT @BronzeCompleted = count(*) from MsmeCertifications where Certification='Bronze' and CertificationBodyUserId=@UserId and DaCertificateNo is not null;
		SELECT @BronzePending = count(*) from MsmeCertifications where Certification='Bronze' and CertificationBodyUserId=@UserId and DaCertificateNo is null and CertificationStatus<6 and CertificationStatus>1;

		SELECT @SilverCompleted = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver' and CertificationStatus=100 AND NcCount=1 and CertificationBodyUserId=@UserId;
		SELECT @SilverPending = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver' and CertificationStatus=100 AND NcCount=2 and CertificationBodyUserId=@UserId;
		SELECT @GoldCompleted = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Gold' and CertificationStatus=100 AND NcCount=1 and CertificationBodyUserId=@UserId;
		SELECT @GoldPending = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Gold' and CertificationStatus=100 AND NcCount=2 and CertificationBodyUserId=@UserId;

		SELECT @SaSilverCompleted = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver' and CertificationStatus=100 AND NcCount=3 and CertificationBodyUserId=@UserId;
		SELECT @SaSilverPending = count(*) from MsmeCertifications where Certification='Silver' and ModeOfAssessment is not null and CertificationBodyUserId=@UserId and SaCertificateNo is null;
		SELECT @SaGoldCompleted = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Gold' and CertificationStatus=100 AND NcCount=3 and CertificationBodyUserId=@UserId;
		SELECT @SaGoldPending = count(*) from MsmeCertifications where Certification='Gold' and ModeOfAssessment is not null and CertificationBodyUserId=@UserId and SaCertificateNo is null;

		SELECT @BronzeTotal = SUM(counts) FROM (SELECT count(*) counts from MsmeCertifications where Certification='Bronze' and CertificationBodyUserId=@UserId and DaCertificateNo is not null UNION ALL SELECT count(*) counts from MsmeCertifications where Certification='Bronze' and CertificationBodyUserId=@UserId and DaCertificateNo is null) A;
		SELECT @SilverTotal = SUM(counts) FROM (SELECT count(*) counts from Msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmeCertifications C on (M.ZedId=C.ZedId) where Certification='Silver' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and CertificationBodyUserId=@UserId and NcCount=1) A;
		SELECT @GoldTotal = SUM(counts) FROM (SELECT count(*) counts from Msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmeCertifications C on (M.ZedId=C.ZedId) where Certification='Gold' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and CertificationBodyUserId=@UserId and NcCount=1) A;
		
		SELECT @FinancialAssessors = count(*) from Users where RoleId=3 and FinancialVerification=1 and CreatedBy=@UserId;
		SELECT @FaTotal = count(*) from FinancialAssistance where TechUpgradeStatus not in (0,1,7) and CertificationBodyUserId=@UserId;
		SELECT @FaPending = count(*) from FinancialAssistance where TechUpgradeStatus in (2,3,4,5,6,8,9,10) and CertificationBodyUserId=@UserId;
		SELECT @FaCompleted = count(*) from FinancialAssistance where TechUpgradeStatus=16 and VerificationStatus=6 and CertificationBodyUserId=@UserId;

		SELECT @BronzeRejected = count(*) from MsmeCertifications C inner join Msme M on (REPLACE(C.ZedId,'_D','')=M.ZedId) where Certification='Bronze' and CertificationStatus=99 AND (@State is null or StateId=@State);
		SELECT @SilverRejected = count(*) from MsmeCertifications C inner join Msme M on (REPLACE(C.ZedId,'_D','')=M.ZedId) where Certification='Silver' and CertificationStatus=99 AND (@State is null or StateId=@State);
		SELECT @GoldRejected = count(*) from MsmeCertifications C inner join Msme M on (REPLACE(C.ZedId,'_D','')=M.ZedId) where Certification='Gold' and CertificationStatus=99 AND (@State is null or StateId=@State);

		SELECT @SilverM1PaymentDone = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification and C.NcCount=P.MileStoneNum) where C.Certification='Silver' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=1 AND CertificationBodyUserId=@UserId;
		SELECT @SilverM2PaymentDone = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification and C.NcCount=P.MileStoneNum) where C.Certification='Silver' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=2 AND CertificationBodyUserId=@UserId;
		SELECT @SilverM3PaymentDone = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification and C.NcCount=P.MileStoneNum) where C.Certification='Silver' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=3 AND CertificationBodyUserId=@UserId;
		SELECT @GoldM1PaymentDone = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification and C.NcCount=P.MileStoneNum) where C.Certification='Gold' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=1 AND CertificationBodyUserId=@UserId;
		SELECT @GoldM2PaymentDone = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification and C.NcCount=P.MileStoneNum) where C.Certification='Gold' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=2 AND CertificationBodyUserId=@UserId;
		SELECT @GoldM3PaymentDone = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification and C.NcCount=P.MileStoneNum) where C.Certification='Gold' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=3 AND CertificationBodyUserId=@UserId;
	END

	---------------------------------------------------------------------------------------------------------
	-- BRANCH 3: ROLE ID 3
	---------------------------------------------------------------------------------------------------------
	ELSE IF @RoleId = 3
	BEGIN
		SELECT @BronzeCompleted = count(*) from MsmeCertifications where Certification='Bronze' and DesktopAssessorId=@UserId and DaCertificateNo is not null;
		SELECT @BronzePending = count(*) from MsmeCertifications where Certification='Bronze' and DesktopAssessorId=@UserId and DaCertificateNo is null;
		SELECT @SilverCompleted = count(*) from MsmeCertifications where Certification='Silver' and DesktopAssessorId=@UserId and DaCertificateNo is not null;
		SELECT @SilverPending = count(*) from MsmeCertifications where Certification='Silver' and DesktopAssessorId=@UserId and DaCertificateNo is null;
		SELECT @GoldCompleted = count(*) from MsmeCertifications where Certification='Gold' and DesktopAssessorId=@UserId and DaCertificateNo is not null;
		SELECT @GoldPending = count(*) from MsmeCertifications where Certification='Gold' and DesktopAssessorId=@UserId and DaCertificateNo is null;

		SELECT @SaSilverCompleted = count(*) from MsmeCertifications where Certification='Silver' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and SaCertificateNo is not null;
		SELECT @SaSilverPending = count(*) from MsmeCertifications where Certification='Silver' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and SaCertificateNo is null;
		SELECT @SaGoldCompleted = count(*) from MsmeCertifications where Certification='Gold' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and SaCertificateNo is not null;
		SELECT @SaGoldPending = count(*) from MsmeCertifications where Certification='Gold' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and SaCertificateNo is null;

		SELECT @BronzeTotal = SUM(counts) FROM (SELECT count(*) counts from MsmeCertifications where Certification='Bronze' and DesktopAssessorId=@UserId and DaCertificateNo is not null UNION ALL SELECT count(*) counts from MsmeCertifications where Certification='Bronze' and DesktopAssessorId=@UserId and DaCertificateNo is null) A;
		SELECT @SilverTotal = SUM(counts) FROM (SELECT count(*) counts from MsmeCertifications where Certification='Silver' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and DaCertificateNo is not null UNION ALL SELECT count(*) counts from MsmeCertifications where Certification='Silver' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and DaCertificateNo is null) A;
		SELECT @GoldTotal = SUM(counts) FROM (SELECT count(*) counts from MsmeCertifications where Certification='Gold' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and DaCertificateNo is not null UNION ALL SELECT count(*) counts from MsmeCertifications where Certification='Gold' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and DaCertificateNo is null) A;

		SELECT @FaTotal = count(*) from FinancialAssistance where TechUpgradeStatus=2 and VerificationStatus!=5 and FinancialAssessorId=@UserId;
		SELECT @FaPending = count(*) from FinancialAssistance where TechUpgradeStatus in (4,5,6,8) and VerificationStatus<5 and FinancialAssessorId=@UserId;
		SELECT @FaCompleted = count(*) from FinancialAssistance where TechUpgradeStatus=16 and VerificationStatus=6 and FinancialAssessorId=@UserId;

		SELECT @BronzeRejected = count(*) from MsmeCertifications C inner join Msme M on (REPLACE(C.ZedId,'_D','')=M.ZedId) where Certification='Bronze' and CertificationStatus=99 and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId);
		SELECT @SilverRejected = count(*) from MsmeCertifications C inner join Msme M on (REPLACE(C.ZedId,'_D','')=M.ZedId) where Certification='Silver' and CertificationStatus=99 and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId);
		SELECT @GoldRejected = count(*) from MsmeCertifications C inner join Msme M on (REPLACE(C.ZedId,'_D','')=M.ZedId) where Certification='Gold' and CertificationStatus=99 and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId);

		SELECT @SilverM1PaymentDone = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification) where C.Certification='Silver' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=1 AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId);
		SELECT @SilverM2PaymentDone = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification) where C.Certification='Silver' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=2 AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId);
		SELECT @SilverM3PaymentDone = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification) where C.Certification='Silver' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=3 AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId);
		SELECT @GoldM1PaymentDone = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification) where C.Certification='Gold' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=1 AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId);
		SELECT @GoldM2PaymentDone = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification) where C.Certification='Gold' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=2 AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId);
		SELECT @GoldM3PaymentDone = count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification) where C.Certification='Gold' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=3 AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId);
	END

	---------------------------------------------------------------------------------------------------------
	-- FINAL OUTPUT RETRIEVAL (Instant Response)
	---------------------------------------------------------------------------------------------------------
	SELECT 
		@AssessmentAgencies AS AssessmentAgencies,
		@DesktopAssessors AS DesktopAssessors, 
		@SiteAssessors AS SiteAssessors,  
		@FinancialAssessors AS FinancialAssessors,
		@BronzeCompleted AS BronzeCompleted,
		@FaBronzeCompleted AS FaBronzeCompleted,		
		@BronzePending AS BronzePending,
		@SilverCompleted AS SilverCompleted, 
		@FaSilverCompleted AS FaSilverCompleted,
		@SilverPending AS SilverPending, 
		@GoldCompleted AS GoldCompleted,
		@FaGoldCompleted AS FaGoldCompleted,
		@GoldPending AS GoldPending,
		@BronzeTotal AS BronzeTotal,
		@SilverTotal AS SilverTotal,
		@GoldTotal AS GoldTotal,
		@FaTotal AS FaTotal,
		@FaPending AS FaPending,
		@FaCompleted AS FaCompleted,
		@SaSilverCompleted AS SaSilverCompleted, 
		@SaGoldCompleted AS SaGoldCompleted,
		@SaSilverPending AS SaSilverPending, 
		@SaGoldPending AS SaGoldPending,
		@BronzeRejected AS BronzeRejected,
		@SilverRejected AS SilverRejected,
		@GoldRejected AS GoldRejected,
		@SilverM1PaymentDone AS SilverM1PaymentDone,
		@SilverM2PaymentDone AS SilverM2PaymentDone,
		@SilverM3PaymentDone AS SilverM3PaymentDone,
		@GoldM1PaymentDone AS GoldM1PaymentDone,
		@GoldM2PaymentDone AS GoldM2PaymentDone,
		@GoldM3PaymentDone AS GoldM3PaymentDone;

END
GO
/****** Object:  StoredProcedure [dbo].[SP_DASHBOARD_GET_DETAILS_TESTING_sk]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

--[SP_DASHBOARD_GET_DETAILS] '<redacted>','<redacted>'
CREATE PROC [dbo].[SP_DASHBOARD_GET_DETAILS_TESTING_sk] --'<redacted>','<redacted>'
(
	@UserId varchar(100) = NULL,
	@RoleId varchar(100) = NULL
)
AS
BEGIN
	
		DECLARE @State varchar(100) =NULL

		IF @State IS NULL OR @State=''
		BEGIN
		SELECT @State=StateCode FROM USERS WHERE UserId=@UserId and RoleId=8
		END

		IF @RoleId=7 OR @RoleId=10 OR @RoleId=8
		BEGIN
				SELECT (select count(*) from Users where RoleId=2) AssessmentAgencies,
			   (select count(*) from Users where RoleId=3 and DesktopVerification=1) DesktopAssessors, (select count(*) from Users where RoleId=3 and SiteVerification=1) SiteAssessors,  
			   (select count(*) from Users where RoleId=3 and FinancialVerification=1) FinancialAssessors,
			   0 BronzeCompleted,
			   0 FaBronzeCompleted,		
			   0 BronzePending,
				
			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) 
			    inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
			   where  UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver' and CertificationStatus=100 AND NcCount=1 AND (@State is null or M.StateId=@State)) SilverCompleted, 
			   0 FaSilverCompleted,

			   
				(select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) 
				inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
			   where  UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
				and Certification='Silver' and CertificationStatus=100 AND NcCount=2  AND (@State is null or M.StateId=@State)) SilverPending, 

			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) 
			   inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
			   where  UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
			   and Certification='Gold' and CertificationStatus=100 AND NcCount=1 AND (@State is null or M.StateId=@State)) GoldCompleted,
			   (select count(*) from FinancialAssistance where CertificationType='Gold' and IsApproved=1) FaGoldCompleted,

			   
				(select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) 
				inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
			   where  UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
				and Certification='Gold' and CertificationStatus=100 AND NcCount=2 AND (@State is null or M.StateId=@State)) GoldPending,

			 --  (select count(*) from Msme where IsBronzePaymentDone=1 AND (@State is null or StateId=@State)) BronzeTotal, 

			 --  --(select count(*) from Msme where IsSilverPaymentDone=1 AND (@State is null or StateId=@State)) SilverTotal, 

			 --  (select count(*) from Msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
				--inner join MsmeCertifications C on (M.ZedId=REPLACE(REPLACE(C.Zedid,'<redacted>',''),concat('<redacted>',C.Id),'')) 
			 --    inner join MsmePaymentInfo P on (C.Zedid=P.Zedid and C.Certification=p.Certification)
				-- where UdyogAadharNo not in ('<redacted>','<redacted>','<redacted>','<redacted>')
				--and P.MileStoneNum=1 and P.Certification='<redacted>' AND (@State is null or M.StateId=@State)) SilverTotal,

			 --  --(select count(*) from Msme where IsGoldPaymentDone=1 AND (@State is null or StateId=@State)) GoldTotal,

			 --  (select count(*) from Msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
				--inner join MsmeCertifications C on (M.ZedId=REPLACE(REPLACE(C.Zedid,'<redacted>',''),concat('<redacted>',C.Id),'')) 
			 --    inner join MsmePaymentInfo P on (C.Zedid=P.Zedid and C.Certification=p.Certification)
				-- where UdyogAadharNo not in ('<redacted>','<redacted>','<redacted>','<redacted>')
				--and P.MileStoneNum=1 and P.Certification='<redacted>' AND (@State is null or M.StateId=@State)) GoldTotal,


				 (select count(*) from Msme M inner join MsmeBasicInformation B  on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (B.ZedId=replace(P.ZedId,'_D',''))
				where P.Certification='Bronze' AND (@State is null or M.StateId=@State) and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')) BronzeTotal,

				(select count(*) from Msme M inner join MsmeBasicInformation B  on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (B.ZedId=replace(P.ZedId,'_D',''))
				where P.Certification='Silver' AND (@State is null or M.StateId=@State) and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')) SilverTotal,

				(select count(*) from Msme M inner join MsmeBasicInformation B  on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (B.ZedId=replace(P.ZedId,'_D',''))
				where P.Certification='Gold' AND (@State is null or M.StateId=@State) and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')) GoldTotal,



			   --(select count(*) from FinancialAssistance where VerificationStatus!=5) FaTotal,
			   --(select count(*) from FinancialAssistance where VerificationStatus<5) FaPending,
			   --(select count(*) from FinancialAssistance where VerificationStatus=6) FaCompleted,

			   --(select count(*) from FinancialAssistance where TechUpgradeStatus in (1,2,4,5,6,8,9,16,19,10) and VerificationStatus!=5) FaTotal,
			   (select count(*) from FinancialAssistance where TechUpgradeStatus not in (0,1,7) and VerificationStatus!=5) FaTotal,
			   (select count(*) from FinancialAssistance where TechUpgradeStatus in (2,3,4,5,6,8,9,10)) FaPending,
			   (select count(*) from FinancialAssistance where TechUpgradeStatus=16 and VerificationStatus=6) FaCompleted,

			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) 
			   inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
			   where  UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
			   and Certification='Silver' 
			   and (CertificationStatus=100 OR  CertificationStatus=16) AND NcCount=3 AND (@State is null or M.StateId=@State)) SaSilverCompleted, 

			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) 
			   inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
			   where  UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
			   and Certification='Gold' and (CertificationStatus=100 OR CertificationStatus=16) AND NcCount=3 AND (@State is null or M.StateId=@State)) SaGoldCompleted,

			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) 
			   inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
			   where  UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
			   and Certification='Silver' and CertificationStatus in (8,9,13,14,15) AND (@State is null or M.StateId=@State)) SaSilverPending, 

			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) 
			   inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
			   where  UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
			   and Certification='Gold' and CertificationStatus in (8,9,13,14,15) AND (@State is null or M.StateId=@State)) SaGoldPending,

			    (select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Bronze' and CertificationStatus=99 AND (@State is null or M.StateId=@State)) BronzeRejected,

			    (select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Silver' and CertificationStatus=99 AND (@State is null or M.StateId=@State)) SilverRejected,

			    (select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('_D', C.ZedId + '_D') - 1)=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Gold' and CertificationStatus=99 AND (@State is null or M.StateId=@State)) GoldRejected,

			   (select count(*) from MsmePaymentInfo C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Silver' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=1 AND (@State is null or M.StateId=@State)) SilverM1PaymentDone,

			   (select count(*) from MsmePaymentInfo C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Silver' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=2 AND (@State is null or M.StateId=@State)) SilverM2PaymentDone,

			   (select count(*) from MsmePaymentInfo C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Silver' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=3 AND (@State is null or M.StateId=@State)) SilverM3PaymentDone,

			   (select count(*) from MsmePaymentInfo C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Gold' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=1 AND (@State is null or M.StateId=@State)) GoldM1PaymentDone,

			   (select count(*) from MsmePaymentInfo C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Gold' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=2 AND (@State is null or M.StateId=@State)) GoldM2PaymentDone,

			   (select count(*) from MsmePaymentInfo C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where Certification='Gold' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=3 AND (@State is null or M.StateId=@State)) GoldM3PaymentDone
		END

		ELSE IF @RoleId=2
		BEGIN
		SELECT 0 AssessmentAgencies,
			   (select count(*) from Users where RoleId=3 and DesktopVerification=1 and CreatedBy=@UserId) DesktopAssessors, 
			   (select count(*) from Users where RoleId=3 and SiteVerification=1 and  CreatedBy=@UserId) SiteAssessors,
			   (select count(*) from MsmeCertifications where Certification='Bronze' and CertificationBodyUserId=@UserId and DaCertificateNo is not null ) BronzeCompleted,
			   (select count(*) from MsmeCertifications where Certification='Bronze' and CertificationBodyUserId=@UserId and DaCertificateNo is null and CertificationStatus<6 and CertificationStatus>1) BronzePending, 

			   --(select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) 
			   -- inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
			   --where  UdyogAadharNo not in ('<redacted>','<redacted>','<redacted>','<redacted>') and Certification='<redacted>' and CertificationStatus=100 AND NcCount=1 AND (@State is null or M.StateId=@State)) SilverCompleted, 

			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) 
			    inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
			   where  UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver' and CertificationStatus=100 AND NcCount=1 and CertificationBodyUserId=@UserId) SilverCompleted, 
			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) 
			    inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
			   where  UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver' and CertificationStatus=100 AND NcCount=2 and CertificationBodyUserId=@UserId) SilverPending, 
			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) 
			    inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
			   where  UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Gold' and CertificationStatus=100 AND NcCount=1 and CertificationBodyUserId=@UserId) GoldCompleted,
			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) 
			    inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
			   where  UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Gold' and CertificationStatus=100 AND NcCount=2 and CertificationBodyUserId=@UserId) GoldPending,

			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) 
			    inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
			   where  UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver' and CertificationStatus=100 AND NcCount=3 and CertificationBodyUserId=@UserId) SaSilverCompleted, 
			   (select count(*) from MsmeCertifications where Certification='Silver' and ModeOfAssessment is not null and CertificationBodyUserId=@UserId and SaCertificateNo is null) SaSilverPending, 
			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) 
			    inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
			   where  UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Gold' and CertificationStatus=100 AND NcCount=3 and CertificationBodyUserId=@UserId) SaGoldCompleted,
			   (select count(*) from MsmeCertifications where Certification='Gold' and ModeOfAssessment is not null and CertificationBodyUserId=@UserId and SaCertificateNo is null) SaGoldPending,

			   (select sum(counts) from (
			   (select count(*) counts from MsmeCertifications where Certification='Bronze' and CertificationBodyUserId=@UserId and DaCertificateNo is not null) union all
			   (select count(*) counts from MsmeCertifications where Certification='Bronze' and CertificationBodyUserId=@UserId and DaCertificateNo is null))A) BronzeTotal, 
			   (select sum(counts) from (
			   (select count(*) counts from Msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join  MsmeCertifications C on (M.ZedId=C.ZedId) where Certification='Silver' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and CertificationBodyUserId=@UserId and NcCount=1))A) SilverTotal, 
			    (select sum(counts) from (
			   (select count(*) counts from Msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join  MsmeCertifications C on (M.ZedId=C.ZedId) where Certification='Gold' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and CertificationBodyUserId=@UserId and NcCount=1))A) GoldTotal,
			   --(select sum(counts) from (
			   --(select count(*) counts from MsmeCertifications where Certification='<redacted>' and CertificationBodyUserId=@UserId and DaCertificateNo is not null) union all
			   --(select count(*) counts from MsmeCertifications where Certification='<redacted>' and CertificationBodyUserId=@UserId and DaCertificateNo is null))A) GoldTotal,
			   (select count(*) from Users where RoleId=3 and FinancialVerification=1 and  CreatedBy=@UserId) FinancialAssessors,

			   --(select count(*) from FinancialAssistance where VerificationStatus!=5 and CertificationBodyUserId=@UserId) FaTotal,
			   --(select count(*) from FinancialAssistance where VerificationStatus<5  and CertificationBodyUserId=@UserId) FaPending,
			   --(select count(*) from FinancialAssistance where VerificationStatus=6  and CertificationBodyUserId=@UserId) FaCompleted,

			   (select count(*) from FinancialAssistance where TechUpgradeStatus not in (0,1,7) and CertificationBodyUserId=@UserId) FaTotal,
			   (select count(*) from FinancialAssistance where TechUpgradeStatus in (2,3,4,5,6,8,9,10)  and CertificationBodyUserId=@UserId) FaPending,
			   (select count(*) from FinancialAssistance where TechUpgradeStatus=16 and VerificationStatus=6  and CertificationBodyUserId=@UserId) FaCompleted,


			   --(select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('<redacted>', C.ZedId + '<redacted>') - 1)=M.ZedId) where Certification='<redacted>' and CertificationStatus=99 and CertificationBodyUserId=@UserId) BronzeRejected,

			   --(select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('<redacted>', C.ZedId + '<redacted>') - 1)=M.ZedId) where Certification='<redacted>' and CertificationStatus=99 and  CertificationBodyUserId=@UserId) SilverRejected,

			   --(select count(*) from MsmeCertifications C inner join Msme M on (SUBSTRING(C.ZedId, 1, CHARINDEX('<redacted>', C.ZedId + '<redacted>') - 1)=M.ZedId) where Certification='<redacted>' and CertificationStatus=99 and CertificationBodyUserId=@UserId) GoldRejected,

			   	(select count(*) from MsmeCertifications C inner join Msme M on (REPLACE(C.ZedId,'_D','')=M.ZedId) where Certification='Bronze' and CertificationStatus=99 AND (@State is null or StateId=@State)) BronzeRejected,

			   (select count(*) from MsmeCertifications C inner join Msme M on (REPLACE(C.ZedId,'_D','')=M.ZedId) where Certification='Silver' and CertificationStatus=99 AND (@State is null or StateId=@State)) SilverRejected,

			   (select count(*) from MsmeCertifications C inner join Msme M on (REPLACE(C.ZedId,'_D','')=M.ZedId) where Certification='Gold' and CertificationStatus=99 AND (@State is null or StateId=@State)) GoldRejected,

			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification and C.NcCount=P.MileStoneNum) where C.Certification='Silver' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=1 AND CertificationBodyUserId=@UserId ) SilverM1PaymentDone,
																								 																																											 																							
			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification and C.NcCount=P.MileStoneNum) where C.Certification='Silver' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=2 AND CertificationBodyUserId=@UserId) SilverM2PaymentDone,
																																																																			 																							
			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification and C.NcCount=P.MileStoneNum) where C.Certification='Silver' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=3 AND CertificationBodyUserId=@UserId) SilverM3PaymentDone,
																								 																																											 																							
			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification and C.NcCount=P.MileStoneNum) where C.Certification='Gold'   and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=1 AND CertificationBodyUserId=@UserId) GoldM1PaymentDone,
																								 																																																																		
			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification and C.NcCount=P.MileStoneNum) where C.Certification='Gold'   and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=2 AND CertificationBodyUserId=@UserId) GoldM2PaymentDone,
																																																																			 																							
			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification and C.NcCount=P.MileStoneNum) where C.Certification='Gold'   and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=3 AND CertificationBodyUserId=@UserId) GoldM3PaymentDone
		END

		ELSE IF @RoleId=3
		BEGIN
		SELECT 0 AssessmentAgencies,
			   0 DesktopAssessors,	
			   0 SiteAssessors,
			   (select count(*) from MsmeCertifications where Certification='Bronze' and DesktopAssessorId=@UserId and DaCertificateNo is not null) BronzeCompleted,
			   (select count(*) from MsmeCertifications where Certification='Bronze' and DesktopAssessorId=@UserId and DaCertificateNo is null) BronzePending, 
			  --(select count(*) from MsmeCertifications where Certification='<redacted>' and DesktopAssessorId=@UserId and DaCertificateNo is not null) SilverCompleted, 

			   --(select count(*) from MsmeCertifications where Certification='<redacted>' and  nccount = 1 and certificationstatus = 100  and siteassessorid=@UserId ) SilverCompleted,

			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) 
			    inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) 
			   where  UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') and Certification='Silver'
			   and CertificationStatus=100 AND NcCount=1 and SiteAssessorId=@UserId) SilverCompleted,



        	   (select count(*) from MsmeCertifications where Certification='Silver' and DesktopAssessorId=@UserId and DaCertificateNo is null) SilverPending, 
			   (select count(*) from MsmeCertifications where Certification='Gold' and DesktopAssessorId=@UserId and DaCertificateNo is not null) GoldCompleted,
			   (select count(*) from MsmeCertifications where Certification='Gold' and DesktopAssessorId=@UserId and DaCertificateNo is null) GoldPending,

			   (select count(*) from MsmeCertifications where Certification='Silver' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and SaCertificateNo is not null) SaSilverCompleted, 
			   (select count(*) from MsmeCertifications where Certification='Silver' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and SaCertificateNo is null) SaSilverPending, 
			   (select count(*) from MsmeCertifications where Certification='Gold' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and SaCertificateNo is not null) SaGoldCompleted,
			   (select count(*) from MsmeCertifications where Certification='Gold' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and SaCertificateNo is null) SaGoldPending,

			   (select sum(counts) from (
			   (select count(*) counts from MsmeCertifications where Certification='Bronze' and DesktopAssessorId=@UserId and DaCertificateNo is not null) union all
			   (select count(*) counts from MsmeCertifications where Certification='Bronze' and DesktopAssessorId=@UserId and DaCertificateNo is null))A) BronzeTotal, 
			   (select sum(counts) from (
			   (select count(*) counts from MsmeCertifications where Certification='Silver' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and DaCertificateNo is not null) union all
			   (select count(*) counts from MsmeCertifications where Certification='Silver' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and DaCertificateNo is null))A) SilverTotal, 
			   (select sum(counts) from (
			   (select count(*) counts from MsmeCertifications where Certification='Gold' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and DaCertificateNo is not null) union all
			   (select count(*) counts from MsmeCertifications where Certification='Gold' and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) and DaCertificateNo is null))A) GoldTotal,

			   -- (select count(*) from FinancialAssistance where VerificationStatus!=5 and FinancialAssessorId=@UserId) FaTotal,
			   --(select count(*) from FinancialAssistance where VerificationStatus<5  and FinancialAssessorId=@UserId) FaPending,
			   --(select count(*) from FinancialAssistance where VerificationStatus=6  and FinancialAssessorId=@UserId) FaCompleted,

			   (select count(*) from FinancialAssistance where TechUpgradeStatus=2 and VerificationStatus!=5 and FinancialAssessorId=@UserId) FaTotal,
			   (select count(*) from FinancialAssistance where TechUpgradeStatus in (4,5,6,8) and VerificationStatus<5 and FinancialAssessorId=@UserId) FaPending,
			   (select count(*) from FinancialAssistance where TechUpgradeStatus=16 and VerificationStatus=6 and FinancialAssessorId=@UserId) FaCompleted,

			    (select count(*) from MsmeCertifications C inner join Msme M on (REPLACE(C.ZedId,'_D','')=M.ZedId) where Certification='Bronze' and CertificationStatus=99 and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId)) BronzeRejected,

			   (select count(*) from MsmeCertifications C inner join Msme M on (REPLACE(C.ZedId,'_D','')=M.ZedId) where Certification='Silver' and CertificationStatus=99 and  (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId)) SilverRejected,

			   (select count(*) from MsmeCertifications C inner join Msme M on (REPLACE(C.ZedId,'_D','')=M.ZedId) where Certification='Gold' and CertificationStatus=99 and (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId)) GoldRejected,

			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId)inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification) where C.Certification='Silver' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=1 AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId) ) SilverM1PaymentDone,
																								 																																										
			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId)inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification) where C.Certification='Silver' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=2 AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId)) SilverM2PaymentDone,
																								 																																											
			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId)inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification) where C.Certification='Silver' and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=3 AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId)) SilverM3PaymentDone,
																								 																																											
			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId)inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification) where C.Certification='Gold'   and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=1 AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId)) GoldM1PaymentDone,
																																																																			 
			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId)inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification) where C.Certification='Gold'   and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=2 AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId)) GoldM2PaymentDone,
																																																																		
			   (select count(*) from MsmeCertifications C inner join Msme M on (C.ZedId=M.ZedId) inner join MsmeBasicInformation B on (M.ZedId=B.ZedId)inner join MsmePaymentInfo P on (C.ZedId=P.ZedId and C.Certification=P.Certification) where C.Certification='Gold'   and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476') AND MileStoneNum=3 AND (DesktopAssessorId=@UserId OR SiteAssessorId=@UserId)) GoldM3PaymentDone


		

		END
		

END





