-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_DASHBOARD_REGISTERED_MSME] --null, null, 28,'<redacted>',null,10,null,'<redacted>',null,null
(
	
	@ZedId varchar(50) = NULL,
	@Status varchar(50) =null,
	@State varchar(100) = NULL,
	@UserId varchar(50) = NULL,
	@CertificationType varchar(50) = NULL,
	@RoleId varchar(50) = NULL,
	@Gender varchar(50) = NULL,
	@MsmeSize varchar(50) = NULL,
	@PageNo int = 1,
	@NoOfRecords int = 25000
	
	
)
AS
BEGIN
	
	SET NOCOUNT ON;
	
	IF @State='' 
	SET @State = NULL

	IF @CertificationType='' 
	SET @CertificationType = NULL

	IF @Gender='' 
	SET @Gender = NULL

	IF @MsmeSize='' 
	SET @MsmeSize = NULL

	IF @State IS NULL OR @State=''
	BEGIN
	SELECT @State=StateCode FROM USERS WHERE UserId=@UserId and RoleId=8
	END

	SELECT P.Id,M.ZedId,Certification,EvidenceSubmissionDate,CertificationBodyUserId,
		AcceptOrRejectDate,P.ReasonForRejection,DesktopAssessorId,SiteAssessorId,ModeOfAssessment,FORMAT(AssessmentDate, 'MMMM d, yyyy') SaAssessmentDate,DesktopAccepted,DesktopAcceptOrRejectDate,DesktopReasonForRejection,NcCount,CertificationStatus,
		--case when (IsBronzePaymentDone is null and IsSilverPaymentDone is null and IsGoldPaymentDone is null) then '<redacted>'			
		--	when CertificationStatus=6 then '<redacted>'
		--	when CertificationStatus=8 then '<redacted>'
		--	when CertificationStatus=9 then '<redacted>'
		--	when CertificationStatus=13 then '<redacted>'
		--	when CertificationStatus=15 then '<redacted>'
		--	when CertificationStatus=16 then '<redacted>' 
		--	when (IsBronzePaymentDone=1 or IsSilverPaymentDone=1 or IsGoldPaymentDone=1) then '<redacted>'
		--end as AssessmentStatus,

		--case when CertificationBodyUserId is null and AcceptOrRejectDate is null then '<redacted>'
		--	when CertificationBodyUserId is not null and AcceptOrRejectDate is null then '<redacted>'
		--	when CertificationBodyUserId is not null and P.ReasonForRejection is not null then '<redacted>'
		--	when CertificationBodyUserId is not null and DesktopAssessorId is not null and DesktopAcceptOrRejectDate is null then '<redacted>'
		--	when CertificationBodyUserId is not null and DesktopAssessorId is not null and DesktopAcceptOrRejectDate is not null and DesktopReasonForRejection is not null then '<redacted>'
		--	when CertificationBodyUserId is not null and DesktopAssessorId is not null and DesktopAccepted=1 then '<redacted>' 
		--end as AllocationStatus,
		case when (IsBronzePaymentDone is null and IsSilverPaymentDone is null and IsGoldPaymentDone is null) then 'Payment Pending By MSME'			
			when CertificationStatus=6 then 'Payment done By MSME'
			when CertificationStatus=8 then 'Consultant Allocated'
			when CertificationStatus=9 then 'Consultancy Planned'
			when CertificationStatus=15 then 'In Quality Check'
			when CertificationStatus=13 then 'Consultancy in progress'
			when CertificationStatus=16 then 'Submitted By Consultant'
			when CertificationStatus=100 then 'Applicant Accepted the Milestone'
			when ((CertificationStatus=16 OR CertificationStatus=100) AND P.NcCount=3) then 'Consultancy Completed'
		end as AssessmentStatus,
				
		DaCertificateNo,SaCertificateNo,
		CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress,
		P.Certification, P.CertificationBodyUserId,P.ReasonForRejection,P.DesktopReasonForRejection, UamNumber,PCity,PStateName,PDistrictName,PPin, M.EnterpriseName, U.UserName,
		M.CreatedDate RegisteredDate, M.PUnitName, P.NcCount MileStoneNo,UdyogAadharNo,
		ROW_NUMBER() OVER (order by M.msmeId desc) as RowNumber
    
	FROM Msme M
	inner join MsmeCertifications P on (P.ZedId=M.ZedId)
	LEFT JOIN Users U on (P.CertificationBodyUserId=U.UserId)
	LEFT JOIN MsmeBasicInformation B on (M.ZedId=B.ZedId)
	WHERE (@State is null or M.StateId=@State) --AND CertificationStatus=@Status
	AND (@CertificationType IS NULL OR Certification=@CertificationType) AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize) AND (@Gender IS NULL OR Gender=@Gender)
	ORDER By M.MsmeId,NcCount desc
	--offset ((@PageNo-1) * @NoOfRecords) rows fetch next @NoOfRecords rows only

END



GO
