CREATE PROCEDURE [dbo].[SP_DYNAMIC_ANALYSIS_REPORT_BREAD_AND_BREAKFAST] 
(
@UlbCode varchar(100) = NULL,  
@Userid varchar(100)= NULL,  
@RoleId varchar(100)= NULL 
)
AS
BEGIN

SET NOCOUNT ON;

      SELECT  ROW_NUMBER() OVER(ORDER BY SelfCertificationDate) [SNo]  
  ,FORMAT(SelfCertificationDate, 'MMMM d, yyyy h:mm tt') [DateofSelfCertification]
  ,EstablishmentName as [Unit Name] ,S.[RegistrationNumber] [HotelCloudRegistrationNumber]
  ,S.[Acommodationtype] [AcommodationType] ,[TotalRooms] [Total Rooms],RestaurantType
  ,Category ,[EstablishmentAddress] ,[EstablishmentCity] ,[DistrictName]    ,[StateName]    ,[EstablishmentPinCode] ,SaDate as [PrefferedSADate] ,[CertificationBodyUserId] ,[ModeOfAssessment]
  ,[AssessorUserId] ,[FinalSaDate],[IsSaDeclarationAccepted],[PaymentDate] ,[AmountPaid] ,[GstNumber] ,[UtrNumber]
  ,CASE WHEN SaStatus=0 then 'Not Started' WHEN SaStatus=1 then 'In Progress'  WHEN SaStatus=2 then 'In Quality Check' WHEN SaStatus=3 then 'Completed' End as SaStatus
  ,[SaCertificateNo],[1.1.1],[1.2.1],[1.3.1],[2.1.1],[2.1.2],[2.2.1],[2.2.2],[2.3.1],[2.3.2],[2.3.3],[2.4.1],[2.5.1],[3.1.1],[3.1.2],[3.1.3],[3.1.4],[3.1.5],[3.2.1],[3.3.1],[3.3.2],[3.3.3],[3.3.4],[3.3.5],[3.3.6],[3.3.7],[3.3.8],[3.3.9],[3.3.10],[3.3.11],[3.4.1],[3.4.2],[3.4.3],[3.4.4],[3.4.5],[3.5.1],[3.6.1],[4.1.1],[4.1.2],[4.1.3],[5.1.1],[5.1.2],[5.1.3],[6.1.1],[6.1.2],[6.1.3],[7.1.1],[7.1.2],[8.1.1],[8.1.2],[9.1.1],[9.1.2],[10.1.1]

  ,[SaFinalSubmitDate]
 from SelfAssessments S inner join 


(select * from (

select concat(R.SectionCode,'.',R.QuestionCode,'.',R.RequirementCode) code, RegistrationNumber,AnswerCode from SaRequirements S 
inner join Requirements R on (S.RequirementId=R.Id) 
) T

PIVOT (
max(answercode) for code in ([1.1.1],[1.2.1],[1.3.1],[2.1.1],[2.1.2],[2.2.1],[2.2.2],[2.3.1],[2.3.2],[2.3.3],[2.4.1],[2.5.1],[3.1.1],[3.1.2],[3.1.3],[3.1.4],[3.1.5],[3.2.1],[3.3.1],[3.3.2],[3.3.3],[3.3.4],[3.3.5],[3.3.6],[3.3.7],[3.3.8],[3.3.9],[3.3.10],[3.3.11],[3.4.1],[3.4.2],[3.4.3],[3.4.4],[3.4.5],[3.5.1],[3.6.1],[4.1.1],[4.1.2],[4.1.3],[5.1.1],[5.1.2],[5.1.3],[6.1.1],[6.1.2],[6.1.3],[7.1.1],[7.1.2],[8.1.1],[8.1.2],[9.1.1],[9.1.2],[10.1.1]

)

) as Pvt
) B on (S.RegistrationNumber=B.RegistrationNumber)
LEFT JOIN AcommodationTypes T on (S.Acommodationtype=T.Acommodationtype) 
WHERE QuestionnaireName='Bed and Breakfast'

ORDER BY SaCertificateNo
END

