CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_BASIC_INFO_PARAMETER_01]  --NULL,'<redacted>',8
(
	@UlbCode varchar(100) = NULL,  
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL 
)
AS
BEGIN
	
	------  LIST OF REGISTERED MSME

	SET NOCOUNT ON;

	SELECT
    C.ZedId,
    C.NcCount AS MileStoneNo,
    M.PUnitName,
    PStateName,
    'OCCUPATIONAL (WORKPLACE) SAFETY' AS ParameterName,
    NumOfAccedents AS [No. of accidents (incl. fatalities & disabilities caused, if any)],
    NumOfNearMisses AS [No. of near misses],
    ManHoursLast AS [Man hours lost],
    LosttimeInjuryfreqRate AS [Lost Time Injury Frequency Rate (LTIFR)]
FROM
    Msme M
    INNER JOIN MsmeCertifications C ON (M.ZedId = C.ZedId)
    INNER JOIN ConsultancyBasicInformation B ON (C.ZedId = B.ZedId AND C.NcCount = B.NcCount AND C.Certification = B.CertificationType)
WHERE
    C.certificationstatus = 100
ORDER BY
    C.ZedId,
    C.NcCount,
    c.certificationstatusdate;


END


