create PROCEDURE [dbo].[SP_DYNAMIC_REPORT_BASIC_INFO_PARAMETER_06]  --NULL,'<redacted>',8
(
	@UlbCode varchar(100) = NULL,  
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL 
)
AS
BEGIN
	
	------  LIST OF REGISTERED MSME

	SET NOCOUNT ON;

	SELECT 
    C.ZedId,
    C.NcCount AS MilestoneNo,
    PUnitName,
    PStateName,
    'Human Resource Management' AS ParameterName,
    EmpEngagedInActivities AS [% of employees engaged in improvement activities],
    NumOfSuggestions AS [No. of suggestions received],
    HrmMeasuresTaken AS [Measures Taken to develop human resources]
FROM 
    Msme M 
    INNER JOIN MsmeCertifications C ON (M.ZedId = C.ZedId)
    INNER JOIN ConsultancyBasicInformation B ON (C.ZedId = B.ZedId AND C.NcCount = B.NcCount AND C.Certification = B.CertificationType)
WHERE 
    C.CertificationStatus = 100
ORDER BY 
    C.ZedId, 
    C.NcCount, 
    C.CertificationStatusDate;


END


