/****** Object:  StoredProcedure [dbo].[SP_DYNAMIC_REPORT_LIST_OF_APPROVED_TRANSACTIONS]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================

CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_OF_APPROVED_TRANSACTIONS]  --NULL,'<redacted>',6
(
	@UlbCode varchar(100) = NULL,  
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL 
)
AS
BEGIN
	
	SET NOCOUNT ON;

	DECLARE @state varchar(100) = NULL

	IF @RoleId = 6
	BEGIN
			SELECT 
    M.ZedId,PUnitName,PStateName,PDistrictName,PAddress,
	B.UdyogAadharNo, B.Gender, B.SocialCategoryName, TUP.TechnologyName,
	TUP.NameOfTheManufacturer, TUP.MakeOrModelName,TUP.AgencyOrSupplier, TUP.InvoiceBillDate,
	P.EnterpriseTypee EnterpriseType, P.SubsidyPercentage,
	TotalPaidAfterQc,EligibleAmount,BankName, AccountNo,IfscCode,BranchAddress,
	F.ApproverDateOfReceiptOfPayment, F.ApproverReferenceNo, F.ApproverAmount, F.Comments
	FROM Msme M
INNER JOIN MsmeBasicInformation B 
    ON M.ZedId = B.ZedId
INNER JOIN FinancialAssistance F 
    ON B.ZedId = F.ZedId
INNER JOIN (
    SELECT 
        ZedId,CertificationType,CertId,FinancialAssistanceId,
        STUFF((SELECT ', ' + concat(TechnologyCode,'-',technologyname)
               FROM technologyupgradation 
               WHERE zedid = TU.zedid
               FOR XML PATH('')), 1, 2, '') AS TechnologyName,

		STUFF((SELECT ', ' + CONVERT(VARCHAR, NameOfTheManufaturer)
           FROM technologyupgradation 
           WHERE zedid = TU.zedid
           FOR XML PATH('')), 1, 2, '') AS NameOfTheManufacturer,

		STUFF((SELECT ', ' + CONVERT(VARCHAR, MakeOrModelName)
           FROM technologyupgradation 
           WHERE zedid = TU.zedid
           FOR XML PATH('')), 1, 2, '') AS MakeOrModelName,

		STUFF((SELECT ', ' + CONVERT(VARCHAR, AgencyOrSupplier)
           FROM technologyupgradation 
           WHERE zedid = TU.zedid
           FOR XML PATH('')), 1, 2, '') AS AgencyOrSupplier,

        STUFF((SELECT ', ' + CONVERT(VARCHAR, invoicebilldate, 23)
               FROM technologyupgradation 
               WHERE zedid = TU.zedid
               FOR XML PATH('')), 1, 2, '') AS InvoiceBillDate
        --STUFF((SELECT '<redacted>' + CONVERT(VARCHAR, amountpaid)
        --       FROM technologyupgradation 
        --       WHERE zedid = TU.zedid
        --       FOR XML PATH('')), 1, 2, '') AS AmountPaid,
        --STUFF((SELECT '<redacted>' + CONVERT(VARCHAR, eligibleamount)
        --       FROM technologyupgradation 
        --       WHERE zedid = TU.zedid
        --       FOR XML PATH('')), 1, 2, '') AS EligibleAmount
    FROM technologyupgradation TU
    WHERE IsEligible = 1
    GROUP BY ZedId,CertificationType,CertId,FinancialAssistanceId
) TUP 
    ON (F.ZedId = TUP.ZedId AND F.certificationType=TUP.CertificationType AND F.CertId=TUP.CertId AND F.FinancialAssistanceId=TUP.FinancialAssistanceId)
	INNER JOIN MsmePaymentInfo P   
		ON (F.ZedId = P.ZedId AND F.CertId = P.MsmePmtCertId AND F.CertificationType = P.Certification AND P.MileStoneNum = 3)

WHERE F.VerificationStatus = 6
and  UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
ORDER BY F.CreatedDate
	END	

	ELSE IF @RoleId = 2
	BEGIN
	SELECT 
		M.ZedId,PUnitName,PStateName,PDistrictName,PAddress,
		B.UdyogAadharNo, B.Gender, B.SocialCategoryName, TUP.TechnologyName,
		TUP.NameOfTheManufacturer, TUP.MakeOrModelName,TUP.AgencyOrSupplier, TUP.InvoiceBillDate,
		P.EnterpriseTypee EnterpriseType, P.SubsidyPercentage,
		TotalPaidAfterQc,EligibleAmount,BankName, AccountNo,IfscCode,BranchAddress,
		F.ApproverDateOfReceiptOfPayment, F.ApproverReferenceNo, F.ApproverAmount, F.Comments
		FROM Msme M
	INNER JOIN MsmeBasicInformation B 
		ON M.ZedId = B.ZedId
	INNER JOIN FinancialAssistance F 
		ON B.ZedId = F.ZedId
	INNER JOIN (
		SELECT 
			ZedId,CertificationType,CertId,FinancialAssistanceId,
			STUFF((SELECT ', ' + concat(TechnologyCode,'-',technologyname)
				   FROM technologyupgradation 
				   WHERE zedid = TU.zedid
				   FOR XML PATH('')), 1, 2, '') AS TechnologyName,

			STUFF((SELECT ', ' + CONVERT(VARCHAR, NameOfTheManufaturer)
			   FROM technologyupgradation 
			   WHERE zedid = TU.zedid
			   FOR XML PATH('')), 1, 2, '') AS NameOfTheManufacturer,

			STUFF((SELECT ', ' + CONVERT(VARCHAR, MakeOrModelName)
			   FROM technologyupgradation 
			   WHERE zedid = TU.zedid
			   FOR XML PATH('')), 1, 2, '') AS MakeOrModelName,

			STUFF((SELECT ', ' + CONVERT(VARCHAR, AgencyOrSupplier)
			   FROM technologyupgradation 
			   WHERE zedid = TU.zedid
			   FOR XML PATH('')), 1, 2, '') AS AgencyOrSupplier,

			STUFF((SELECT ', ' + CONVERT(VARCHAR, invoicebilldate, 23)
				   FROM technologyupgradation 
				   WHERE zedid = TU.zedid
				   FOR XML PATH('')), 1, 2, '') AS InvoiceBillDate
			--STUFF((SELECT '<redacted>' + CONVERT(VARCHAR, amountpaid)
			--       FROM technologyupgradation 
			--       WHERE zedid = TU.zedid
			--       FOR XML PATH('')), 1, 2, '') AS AmountPaid,
			--STUFF((SELECT '<redacted>' + CONVERT(VARCHAR, eligibleamount)
			--       FROM technologyupgradation 
			--       WHERE zedid = TU.zedid
			--       FOR XML PATH('')), 1, 2, '') AS EligibleAmount
		FROM technologyupgradation TU
		WHERE IsEligible = 1
		GROUP BY ZedId,CertificationType,CertId,FinancialAssistanceId
	) TUP 
		ON (F.ZedId = TUP.ZedId AND F.certificationType=TUP.CertificationType AND F.CertId=TUP.CertId AND F.FinancialAssistanceId=TUP.FinancialAssistanceId)
		INNER JOIN MsmePaymentInfo P   
		ON (F.ZedId = P.ZedId AND F.CertId = P.MsmePmtCertId AND F.CertificationType = P.Certification AND P.MileStoneNum = 3)

	WHERE F.VerificationStatus = 6 AND F.CertificationBodyUserId = @UserId
	and  UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
	ORDER BY F.CreatedDate

	END

	ELSE
		BEGIN
		SELECT NULL DATAS
		END

END


--select * from technologyupgradation
GO
/****** Object:  StoredProcedure [dbo].[SP_DYNAMIC_REPORT_LIST_OF_ASSESSMENT_AGENCIES]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_OF_ASSESSMENT_AGENCIES] --NULL, NULL, 10
(
	@UlbCode varchar(100) = NULL,  
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL 
)
AS
BEGIN
	
	SET NOCOUNT ON;

	   select 
 CoId,CoName,MobileNo,Email, SpocName,Address,Pincode,AgencyGstNumber,status,DesktopVerification,SiteVerification,FinancialVerification, ApplicableStates,NicSector,
 NoOfConsultants,
 isnull(p.[1],0) as [Allcoation of ZEDIds in MileStone 1],
 isnull(p.[2],0) as [Allcoation of ZEDIds in MileStone 2],
 isnull(p.[3],0) as [Allcoation of ZEDIds in MileStone 3] from 
 (select U.UserId as CoId,UserName as CoName,MobileNo,Email,SpocName, Address,Pincode,AgencyGstNumber, 
		case when IsActive=1 then 'Active' when IsActive=0 then 'Blocked' end as Status,
		case when DesktopVerification=1 then 'Yes' else 'No' end as DesktopVerification,
		case when SiteVerification=1 then 'Yes' else 'No' end as SiteVerification,
		case when FinancialVerification=1 then 'Yes' else 'No' end as FinancialVerification,
		case when States is null then 'All States' else States end as ApplicableStates,
		NicSector, NcCount, isnull(NoOfZedIds,0) AllocatedtoNoOfZedIds,isnull(NoOfAssessors,0) as NoOfConsultants from users U  
		left join 
			(SELECT UserId, States=STUFF  
			(  
				(  
				  SELECT DISTINCT ', '+ CAST( e.States as VARCHAR(MAX))  
				  FROM Users G,AgencyUserStates E  
				  WHERE G.UserId=E.UserId and E.UserId=T1.UserId   
				  FOR XMl PATH('')  
				),1,1,''  
			)  
			FROM AgencyUserStates t1 
			GROUP BY UserId  ) X
			on (U.UserId=X.Userid)

		left join 
			(SELECT UserId, NicSector=STUFF  
			(  
				(  
				  SELECT DISTINCT ', '+ CAST( e.NicSector as VARCHAR(MAX))  
				  FROM Users G,UserNicSectors E  
				  WHERE G.UserId=E.UserId and E.UserId=T1.UserId   
				  FOR XMl PATH('')  
				),1,1,''  
			)  
			FROM UserNicSectors t1 
			GROUP BY UserId  ) Y
			on (U.UserId=Y.UserId)

	LEFT join 

	(select CertificationBodyUserId,NcCount,count(*) NoOfZedIds from Msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId)
	inner join MsmeCertifications C on (M.ZedId=C.ZedId)
	where ReasonForRejection is null and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915')
	
	group by CertificationBodyUserId,NcCount) Z
	on (U.UserId=Z.CertificationBodyUserId)

	left join

	(select CreatedBy,count(*) NoOfAssessors from Users where RoleId=3 group by CreatedBy) YY
	on (U.UserId=YY.CreatedBy)

		where roleid=2 AND @RoleId=10) A

		Pivot
		(
		max(AllocatedtoNoOfZedIds) for NcCount in ([1],[2],[3])
		
		) p

END

GO
