-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_OF_ASSESSMENT_AGENCIES_KAWACH] 
(
	@UlbCode varchar(100) = NULL,  
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL 
)
AS
BEGIN
	
	SET NOCOUNT ON;

	   select U.UserId as AgencyId,UserName as AgencyName,MobileNo,Email,SpocName, Address,Pincode,AgencyGstNumber, 
		case when IsActive=1 then 'Active' when IsActive=0 then 'Blocked' end as Status,
		case when States is null then 'All States' else States end as ApplicableStates,
		NicSector,isnull(NoOfZedIds,0) AllocatedtoNoOfZedIds,isnull(NoOfAssessors,0) as NoOfAssessors from kawach.dbo.users U  
		left join 
			(SELECT UserId, States=STUFF  
			(  
				(  
				  SELECT DISTINCT ', '+ CAST( e.States as VARCHAR(MAX))  
				  FROM kawach.dbo.Users G,AgencyUserStates E  
				  WHERE G.UserId=E.UserId and E.UserId=T1.UserId   
				  FOR XMl PATH('')  
				),1,1,''  
			)  
			FROM kawach.dbo.AgencyUserStates t1 
			GROUP BY UserId  ) X
			on (U.UserId=X.Userid)

		left join 
			(SELECT UserId, NicSector=STUFF  
			(  
				(  
				  SELECT DISTINCT ', '+ CAST( e.NicSector as VARCHAR(MAX))  
				  FROM kawach.dbo.Users G,UserNicSectors E  
				  WHERE G.UserId=E.UserId and E.UserId=T1.UserId   
				  FOR XMl PATH('')  
				),1,1,''  
			)  
			FROM kawach.dbo.UserNicSectors t1 
			GROUP BY UserId  ) Y
			on (U.UserId=Y.UserId)

	left join 

	(select CertificationBodyUserId,count(*) NoOfZedIds from kawach.dbo.MsmeCertifications where AcceptOrRejectDate is not null and ReasonForRejection is null group by CertificationBodyUserId) Z
	on (U.UserId=Z.CertificationBodyUserId)

	left join

	(select CreatedBy,count(*) NoOfAssessors from kawach.dbo.Users where RoleId=3 group by CreatedBy) YY
	on (U.UserId=YY.CreatedBy)

		where roleid=2 order by Id

END

