-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_OF_CERTIFIED_MSME_KAWACH] --NULL,'<redacted>',8
(
	@UlbCode varchar(100) = NULL,  
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL 
)
AS
BEGIN
	
	------  LIST OF REGISTERED MSME

	SET NOCOUNT ON;

		DECLARE @state varchar(100) = NULL

		IF @RoleId = 8
		BEGIN
			SELECT @State=StateCode FROM USERS WHERE UserId=@UserId and RoleId=8
		

			SELECT 
			P.Id,M.ZedId,Certification,M.CreatedDate as RegisteredDate,
			DaCertificateNo WASHCertificateNo,
			CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress,
			P.Certification, P.CertificationBodyUserId,PCity,PStateName StateNam,PDistrictName DistrictName, EnterpriseName,P.CertificationStatusDate CertificationDate
		
		
			FROM kawach.dbo.Msme M
			left join kawach.dbo.MsmeCertifications P on (P.ZedId=M.ZedId)
			LEFT JOIN kawach.dbo.Users U on (P.CertificationBodyUserId=U.UserId)
			LEFT JOIN kawach.dbo.Users UA on (P.DesktopAssessorId=UA.UserId)
			WHERE CertificationStatus=6
			AND (@State is null or StateId=@State)
			ORDER By MsmeId desc
		END

		ELSE
		
		BEGIN
			SELECT @State=StateCode FROM USERS WHERE UserId=@UserId and RoleId=8
		

			SELECT 
			P.Id,M.ZedId,Certification,M.CreatedDate as RegisteredDate,
			DaCertificateNo WASHCertificateNo,
			CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress,
			P.Certification, P.CertificationBodyUserId,PCity,PStateName StateNam,PDistrictName DistrictName, EnterpriseName, U.UserName AgencyName,
			UA.UserName AssessorName, P.DesktopAssessorId,P.CertificationStatusDate CertificationDate
		
		
			FROM kawach.dbo.Msme M
			left join kawach.dbo.MsmeCertifications P on (P.ZedId=M.ZedId)
			LEFT JOIN kawach.dbo.Users U on (P.CertificationBodyUserId=U.UserId)
			LEFT JOIN kawach.dbo.Users UA on (P.DesktopAssessorId=UA.UserId)
			WHERE CertificationStatus=6
			AND (@State is null or StateId=@State)
			ORDER By MsmeId desc
		END
		


END

