-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_OF_MILESTONE1_COMPLETED] -- NULL,'<redacted>',2
(
	@UlbCode varchar(100) = NULL,  
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL 
)
AS
BEGIN
	
	------  LIST OF REGISTERED MSME

	SET NOCOUNT ON;


	IF @RoleId = 2
	BEGIN
		
		SELECT 
        M.ZedId,
		FORMAT(H.CreatedDate, 'MMMM d, yyyy') AS AllocationDate,
        FORMAT(BdsFromDate, 'MMMM d, yyyy') AS BdsFromDate,
        FORMAT(BdsToDate, 'MMMM d, yyyy') AS BdsToDate,
        FORMAT(HapFromDate, 'MMMM d, yyyy') AS HapFromDate,
        FORMAT(HapToDate, 'MMMM d, yyyy') AS HapToDate,

        M.PUnitName,
        P.Certification,
        M.OwnerName,
        M.EnterpriseTypee,
        M.MobileNo,
        M.EmailId,
        TwoDigitActivity,
        B.UdyogAadharNo,
        B.SocialCategoryName,
        B.Gender,
        PAddress,
        PStateName,
        PDistrictName,
        U.UserName AS ConsultantOrganisation,
        US.UserName AS LeadConsultant,
        PVA.CoAssessor1 AS CoConsultant1,
        PVA.CoAssessor2 AS CoConsultant2,
        PVA.CoAssessor3 AS CoConsultant3,
        PVA.CoAssessor4 AS CoConsultant4,
        PVA.CoAssessor5 AS CoConsultant5,
		UT.TechExpertName AS TechExpertName
    FROM Msme M
    INNER JOIN MsmeCertifications P ON (P.ZedId = M.ZedId)
    INNER JOIN MsmeBasicInformation B ON (B.ZedId = M.ZedId)
	OUTER APPLY (
			SELECT STRING_AGG(U_TE.UserName, ', ') AS TechExpertName
			FROM STRING_SPLIT(P.TechExpert, ',') s
			INNER JOIN Users U_TE ON LTRIM(RTRIM(s.value)) = U_TE.UserId
		) UT
	OUTER APPLY (
            SELECT TOP 1 CreatedDate 
            FROM MsmeHistory 
            WHERE ZedId = P.ZedId 
              AND CertificationType = P.Certification 
              AND NcCount = P.NcCount 
              AND StatusType = 'CoAlloted'
            ORDER BY CreatedDate DESC
        ) H
    LEFT JOIN Users U ON (P.CertificationBodyUserId = U.UserId)
    LEFT JOIN Users US ON (P.SiteAssessorId = US.UserId)
    LEFT JOIN
    (SELECT * FROM(SELECT ZedId, Certification,NcCount,UserName,
    CONCAT('CoAssessor', ROW_NUMBER() OVER (PARTITION BY ZedId, NcCount ORDER BY CoAssessorId)) AS CoAssessors
    FROM(SELECT DISTINCT A.ZedId,A.Certification,A.CoAssessorId,U.UserName,A.NcCount FROM AllotedCoAssessors A
    INNER JOIN Users U ON A.CoAssessorId = U.UserId) A) X
    PIVOT(MAX(UserName)FOR CoAssessors IN ([CoAssessor1], [CoAssessor2],[CoAssessor3],[CoAssessor4],[CoAssessor5])) PV) PVA
    ON (P.ZedId = PVA.ZedId) AND P.Certification = PVA.Certification AND P.NcCount = PVA.NcCount
    WHERE P.CertificationStatus in(100) AND P.NcCount = 1 AND P.CertificationBodyUserId = @UserId
    AND B.UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915')
    ORDER BY M.MsmeId DESC;
		
	END
	
	ELSE
	BEGIN

	SELECT NULL DATAS;
		
	END

END


