        U.UserName AS ConsultantOrganisation,
        US.UserName AS LeadConsultant,
        PVA.CoAssessor1 AS CoConsultant1,
        PVA.CoAssessor2 AS CoConsultant2,
        PVA.CoAssessor3 AS CoConsultant3,
        PVA.CoAssessor4 AS CoConsultant4,
        PVA.CoAssessor5 AS CoConsultant5,
		UT.TechExpertName AS TechExpertName
    FROM Msme M
    INNER JOIN MsmeCertifications P ON (P.ZedId = M.ZedId)
    INNER JOIN MsmeBasicInformation B ON (B.ZedId = M.ZedId)
	OUTER APPLY (
			SELECT STRING_AGG(U_TE.UserName, ', ') AS TechExpertName
			FROM STRING_SPLIT(P.TechExpert, ',') s
			INNER JOIN Users U_TE ON LTRIM(RTRIM(s.value)) = U_TE.UserId
		) UT
	OUTER APPLY (
            SELECT TOP 1 CreatedDate 
            FROM MsmeHistory 
            WHERE ZedId = P.ZedId 
              AND CertificationType = P.Certification 
              AND NcCount = P.NcCount 
              AND StatusType = 'CoAlloted'
            ORDER BY CreatedDate DESC
        ) H
 

    LEFT JOIN Users U ON (P.CertificationBodyUserId = U.UserId)
    LEFT JOIN Users US ON (P.SiteAssessorId = US.UserId)
    LEFT JOIN
    (SELECT * FROM(SELECT ZedId, Certification,NcCount,UserName,
    CONCAT('CoAssessor', ROW_NUMBER() OVER (PARTITION BY ZedId, NcCount ORDER BY CoAssessorId)) AS CoAssessors
    FROM(SELECT DISTINCT A.ZedId,A.Certification,A.CoAssessorId,U.UserName,A.NcCount FROM AllotedCoAssessors A
    INNER JOIN Users U ON A.CoAssessorId = U.UserId) A) X
    PIVOT(MAX(UserName)FOR CoAssessors IN ([CoAssessor1], [CoAssessor2],[CoAssessor3],[CoAssessor4],[CoAssessor5])) PV) PVA
    ON (P.ZedId = PVA.ZedId) AND P.Certification = PVA.Certification AND P.NcCount = PVA.NcCount
    WHERE P.CertificationStatus >=6  and P.CertificationStatus <= 16
	AND P.NcCount = 3 AND P.CertificationBodyUserId = @UserId
    AND B.UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915')
    ORDER BY M.MsmeId DESC;
		
	END
	
	ELSE
	BEGIN

	SELECT NULL DATAS;
		
	END

END


GO
/****** Object:  StoredProcedure [dbo].[SP_DYNAMIC_REPORT_LIST_OF_NEW_TRANSACTIONS]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================

CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_OF_NEW_TRANSACTIONS] --NULL,'<redacted>',6
(
	@UlbCode varchar(100) = NULL,  
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL 
)
AS
BEGIN
	
	SET NOCOUNT ON;

	DECLARE @state varchar(100) = NULL

	IF @RoleId = 6
	BEGIN
			SELECT 
    M.ZedId,PUnitName,PStateName,PDistrictName,PAddress,
	B.UdyogAadharNo, B.Gender, B.SocialCategoryName,  TUP.TechnologyName,
	TUP.NameOfTheManufacturer, TUP.MakeOrModelName,TUP.AgencyOrSupplier, TUP.InvoiceBillDate,
	P.EnterpriseTypee EnterpriseType, P.SubsidyPercentage,
	TotalPaidAfterQc,EligibleAmount,BankName, AccountNo,IfscCode,BranchAddress,
	F.ApproverDateOfReceiptOfPayment, F.ApproverReferenceNo, F.ApproverAmount, F.Comments
	FROM Msme M
INNER JOIN MsmeBasicInformation B 
    ON M.ZedId = B.ZedId
INNER JOIN FinancialAssistance F 
    ON B.ZedId = F.ZedId
INNER JOIN (
    SELECT 
        ZedId,CertificationType,CertId,FinancialAssistanceId,
        STUFF((SELECT ', ' + concat(TechnologyCode,'-',technologyname)
               FROM technologyupgradation 
               WHERE zedid = TU.zedid
               FOR XML PATH('')), 1, 2, '') AS TechnologyName,
		STUFF((SELECT ', ' + CONVERT(VARCHAR, NameOfTheManufaturer)
           FROM technologyupgradation 
           WHERE zedid = TU.zedid
           FOR XML PATH('')), 1, 2, '') AS NameOfTheManufacturer,

		STUFF((SELECT ', ' + CONVERT(VARCHAR, MakeOrModelName)
           FROM technologyupgradation 
           WHERE zedid = TU.zedid
           FOR XML PATH('')), 1, 2, '') AS MakeOrModelName,

		STUFF((SELECT ', ' + CONVERT(VARCHAR, AgencyOrSupplier)
           FROM technologyupgradation 
           WHERE zedid = TU.zedid
           FOR XML PATH('')), 1, 2, '') AS AgencyOrSupplier,
        STUFF((SELECT ', ' + CONVERT(VARCHAR, invoicebilldate, 23)
               FROM technologyupgradation 
               WHERE zedid = TU.zedid
               FOR XML PATH('')), 1, 2, '') AS InvoiceBillDate
        --STUFF((SELECT '<redacted>' + CONVERT(VARCHAR, amountpaid)
        --       FROM technologyupgradation 
        --       WHERE zedid = TU.zedid
        --       FOR XML PATH('')), 1, 2, '') AS AmountPaid,
        --STUFF((SELECT '<redacted>' + CONVERT(VARCHAR, eligibleamount)
        --       FROM technologyupgradation 
        --       WHERE zedid = TU.zedid
        --       FOR XML PATH('')), 1, 2, '') AS EligibleAmount
    FROM technologyupgradation TU
    WHERE IsEligible = 1
    GROUP BY ZedId,CertificationType,CertId,FinancialAssistanceId
) TUP 
    ON (F.ZedId = TUP.ZedId AND F.certificationType=TUP.CertificationType AND F.CertId=TUP.CertId AND F.FinancialAssistanceId=TUP.FinancialAssistanceId)

	INNER JOIN MsmePaymentInfo P   
		ON (F.ZedId = P.ZedId AND F.CertId = P.MsmePmtCertId AND F.CertificationType = P.Certification AND P.MileStoneNum = 3)


WHERE F.VerificationStatus = 4
and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
ORDER BY F.CreatedDate
	END	

	ELSE IF @RoleId = 2
	BEGIN
		SELECT 
		M.ZedId,PUnitName,PStateName,PDistrictName,PAddress,
		B.UdyogAadharNo, B.Gender, B.SocialCategoryName,  TUP.TechnologyName,
		TUP.NameOfTheManufacturer, TUP.MakeOrModelName,TUP.AgencyOrSupplier, TUP.InvoiceBillDate,
		P.EnterpriseTypee EnterpriseType, P.SubsidyPercentage,
		TotalPaidAfterQc,EligibleAmount,BankName, AccountNo,IfscCode,BranchAddress,
			F.ApproverDateOfReceiptOfPayment, F.ApproverReferenceNo, F.ApproverAmount, F.Comments
		FROM Msme M
	INNER JOIN MsmeBasicInformation B 
		ON M.ZedId = B.ZedId
	INNER JOIN FinancialAssistance F 
		ON B.ZedId = F.ZedId
	INNER JOIN (
		SELECT 
			ZedId,CertificationType,CertId,FinancialAssistanceId,
			STUFF((SELECT ', ' + concat(TechnologyCode,'-',technologyname)
				   FROM technologyupgradation 
				   WHERE zedid = TU.zedid
				   FOR XML PATH('')), 1, 2, '') AS TechnologyName,
			STUFF((SELECT ', ' + CONVERT(VARCHAR, NameOfTheManufaturer)
			   FROM technologyupgradation 
			   WHERE zedid = TU.zedid
			   FOR XML PATH('')), 1, 2, '') AS NameOfTheManufacturer,

			STUFF((SELECT ', ' + CONVERT(VARCHAR, MakeOrModelName)
			   FROM technologyupgradation 
			   WHERE zedid = TU.zedid
			   FOR XML PATH('')), 1, 2, '') AS MakeOrModelName,

			STUFF((SELECT ', ' + CONVERT(VARCHAR, AgencyOrSupplier)
			   FROM technologyupgradation 
			   WHERE zedid = TU.zedid
			   FOR XML PATH('')), 1, 2, '') AS AgencyOrSupplier,
			STUFF((SELECT ', ' + CONVERT(VARCHAR, invoicebilldate, 23)
				   FROM technologyupgradation 
				   WHERE zedid = TU.zedid
				   FOR XML PATH('')), 1, 2, '') AS InvoiceBillDate
			--STUFF((SELECT '<redacted>' + CONVERT(VARCHAR, amountpaid)
			--       FROM technologyupgradation 
			--       WHERE zedid = TU.zedid
			--       FOR XML PATH('')), 1, 2, '') AS AmountPaid,
			--STUFF((SELECT '<redacted>' + CONVERT(VARCHAR, eligibleamount)
			--       FROM technologyupgradation 
			--       WHERE zedid = TU.zedid
			--       FOR XML PATH('')), 1, 2, '') AS EligibleAmount
		FROM technologyupgradation TU
		WHERE IsEligible = 1
		GROUP BY ZedId,CertificationType,CertId,FinancialAssistanceId
	) TUP 
		ON (F.ZedId = TUP.ZedId AND F.certificationType=TUP.CertificationType AND F.CertId=TUP.CertId AND F.FinancialAssistanceId=TUP.FinancialAssistanceId)
		INNER JOIN MsmePaymentInfo P   
		ON (F.ZedId = P.ZedId AND F.CertId = P.MsmePmtCertId AND F.CertificationType = P.Certification AND P.MileStoneNum = 3)

	WHERE F.VerificationStatus = 4 AND F.CertificationBodyUserId = @UserId
	and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
	ORDER BY F.CreatedDate

	END

	ELSE
		BEGIN
		SELECT NULL DATAS
		END

END


--select * from technologyupgradation
