/****** Object:  StoredProcedure [dbo].[SP_DYNAMIC_REPORT_LIST_OF_PAYMENT_RECEIVED]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_OF_PAYMENT_RECEIVED]  --NULL,'<redacted>',10
(
	@UlbCode varchar(100) = NULL,  
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL 
)
AS
BEGIN
	

	SET NOCOUNT ON;

	DECLARE @state varchar(100) = NULL

	IF @RoleId = 8
	BEGIN
	SELECT @State=StateCode FROM USERS WHERE UserId=@UserId and RoleId=8
	END

	SELECT m.ZedId,P.Certification,P.MileStoneNum, PUnitName PUnitName,
	--PAddress,m.pstatename StateName,m.PDistrictName DistrictName,PPin,
	m.EnterpriseTypee Size,UdyogAadharNo,TotalEmp,
		B.Gender, B.SocialCategoryName,PanNo,
		P.GstinNumber, P.TanNumber,
		P.Id TransactionId, P.TransactionStatus,
		--P.UtrNumber,P.PaymentType,
		convert(varchar, P.CreatedDate, 9) as TransactionDate,
		P.SubsidyPercentage,
		case when P.Tds='7.5' then 10 when P.Tds='1.5' then 2 end as Tds,P.Total as MilestoneFee,ApplicantContributionAfterSubsidy, ISNULL(Amount,0) AmountPaid
		,T.TrackingId as [CCAvenue Ref#]
		,DATEDIFF(DAY, '18991230', P.CreatedDate) AS TransactionDate
		--Convert(varchar,P.ApproverDateOfReceiptOfPayment,106) ApproverDateOfReceiptOfPayment, P.ApproverReferenceNo, P.ApproverAmount, P.Comments
		
	FROM MsmePaymentInfo P inner join Msme M on (P.ZedId=M.ZedId)
	inner join MsmeBasicInformation B on (P.ZedId=B.ZedId )
	left join PaymentGateWayTransactions T on (M.ZedId=T.ZedId and P.Certification=T.Certification and P.MileStoneNum=T.MileStoneNumber and PaymentStatus='Success')
	WHERE P.ZedId=M.ZedId AND M.ZedId=B.ZedId and UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
	AND (@State is null or M.StateId=@State)
	ORDER By ZedId desc 

END


