CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_OF_PAYMENT_RECEIVED_KAWACH] 
(
	@UlbCode varchar(100) = NULL,  
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL 
)
AS
BEGIN
	

	SET NOCOUNT ON;

	SELECT m.ZedId,P.Certification, PUnitName,m.pstatename StateName,m.PDistrictName DistrictName,m.EnterpriseTypee Size,case when (M.IsCouponUsed)=1 then 'Yes' when IsCouponUsed is null then 'No' end as JoiningReward,
		B.UdyogAadharNo, B.TotalEmp, B.Gender, B.SocialCategoryName,
		P.GstinNumber, P.TanNumber, P.UtrNumber, P.Id TransactionId, P.TransactionStatus, P.PaymentType, P.SubsidyPercentage,P.Tds,ISNULL(Amount,0) AmountPaid
		--Convert(varchar,P.ApproverDateOfReceiptOfPayment,106) ApproverDateOfReceiptOfPayment, P.ApproverReferenceNo, P.ApproverAmount, P.Comments
		
	FROM kawach.dbo.MsmePaymentInfo P inner join kawach.dbo.Msme M on (P.ZedId=M.ZedId)
	inner join kawach.dbo.MsmeBasicInformation B on (P.ZedId=B.ZedId )
	left join kawach.dbo.PaymentGateWayTransactions T on (M.ZedId=T.ZedId and P.Certification=T.Certification and PaymentStatus='Success')
	WHERE P.ZedId=M.ZedId AND M.ZedId=B.ZedId 
	ORDER By ZedId desc

END


