/****** Object:  StoredProcedure [dbo].[SP_DYNAMIC_REPORT_LIST_OF_REGISTERED_MSME]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_OF_REGISTERED_MSME] --NULL,'<redacted>',10
(
	@UlbCode varchar(100) = NULL,  
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL 
)
AS
BEGIN
	
	------  LIST OF REGISTERED MSME

	SET NOCOUNT ON;

	DECLARE @state varchar(100) = NULL

	IF @RoleId = 8
	BEGIN
	SELECT @State=StateCode FROM USERS WHERE UserId=@UserId and RoleId=8
	END

	SELECT M.ZedId,
	--case when (IsBronzePaymentDone is null and IsSilverPaymentDone is null and IsGoldPaymentDone is null) then '<redacted>'			
	--		when (CertificationStatus=6 and CertificationBodyUserId is null) then '<redacted>'
	--		when (CertificationStatus=6 and CertificationBodyUserId is not null) then '<redacted>'
	--		when CertificationStatus=8 then '<redacted>'
	--		when CertificationStatus=9 then '<redacted>'
	--		when CertificationStatus=15 then '<redacted>'
	--		when CertificationStatus=13 then '<redacted>'
	--		when CertificationStatus=16 then '<redacted>'
	--		when CertificationStatus=100 then '<redacted>'
	--		when ((CertificationStatus=16 OR CertificationStatus=100) AND P.NcCount=3) then '<redacted>'
	--	end as AssessmentStatus,

	CASE 
    -- 1. Check for Milestone 3 Completion first (Status 16 or 100)
    WHEN (CertificationStatus IN (16, 100) AND P.NcCount = 3) THEN 'Completed'
    
    -- 2. Check for general Completion (Milestones 1 & 2)
    WHEN CertificationStatus = 100 THEN 'Completed'
    
    -- 3. Now handle other statuses
    WHEN (IsBronzePaymentDone IS NULL AND IsSilverPaymentDone IS NULL AND IsGoldPaymentDone IS NULL) THEN 'Payment Pending By MSME'
    WHEN (CertificationStatus = 6 AND CertificationBodyUserId IS NULL) THEN 'Allocation Pending to CO'
    WHEN (CertificationStatus = 6 AND CertificationBodyUserId IS NOT NULL) THEN 'Allocated to CO'
    WHEN CertificationStatus = 8 THEN 'Scheduled'
    WHEN CertificationStatus = 9 THEN 'Started'
    WHEN CertificationStatus = 13 THEN 'In-progress'
    WHEN CertificationStatus = 15 THEN 'Quality Check Pending by CO'
    WHEN CertificationStatus = 16 THEN 'Quality Check Completed by CO'
END AS AssessmentStatus,




		P.NcCount as MileStoneNo,
		DATEDIFF(DAY, '18991230', ApplicationReceived)  [MileStone Payment Date],
		DATEDIFF(DAY, '18991230', CoAlloted)  [Date Of Allocation],
		--FORMAT(BdsFromDate, '<redacted>') BdsFromDate,
		--FORMAT(BdsToDate, '<redacted>') BdsToDate,
		--FORMAT(HapFromDate, '<redacted>') HapFromDate,
		--FORMAT(HapToDate, '<redacted>') HapToDate,
		DATEDIFF(DAY, '18991230', BdsFromDate) BdsFromDate,
		DATEDIFF(DAY, '18991230', BdsToDate) BdsToDate,
		DATEDIFF(DAY, '18991230', HapFromDate) HapFromDate,
		DATEDIFF(DAY, '18991230', HapToDate) HapToDate,
			[SubmittedByConsultant],
			[ApplicantAcceptedOn],			
		PUnitName,	p.Certification,
	M.OwnerName,	M.EnterpriseTypee,	M.MobileNo,
	M.EmailId,	TwoDigitActivity,
	B.UdyogAadharNo, B.SocialCategoryName,	B.Gender, PAddress,	PStateName,	PDistrictName,
	U.UserName as ConsultantOrganisation, US.UserName as LeadConsultant,
	[CoAssessor1] [CoConsultant1],[CoAssessor2] [CoConsultant2],[CoAssessor3] [CoConsultant3],
	[CoAssessor4] [CoConsultant4],[CoAssessor5] [CoConsultant5],[CoAssessor6] [CoConsultant6],
	[CoAssessor7] [CoConsultant7],[CoAssessor8]	[CoConsultant8],
	UT.TechExpertName as [TechExpertName],
	[TechnologiesRecommended] [Technologies Recommended On],
	[ApplicationOfTUDoneByMSME] [MSME Submitted Application for TU On]
	

	FROM Msme M
	inner join MsmeCertifications P on (P.ZedId=M.ZedId)
	inner join msmebasicinformation B on (B.ZedId=M.ZedId)
	LEFT JOIN Users U on (P.CertificationBodyUserId=U.UserId)
	LEFT JOIN Users US on (P.SiteAssessorId=US.UserId)
	OUTER APPLY (
		SELECT STRING_AGG(U_TE.UserName, ', ') AS TechExpertName
		FROM STRING_SPLIT(P.TechExpert, ',') s
		INNER JOIN Users U_TE ON LTRIM(RTRIM(s.value)) = U_TE.UserId
	) UT

	left join
			(select ZedId,CertificationType,
			[ApplicationReceived],
			[ScheduledOn],
			[AllocationCompleted],
			[BdsScheduledOn],
			[HapScheduledOn],
			[SubmittedByConsultant],
			[Completed],
			[ApplicantAcceptedOn],
			[TechnologiesRecommended],
			[ApplicationOfTUDoneByMSME],
			[CoAlloted],
			NcCount
			from 
			(select ZedId, FORMAT(CreatedDate, 'MMMM d, yyyy') CreatedOn,StatusType,CertificationType,NcCount from MsmeHistory where StatusType is not null) A
			pivot (
			max(CreatedOn) for StatusType in (
			[ApplicationReceived],
			[ScheduledOn],
			[AllocationCompleted],
			[BdsScheduledOn],
			[HapScheduledOn],
			[SubmittedByConsultant],
			[Completed],
			[ApplicantAcceptedOn],
			[TechnologiesRecommended],
			[ApplicationOfTUDoneByMSME],
			[CoAlloted]
			) ) as Pvt
		) PVD
		on (P.ZedId=PVD.ZedId and P.Certification=PVD.CertificationType and p.NcCount=PVD.NcCount ) 

		left join
		(
		select * from 
		(
		select ZedId,Certification,UserName,NcCount, concat('CoAssessor', ROW_NUMBER()
		over(partition by zedid,nccount order by coassessorid)) CoAssessors from
		(select distinct zedid,Certification,CoAssessorId,U.UserName,NcCount from AllotedCoAssessors A inner join Users U on (A.CoAssessorId=U.UserId)) A
		) X
		pivot
		(
		max(UserName) for CoAssessors in ([CoAssessor1],[CoAssessor2],[CoAssessor3],[CoAssessor4],[CoAssessor5],[CoAssessor6],[CoAssessor7],[CoAssessor8])
		) P
		) PVA
		on (P.ZedId=PVA.ZedId and P.Certification=PVA.Certification and p.NcCount=PVA.NcCount)

	where UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
	and (@State is null or M.StateId=@State)
	ORDER By M.MsmeId desc

END


