/****** Object:  StoredProcedure [dbo].[SP_DYNAMIC_REPORT_LIST_OF_REGISTERED_MSME_LATEST_RECORDS]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_OF_REGISTERED_MSME_LATEST_RECORDS] --NULL,'<redacted>',10
(
	@UlbCode varchar(100) = NULL,  
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL 
)
AS
BEGIN
	
	------  LIST OF REGISTERED MSME

	SET NOCOUNT ON;

	DECLARE @state varchar(100) = NULL

	IF @RoleId = 8
	BEGIN
	SELECT @State=StateCode FROM USERS WHERE UserId=@UserId and RoleId=8
	END

	
	;WITH RecentNc AS (
    SELECT *,
           ROW_NUMBER() OVER (PARTITION BY ZedId ORDER BY NcCount DESC) AS rn
    FROM MsmeCertifications
)
SELECT M.ZedId,
    CASE 
        WHEN (IsBronzePaymentDone IS NULL AND IsSilverPaymentDone IS NULL AND IsGoldPaymentDone IS NULL) 
            THEN 'Payment Pending By MSME'			
        WHEN CertificationStatus = 6 THEN 'Payment done By MSME'
        WHEN CertificationStatus = 8 THEN 'Consultant Allocated'
        WHEN CertificationStatus = 9 THEN 'Consultancy Planned'
        WHEN CertificationStatus = 15 THEN 'In Quality Check'
        WHEN CertificationStatus = 13 THEN 'Consultancy in progress'
        WHEN CertificationStatus = 16 THEN 'Submitted By Consultant'
        WHEN CertificationStatus = 100 THEN 'Applicant Accepted the Milestone'
        WHEN ((CertificationStatus = 16 OR CertificationStatus = 100) AND P.NcCount = 3) 
            THEN 'Consultancy Completed'
    END AS LatestStatus,
    P.NcCount AS MileStoneNo,
	--DATEDIFF(DAY, '<redacted>', P.CreatedDate)
    --[ApplicationReceived] AS [MileStone Payment Date],
    --FORMAT(BdsFromDate, '<redacted>') AS BdsFromDate,
    --FORMAT(BdsToDate, '<redacted>') AS BdsToDate,
    --FORMAT(HapFromDate, '<redacted>') AS HapFromDate,
    --FORMAT(HapToDate, '<redacted>') AS HapToDate,
	DATEDIFF(DAY, '18991230', [ApplicationReceived]) AS [MileStone Payment Date],
	DATEDIFF(DAY, '18991230', BdsFromDate) AS BdsFromDate,
    DATEDIFF(DAY, '18991230', BdsToDate) AS BdsToDate,
    DATEDIFF(DAY, '18991230', HapFromDate) AS HapFromDate,
    DATEDIFF(DAY, '18991230', HapToDate) AS HapToDate,
    [SubmittedByConsultant],
    [ApplicantAcceptedOn],			
    PUnitName, P.Certification,
    M.OwnerName, M.EnterpriseTypee, M.MobileNo,
    M.EmailId, TwoDigitActivity,
    B.UdyogAadharNo, B.SocialCategoryName, B.Gender, 
    PAddress, PStateName, PDistrictName,
    U.UserName AS ConsultantOrganisation, 
    US.UserName AS LeadConsultant,
    [CoAssessor1] AS [CoConsultant1], [CoAssessor2] AS [CoConsultant2], [CoAssessor3] AS [CoConsultant3],
    [CoAssessor4] AS [CoConsultant4], [CoAssessor5] AS [CoConsultant5], [CoAssessor6] AS [CoConsultant6],
    [CoAssessor7] AS [CoConsultant7], [CoAssessor8] AS [CoConsultant8],
    [TechnologiesRecommended] AS [Technologies Recommended On],
    [ApplicationOfTUDoneByMSME] AS [MSME Submitted Application for TU On]
FROM Msme M
INNER JOIN RecentNc P ON P.ZedId = M.ZedId AND P.rn = 1
INNER JOIN msmebasicinformation B ON B.ZedId = M.ZedId
LEFT JOIN Users U ON P.CertificationBodyUserId = U.UserId
LEFT JOIN Users US ON P.SiteAssessorId = US.UserId
LEFT JOIN (
    SELECT ZedId, CertificationType,
           [ApplicationReceived],
           [ScheduledOn],
           [AllocationCompleted],
           [BdsScheduledOn],
           [HapScheduledOn],
           [SubmittedByConsultant],
           [Completed],
           [ApplicantAcceptedOn],
           [TechnologiesRecommended],
           [ApplicationOfTUDoneByMSME],
           NcCount
    FROM (
        SELECT ZedId, 
               FORMAT(CreatedDate, 'MMMM d, yyyy') AS CreatedOn, 
               StatusType, CertificationType, NcCount
        FROM MsmeHistory 
        WHERE StatusType IS NOT NULL
    ) A
    PIVOT (
        MAX(CreatedOn) FOR StatusType IN (
            [ApplicationReceived],
            [ScheduledOn],
            [AllocationCompleted],
            [BdsScheduledOn],
            [HapScheduledOn],
            [SubmittedByConsultant],
            [Completed],
            [ApplicantAcceptedOn],
            [TechnologiesRecommended],
            [ApplicationOfTUDoneByMSME]
        )
    ) AS Pvt
) PVD ON P.ZedId = PVD.ZedId AND P.Certification = PVD.CertificationType AND P.NcCount = PVD.NcCount
LEFT JOIN (
    SELECT * 
    FROM (
        SELECT ZedId, Certification, UserName, NcCount, 
               CONCAT('CoAssessor', ROW_NUMBER() OVER (PARTITION BY ZedId, NcCount ORDER BY CoAssessorId)) AS CoAssessors
        FROM (
            SELECT DISTINCT ZedId, Certification, CoAssessorId, U.UserName, NcCount 
            FROM AllotedCoAssessors A 
            INNER JOIN Users U ON A.CoAssessorId = U.UserId
        ) A
    ) X
    PIVOT (
        MAX(UserName) FOR CoAssessors IN (
            [CoAssessor1], [CoAssessor2], [CoAssessor3], [CoAssessor4], 
            [CoAssessor5], [CoAssessor6], [CoAssessor7], [CoAssessor8]
        )
    ) P
) PVA ON P.ZedId = PVA.ZedId AND P.Certification = PVA.Certification AND P.NcCount = PVA.NcCount
WHERE UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
and (@State is null or M.StateId=@State)
ORDER BY M.MsmeId DESC;

END


