/****** Object:  StoredProcedure [dbo].[SP_DYNAMIC_REPORT_LIST_OF_REGISTERED_MSME_WITH_DATES]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_OF_REGISTERED_MSME_WITH_DATES] --NULL,'<redacted>',10
(
	@UlbCode varchar(100) = NULL,  
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL 
)
AS
BEGIN
	
	------  LIST OF REGISTERED MSME

	SET NOCOUNT ON;

	DECLARE @state varchar(100) = NULL

	IF @RoleId = 8
	BEGIN
	SELECT @State=StateCode FROM USERS WHERE UserId=@UserId and RoleId=8
	END

	SELECT M.ZedId,
	case when (IsBronzePaymentDone is null and IsSilverPaymentDone is null and IsGoldPaymentDone is null) then 'Payment Pending By MSME'			
			when CertificationStatus=6 then 'Payment done By MSME'
			when CertificationStatus=8 then 'Consultant Allocated'
			when CertificationStatus=9 then 'Consultancy Planned'
			when CertificationStatus=15 then 'In Quality Check'
			when CertificationStatus=13 then 'Consultancy in progress'
			when CertificationStatus=16 then 'Submitted By Consultant'
			when CertificationStatus=100 then 'Applicant Accepted the Milestone'
			when ((CertificationStatus=16 OR CertificationStatus=100) AND P.NcCount=3) then 'Consultancy Completed'
		end as AssessmentStatus,
		P.NcCount as MileStoneNo,
		--[ApplicationReceived]  [MileStone Payment Date],
		FORMAT(BdsFromDate, 'MMMM d, yyyy') BdsFromDate,
		FORMAT(BdsToDate, 'MMMM d, yyyy') BdsToDate,
		FORMAT(HapFromDate, 'MMMM d, yyyy') HapFromDate,
		FORMAT(HapToDate, 'MMMM d, yyyy') HapToDate,
			[SubmittedByConsultant],
			[ApplicantAcceptedOn],	
		PUnitName,	p.Certification,
	--M.OwnerName,	M.EnterpriseTypee,	
	--M.MobileNo,
	--M.EmailId,
	--TwoDigitActivity,
	--B.UdyogAadharNo, 
	--B.SocialCategoryName,	B.Gender, PAddress,	
	[Open Meeting] OpenMeetingDate, [Close Meeting] CloseMeetingDate,
	PStateName,	PDistrictName,
	U.UserName as ConsultantOrganisation, US.UserName as LeadConsultant,
	[CoAssessor1] [CoConsultant1],[CoAssessor2] [CoConsultant2],[CoAssessor3] [CoConsultant3],
	[CoAssessor4] [CoConsultant4],[CoAssessor5] [CoConsultant5],[CoAssessor6] [CoConsultant6],
	[CoAssessor7] [CoConsultant7],[CoAssessor8]	[CoConsultant8]
	

	FROM Msme M
	inner join MsmeCertifications P on (P.ZedId=M.ZedId)
	inner join msmebasicinformation B on (B.ZedId=M.ZedId)
	LEFT JOIN Users U on (P.CertificationBodyUserId=U.UserId)
	LEFT JOIN Users US on (P.SiteAssessorId=US.UserId)
	left join
			(select ZedId,CertificationType,
			[ApplicationReceived],
			[ScheduledOn],
			[AllocationCompleted],
			[BdsScheduledOn],
			[HapScheduledOn],
			[SubmittedByConsultant],
			[Completed],
			[ApplicantAcceptedOn],
			NcCount
			from 
			(select ZedId, FORMAT(CreatedDate, 'MMMM d, yyyy') CreatedOn,StatusType,CertificationType,NcCount from MsmeHistory where StatusType is not null) A
			pivot (
			max(CreatedOn) for StatusType in (
			[ApplicationReceived],
			[ScheduledOn],
			[AllocationCompleted],
			[BdsScheduledOn],
			[HapScheduledOn],
			[SubmittedByConsultant],
			[Completed],
			[ApplicantAcceptedOn]
			) ) as Pvt
		) PVD
		on (P.ZedId=PVD.ZedId and P.Certification=PVD.CertificationType and p.NcCount=PVD.NcCount ) 

		left join
		(
		select * from 
		(
		select ZedId,Certification,UserName,NcCount, concat('CoAssessor', ROW_NUMBER()
		over(partition by zedid,nccount order by coassessorid)) CoAssessors from
		(select distinct zedid,Certification,CoAssessorId,U.UserName,NcCount from AllotedCoAssessors A inner join Users U on (A.CoAssessorId=U.UserId)) A
		) X
		pivot
		(
		max(UserName) for CoAssessors in ([CoAssessor1],[CoAssessor2],[CoAssessor3],[CoAssessor4],[CoAssessor5],[CoAssessor6],[CoAssessor7],[CoAssessor8])
		) P
		) PVA
		on (P.ZedId=PVA.ZedId and P.Certification=PVA.Certification and p.NcCount=PVA.NcCount)

		LEFT JOIN
		(
		select * from 
	(select ZedId,CertificationType,nccount,MeetingType,CreatedDate from Meetings) A
	pivot
	(
	max(createddate) for meetingtype in ([Open Meeting],[Close Meeting])
	) p
		) MTS
		ON (P.ZedId=MTS.ZedId AND P.Certification=MTS.CertificationType AND P.NcCount=MTS.NcCount)
		

	where UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915')
	and (@State is null or M.StateId=@State)
	ORDER By M.MsmeId,MileStoneNo desc


END


