/****** Object:  StoredProcedure [dbo].[SP_DYNAMIC_REPORT_LIST_TECH_UPGRADE_STATUSES]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================

--[SP_DYNAMIC_REPORT_LIST_TECH_UPGRADE_STATUSES]  NULL,'<redacted>',10
CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_LIST_TECH_UPGRADE_STATUSES]  --NULL,'<redacted>',10
(
	@UlbCode varchar(100) = NULL,  
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL 
)
AS
BEGIN	
		IF @RoleId = 10
		BEGIN
	
			SET NOCOUNT ON;

			SELECT M.ZedId, PUnitName,

			CASE 
				WHEN F.TechUpgradeStatus = 2 AND F.CertificationBodyUserId IS NULL 
					THEN 'Allocation is Pending'
				WHEN F.TechUpgradeStatus = 2 AND F.CertificationBodyUserId IS NOT NULL
					THEN 'Allocation is Completed'
				ELSE G.StatusText
			END AS CurrentStatus,
			
			
			--DATEDIFF(DAY, '<redacted>', ApproveOrRejectDate) ApprovalDate,
			DATEDIFF(DAY, '18991230', TUD.LatestStatusDate) AS StatusDate,
			P.EnterpriseTypee EnterpriseType,B.Gender,PStateName,PDistrictName, concat(PAddress, Ppin) UnitAddress,
			 --B.UdyogAadharNo, B.TotalEmp,  B.SocialCategoryName,
			 TUP.TechnologyName, UU.UserName as [NameOfDFOOffice],U.UserName as [ApproverOfficialName],
			 TUP.TechnologyPurchaseAmountByMSME,
			 case when F.TechUpgradeStatus>=8 then TotalPaidAfterQc else NULL end as TechnologyPurchaseAmountByDFO,  SubsidyPercentage, 
			 case when F.TechUpgradeStatus>=8 then EligibleAmount else NULL end as EligibleAmount
			FROM Msme M
		INNER JOIN MsmeBasicInformation B 
			ON M.ZedId = B.ZedId
		INNER JOIN FinancialAssistance F 
			ON B.ZedId = F.ZedId
		INNER JOIN (
			SELECT 
				ZedId,CertificationType,CertId,FinancialAssistanceId,
				-- Add the SUM of MsmeAmountPaid here
				SUM(MsmeAmountPaid) AS TechnologyPurchaseAmountByMSME,
				-- End of addition
				STUFF((SELECT ', ' + concat(TechnologyCode,'-',technologyname)
					   FROM technologyupgradation 
					   WHERE zedid = TU.zedid
					   FOR XML PATH('')), 1, 2, '') AS TechnologyName,

				STUFF((SELECT ', ' + CONVERT(VARCHAR, NameOfTheManufaturer)
				   FROM technologyupgradation 
				   WHERE zedid = TU.zedid
				   FOR XML PATH('')), 1, 2, '') AS NameOfTheManufacturer,

				STUFF((SELECT ', ' + CONVERT(VARCHAR, MakeOrModelName)
				   FROM technologyupgradation 
				   WHERE zedid = TU.zedid
				   FOR XML PATH('')), 1, 2, '') AS MakeOrModelName,

				STUFF((SELECT ', ' + CONVERT(VARCHAR, AgencyOrSupplier)
				   FROM technologyupgradation 
				   WHERE zedid = TU.zedid
				   FOR XML PATH('')), 1, 2, '') AS AgencyOrSupplier,

				STUFF((SELECT ', ' + CONVERT(VARCHAR, invoicebilldate, 23)
					   FROM technologyupgradation 
					   WHERE zedid = TU.zedid
					   FOR XML PATH('')), 1, 2, '') AS InvoiceBillDate
			FROM technologyupgradation TU
			WHERE IsEligible = 1
			GROUP BY ZedId,CertificationType,CertId,FinancialAssistanceId
		) TUP 
			ON (F.ZedId = TUP.ZedId AND F.certificationType=TUP.CertificationType AND F.CertId=TUP.CertId AND F.FinancialAssistanceId=TUP.FinancialAssistanceId)
				INNER JOIN MsmePaymentInfo P ON (F.ZedId=P.ZedId and F.CertId=P.MsmePmtCertId and F.CertificationType=P.Certification and P.MileStoneNum=3)
				INNER JOIN TechupgradationStatuses G ON (F.TechUpgradeStatus=G.SNo)
			LEFT JOIN Users UU on (F.CertificationBodyUserId=UU.UserId)
			LEFT JOIN Users U on (F.FinancialAssessorId=U.UserId)
		CROSS APPLY (
				SELECT TOP 1 CreatedDate AS LatestStatusDate
				FROM msmehistory MH
				WHERE MH.ZedId = F.ZedId
				  AND MH.CertificationType = F.CertificationType -- Match certification type for relevance
				ORDER BY MH.CreatedDate DESC
		) AS TUD
		where UdyogAadharNo NOT IN ('UDYAM-GJ-01-0013310', 'UDYAM-MH-23-0006117', 'UDYAM-UP-29-0003915','UDYAM-UP-16-0001476')
		ORDER BY F.CreatedDate

		END

		
	ELSE
		BEGIN
		SELECT NULL DATAS
		END

	
END


GO
/****** Object:  StoredProcedure [dbo].[SP_DYNAMIC_REPORT_SA_UNITS]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_DYNAMIC_REPORT_SA_UNITS] 
(
	@UlbCode varchar(100) = NULL,  
	@Userid varchar(100)= NULL,  
	@RoleId varchar(100)= NULL 
)
AS
BEGIN
	
	SET NOCOUNT ON;

    SELECT  ROW_NUMBER() OVER(ORDER BY SelfCertificationDate) [SNo]
	  
	  ,FORMAT(SelfCertificationDate, 'MMMM d, yyyy h:mm tt') [Date of Self Certification]
	  ,EstablishmentName as [Unit Name] 
	  ,[RegistrationNumber] [Hotel Cloud Registration Number]
	  ,S.[Acommodationtype] [Acommodation Type]
      ,[TotalRooms] [Total Rooms]
	  ,RestaurantType
	  ,Category
	  ,SelfCertificateNo CertificateNo
	  ,IsCertificateGenerated as [No. of Self Certification]
	  ,FORMAT(ResetDate, 'MMMM d, yyyy h:mm tt') [Reset Or Retake Date]
	  ,[EstablishmentAddress]
	  ,[EstablishmentCity]
	  ,[DistrictName]
      ,[StateName]
      ,[EstablishmentPinCode]
	  ,[EstablishmentPhoneNo]
      ,[EstablishmentFaxNo]
      ,[RespondentName]
      ,[MobileNo]
      ,[EmailId]
	  ,CASE WHEN [AmountPaid] is NOT NULL then SaDate ELSE NULL END as [PrefferedSADate]
	  ,[CertificationBodyUserId]
	  ,[ModeOfAssessment]
	  ,[AssessorUserId]
	  ,[FinalSaDate]
	  ,[AcceptOrRejectDate]
	  ,[ReasonForRejection]		
	  ,[IsSaDeclarationAccepted]
	  ,[PaymentDate]	
	  ,[AmountPaid]
	  ,[GstNumber]
	  ,[UtrNumber]
	  ,CASE WHEN SaStatus=0 then 'Not Started' WHEN SaStatus=1 then 'In Progress'  WHEN SaStatus=2 then 'In Quality Check' WHEN SaStatus=3 then 'Completed' End as SaStatus	
	  ,[AgencyComments]
	  ,[SaCertificateNo]
	  ,[SaFinalSubmitDate]


	  --,REPLACE(UPPER(case when EstablishmentCity is null or EstablishmentCity = '' then '' else EstablishmentCity + '<redacted>' end + case when DistrictName is null or DistrictName='' then '' else DistrictName + '<redacted>' end + StateName),'<redacted>','') EstablishmentFullAddress
	FROM SelfAssessments S 
	WHERE IsCertificateGenerated>0 and RegistrationNumber not in ('UC23111823863','UC23111823861','UC13111923860','UC3250522285')
	ORDER BY SelfCertificationDate
END

