/****** Object:  StoredProcedure [dbo].[SP_EMAIL_GET_DETAILS]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_EMAIL_GET_DETAILS] --'<redacted>','<redacted>'
(
	@ZedId Varchar(100) =NULL,
	@Certification Varchar(100) =NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	DECLARE @NcCount int = NULL
	SELECT @NcCount=max(NcCount) FROM ZED_CONSULTANT.dbo.MsmeCertifications where ZedId=@ZedId and Certification= @Certification

	SELECT  M.MobileNo, M.EmailId, M.EnterpriseName, concat(PAddress,', ',PDistrictName,', ',PStateName,'-',PPin) Address,
		U.UserName AgencyName, U.Email AgencyEmailId, U.UserId AgencyUserId,U.SpocName,U.MobileNo AgencyMobileNo,

		case when CertificationStatus<=6 then U2.MobileNo else U5.MobileNo end as AssessorMobileNo,
		case when CertificationStatus<=6 then U2.UserName else U5.UserName end as AssessorName,
		case when CertificationStatus<=6 then U2.Email else U5.Email end as AssessorEmailId,
		case when CertificationStatus<=6 then U2.UserId else U5.UserId end as AssessorUserId,
		case when CertificationStatus<=6 then U2.Password else U5.Password end as Password,
		ModeOfAssessment, FORMAT(AssessmentDate, 'MMMM dd, yyyy') FinalSaDate, NcCount,U3.Password MsmePassword,
		U4.UserName CoAssessorName, U4.Email CoAssessorEmailId, U4.UserId CoAssessorUserId, U4.Password CoAssessorPassword,
		PUnitName,FORMAT(NcFinalClosureDt, 'MMMM dd, yyyy') NcFinalClosureDt,
		FORMAT(BdsFromDate, 'MMMM dd, yyyy') BdsFromDate, FORMAT(HapFromDate, 'MMMM dd, yyyy') HapFromDate,
		FORMAT(BdsToDate, 'MMMM dd, yyyy') BdsToDate, FORMAT(HapToDate, 'MMMM dd, yyyy') HapToDate,
		null  CategoryOfCertificate
		
		
	from Msme M inner join MsmeCertifications C on (M.ZedId=C.ZedId)
	inner join MsmeBasicInformation B on (M.ZedId=B.ZedId)
	left join Users U on (U.UserId=C.CertificationBodyUserId)
	left join Users U2 on (U2.UserId=C.DesktopAssessorId)
	left join Users U3 on (U3.UserId=C.ZedId)
	left join Users U4 on (U4.UserId=C.CoAssessorId)
	left join Users U5 on (U5.UserId=C.SiteAssessorId)
	where Certification=@Certification and C.ZedId=@ZedId and C.NcCount=@NcCount


	select U.UserName CoAssessorName, U.Email CoAssessorEmailId, A.CoAssessorId CoAssessorUserId,U.Password CoAssessorPassword
	from AllotedCoAssessors A
	inner join Users U on (A.CoAssessorId=U.UserId)
	where ZedId=@ZedId and Certification=@Certification and NcCount=@NcCount


END


GO
/****** Object:  StoredProcedure [dbo].[SP_EMAIL_GET_DETAILS_FA]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
