CREATE PROC [dbo].[SP_EXPORT_SELF_ASSESSMENTS] --1,1
( 
	@RoleId varchar(50)=NULL,
	@UserId varchar(50)=NULL
)
AS
BEGIN

	select S.StateName,DistrictName,RespondentName,Email,Gender,RespondentAge,Service,Experience,convert(date,CreatedDate) StartDate,P.* from SelfAssessments S inner join 
	(select * from (

		select MobileNo,QuestionCode,AnswerCode from SelfAssessmentQuestions

		) A

		pivot (max(answercode) for questioncode in ([Q101],[Q102],[Q103],[Q201],[Q202],[Q203],[Q204a],[Q204b],[Q205],[Q206],[Q207],[Q208],[Q209],[Q210],[Q211],[Q212],
		[Q213],[Q214],[Q215],[Q216],[Q217],[Q218],[Q219],[Q220],[Q221],[Q222],[Q223],[Q224],[Q225],[Q226],[Q227],[Q228],[Q229],[Q230],[Q231],[Q232],[Q233],[Q234],[Q235],
		[Q236],[Q237],[Q238],[Q239],[Q240],[Q241],[Q242],[Q243],[Q244],[Q245],[Q246],[Q247],[Q248],[Q249],[Q250],[Q251],[Q252],[Q253],[Q254],[Q255],[Q256],[Q257],[Q258],
		[Q259],[Q260],[Q261],[Q262],[Q263],[Q264],[Q265],[Q266a],[Q266b],[Q267],[Q301],[Q302],[Q303],[Q304],[Q305],[Q306],[Q307],[Q308],[Q309],[Q310],[Q311],[Q312],[Q313],
		[Q314],[Q315],[Q316],[Q317],[Q318],[Q319],[Q320],[Q321],[Q322],[Q323],[Q324],[Q325],[Q326],[Q327],[Q328],[Q329],[Q330],[Q331],[Q332],[Q333],[Q334],[Q335],[Q336],
		[Q337],[Q338],[Q339],[Q340],[Q341],[Q342],[Q343],[Q344],[Q345],[Q346],[Q347],[Q348],[Q349],[Q350],[Q351],[Q352],[Q353],[Q354],[Q355]) 

		) as Pvt) P on (S.MobileNo=P.MobileNo)
	order by StateName,DistrictName



END




