GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================

CREATE PROCEDURE [dbo].[SP_FINANCIAL_ASSISTANCE_FINAL_AUBMIT] --'<redacted>',null,'<redacted>','<redacted>', '<redacted>',null,null
(
	@IsApproved varchar(50) = NULL,
	@Comments varchar(2000) = NULL,
	@CertificationType varchar(50) = NULL,
	@ZedId varchar(50) = NULL,
	@Id varchar(50) = NULL,
	@UserId varchar(50) = NULL,
	@RoleId varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	DECLARE @CertId varchar(50)
	DECLARE @ConsultantId varchar(50)	
	DECLARE @ConsultantEmail varchar(50)	
	DECLARE @FinancialAssistanceId varchar(50)

	select @CertId=CertId, @FinancialAssistanceId=FinancialAssistanceId from FinancialAssistance WHERE ZedId=@ZedId AND CertificationType=@CertificationType AND Id=@Id

	select @ConsultantId=FinancialAssessorId from FinancialAssistance where ZedId=@ZedId AND CertificationType=@CertificationType AND Id=@Id and CertId=@CertId


	IF @RoleId IS NULL OR @RoleId =''
	SET @RoleId =3


	IF @RoleId=3 and (select VerificationStatus from FinancialAssistance WHERE ZedId=@ZedId AND CertificationType=@CertificationType AND Id=@Id)=2
	BEGIN

	---------------------- CODE TO UPDATE THE ELIGIBLE AMOUNT START-----------------

			DECLARE @TotalAmountPaid DECIMAL(18,2), 
				@SubsidyPercentage DECIMAL(5,2),
				@SubsidyAmount DECIMAL(18,2),
				@EligibleAmount DECIMAL(18,2)

			SELECT @TotalAmountPaid=SUM(CAST(amountpaid AS DECIMAL(18,2))) FROM ZED_CONSULTANT.DBO.TechnologyUpgradation WHERE ZedId=@ZedId AND CertificationType=@CertificationType AND CertId=@CertId and IsEligible=1
			and FinancialAssistanceId in (select TOP 1 FinancialAssistanceId from FinancialAssistance WHERE ZedId=@ZedId AND CertificationType=@CertificationType and TechUpgradeStatus!=7)

			SELECT @SubsidyPercentage=SubsidyPercentage FROM ZED_CONSULTANT.DBO.MsmePaymentInfo WHERE ZedId=@ZedId and Certification=@CertificationType and MileStoneNum=3 AND MsmePmtCertId=@CertId

			SET @SubsidyAmount = @TotalAmountPaid*(@SubsidyPercentage/100)

			SET @EligibleAmount = CASE WHEN @SubsidyAmount>300000 THEN 300000 ELSE @SubsidyAmount END	

	--------------------- CODE TO UPDATE THE ELIGIBLE AMOUNT END------------------------


		IF @IsApproved=1 
		BEGIN
			UPDATE FinancialAssistance SET IsApproved=@IsApproved,VerificationStatus=3,ReasonForRejection=null, EligibleAmount=@EligibleAmount, TotalPaidAfterQc=@TotalAmountPaid WHERE ZedId=@ZedId AND CertificationType=@CertificationType AND Id=@Id
			UPDATE ZED_CONSULTANT.DBO.FinancialAssistance SET TechUpgradeStatus=6 WHERE ZedId=@ZedId AND CertificationType=@CertificationType AND Id=@Id

			INSERT INTO ZED_CONSULTANT.DBO.MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType,nccount)
			VALUES (@ZedId,concat('Consultant approved Technology upgradation on ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'ConsultantApprovedTU','3')
		END
		ELSE
		BEGIN
			UPDATE FinancialAssistance SET IsApproved=@IsApproved,VerificationStatus=5,ReasonForRejection=@Comments, EligibleAmount=@EligibleAmount, TotalPaidAfterQc=@TotalAmountPaid WHERE ZedId=@ZedId AND CertificationType=@CertificationType AND Id=@Id
			UPDATE ZED_CONSULTANT.DBO.FinancialAssistance SET TechUpgradeStatus=7 WHERE ZedId=@ZedId AND CertificationType=@CertificationType AND Id=@Id

			INSERT INTO ZED_CONSULTANT.DBO.MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType,nccount)
			VALUES (@ZedId,concat('Consultant rejected Technology upgradation on ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'ConsultantRejectedTU','3')

			UPDATE Msme set TechnologyUpgradation=1 where ZedId=@ZedId

			----MAIL ALREADY THERE IN CODE------
			---EXEC [dbo].[SP_SEND_AUTO_MAIL_TO_MSME_FOR_CONSULTANT_REJECTION] @ZedId, @CertificationType

		END


	END

	IF @RoleId=2
	BEGIN
		IF @IsApproved=1
		BEGIN
			UPDATE FinancialAssistance SET IsApproved=@IsApproved,VerificationStatus=4 WHERE ZedId=@ZedId AND CertificationType=@CertificationType AND Id=@Id
			UPDATE ZED_CONSULTANT.DBO.FinancialAssistance SET TechUpgradeStatus=8 WHERE ZedId=@ZedId AND CertificationType=@CertificationType AND Id=@Id

			INSERT INTO ZED_CONSULTANT.DBO.MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType,nccount)
			VALUES (@ZedId,concat('Consultant Organisation approved Technology upgradation on ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'COApprovedTU','3')

			EXEC [dbo].[SP_SEND_AUTO_MAIL_TO_MSME_FOR_CO_ACCEPT_QC] @ZedId, @CertificationType

		END
		ELSE
		BEGIN
			UPDATE FinancialAssistance SET IsApproved=0,VerificationStatus=2,ReasonForRejectionAgency=@Comments WHERE ZedId=@ZedId AND CertificationType=@CertificationType AND Id=@Id			
			UPDATE ZED_CONSULTANT.DBO.FinancialAssistance SET TechUpgradeStatus=9 WHERE ZedId=@ZedId AND CertificationType=@CertificationType AND Id=@Id

			INSERT INTO ZED_CONSULTANT.DBO.MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType,nccount)
			VALUES (@ZedId,concat('Consultant Organisation rejected and send back to CC Technology upgradation on ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'CORejectedTU','3')

			--Update ConsultantDailyAttendance SET AttendanceType=CONCAT(AttendanceType,'<redacted>') WHERE ZedId=@ZedId AND Certification=@CertificationType and FinancialAssistanceId=@FinancialAssistanceId

			-----------UPDATING EXISTING MEETING RECORDS AND ATTENDANCE TO 

			Update ConsultantDailyAttendance SET ZedId=Concat(ZedId,'_D') WHERE ZedId=@ZedId AND Certification=@CertificationType and FinancialAssistanceId=@FinancialAssistanceId and MileStoneNo is null
			update TuMeetings SET ZedId=Concat(ZedId,'_D') WHERE ZedId=@ZedId AND CertificationType=@CertificationType and FinancialAssistanceId=@FinancialAssistanceId 
			update TuMeetingParticipants SET ZedId=Concat(ZedId,'_D') WHERE ZedId=@ZedId AND CertificationType=@CertificationType and FinancialAssistanceId=@FinancialAssistanceId
			update TuMeetingPhotos SET ZedId=Concat(ZedId,'_D') WHERE ZedId=@ZedId AND Certification=@CertificationType and FinancialAssistanceId=@FinancialAssistanceId

			update P set P.ZedId=Concat(P.ZedId,'_D') from FinancialAssistancePhotos F INNER JOIN financialAssistanceScreenshotPhotos P on (F.Id=P.PhotoId and F.ZedId=P.ZedId and F.CertificationType=P.Certification)  where F.ZedId=@ZedId AND Certification=@CertificationType and F.FinancialAssistanceId=@FinancialAssistanceId
			update FinancialAssistancePhotos set IsVerified=NULL where ZedId=@ZedId AND CertificationType=@CertificationType and FinancialAssistanceId=@FinancialAssistanceId

			EXEC [dbo].[SP_SEND_AUTO_MAIL_TO_CONSULTANT_WHEN_CO_REJECT_QC] @ZedId, @ConsultantId
		END
	END



	----------------NEWLY ADDED CODE FOR REJECTION OPTION IN MASTERADMIN ---------CODE START HERE--------------------------
	IF @RoleId=7
	BEGIN
		IF @IsApproved=2
		BEGIN
			UPDATE FinancialAssistance SET TechUpgradeStatus=7,IsApproved=@IsApproved,VerificationStatus=5,ReasonForRejection=@Comments WHERE ZedId=@ZedId AND CertificationType=@CertificationType AND Id=@Id
			

			INSERT INTO ZED_CONSULTANT.DBO.MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType,nccount)
			VALUES (@ZedId,concat('MasterAdmin rejected Technology upgradation on ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'MasterAdminRejectedTU','3')

			UPDATE Msme set TechnologyUpgradation=1 where ZedId=@ZedId
		END
		
	END

		----------------NEWLY ADDED CODE FOR REJECTION OPTION IN MASTERADMIN ---------CODE END HERE--------------------------




END


GO
