-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_FINANCIAL_ASSISTANCE_GET_CURRENT_CERTIFICATE_NOT_USING] --'<redacted>'
(
	@ZedId varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	IF EXISTS (SELECT Certification from MsmeCertifications where ZedId=@Zedid AND Certification='Gold' AND CertificationStatus=100 and NcCount=3)
	BEGIN
		select 'Gold' CertificationType
	END
	ELSE
	IF EXISTS (SELECT Certification from MsmeCertifications where ZedId=@Zedid AND Certification='Silver' AND CertificationStatus=100 and NcCount=3)
	BEGIN
		select 'Silver' CertificationType
	END
	ELSE
	IF EXISTS (SELECT Certification from MsmeCertifications where ZedId=@Zedid AND Certification='Bronze' AND CertificationStatus=100 and NcCount=3)
	BEGIN
		select 'Bronze' CertificationType 
	END
	
	
END
