/****** Object:  StoredProcedure [dbo].[SP_FINANCIAL_ASSISTANCE_GET_DETAILS]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
 --[SP_FINANCIAL_ASSISTANCE_GET_DETAILS] '<redacted>'
CREATE PROCEDURE [dbo].[SP_FINANCIAL_ASSISTANCE_GET_DETAILS] --'<redacted>'
(
	@ZedId varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	DECLARE @CurrentUrl varchar(100) = NULL
	SELECT @CurrentUrl=UrlName from UrlsMasterData

	DECLARE @Certification varchar(100) = NULL
	--SELECT TOP 1 @Certification = Certification FROM MsmeCertifications WHERE ZedId = @ZedId and NcCount=3 and CertificationStatus=100 ORDER BY CertificationStatusDate DESC, Id DESC;
	SELECT TOP 1 @Certification = M.Certification FROM MsmeCertifications M inner join RecommandedTechnologies R on (M.zedid=R.zedid and M.certification=R.certification)
	WHERE M.ZedId = @ZedId and NcCount=3 and CertificationStatus=100 ORDER BY CertificationStatusDate DESC, M.Id DESC;



		SELECT 
		R.Id, R.ZedId, CategoryOfCertificate, AccountNo, IfscCode, BranchAddress, R.CreatedDate, SubmittedFrom, BankName, EligibleAmount, R.CertificationType, VerificationStatus
		, CertificationBodyUserId, FinancialAssessorId, ReasonForRejection, IsApproved, R.FinancialAssistanceId, ReasonForRejectionAgency, R.TransactionStatus
		, R.ApproverDateOfReceiptOfPayment, R.ApproverReferenceNo, R.ApproverAmount, R.Comments, TechUpgradeStatus, R.CertId, SubsidyPercentage EligibleSubsidyPer, 300000 MaxEligibleSubsidy, TotalPaidAfterQc,
		(select count(*) from ZED_CONSULTANT.dbo.TuMeetings A where R.ZedId=A.ZedId and R.CertificationType=A.CertificationType and R.FinancialAssistanceId=A.FinancialAssistanceId) MeetingSubmitted
	FROM FinancialAssistance R
	INNER JOIN ZED_CONSULTANT.dbo.MsmePaymentInfo P on (R.ZedId=P.ZedId and R.CertificationType=P.Certification and P.MsmePmtCertId=R.CertId and MileStoneNum=3)
	--LEFT JOIN ZED_CONSULTANT.dbo.TuMeetings A on (R.ZedId=A.ZedId and R.CertificationType=A.CertificationType and R.FinancialAssistanceId=A.FinancialAssistanceId)
	WHERE R.ZedId=@ZedId AND R.CertificationType='Bronze' AND (VerificationStatus<5 OR VerificationStatus=6)


		SELECT 
		R.Id, R.ZedId, CategoryOfCertificate, AccountNo, IfscCode, BranchAddress, R.CreatedDate, SubmittedFrom, BankName, EligibleAmount, R.CertificationType, VerificationStatus
		, CertificationBodyUserId, FinancialAssessorId, ReasonForRejection, IsApproved, R.FinancialAssistanceId, ReasonForRejectionAgency, R.TransactionStatus
		, R.ApproverDateOfReceiptOfPayment, R.ApproverReferenceNo, R.ApproverAmount, R.Comments, TechUpgradeStatus, R.CertId, SubsidyPercentage EligibleSubsidyPer, 300000 MaxEligibleSubsidy, TotalPaidAfterQc,
		(select count(*) from ZED_CONSULTANT.dbo.TuMeetings A where R.ZedId=A.ZedId and R.CertificationType=A.CertificationType and R.FinancialAssistanceId=A.FinancialAssistanceId) MeetingSubmitted
	FROM FinancialAssistance R
	INNER JOIN ZED_CONSULTANT.dbo.MsmePaymentInfo P on (R.ZedId=P.ZedId and R.CertificationType=P.Certification and P.MsmePmtCertId=R.CertId and MileStoneNum=3)
	--LEFT JOIN ZED_CONSULTANT.dbo.TuMeetings A on (R.ZedId=A.ZedId and R.CertificationType=A.CertificationType and R.FinancialAssistanceId=A.FinancialAssistanceId)
	WHERE R.ZedId=@ZedId AND R.CertificationType='Silver' AND (VerificationStatus<5 OR VerificationStatus=6)


		SELECT 
		R.Id, R.ZedId, CategoryOfCertificate, AccountNo, IfscCode, BranchAddress, R.CreatedDate, SubmittedFrom, BankName, EligibleAmount, R.CertificationType, VerificationStatus
		, CertificationBodyUserId, FinancialAssessorId, ReasonForRejection, IsApproved, R.FinancialAssistanceId, ReasonForRejectionAgency, R.TransactionStatus
		, R.ApproverDateOfReceiptOfPayment, R.ApproverReferenceNo, R.ApproverAmount, R.Comments, TechUpgradeStatus, R.CertId, SubsidyPercentage EligibleSubsidyPer, 300000 MaxEligibleSubsidy, TotalPaidAfterQc,
		(select count(*) from ZED_CONSULTANT.dbo.TuMeetings A where R.ZedId=A.ZedId and R.CertificationType=A.CertificationType and R.FinancialAssistanceId=A.FinancialAssistanceId) MeetingSubmitted
	FROM FinancialAssistance R
	INNER JOIN ZED_CONSULTANT.dbo.MsmePaymentInfo P on (R.ZedId=P.ZedId and R.CertificationType=P.Certification and P.MsmePmtCertId=R.CertId and MileStoneNum=3)
	--LEFT JOIN ZED_CONSULTANT.dbo.TuMeetings A on (R.ZedId=A.ZedId and R.CertificationType=A.CertificationType and R.FinancialAssistanceId=A.FinancialAssistanceId)
	WHERE R.ZedId=@ZedId AND R.CertificationType='Gold' AND (VerificationStatus<5 OR VerificationStatus=6)

	SELECT P.* FROM FinancialAssistancePhotos P inner join FinancialAssistance F on (P.FinancialAssistanceId=F.FinancialAssistanceId) WHERE P.ZedId=@ZedId AND P.CertificationType='Bronze' AND (F.VerificationStatus<5 OR F.VerificationStatus=6)
	SELECT P.* FROM FinancialAssistancePhotos P inner join FinancialAssistance F on (P.FinancialAssistanceId=F.FinancialAssistanceId) WHERE P.ZedId=@ZedId AND P.CertificationType='Silver' AND (F.VerificationStatus<5 OR F.VerificationStatus=6)
	SELECT P.* FROM FinancialAssistancePhotos P inner join FinancialAssistance F on (P.FinancialAssistanceId=F.FinancialAssistanceId) WHERE P.ZedId=@ZedId AND P.CertificationType='Gold' AND (F.VerificationStatus<5 OR F.VerificationStatus=6)

	SELECT C.* FROM FinancialAssistancePhotos P inner join FinancialAssistance F on (P.FinancialAssistanceId=F.FinancialAssistanceId AND P.ZedId=F.ZedId) inner join FinancialAssistanceScreenshotPhotos C on (P.Id=C.PhotoId AND P.ZedId=C.ZedId) WHERE P.ZedId=@ZedId AND P.CertificationType='Bronze' AND (F.VerificationStatus<5 OR F.VerificationStatus=6)
	SELECT C.* FROM FinancialAssistancePhotos P inner join FinancialAssistance F on (P.FinancialAssistanceId=F.FinancialAssistanceId AND P.ZedId=F.ZedId) inner join FinancialAssistanceScreenshotPhotos C on (P.Id=C.PhotoId AND P.ZedId=C.ZedId) WHERE P.ZedId=@ZedId AND P.CertificationType='Silver' AND (F.VerificationStatus<5 OR F.VerificationStatus=6)
	SELECT C.* FROM FinancialAssistancePhotos P inner join FinancialAssistance F on (P.FinancialAssistanceId=F.FinancialAssistanceId AND P.ZedId=F.ZedId) inner join FinancialAssistanceScreenshotPhotos C on (P.Id=C.PhotoId AND P.ZedId=C.ZedId) WHERE P.ZedId=@ZedId AND P.CertificationType='Gold' AND (F.VerificationStatus<5 OR F.VerificationStatus=6)

	SELECT R.* FROM FinancialAssistance F Inner join TechnologyUpgradation R on (F.ZedId=R.ZedId and F.CertificationType=R.CertificationType and F.CertId=R.CertId AND F.FinancialAssistanceId=R.FinancialAssistanceId) WHERE F.ZedId=@ZedId AND F.CertificationType='Bronze' AND (VerificationStatus<5 OR VerificationStatus=6) 
	SELECT R.* FROM FinancialAssistance F Inner join TechnologyUpgradation R on (F.ZedId=R.ZedId and F.CertificationType=R.CertificationType and F.CertId=R.CertId AND F.FinancialAssistanceId=R.FinancialAssistanceId) WHERE F.ZedId=@ZedId AND F.CertificationType='Silver' AND (VerificationStatus<5 OR VerificationStatus=6) 
	SELECT R.* FROM FinancialAssistance F Inner join TechnologyUpgradation R on (F.ZedId=R.ZedId and F.CertificationType=R.CertificationType and F.CertId=R.CertId AND F.FinancialAssistanceId=R.FinancialAssistanceId) WHERE F.ZedId=@ZedId AND F.CertificationType='Gold' AND (VerificationStatus<5 OR VerificationStatus=6) 

	---------------------------------- THE BELOW CODE IS TO DISPLAY THE MEETING DETAILS AND ATTENDANCE IN PAGE. CERTIFICATION FILTER IS APPLYING IN CODE SIDE.--------------
	


	SELECT M.* FROM FinancialAssistance F inner join TuMeetings M on (F.FinancialAssistanceId=M.FinancialAssistanceId) WHERE M.ZedId=@ZedId order by M.Id
	SELECT M.Id,
		M.RefId,
		M.ZedId,
		M.CertificationType,
		M.Name,
		CASE WHEN M.Designation='Lead Consultant' THEN 'MSME-DFO Officer' ELSE M.Designation end  Designation,
		M.MeetingType,
		M.FinancialAssistanceId,
		M.CertId FROM FinancialAssistance F inner join TuMeetingParticipants M on (F.FinancialAssistanceId=M.FinancialAssistanceId)  WHERE M.ZedId=@ZedId order by M.Id
	SELECT M.*,concat(@CurrentUrl,'/consultancy/Uploads/TechnologyUpgradation/',@ZedId,'/',CertificationType,'/OpenMeeting/',Name,'_',PhotoId,'.jpg') as src FROM FinancialAssistance F inner join TuMeetingPhotos M on (F.FinancialAssistanceId=M.FinancialAssistanceId) WHERE M.ZedId=@ZedId order by M.Id

	--SELECT * FROM ConsultantDailyAttendance WHERE ZedId=@ZedId and MileStoneNo is null ORDER BY Certification,Id

	SELECT 
		ZedId,
		Certification,
		ConsultantId,MileStoneNo,
		FORMAT(CONVERT(date, timestamp), 'dd-MMM-yyyy') TimeStamps,
		CONVERT(TIME,MAX(CASE WHEN AttendanceType = 'LOGIN' THEN Timestamp END)) AS LoginTime,
		CONVERT(TIME,MAX(CASE WHEN AttendanceType = 'LOGOUT' THEN Timestamp END)) AS LogoutTime,
		MAX(CASE WHEN AttendanceType = 'LOGIN' THEN PhotoId END) AS LoginPhotoId1,
		MAX(CASE WHEN AttendanceType = 'LOGOUT' THEN PhotoId END) AS LogoutPhotoId1,
		concat(@CurrentUrl,'/consultancymobileapi/Attendance/',@ZedId,'/',Certification,'/',MAX(CASE WHEN AttendanceType = 'LOGIN' THEN PhotoId END),'.jpg') AS LoginPhotoId,
		concat(@CurrentUrl,'/consultancymobileapi/Attendance/',@ZedId,'/',Certification,'/',MAX(CASE WHEN AttendanceType = 'LOGOUT' THEN PhotoId END),'.jpg') AS LogoutPhotoId,
		--DATEDIFF(HOUR, MAX(CASE WHEN AttendanceType = '<redacted>' THEN Timestamp END), MAX(CASE WHEN AttendanceType = '<redacted>' THEN Timestamp END)) AS NoOfHours,
		--DATEDIFF(MINUTE, MAX(CASE WHEN AttendanceType = '<redacted>' THEN Timestamp END), MAX(CASE WHEN AttendanceType = '<redacted>' THEN Timestamp END)) AS NoOfMinutes,

		DATEDIFF(MINUTE, MAX(CASE WHEN AttendanceType = 'LOGIN' THEN Timestamp END), MAX(CASE WHEN AttendanceType = 'LOGOUT' THEN Timestamp END)) / 60 AS NoOfHours,
    DATEDIFF(MINUTE, MAX(CASE WHEN AttendanceType = 'LOGIN' THEN Timestamp END), MAX(CASE WHEN AttendanceType = 'LOGOUT' THEN Timestamp END)) % 60 AS NoOfMinutes
		--DATEDIFF(DAY,convert(date,CreatedDate),convert(date,timestamp)) RowNumber
	FROM ConsultantDailyAttendance A-- INNER JOIN MsmeCertifications C on (A.ZedId=C.ZedId and A.Certification=C.Certification and A.MileStoneNo=C.NcCount) 
	where A.ZedId=@ZedId AND --A.Certification=@Certification
	MileStoneNo IS NULL 
	GROUP BY 
		A.ZedId,
		A.Certification,
		ConsultantId,MileStoneNo,
		convert(date,timestamp)



		----------QUERY FOR OVER VIEW AND RECOMMENDED TECHNOLOGIES------------------
		SELECT 
    MAX(C.Id) AS Id, 
    C.ZedId, 
    @Certification Certification, 
    M.EnterpriseName, 
    M.PUnitName, 
    B.UdyogAadharNo,
    CONCAT(M.PAddress, ', ', M.PDistrictName, ', ', M.PStateName, ', ', M.PPin) AS PlantAddress,
    -- Conditional inline aggregation strategies parsing direct structures mapping
    FORMAT(MAX(CASE WHEN C.NcCount = 1 THEN C.CertificationStatusDate END), 'MMMM d, yyyy') AS Milestone1Date,
    FORMAT(MAX(CASE WHEN C.NcCount = 2 THEN C.CertificationStatusDate END), 'MMMM d, yyyy') AS Milestone2Date,
    FORMAT(MAX(CASE WHEN C.NcCount = 3 THEN C.CertificationStatusDate END), 'MMMM d, yyyy') AS Milestone3Date
FROM MsmeCertifications C 
INNER JOIN Msme M ON C.ZedId = M.ZedId
INNER JOIN MsmeBasicInformation B ON M.ZedId = B.ZedId
WHERE C.ZedId = @ZedId and C.certification=@Certification
GROUP BY 
    C.ZedId, 
    Certification, 
    M.EnterpriseName, 
    M.PUnitName, 
    B.UdyogAadharNo,
    CONCAT(M.PAddress, ', ', M.PDistrictName, ', ', M.PStateName, ', ', M.PPin);

		SELECT TOP 1 ZedId,Certification,NcCount,Latitude, Longitude,Latitude SaLatitude, Longitude SaLongitude FROM 
		SaPhotos
		WHERE  ZedId=@ZedId and Certification=@Certification AND PhotoType='Open Meeting' AND NcCount=3


		SELECT R.* FROM FinancialAssistance F Inner join RecommandedTechnologies R on (F.ZedId=R.ZedId and F.CertificationType=R.Certification and F.CertId=R.CertId) WHERE F.ZedId=@ZedId AND F.CertificationType=@Certification


		


END
