-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
-- [SP_FINANCIAL_ASSISTANCE_GET_LIST] '<redacted>', '<redacted>','<redacted>','<redacted>'
CREATE PROCEDURE [dbo].[SP_FINANCIAL_ASSISTANCE_GET_LIST_BACKUP]
(
	@UserId varchar(50) = NULL,
	@Status int =null,
	@CertificationType varchar(50) = NULL,
	@ZedId varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	DECLARE @RoleId INT 
	SELECT @RoleId=ROLEID FROM USERS WHERE USERID=@UserId

	IF @RoleId=7
	BEGIN
		SELECT P.Id, M.ZedId, CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress, PCity, PStateName, PDistrictName, PPin, M.PUnitName, B.LastestCertification,
			U.UserName CertificationBodyName, CertificationBodyUserId, P.ReasonForRejection,P.ReasonForRejectionAgency, FinancialAssessorId,format(FinancialStatusDate,'dd-MMM-yyyy') VerificationDate,UA.UserName FaAssessorName, P.CertificationType, UamNumber, @RoleId RoleId, TechUpgradeStatus
		FROM FinancialAssistance P
		inner join Msme M on (P.ZedId=M.ZedId)
		inner join MsmeBasicInformation B on (P.ZedId=B.ZedId)
		LEFT JOIN Users U on (P.CertificationBodyUserId=U.UserId)
		LEFT JOIN Users UA on (P.FinancialAssessorId=UA.UserId)
	--	WHERE TechUpgradeStatus=@Status 
		WHERE (@Status = 2 AND TechUpgradeStatus IN (2, 4)) OR (@Status = 5 AND TechUpgradeStatus IN (5, 10)) OR (@Status!= 2 AND TechUpgradeStatus = @Status)
		ORDER By Id desc

		--SELECT ISNULL([2],0) New, ISNULL([5],0) InProgress, ISNULL([6],0) Qc, ISNULL([8],0) Approved, ISNULL([9],0) Rejected FROM 
		--(SELECT CASE WHEN TechUpgradeStatus = 4 THEN 2 WHEN TechUpgradeStatus = 10 THEN 5 ELSE TechUpgradeStatus END AS TechUpgradeStatus,  Count(*) Cnt 
		--FROM FinancialAssistance where ZedId not like '<redacted>' GROUP BY TechUpgradeStatus) src
		--PIVOT
		--(max(cnt) for TechUpgradeStatus in ([2],[5],[6],[8],[9])) pvt

		SELECT ISNULL([2], 0) AS New,ISNULL([5], 0) AS InProgress,ISNULL([6], 0) AS Qc,ISNULL([8], 0) AS Approved,ISNULL([9], 0) AS Rejected
		FROM (
		SELECT CASE WHEN TechUpgradeStatus = 4 THEN 2 WHEN TechUpgradeStatus = 10 THEN 5 ELSE TechUpgradeStatus END AS TechUpgradeStatus,Count(*) AS Cnt FROM FinancialAssistance
        WHERE ZedId NOT LIKE '%[_]%' GROUP BY CASE WHEN TechUpgradeStatus = 4 THEN 2 WHEN TechUpgradeStatus = 10 THEN 5 ELSE TechUpgradeStatus END
		) src 
		PIVOT (
        MAX(Cnt) FOR TechUpgradeStatus IN ([2], [5], [6], [8], [9])
	    ) pvt;

	END

	IF @RoleId=2
	BEGIN
		SELECT P.Id, M.ZedId, CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress, PCity, PStateName, PDistrictName, PPin, M.PUnitName, B.LastestCertification,
			U.UserName CertificationBodyName, CertificationBodyUserId, P.ReasonForRejection,P.ReasonForRejectionAgency, FinancialAssessorId,format(FinancialStatusDate,'dd-MMM-yyyy') VerificationDate, UA.UserName FaAssessorName, P.CertificationType, UamNumber, @RoleId RoleId, TechUpgradeStatus
		FROM FinancialAssistance P
		left join Msme M on (P.ZedId=M.ZedId)
		inner join MsmeBasicInformation B on (P.ZedId=B.ZedId)
		LEFT JOIN Users U on (P.CertificationBodyUserId=U.UserId)
		LEFT JOIN Users UA on (P.FinancialAssessorId=UA.UserId)
		WHERE P.ZedId not like '%[_]%' and ((@Status = 2 AND TechUpgradeStatus IN (2, 4)) OR (@Status = 5 AND TechUpgradeStatus IN (5, 10)) OR (@Status!= 2 AND TechUpgradeStatus = @Status)) AND CertificationBodyUserId=@UserId AND ((p.ReasonForRejection is NULL and VerificationStatus<5) OR (p.ReasonForRejection is NOT NULL and VerificationStatus=5))
		ORDER By Id desc

		
		--SELECT ISNULL([2],0) New, ISNULL([5],0) InProgress, ISNULL([6],0) Qc, ISNULL([8],0) Approved, ISNULL([9],0) Rejected FROM 
		--(SELECT CASE WHEN TechUpgradeStatus = 4 THEN 2 WHEN TechUpgradeStatus = 10 THEN 5 ELSE TechUpgradeStatus END AS TechUpgradeStatus, Count(*) Cnt FROM FinancialAssistance where ZedId not like '<redacted>' and CertificationBodyUserId=@UserId and ((ReasonForRejection is NULL and VerificationStatus<5) OR (ReasonForRejection is NOT NULL and VerificationStatus=5)) GROUP BY TechUpgradeStatus) src
		--PIVOT
		--(max(cnt) for TechUpgradeStatus in ([2],[5],[6],[8],[9])) pvt

		SELECT ISNULL([2], 0) New,ISNULL([5], 0) InProgress,ISNULL([6], 0) Qc,ISNULL([8], 0) Approved,ISNULL([9], 0) Rejected FROM
		(SELECT CASE WHEN TechUpgradeStatus = 4 THEN 2 WHEN TechUpgradeStatus = 10 THEN 5 ELSE TechUpgradeStatus END AS TechUpgradeStatus,Count(*) Cnt
        FROM FinancialAssistance WHERE ZedId NOT LIKE '%[_]%' AND CertificationBodyUserId = @UserId AND ((ReasonForRejection IS NULL AND VerificationStatus < 5) OR (ReasonForRejection IS NOT NULL AND VerificationStatus = 5))
        GROUP BY CASE WHEN TechUpgradeStatus = 4 THEN 2 WHEN TechUpgradeStatus = 10 THEN 5 ELSE TechUpgradeStatus END
        ) src 
		PIVOT
		(MAX(Cnt) FOR TechUpgradeStatus IN ([2], [5], [6], [8], [9])
        ) pvt;

	END


	IF @RoleId=3
	BEGIN
		SELECT P.Id, M.ZedId, CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress, PCity, PStateName, PDistrictName, PPin, M.PUnitName, B.LastestCertification,
			U.UserName CertificationBodyName, CertificationBodyUserId, P.ReasonForRejection,P.ReasonForRejectionAgency, FinancialAssessorId,format(FinancialStatusDate,'dd-MMM-yyyy') VerificationDate, P.CertificationType, UamNumber, @RoleId RoleId,
			UA.UserName as FinAssessorName,FinancialAssessorId
		FROM FinancialAssistance P
		left join Msme M on (P.ZedId=M.ZedId)
		inner join MsmeBasicInformation B on (P.ZedId=B.ZedId)
		LEFT JOIN Users U on (P.CertificationBodyUserId=U.UserId)
		LEFT JOIN Users UA on (P.FinancialAssessorId=UA.UserId)
		WHERE ((@Status = 2 AND TechUpgradeStatus IN (2, 4)) OR (@Status!= 2 AND TechUpgradeStatus = @Status))
		AND FinancialAssessorId=@UserId
		ORDER By Id desc


		SELECT ISNULL([2], 0) New,ISNULL([5], 0) InProgress,ISNULL([6], 0) Qc,ISNULL([8], 0) Approved,ISNULL([9], 0) Rejected FROM
		(SELECT CASE WHEN TechUpgradeStatus = 4 THEN 2 WHEN TechUpgradeStatus = 10 THEN 5 ELSE TechUpgradeStatus END AS TechUpgradeStatus,Count(*) Cnt
        FROM FinancialAssistance WHERE ZedId NOT LIKE '%[_]%' AND FinancialAssessorId=@UserId
        GROUP BY CASE WHEN TechUpgradeStatus = 4 THEN 2 WHEN TechUpgradeStatus = 10 THEN 5 ELSE TechUpgradeStatus END
        ) src 
		PIVOT
		(MAX(Cnt) FOR TechUpgradeStatus IN ([2], [5], [6], [8], [9])
        ) pvt;
		
		--SELECT ISNULL([2],0) New, ISNULL([5],0) InProgress, ISNULL([6],0) Qc, ISNULL([8],0) Approved, ISNULL([9],0) Rejected FROM 
