/****** Object:  StoredProcedure [dbo].[SP_FINANCIAL_ASSISTANCE_SUBMIT_OPEN_MEETING]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_FINANCIAL_ASSISTANCE_SUBMIT_OPEN_MEETING] 
(
	@RefId                  VarChar(50)			= NULL,
	@ZedId				    VarChar(200)		= NULL,
	@AssessorId             VarChar(200)		= NULL,
	@CertificationType      VarChar(200)		= NULL,
	@PhotoType			    VarChar(200)		= NULL,
	@Latitude               VarChar(200)		= NULL,
	@Longitude              VarChar(200)		= NULL,
	@Comments               VarChar(5000)		= NULL,
	@ParticipantsList		DynamicParticipants READONLY,
	@PhotoList				DynamicPhotoList	READONLY
)
AS
BEGIN
	      
	SET NOCOUNT ON;

	DECLARE @FinancialAssistanceId int = NULL
	DECLARE @CertId int = NULL

	BEGIN TRY
    BEGIN TRANSACTION;

		SELECT TOP 1 @FinancialAssistanceId=FinancialAssistanceId, @CertId=CertId FROM FinancialAssistance WHERE ZedId=@ZedId and CertificationType=@CertificationType ORDER BY Id DESC

		
		INSERT INTO TuMeetings(RefId,ZedId,AssessorId,Latitude,Longitude,Comments,FieldComments,MeetingType,CertificationType, FinancialAssistanceId, CertId)
		values(@RefId,@ZedId,@AssessorId,@Latitude,@Longitude,@Comments,@Comments,@PhotoType,@CertificationType, @FinancialAssistanceId, @CertId)

		INSERT INTO TuMeetingParticipants (RefId,ZedId,Name,Designation,MeetingType,CertificationType, FinancialAssistanceId, CertId)
		select @RefId,@ZedId,Name,replace(Designation,'Lead Assessor','MSME-DFO Officer'),@PhotoType,@CertificationType, @FinancialAssistanceId, @CertId from @ParticipantsList 

		INSERT INTO TuMeetingPhotos (ZedId,AssessorId,  Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, FinancialAssistanceId, CertId)
		SELECT @ZedId, @AssessorId,  @CertificationType, @PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, @FinancialAssistanceId, @CertId FROM @PhotoList

		UPDATE FinancialAssistance SET TechUpgradeStatus=10, FinancialStatusDate=getdate() WHERE FinancialAssistanceId=@FinancialAssistanceId AND ZedId=@ZedId and CertificationType=@CertificationType and CertId=@CertId

		select 200 StatusCode, '' StatusMessage

		COMMIT TRANSACTION;
	END TRY
	BEGIN CATCH
		-- Rollback transaction if an error occurs
		ROLLBACK TRANSACTION;

		-- Capture and return the error
		SELECT ERROR_NUMBER() AS StatusCode, ERROR_MESSAGE() AS StatusMessage;
	END CATCH;
		

	
END


GO
