/****** Object:  StoredProcedure [dbo].[SP_FINANCIAL_ASSISTANCE_UPDATE_TECHNOLOGY_DATA]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_FINANCIAL_ASSISTANCE_UPDATE_TECHNOLOGY_DATA] 
(
	@Id VarChar(50)						= NULL,
	@ZedId VarChar(50)					= NULL,
	@AmountPaid varchar(50)				= NULL
)
AS
BEGIN

	update TechnologyUpgradation set AmountPaid=@AmountPaid WHERE Id=@Id AND ZedId=@ZedId 


	---------------------- CODE TO UPDATE THE ELIGIBLE AMOUNT START-----------------

			DECLARE @TotalAmountPaid DECIMAL(18,2), 
				@SubsidyPercentage DECIMAL(5,2),
				@SubsidyAmount DECIMAL(18,2),
				@EligibleAmount DECIMAL(18,2),
				@CertificationType varchar(50),
				@CertId varchar(50),
				@FinancialAssistanceId varchar(50)

			select @CertId=CertId, @FinancialAssistanceId=FinancialAssistanceId, @CertificationType=CertificationType  from TechnologyUpgradation WHERE ZedId=@ZedId AND Id=@Id 

			SELECT @TotalAmountPaid=SUM(CAST(amountpaid AS DECIMAL(18,2))) FROM TechnologyUpgradation WHERE ZedId=@ZedId AND CertificationType=@CertificationType AND CertId=@CertId and IsEligible=1
			and FinancialAssistanceId=@FinancialAssistanceId

			SELECT @SubsidyPercentage=SubsidyPercentage FROM MsmePaymentInfo WHERE ZedId=@ZedId and Certification=@CertificationType and MileStoneNum=3 AND MsmePmtCertId=@CertId

			SET @SubsidyAmount = @TotalAmountPaid*(@SubsidyPercentage/100)

			SET @EligibleAmount = CASE WHEN @SubsidyAmount>300000 THEN 300000 ELSE @SubsidyAmount END	

			--------------------- CODE TO UPDATE THE ELIGIBLE AMOUNT END------------------------

			UPDATE FinancialAssistance SET EligibleAmount=@EligibleAmount, TotalPaidAfterQc=@TotalAmountPaid WHERE ZedId=@ZedId AND CertificationType=@CertificationType AND FinancialAssistanceId=@FinancialAssistanceId AND TechUpgradeStatus != 7

	

	
END
