/****** Object:  StoredProcedure [dbo].[SP_FINANCIAL_ASSISTANCE_VALIDATE_EVIDENCES]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_FINANCIAL_ASSISTANCE_VALIDATE_EVIDENCES] 
(
	@Id VarChar(50)						= NULL,
	@ZedId VarChar(50)					= NULL,
	@CertificationType VarChar(50)		= NULL,
	@IsVerified VarChar(50)				= NULL,
	@SourceOfValidation VarChar(2000)	= NULL,
	@Remark VarChar(2000)				= NULL,
	@Screenshots FileDetails READONLY
)
AS
BEGIN
	
	DECLARE @FinancialAssistanceId varchar(50) = NULL,
	@TechnologyCode varchar(50) = null
	SELECT @FinancialAssistanceId=FinancialAssistanceId, @TechnologyCode=TechnologyCode FROM FinancialAssistancePhotos where Id=@Id AND ZedId=@ZedId 

	DECLARE @NewFileName varchar(2000) = NULL
	select @NewFileName=FileName from @Screenshots

	UPDATE FinancialAssistancePhotos set IsVerified=@IsVerified,SourceOfValidation=@SourceOfValidation,AssessorRemarks=@Remark, UpdatedDate=getdate() 
	where Id=@Id AND ZedId=@ZedId --AND CertificationType=@CertificationType

	IF @IsVerified='No'
	BEGIN
		UPDATE TechnologyUpgradation set IsEligible=0 where ZedId=@ZedId and CertificationType=@CertificationType and FinancialAssistanceId=@FinancialAssistanceId and TechnologyCode=@TechnologyCode	
	END

	IF @IsVerified='Yes'
	BEGIN
		UPDATE TechnologyUpgradation set IsEligible=1 where ZedId=@ZedId and CertificationType=@CertificationType and FinancialAssistanceId=@FinancialAssistanceId and TechnologyCode=@TechnologyCode and IsEligible=0
	END

	IF EXISTS (select * from FinancialAssistanceScreenshotPhotos where ZedId=@ZedId and Certification=@CertificationType and PhotoId=@Id)
		BEGIN
			delete from FinancialAssistanceScreenshotPhotos where PhotoId=@Id and  ZedId=@ZedId and Certification=@CertificationType
			INSERT INTO [FinancialAssistanceScreenshotPhotos] (PhotoId,ZedId,Certification,FileName)
			SELECT @Id,@ZedId,@CertificationType,FileName from @Screenshots
			--update FinancialAssistanceScreenshotPhotos set FileName=@NewFileName, UpdatedDate=Getdate() where PhotoId=@Id and  ZedId=@ZedId and Certification=@CertificationType
		END
		ELSE
		BEGIN
			INSERT INTO [FinancialAssistanceScreenshotPhotos] (PhotoId,ZedId,Certification,FileName)
			SELECT @Id,@ZedId,@CertificationType,FileName from @Screenshots
		END

	UPDATE FinancialAssistance SET TechUpgradeStatus=5 WHERE FinancialAssistanceId=@FinancialAssistanceId AND ZedId=@ZedId and CertificationType=@CertificationType
	


END
GO
/****** Object:  StoredProcedure [dbo].[SP_GET_ASSESSORS]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_GET_ASSESSORS]
(
	@UserId varchar(100) = NULL,					-- Login User UserId (Reserved for future use/logging)
	@AssessorType varchar(100) = NULL,				-- DA / SA / FA
	@CertificationBodyUserId varchar(100) = NULL	-- Agency UserId
)
AS
BEGIN
	SET NOCOUNT ON;

	-- 1. Normalize empty strings to NULL for consistent logic
	IF @AssessorType = '' SET @AssessorType = NULL;
	IF @CertificationBodyUserId = '' SET @CertificationBodyUserId = NULL;

	-- 2. Pre-aggregate States per UserId using STRING_AGG
	-- This processes state concatenation ONCE per distinct user before joining main tables
	WITH AggregatedStates AS 
	(
		SELECT 
			UserId,
			STRING_AGG(CAST(States AS VARCHAR(MAX)), ', ') WITHIN GROUP (ORDER BY States) AS States
		FROM (
			SELECT DISTINCT UserId, States 
			FROM dbo.AgencyUserStates WITH (NOLOCK)
		) DISTINCT_STATES
		GROUP BY UserId
	)
	-- 3. Main Query with optimized joins and sargable predicates
	SELECT 
		U.*, 
		ISNULL(X.States, 'Pan-India') AS States, 
		U1.UserId AS AgencyUserId, 
		U1.UserName AS AgencyUserName, 
		CASE WHEN U.IsActive = 1 THEN 'Active' ELSE 'In-Active' END AS IdStatus,
		ROW_NUMBER() OVER (ORDER BY U1.UserId, U.UserId) AS RowNumber
	FROM dbo.Users U WITH (NOLOCK)
	INNER JOIN dbo.Users U1 WITH (NOLOCK) 
		ON U.CreatedBy = U1.UserId 
	   AND U1.RoleId = 2
	LEFT JOIN AggregatedStates X 
		ON U.UserId = X.UserId
	WHERE U.RoleId = 3 
	  -- Sargable filter allows SQL Server to perform Index Seeks on CreatedBy
	  AND (@CertificationBodyUserId IS NULL OR U.CreatedBy = @CertificationBodyUserId)
	  -- Verification type filter
	  AND (
			@AssessorType IS NULL 
			OR (@AssessorType = 'DA' AND U.DesktopVerification = 1) 
			OR (@AssessorType = 'SA' AND U.SiteVerification = 1) 
			OR (@AssessorType = 'FA' AND U.FinancialVerification = 1)
		  )
	ORDER BY U1.UserId, U.UserId
	OPTION (RECOMPILE); -- Prevents parameter sniffing issues across different input combinations

END
GO
