/****** Object:  StoredProcedure [dbo].[SP_GET_INCENTIVES]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_GET_INCENTIVES] --'', '<redacted>'
(
	@State varchar(100) = NULL,
	@CertificationType  varchar(100) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	IF @State=''
		SET @State=NULL

	IF @CertificationType='Bronze'
	BEGIN
		select *, null ApplicableFor FROM Incentives WHERE IncentiveType='Common' AND ApplicableForBronze = 1  ORDER By OrderNo

		select *, null ApplicableFor  FROM Incentives WHERE IncentiveType in (SELECT StateName FROM States WHERE StateCode=ISNULL(@State,StateCode)) AND ApplicableForBronze = 1 ORDER By OrderNo

		select *, null ApplicableFor FROM Incentives WHERE IncentiveType='Other' AND ApplicableForBronze = 1  ORDER By OrderNo

		select *, null ApplicableFor FROM Incentives WHERE IncentiveType='Financial' AND ApplicableForBronze = 1  ORDER By OrderNo
	END

	ELSE IF @CertificationType='Silver'
	BEGIN
		select *, null ApplicableFor  FROM Incentives WHERE IncentiveType='Common' AND ApplicableForSilver = 1  ORDER By OrderNo

		select *, null ApplicableFor  FROM Incentives WHERE IncentiveType in (SELECT StateName FROM States WHERE StateCode=ISNULL(@State,StateCode)) AND ApplicableForSilver = 1 ORDER By OrderNo

		select *, null ApplicableFor FROM Incentives WHERE IncentiveType='Other' AND ApplicableForSilver = 1  ORDER By OrderNo

		select *, null ApplicableFor FROM Incentives WHERE IncentiveType='Financial' AND ApplicableForSilver = 1  ORDER By OrderNo
	END

	ELSE IF @CertificationType='Gold'
	BEGIN
		select *, null ApplicableFor  FROM Incentives WHERE IncentiveType='Common' AND ApplicableForGold = 1  ORDER By OrderNo

		select *, null ApplicableFor  FROM Incentives WHERE IncentiveType in (SELECT StateName FROM States WHERE StateCode=ISNULL(@State,StateCode)) AND ApplicableForGold = 1 ORDER By OrderNo

		select *, null ApplicableFor FROM Incentives WHERE IncentiveType='Other' AND ApplicableForGold = 1  ORDER By OrderNo

		select *, null ApplicableFor FROM Incentives WHERE IncentiveType='Financial' AND ApplicableForGold = 1  ORDER By OrderNo
	END
	ELSE 
	BEGIN
		select *, null ApplicableFor  FROM Incentives WHERE IncentiveType='Common' AND 1=2

		select *, null ApplicableFor  FROM Incentives WHERE IncentiveType in (SELECT StateName FROM States WHERE StateCode=ISNULL(@State,StateCode)) AND 1=2

		select *, null ApplicableFor FROM Incentives WHERE IncentiveType='Other' AND 1=2

		select *, null ApplicableFor FROM Incentives WHERE IncentiveType='Financial' AND 1=2
	END
END
GO
/****** Object:  StoredProcedure [dbo].[SP_GET_LIST_OF_CERTIFIED_UNITS]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_GET_LIST_OF_CERTIFIED_UNITS] --'<redacted>', '<redacted>'
(
	@State varchar(50) = NULL,
	@Category varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

    SELECT  ROW_NUMBER() OVER(ORDER BY SelfCertificationDate) SNo
	  ,[Id]
      ,[StateCode]
      ,[StateName]
      ,[DistrictCode]
      ,[DistrictName]
      ,[RespondentName]
      ,[MobileNo]
      ,[EmailId]
      ,S.[CreatedDate]
      ,[Gender]
      ,[RespondentAge]
      ,[Service]
      ,[Experience]
      ,[Email]
      ,[Status]
      ,[IsTerminated]
      ,[FinalSubmitDate]
      ,[EstablishmentType]
      ,[RespondentMobileNo]
      ,UPPER([EstablishmentName]) EstablishmentName
      ,[EstablishmentAddress]
      ,[EstablishmentPinCode]
      ,[EstablishmentPhoneNo]
      ,[EstablishmentFaxNo]
      ,[IsDeclarationAccepted]
      ,[CurrentQuestion]
      ,[CertificateNo]
      ,[Name]
      ,[IssuedOn]
	  --, FORMAT(FinalSubmitDate, '<redacted>') [FinalSubmittedDate]
	  , FORMAT(SelfCertificationDate, 'MMMM d, yyyy h:mm tt') [FinalSubmittedDate]
	  ,[IsCertificateGenerated]
      ,[EstablishmentCity]
      ,[EstablishmentWebsite]
      ,S.[Acommodationtype]
      ,[TotalRooms]
      ,[RegistrationNumber]
      ,[Category]
	  ,[CertificateNo]
	  ,[RestaurantType]
	  ,REPLACE(UPPER(case when EstablishmentCity is null or EstablishmentCity = '' then '' else EstablishmentCity + ', ' end + case when DistrictName is null or DistrictName='' then '' else DistrictName + ', ' end + StateName),'*','') EstablishmentFullAddress
	FROM SelfAssessments S 
	WHERE IsCertificateGenerated>0 and RegistrationNumber not in ('UC23111823863','UC23111823861','UC13111923860','UC3250522285')
		AND StateName = ISNULL(@State, StateName) AND Category = ISNULL(@Category, Category)
	ORDER BY SelfCertificationDate
END

GO
/****** Object:  StoredProcedure [dbo].[SP_GET_LIST_OF_CERTIFIED_UNITS_SUMMARY]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_GET_LIST_OF_CERTIFIED_UNITS_SUMMARY] --'<redacted>', '<redacted>'
(
	@State varchar(50) = NULL,
	@Category varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

    SELECT  ROW_NUMBER() OVER(ORDER BY StateName) SNo, upper(StateName) StateName, ISNULL(Classified,0) Classified, ISNULL(UnClassified,0) UnClassified, ISNULL(Classified,0) + ISNULL(UnClassified,0) Total FROM
	(
		SELECT StateName, Category, Count(*) Cnt FROM SelfAssessments S 
		WHERE IsCertificateGenerated>0 and RegistrationNumber not in ('UC23111823863','UC23111823861','UC13111923860','UC3250522285')
		GROUP BY StateName, Category
	) src
	PIVOT
	(
		max(Cnt) for Category in ([Classified],[UnClassified])
	) pvt
	ORDER BY StateName

	SELECT  ISNULL(Classified,0) Classified, ISNULL(UnClassified,0) UnClassified, ISNULL(Classified,0) + ISNULL(UnClassified,0) Total FROM
	(
		SELECT Category, Count(*) Cnt FROM SelfAssessments S 
		WHERE IsCertificateGenerated>0 and RegistrationNumber not in ('UC23111823863','UC23111823861','UC13111923860','UC3250522285')
		GROUP BY Category
	) src
	PIVOT
	(
		max(Cnt) for Category in ([Classified],[UnClassified])
	) pvt
END

GO
