/****** Object:  StoredProcedure [dbo].[SP_GET_PROFESSIONAL_DETAILS_BY_CERT_NO_duplicatetest]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_GET_PROFESSIONAL_DETAILS_BY_CERT_NO_duplicatetest] --'<redacted>','<redacted>','<redacted>','<redacted>','<redacted>'
(
	 @UserId varchar(50) = NULL
	,@RoleId varchar(50) = NULL
	,@CertificationNo varchar(50) = NULL
	,@EmailId varchar(100) = NULL
	,@AssessorType varchar(50) = NULL
)
AS
BEGIN

	IF EXISTS(SELECT 1 FROM Users where IsActive=1 and UserId=@UserId AND RoleId=2 AND @RoleId=2)
	BEGIN
		IF @AssessorType=3
		BEGIN
			IF EXISTS (SELECT 1 from ZED_CENTER_AUDIT_V2.dbo.Candidates WHERE ZEDTAC=@CertificationNo AND EmailId=@EmailId AND Zedtac Is not null and left(ZEDTAC,2)='CO')
			BEGIN
				SELECT R.Email,R.ContactNumber,R.Name,R.State,R.District,R.City,C.ZEDTAC,R.data as CertificateNo FROM ZED_CENTER_AUDIT_V2.dbo.Candidates C 
				INNER JOIN ZED_CENTER_AUDIT_V2.dbo.Registrations R ON (C.RegistrationId=R.Id)  
				WHERE ZEDTAC=@CertificationNo and EmailId=@EmailId AND C.zedtac is not null and R.ApplyingFor='ZedConsultant'

				SELECT 1 Status, 'Details Fetched Successfully' ErrorMessage
			END
			ELSE
			BEGIN
				SELECT NULL Email,NULL ContactNumber,NULL Name,NULL State,NULL District,NULL City,ZEDTAC,NULL data, NULL as CertificateNo FROM ZED_CENTER_AUDIT_V2.dbo.Candidates 
				WHERE 1=2
				
				SELECT 0 Status, 'Invalid details.' ErrorMessage
			END
		END
		
	END

	ELSE
	BEGIN
		SELECT NULL Email,NULL ContactNumber,NULL Name,NULL State,NULL District,NULL City,ZEDTAC,NULL data, NULL as CertificateNo FROM ZED_CENTER_AUDIT_V2.dbo.Candidates 
		WHERE 1=2

		SELECT 0 Status, 'Unauthorised User.' ErrorMessage
	END
	

END
GO
