CREATE PROCEDURE [dbo].[SP_GET_SELF_ASSESSMENT_DETAILS_BY_REG_NUMBER] --'<redacted>'
(
	@RegistrationNumber varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;
    SELECT  S.[Id]
      ,[StateCode]
      ,[StateName]
      ,[DistrictCode]
      ,[DistrictName]
      ,[RespondentName]
      ,[MobileNo]
      ,[EmailId]
      ,S.[CreatedDate]
      ,[Gender]
      ,[RespondentAge]
      ,[Service]
      ,[Experience]
      ,[Email]
      ,[Status]
      ,[IsTerminated]
      ,[FinalSubmitDate]
