/****** Object:  StoredProcedure [dbo].[SP_GET_SELF_ASSESSMENT_SUMMARY]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_GET_SELF_ASSESSMENT_SUMMARY] --'<redacted>', '<redacted>'
(
	@MobileNo varchar(50) = NULL,
	@RegistrationNumber varchar(100) = NULL
)
AS
BEGIN
	
	Declare @Acommodationtype Varchar(50)
	Declare @StateName Varchar(100)

	SET NOCOUNT ON;

	SELECT @Acommodationtype=CASE WHEN QuestionnaireName in ('Restaurants','Bed and Breakfast')  then QuestionnaireName 
	WHEN  RestaurantType='With in-house restaurant' then 'Hotel and Restaurants' else 'Hotel' end,
			@StateName=StateName 
	FROM SelfAssessments S left join Acommodationtypes A on (S.Acommodationtype=A.Acommodationtype) WHERE RegistrationNumber=@RegistrationNumber

    SELECT Id, StateName, DistrictName, RespondentName, MobileNo, CreatedDate, Email, Status, IsTerminated, FinalSubmitDate, EstablishmentType, RespondentMobileNo, 
		UPPER([EstablishmentName]) EstablishmentName, EstablishmentAddress, EstablishmentCity, EstablishmentPinCode, EstablishmentPhoneNo, EstablishmentFaxNo, EstablishmentWebsite, 
		Acommodationtype, TotalRooms, RegistrationNumber, IsDeclarationAccepted, CertificateNo, RestaurantType,
		ISNULL(CurrentQuestion,-1) + 1 CurrentQuestion,
		WebinarId, convert(varchar, WebinarDate, 100) WebinarDate, WebinarUrl,
		FORMAT(FinalSubmitDate, 'MMMM d, yyyy  h:mm tt') [FinalSubmittedDate],
		REPLACE(UPPER(case when EstablishmentCity is null or EstablishmentCity = '' then '' else EstablishmentCity + ', ' end + case when DistrictName is null or DistrictName='' then '' else DistrictName + ', ' end + StateName),'*','') EstablishmentFullAddress,
		Category
	FROM SelfAssessments WHERE  RegistrationNumber=@RegistrationNumber

	select S.Id,CASE WHEN T.OrderNo=2 then 'S' + S.SectionCode else S.SectionCode end as SectionCode,S.SectionName,S.OrderNo,iButton,SectionImage,S.SectionType, T.OrderNo QType from Sections S inner join SectionTypes T on (S.SectionType=T.SectionType)
	where S.SectionType in (@Acommodationtype,@statename) order by T.OrderNo,S.OrderNo

	SELECT ROW_NUMBER() OVER(ORDER BY S.OrderNo, Q.OrderNo) SNo, CASE WHEN T.OrderNo=2 then 'S' + S.SectionCode else S.SectionCode end as SectionCode, S.SectionName, S.iButton,NULL AnswerCode, 
		Q.Id, Q.QuestionCode, Q.QuestionName, Q.OrderNo, Q.iButton iButtonQ, Q.QuestionImage
	FROM Questions Q 
	inner join Sections S on (Q.SectionCode=S.SectionCode and Q.SectionType=S.SectionType)
    inner join SectionTypes T on (Q.SectionType=T.SectionType) 
	where Q.SectionType in (@Acommodationtype,@statename) and S.SectionType in (@Acommodationtype,@statename)
	ORDER By T.OrderNo, SectionCode

END

