/****** Object:  StoredProcedure [dbo].[SP_GET_SUB_ROLE]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_GET_SUB_ROLE] --'<redacted>', '<redacted>'
(
	@UserId varchar(50) = NULL,
	@RoleId varchar(50) = NULL
)
AS
BEGIN
	
	IF @RoleId = 3
	BEGIN
		select CONVERT(int,DesktopVerification) DesktopVerification, CONVERT(int,SiteVerification) SiteVerification, CONVERT(int,FinancialVerification) FinancialVerification FROM Users WHERE UserId=@UserId
	END
	ELSE IF @RoleId = 2
	BEGIN
		select 
		1 DesktopVerification,
		--(select SiteVerification from Users where RoleId=2 and UserId=@UserId) SiteVerification,
		(select case when SiteVerification=1 then 1 else 0 end from Users where RoleId=2 and UserId=@UserId) SiteVerification,
		CASE WHEN (select count(*) from FinancialAssistance where CertificationBodyUserId=@UserId)>0 THEN 1 ELSE 0 END AS FinancialVerification

	END
	ELSE
	BEGIn
		select 1 DesktopVerification, 1 SiteVerification, 1 FinancialVerification
	END
END

