/****** Object:  StoredProcedure [dbo].[SP_GET_USERS_BY_ROLE]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_GET_USERS_BY_ROLE] --'<redacted>',3
(
	@UserId varchar(100) = NULL,	-- Login User UserId
	@RoleId varchar(100)= NULL		-- Non Loggedin User RoleId
)
AS
BEGIN
	--SELECT * FROM Users U WHERE RoleId=@RoleId AND CreatedBy=@UserId ORDER BY UserId

	   SELECT Id,U.UserId, Password, UserName, RoleId,
	   IsActive, Email, MobileNo, SpocName, Address, Pincode, U.CreatedBy, CreatedDate, StateCode,
	   DistrictCode, IdProofType, IdProofNumber, AgencyGstNumber, PwdCode, DesktopVerification,
	   SiteVerification, FinancialVerification, X.UserId, ISNULL(States,'Pan-India') States, CASE WHEN IsActive=1 THEN 'Active' else 'In-Active' end as IdStatus,
	   DesktopVerfi, SiteVerifi, FinanceVerfi,isnull(NoOfUsers,0) NoOfUsers,
	   CASE 
        WHEN U.RoleId = 3 THEN 'Consultant'
        WHEN U.RoleId = 33 THEN 'Technical Expert'
        ELSE NULL
    END AS UserType

	   from Users U 
	left join 
	(SELECT UserId, States=STUFF  
	(  
		(  
		  SELECT DISTINCT ', '+ CAST( e.States as VARCHAR(MAX))  
		  FROM Users G,AgencyUserStates E  
		  WHERE G.UserId=E.UserId and E.UserId=T1.UserId   
		  FOR XMl PATH('')  
		),1,1,''  
	)  
	FROM AgencyUserStates t1 
	GROUP BY UserId  ) X

	on (U.UserId=X.Userid)
	
	left join (select CreatedBy,count(*) NoOfUsers from Users group by CreatedBy ) UC on (U.UserId=UC.CreatedBy)
	left join 
	(select userid,case when DesktopVerification=1 then 'Desktop' else '' end as DesktopVerfi from users) UD
	on (U.UserId=UD.Userid)
	left join  
	(select userid,case when SiteVerification=1 then 'Remote/Onsite' else '' end as SiteVerifi from users) US
	on (UD.UserId=US.UserId)
	left join 
	(select userid,case when FinancialVerification=1 then 'Financial' else '' end as FinanceVerfi from users) UF
	on (UD.UserId=UF.UserId)

	WHERE replace(RoleId,33,3)=@RoleId AND U.CreatedBy=@UserId ORDER BY U.UserId

END





