/****** Object:  StoredProcedure [dbo].[SP_INSERT_CLOSING_MEETING_RECORDS_BACKEND]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[SP_INSERT_CLOSING_MEETING_RECORDS_BACKEND] --'<redacted>','<redacted>'
(
    @ZEDID         VARCHAR(50),
    @Certification VARCHAR(50)
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    BEGIN TRY

        BEGIN TRANSACTION;

        DECLARE @NcCount INT;
        DECLARE @CertificationStatus INT;

        DECLARE @SaPhotosInserted INT = 0;
        DECLARE @MeetingsInserted INT = 0;
        DECLARE @ParticipantsInserted INT = 0;

      

        SELECT @NcCount = NcCount,@CertificationStatus = CertificationStatus FROM MsmeCertifications WHERE ZedId = @ZEDID AND Certification = @Certification AND CertificationStatus = 9;


        --If id did not found inprogress id will throw below error.

        IF @NcCount IS NULL
        BEGIN
            ROLLBACK TRANSACTION;
            RAISERROR( 'No in-progress certification found for the given ZEDID and Certification.',16, 1);
            RETURN;
        END;


        
          -- Insert Closing Meeting Photo in saphotos table
           

        INSERT INTO SaPhotos
        (
            ZedId,
            Certification,
            PhotoId,
            Name,
            TimeStamp,
            Latitude,
            Longitude,
            PhotoType,
            AssessorId,
            NcCount,
            CreatedDate
        )
        SELECT
            SP.ZedId,
            SP.Certification,
            CONCAT(LEFT(SP.PhotoId, LEN(SP.PhotoId) - 9),'_bcknd_ud'),
            'Closing Meeting Photo',
            SP.TimeStamp,
            SP.Latitude,
            SP.Longitude,
            'Close Meeting',
            SP.AssessorId,
            @NcCount,
            GETDATE()
        FROM SaPhotos SP
        WHERE SP.ZedId = @ZEDID
          AND SP.Certification = @Certification
          AND SP.PhotoType = 'Open Meeting'
          AND SP.Name = 'Opening Meeting Photo'
          AND SP.NcCount = @NcCount
          AND NOT EXISTS
          (SELECT 1 FROM SaPhotos CP
              WHERE CP.ZedId = @ZEDID AND CP.Certification = @Certification AND CP.NcCount = @NcCount AND CP.PhotoType = 'Close Meeting' AND CP.Name = 'Closing Meeting Photo');

            SET @SaPhotosInserted = @@ROWCOUNT;


       
           --Insert Closing Meeting in meetings tables
          

        INSERT INTO Meetings
        (
            ZedId,
            CertificationType,
            AssessorId,
            Latitude,
            Longitude,
            Comments,
            CreatedDate,
            MeetingType,
            FieldComments,
            NcCount
        )
        SELECT
            M.ZedId,
            M.CertificationType,
            M.AssessorId,
            M.Latitude,
            M.Longitude,
            M.Comments,
            GETDATE(),
            'Close Meeting',
            M.FieldComments,
            @NcCount
        FROM Meetings M
        WHERE M.ZedId = @ZEDID
          AND M.CertificationType = @Certification
          AND M.MeetingType = 'Open Meeting'
          AND M.NcCount = @NcCount
          AND NOT EXISTS
          (
              SELECT 1
              FROM Meetings CM
              WHERE CM.ZedId = @ZEDID
                AND CM.CertificationType = @Certification
                AND CM.MeetingType = 'Close Meeting'
                AND CM.NcCount = @NcCount
          );

        SET @MeetingsInserted = @@ROWCOUNT;


        
           -- Insert Closing Meeting Participants tables
           

        INSERT INTO MeetingParticipants ( ZedId, CertificationType, Name, Designation, MeetingType, NcCount)
        SELECT MP.ZedId, MP.CertificationType, MP.Name, MP.Designation, 'Close Meeting', @NcCount
        FROM MeetingParticipants MP WHERE MP.ZedId = @ZEDID  AND MP.CertificationType = @Certification AND MP.MeetingType = 'Open Meeting'
         AND MP.NcCount = @NcCount AND NOT EXISTS
          ( SELECT 1 FROM MeetingParticipants CMP  WHERE CMP.ZedId = @ZEDID AND CMP.CertificationType = @Certification AND CMP.MeetingType = 'Close Meeting'
                AND CMP.NcCount = @NcCount AND CMP.Name = MP.Name AND CMP.Designation = MP.Designation);
          SET @ParticipantsInserted = @@ROWCOUNT;


      

        COMMIT TRANSACTION;

		 INSERT INTO UploadPhotoBackend(ZedId,Certification,NcCount,CertificationStatusBeforInsert,SaPhotosInserted,MeetingsInserted,ParticipantsInserted,TotalRowsInserted,Status,Message)
		VALUES(@ZEDID,@Certification,@NcCount,@CertificationStatus,@SaPhotosInserted,@MeetingsInserted,@ParticipantsInserted,
		 (@SaPhotosInserted+ @MeetingsInserted + @ParticipantsInserted ), 'Success', 'Process completed successfully' );
        

        SELECT @ZEDID AS ZEDID, @Certification AS Certification, @NcCount AS NcCount, @CertificationStatus AS CertificationStatus,@SaPhotosInserted AS SaPhotosInserted,
              @MeetingsInserted AS MeetingsInserted,@ParticipantsInserted AS ParticipantsInserted,
              (@SaPhotosInserted+ @MeetingsInserted+ @ParticipantsInserted) AS TotalRowsInserted,'Success' AS Message;

    END TRY

    BEGIN CATCH

        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;

        DECLARE @ErrorMessage NVARCHAR(4000);
        DECLARE @ErrorSeverity INT;
        DECLARE @ErrorState INT;

        SELECT @ErrorMessage = ERROR_MESSAGE(),@ErrorSeverity = ERROR_SEVERITY(),@ErrorState = ERROR_STATE();
            

        RAISERROR(@ErrorMessage,@ErrorSeverity,@ErrorState);

    END CATCH
END;
GO
