      ,[IsTerminated]
      ,[FinalSubmitDate]
      ,[EstablishmentType]
      ,[RespondentMobileNo]
      ,[EstablishmentName]
      ,[EstablishmentAddress]
      ,[EstablishmentPinCode]
      ,[EstablishmentPhoneNo]
      ,[EstablishmentFaxNo]
      ,[IsDeclarationAccepted]
      ,[CurrentQuestion]
      ,[CertificateNo]
      ,[Name]
      ,[IssuedOn]
      ,[ResetDate]
      ,[EstablishmentCity]
      ,[EstablishmentWebsite]
      ,[Acommodationtype]
      ,[TotalRooms]
      ,[RegistrationNumber]
      ,[Category]
      ,[RestaurantType]
      ,[WebinarId]
      ,[WebinarDate]
