-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_INSERT_SELF_ASSESSMENT_STEP_2] --'<redacted>', '<redacted>'
(
	@IpAddress varchar(50) = NULL,

	@RegistrationNo varchar(50) = NULL,
	@Category varchar(50) = NULL,
	@MobileNo varchar(50) = NULL,
	@EmailId varchar(200) = NULL,

	@Name varchar(200) = NULL,
    @PostalAddress varchar(2000) = NULL,
    @State varchar(200) = NULL,
    @City varchar(200) = NULL,
    @District varchar(200) = NULL,
    @PinCode varchar(200) = NULL,
    @PhoneNumber varchar(200) = NULL,
    @FaxNumber varchar(200) = NULL,
    @Website varchar(200) = NULL,
    @ContactPerson varchar(200) = NULL,
    @MobileNumber varchar(200) = NULL,
    @Email varchar(200) = NULL,
    @Acommodationtype varchar(200) = NULL,
    @TotalRooms varchar(200) = NULL,
	@NidhiStateName varchar(200) =	NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;
	SET @NidhiStateName=@State

	 IF EXISTS (select * from States where StateName=@State)
	 BEGIN
	   SELECT  @State=StateName from states where StateName=@State
	   END

	IF NOT EXISTS(select * from SelfAssessments where RegistrationNumber=@RegistrationNo)
	BEGIN
		INSERT INTO SelfAssessments (
			Category, EstablishmentName, EstablishmentAddress, EstablishmentCity, DistrictName, StateName, EstablishmentPinCode, EstablishmentPhoneNo, EstablishmentFaxNo, 
			EstablishmentWebsite, RespondentName, Email, RespondentMobileNo, Acommodationtype, TotalRooms, RegistrationNumber, CreatedDate, EmailId, MobileNo, IpAddress,NidhiStateName
		)
		VALUES (
			@Category, @Name, @PostalAddress, @City, @District, @State, @PinCode, @PhoneNumber, @FaxNumber,
			@Website, @ContactPerson, @Email, @MobileNumber, @Acommodationtype, @TotalRooms, @RegistrationNo, GETDATE(), @EmailId, @MobileNo, @IpAddress,@NidhiStateName 
		)
	END

	ELSE
	 BEGIN
		UPDATE SelfAssessments SET Category=@Category,	EstablishmentName=@Name, 	EstablishmentAddress=@PostalAddress,	EstablishmentCity=@City, DistrictName=@District, StateName=@State,
		EstablishmentPinCode=@PinCode, 	EstablishmentPhoneNo=@PhoneNumber,	EstablishmentFaxNo=@FaxNumber, 	EstablishmentWebsite=@Website,	RespondentName=@ContactPerson,	Email=@Email,
		RespondentMobileNo=@MobileNumber, 	Acommodationtype=@Acommodationtype, TotalRooms=@TotalRooms,	EmailId=@EmailId, MobileNo=@MobileNo, IpAddress=@IpAddress,	NidhiStateName=@NidhiStateName,
		FetchedDate=GETDATE()
		WHERE RegistrationNumber=@RegistrationNo
	 END
END
