/****** Object:  StoredProcedure [dbo].[SP_INSERT_USER]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_INSERT_USER] 
(
	 @UserId varchar(200)=NULL
	,@UserName varchar(200)
	,@Password varchar(200)=NULL
	,@RoleId int = NULL
	,@Email varchar(200) = NULL
	,@MobileNo varchar(15) = NULL
	,@CreatedBy varchar(50) = NULL
	,@SpocName varchar(200) = NULL
	,@Address varchar(2000) = NULL
	,@PinCode varchar(50) = NULL
	,@PreferredStates varchar(2000) = NULL
	,@NicSectors varchar(4000) = NULL
	,@AreaOfknowledge varchar(4000) = NULL
	,@IdProofType varchar(50) = NULL
	,@IdProofNumber varchar(50) = NULL
	,@GstNumber varchar(50) = NULL
	,@DesktopVerification varchar(50) = NULL
	,@SiteVerification varchar(50) = NULL
	,@FinancialVerification varchar(50) = NULL
	,@ReasonForRejection varchar(2000) = NULL
	,@TuPreferredState varchar(2000) = NULL
	,@TuPreferredDistricts varchar(2000) = NULL
	--,@AssessorType varchar(50) ='<redacted>'
	,@CertificateNo varchar(50) = NULL
	,@ProfessionalEmail varchar(50) = NULL
	

)
AS
BEGIN
     
	 IF (@FinancialVerification is null or @FinancialVerification=0 or @FinancialVerification='')
	 BEGIN
		SET @TuPreferredState=NULL
	 END

	 IF @RoleId=2
	  Begin

		DECLARE @BodiesUserId varchar(200)    
		SET @BodiesUserId =concat ('ZEDCO',RIGHT(concat('00',convert(varchar(200),Next Value For BodiesSequence)),4))
		select @BodiesUserId

		INSERT INTO USERS (UserId, UserName,[Password],Email,MobileNo,SpocName,[Address],PinCode,CreatedBy,RoleId,AgencyGstNumber,IsActive,DesktopVerification,SiteVerification, FinancialVerification, TuPreferredState)
	    VALUES(@BodiesUserId, @UserName, @Password, @Email, @MobileNo, @SpocName, @Address,@PinCode, @CreatedBy, @RoleId,@GstNumber, 1, @DesktopVerification,@SiteVerification, @FinancialVerification, @TuPreferredState)

		INSERT INTO AgencyUserStates (UserId,RoleId,States,IsActive)
	    select @BodiesUserId, @RoleId, value, 1 from string_split(@PreferredStates,',')

		INSERT INTO UserNicSectors (UserId,RoleId,NicSectorCode,IsActive)
	    select @BodiesUserId, @RoleId, value, 1 from string_split(@NicSectors,',')
		update U set NicSector=SectorName from Sectors S inner join UserNicSectors U on (S.SectorCode=U.NicSectorCode) where NicSector is null

		INSERT INTO TuAgencyUserDistricts (UserId,RoleId,Districts,IsActive)
	    select @BodiesUserId, @RoleId, value, 1 from string_split(@TuPreferredDistricts,',')
			
	  End

	 IF (@RoleId=3 OR @RoleId=33)
	  Begin

		DECLARE @AssessorsUserId varchar(200)    

		IF @RoleId = 33
		BEGIN
			SET @AssessorsUserId = CONCAT('ZEDCT', RIGHT(CONCAT('00', CONVERT(varchar(200), NEXT VALUE FOR AssessorsSequence)), 4))			
		END
		ELSE
		BEGIN
			SET @AssessorsUserId = CONCAT('ZEDCC', RIGHT(CONCAT('00', CONVERT(varchar(200), NEXT VALUE FOR AssessorsSequence)), 4))
		END

		--SET @AssessorsUserId =concat ('<redacted>',RIGHT(concat('<redacted>',convert(varchar(200),Next Value For AssessorsSequence)),4))
		--select @AssessorsUserId

		select  @DesktopVerification=DesktopVerification,@SiteVerification=SiteVerification, @FinancialVerification=FinancialVerification from users where UserId=@CreatedBy
		IF @SiteVerification=1 
		BEGIN
		SET @DesktopVerification=1
		END

		INSERT INTO USERS (UserId, UserName,[Password],Email,MobileNo,CreatedBy,RoleId,IdProofType,IdProofNumber,DesktopVerification,SiteVerification, FinancialVerification,IsActive,Address,Pincode,CertificateNo,ProfessionalEmailId)
	    VALUES(@AssessorsUserId, @UserName, @Password, @Email, @MobileNo, @CreatedBy, @RoleId,@IdProofType,@IdProofNumber,@DesktopVerification,@SiteVerification, @FinancialVerification, 1,@Address,@PinCode,@CertificateNo,@ProfessionalEmail)

		INSERT INTO AgencyUserStates (UserId,RoleId,States,IsActive)
	    select @AssessorsUserId, @RoleId, value, 1 from string_split(@PreferredStates,',')

		INSERT INTO UserNicSectors (UserId,RoleId,NicSectorCode,IsActive)
	    select @AssessorsUserId, @RoleId, value, 1 from string_split(@NicSectors,',')
		update U set NicSector=SectorName from Sectors S inner join UserNicSectors U on (S.SectorCode=U.NicSectorCode) where NicSector is null

		INSERT INTO UserAreaOfKnowledge (UserId,RoleId,AreaOfKnowledge,IsActive)
	    select @AssessorsUserId, @RoleId, value, 1 from string_split(@AreaOfknowledge,',')
			
	  End
END



