CREATE PROCEDURE [dbo].[SP_MASTER_GET_REQUIREMENTS_BY_QUESTION_ID] --'<redacted>'
(
	@SectionType varchar(50) NULL,
	@SectionCode varchar(50) = NULL,
	@QuestionCode varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

    SELECT * FROM Requirements WHERE SectionType=@SectionType and SectionCode=@SectionCode ORDER By OrderNo
    SELECT * FROM Options WHERE SectionType=@SectionType and SectionCode=@SectionCode ORDER By RequirementCode, OptionCode
    SELECT * FROM SubOptions WHERE SectionType=@SectionType and SectionCode=@SectionCode ORDER By RequirementCode, OptionCode, SubOptionCode
    SELECT * FROM Evidences WHERE SectionType=@SectionType and SectionCode=@SectionCode and EvidenceType=1 ORDER By RequirementCode, EvidenceCode
    SELECT * FROM Evidences WHERE SectionType=@SectionType and SectionCode=@SectionCode and EvidenceType=0 ORDER By RequirementCode, EvidenceCode

END

