	SET NOCOUNT ON;
	DECLARE @RequirementCode varchar(50)
	SELECT @RequirementCode = ISNULL(max(OrderNo),0)+1 FROM Requirements WHERE SectionType=@SectionType and SectionCode=@SectionCode

    INSERT INTO Requirements(SectionType, SectionCode, QuestionCode, RequirementCode, RequirementName, OrderNo)
