/****** Object:  StoredProcedure [dbo].[SP_MONITORING_DA_FINAL_SUBMIT]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_MONITORING_DA_FINAL_SUBMIT] --'<redacted>'
(
	@UserId varchar(50) = NULL,
	@ZedId varchar(50) = NULL,
	@CertificationType varchar(50) = NULL,
	@QrCodeSeqNo varchar(50) = NULL
)
AS
BEGIN
		Declare @CertificateNo varchar(50)= NULL,
			@SerialNo varchar(50)
		--SET  @SerialNo = Next Value For CertificateSequence; 
		 select @SerialNo=right(ZedId,6) from MsmeCertifications where ZedId=@ZedId

		Declare @PlantIdNo varchar(50) = NULL
		select @PlantIdNo=PlantIdNo from Msme where ZedId=@ZedId


		IF @CertificationType='Bronze'
		BEGIN
			select @CertificateNo=concat(replace(convert(varchar, getdate(),103),'/',''),'_',@SerialNo)		
			UPDATE MsmeCertifications SET   DaCertificateNo=@CertificateNo, CertificationStatusDate=getdate(),CertificationStatus=6 where  ZedId=@ZedId and Certification=@CertificationType
			
			Update MsmeCertifications set QrCodeSeqNo=concat(@PlantIdNo,'2',@QrCodeSeqNo) where ZedId=@ZedId and Certification=@CertificationType

			insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			values (@ZedId,concat('Completed On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'Completed')

			insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			values (@ZedId,concat('Certificate & Report generated on ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'GetCertified')

			UPDATE Msme SET FinancialAssistanceStatus=1 WHERE ZedId=@ZedId
			UPDATE MsmeBasicInformation SET LastestCertification='Bronze' WHERE ZedId=@ZedId

		END

		ELSE
		BEGIN
			UPDATE MsmeCertifications SET    CertificationStatusDate=getdate(),CertificationStatus=6 where  ZedId=@ZedId and Certification=@CertificationType 
			insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
			values (@ZedId,concat('Completed On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'DesktopVerification')
		END

END


GO
/****** Object:  StoredProcedure [dbo].[SP_MONITORING_GET_COMPLETED_LIST]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_MONITORING_GET_COMPLETED_LIST] --'<redacted>', '<redacted>','<redacted>'
(
	@UserId varchar(50) = NULL,
	@Status int =null,
	@CertificationType varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	 DECLARE @RoleId INT 
	 SELECT @RoleId=ROLEID FROM USERS WHERE USERID=@UserId

		IF @RoleId=7
		BEGIN
			SELECT P.Id,M.ZedId,Certification,AuditsConducted,DomesticCustomers,InternationalCustomers,RawMaterialImported,OutsourcedProcesses,EnergySources,EvidenceSubmissionDate,CertificationBodyUserId,
			AcceptOrRejectDate,P.ReasonForRejection,DesktopAssessorId,SiteAssessorId,ModeOfAssessment,AssessmentDate,DesktopAccepted,DesktopAcceptOrRejectDate,DesktopReasonForRejection,NcCount,CertificationStatus,
			case when CertificationStatus>2 then FORMAT(CertificationStatusDate, 'MMMM d, yyyy') else null end as CertificationStatusDate,
			DaCertificateNo,SaCertificateNo,
			CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress,
			P.Certification, P.CertificationBodyUserId,P.ReasonForRejection,P.DesktopReasonForRejection, UamNumber,PCity,PStateName,PDistrictName,PPin,PUnitName, EnterpriseName, U.UserName 
			,case when @UserId=P.SiteAssessorId then 1 else 0 end as DisplayRecTech
			FROM MsmeCertifications P
			inner join Msme M on (P.ZedId=M.ZedId)
			LEFT JOIN Users U on (P.CertificationBodyUserId=U.UserId)
			WHERE CertificationStatus=6
			and Certification=@CertificationType 
			ORDER By Id
		
		END
		
		


		IF @RoleId=2
		BEGIN
			SELECT P.Id,M.ZedId,Certification,AuditsConducted,DomesticCustomers,InternationalCustomers,RawMaterialImported,OutsourcedProcesses,EnergySources,EvidenceSubmissionDate,CertificationBodyUserId,
			AcceptOrRejectDate,P.ReasonForRejection,DesktopAssessorId,SiteAssessorId,ModeOfAssessment,AssessmentDate,DesktopAccepted,DesktopAcceptOrRejectDate,DesktopReasonForRejection,NcCount,CertificationStatus,
			case when CertificationStatus>2 then FORMAT(CertificationStatusDate, 'MMMM d, yyyy') else null end as CertificationStatusDate,
			DaCertificateNo,SaCertificateNo,
			CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress,
			P.Certification, P.CertificationBodyUserId,P.ReasonForRejection,P.DesktopReasonForRejection, UamNumber,PCity,PStateName,PDistrictName,PPin, EnterpriseName , U.UserName 
			,case when @UserId=P.SiteAssessorId then 1 else 0 end as DisplayRecTech
			FROM MsmeCertifications P
			inner join Msme M on (P.ZedId=M.ZedId)
			LEFT JOIN Users U on (P.CertificationBodyUserId=U.UserId)
			WHERE CertificationStatus=6
			and Certification=@CertificationType and CertificationBodyUserId=@UserId
			ORDER By Id
		
		END

		IF @RoleId=3
		BEGIN
			SELECT P.Id,M.ZedId,Certification,AuditsConducted,DomesticCustomers,InternationalCustomers,RawMaterialImported,OutsourcedProcesses,EnergySources,EvidenceSubmissionDate,CertificationBodyUserId,
			AcceptOrRejectDate,P.ReasonForRejection,DesktopAssessorId,SiteAssessorId,ModeOfAssessment,AssessmentDate,DesktopAccepted,DesktopAcceptOrRejectDate,DesktopReasonForRejection,NcCount,CertificationStatus,
			case when CertificationStatus>2 then FORMAT(CertificationStatusDate, 'MMMM d, yyyy') else null end as CertificationStatusDate,
			DaCertificateNo,SaCertificateNo,
			CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress,
			P.Certification, P.CertificationBodyUserId,P.ReasonForRejection,P.DesktopReasonForRejection, UamNumber,PCity,PStateName,PDistrictName,PPin, EnterpriseName , U.UserName 
			,case when @UserId=P.SiteAssessorId then 1 else 0 end as DisplayRecTech
			FROM MsmeCertifications P
			inner join Msme M on (P.ZedId=M.ZedId)
			LEFT JOIN Users U on (P.CertificationBodyUserId=U.UserId)
			WHERE CertificationStatus=6
			and Certification=@CertificationType and ((DesktopAssessorId=@UserId OR SiteAssessorId=@UserId))
			ORDER By Id
		
		END


END



GO
/****** Object:  StoredProcedure [dbo].[SP_MONITORING_GET_LIST]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
