-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_MONITORING_GET_LIST] --'<redacted>',2,'<redacted>'
(
	@UserId varchar(50) = NULL,
	@Status int =null,
	@CertificationType varchar(50) = NULL,
	@ZedId varchar(50) = NULL,
	@State varchar(100) = NULL,
	@RoleId varchar(50) = NULL,
	@Gender varchar(50) = NULL,
	@MsmeSize varchar(50) = NULL,
	@PageNo int = 1,
	@NoOfRecords int = 25000

)
AS
BEGIN
	
	SET NOCOUNT ON;

	IF @State='' 
	SET @State = NULL

	IF  @CertificationType='' 
	SET @CertificationType = NULL

	IF @Gender='' 
	SET @Gender = NULL

	IF @MsmeSize='' 
	SET @MsmeSize = NULL

	--DECLARE @RoleId INT 
	SELECT @RoleId=ROLEID FROM USERS WHERE USERID=@UserId

	DECLARE @CurrentUrl varchar(100) = NULL
	SELECT @CurrentUrl=UrlName from UrlsMasterData

	DECLARE @NcCount int = NULL
	SELECT @NcCount=isnull(max(NcCount),0) FROM MsmeCertifications where ZedId=@ZedId and Certification= @CertificationType

	IF @RoleId=7
	BEGIN
		SELECT P.Id,M.ZedId,Certification,AuditsConducted,DomesticCustomers,InternationalCustomers,RawMaterialImported,OutsourcedProcesses,EnergySources,EvidenceSubmissionDate,CertificationBodyUserId,
			AcceptOrRejectDate,P.ReasonForRejection,DesktopAssessorId,SiteAssessorId,ModeOfAssessment,FORMAT(AssessmentDate, 'MMMM d, yyyy') SaAssessmentDate,DesktopAccepted,DesktopAcceptOrRejectDate,DesktopReasonForRejection,NcCount,CertificationStatus,
			case when CertificationStatus>2 then FORMAT(CertificationStatusDate, 'MMMM d, yyyy') else null end as CertificationStatusDate,
			DaCertificateNo,SaCertificateNo,
			CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress,
			P.Certification, P.CertificationBodyUserId,P.ReasonForRejection,P.DesktopReasonForRejection, UamNumber,PCity,PStateName,PDistrictName,PPin,PUnitName, M.EnterpriseName, U.UserName AgencyName,
			concat(@CurrentUrl, '/PDFs/SA/',P.ZedId,'/',@CertificationType,'_Report.pdf') ReportPath,
			PV.BasicInfoStatus, PV.DocVerifiAllot, PV.DesktopVerification DesktopVerificationCompleted,PV.ScheduledOn, PV.Completed SaCompletedOn,
			UA.UserName as DesktopAssessorName,
			UL.UserName as SiteAssessorName,
			UC.UserName as CoAssessorName,
			--UT.UserName as 
			TechExpertName,
			CoAssessorId,TechExpert,
			CASE when DesktopAssessorId=@UserId then 'D' else '' end as DeskAssessment, 
			CASE when SiteAssessorId=@UserId then 'S' else '' end as SiteAssessment,
			M.OwnerName as UnitSpocName, M.MobileNo as UnitSpocMobileNo, M.EmailId as UnitSpocEmailId,
			FORMAT(BdsFromDate, 'MMMM d, yyyy') BdsFromDate,FORMAT(BdsToDate, 'MMMM d, yyyy') BdsToDate,
			FORMAT(HapFromDate, 'MMMM d, yyyy') HapFromDate,FORMAT(HapToDate, 'MMMM d, yyyy') HapToDate, B.UdyogAadharNo,TuStatus,

			case when (IsBronzePaymentDone is null and IsSilverPaymentDone is null and IsGoldPaymentDone is null) then 'Payment Pending By MSME'			
			when CertificationStatus=1 then 'Payment done By MSME'
			when CertificationStatus=2 then 'Evidence upload done by MSME'
			when CertificationStatus=3 then 'DA Verification in progress'
			when CertificationStatus=4 then 'DA Verification done with errors'
			when CertificationStatus=5 then 'DA Verification done without errors'
			when CertificationStatus=6 then 'Agency Final submit done for DA'
			when CertificationStatus=7 then 'Failed in NC'
			when CertificationStatus=8 then 'SA Allocation Done'
			when CertificationStatus=9 then 'SA is ready to start'
			when CertificationStatus=13 then 'SA Verification in progress'
			when CertificationStatus=14 then 'SA Verification done with errors'
			when CertificationStatus=15 then 'SA verification done without errors'
			when CertificationStatus=16 then 'Agency Final submit for SA' 
			when (IsBronzePaymentDone=1 or IsSilverPaymentDone=1 or IsGoldPaymentDone=1) then 'Payment Done By MSME'
		end as AssessmentStatus,
		ROW_NUMBER() OVER (order by p.CertificationStatusDate desc) as RowNumber, NcStatus, FORMAT(P.NcFinalClosureDt, 'MMMM d, yyyy') NcFinalClosureDt
		,1 DisplayRecTech

		FROM MsmeCertifications P
		inner join Msme M on (P.ZedId=M.ZedId)
		LEFT JOIN Users U on (P.CertificationBodyUserId=U.UserId)
		LEFT JOIN Users UA on (P.DesktopAssessorId=UA.UserId)
		LEFT JOIN Users UL on (P.SiteAssessorId=UL.UserId)
		LEFT JOIN Users UC on (P.CoAssessorId=UC.UserId)
		--LEFT JOIN Users UT on (P.TechExpert=UT.UserId)
		
		OUTER APPLY (
    SELECT STRING_AGG(U_TE.UserName, ', ') AS TechExpertName
    FROM STRING_SPLIT(P.TechExpert, ',') s
    INNER JOIN Users U_TE ON LTRIM(RTRIM(s.value)) = U_TE.UserId
	) UT

		LEFT JOIN
		(select * from 
		(
		  select ZedId, StatusType, FORMAT(CreatedDate, 'MMMM d, yyyy') CreatedOn,CertificationType
		  from MsmeHistory where CertificationType is not null and StatusType is not null
		) src
		pivot
		(
		  max(CreatedOn)
		  for StatusType in ([BasicInfoStatus], [DocVerifiAllot], [DesktopVerification],[ScheduledOn],[Completed])
		) piv) PV
		on (P.ZedId=PV.ZedId and P.Certification=PV.CertificationType and PV.CertificationType=@CertificationType)
		LEFT JOIN MsmeBasicInformation B on (M.ZedId=B.ZedId)

		WHERE ((CertificationStatus=ISNULL(@Status,0) and @Status!=6) OR (@Status=3 AND CertificationStatus=13 AND P.ModeOfAssessment!='Remote Assessment')  OR (@Status=3 AND CertificationStatus=9 AND P.ModeOfAssessment!='Remote Assessment')  OR (@Status=3 AND CertificationStatus=9 AND JoinRoomStatus=1 AND P.ModeOfAssessment='Remote Assessment') OR (@Status=2 AND CertificationStatus=8) OR (@Status=7 AND CertificationStatus=7) OR (@Status=7 AND CertificationStatus=17) OR (@Status=99 AND CertificationStatus=99) OR (@Status=2 AND P.ModeOfAssessment='Remote Assessment' AND CertificationStatus=9 AND JoinRoomStatus=0) OR (@Status=5 AND CertificationStatus=15) OR (@Status=4 AND CertificationStatus=14) OR (@Status=6 AND ((P.Certification='Bronze' and CertificationStatus=6) OR ( P.Certification!='Bronze' and CertificationStatus in (16,100)))))
			 AND (@ZedId IS NULL OR p.ZedId=@ZedId)
			and DesktopAccepted=1
			and (@State is null or M.StateId=@State) AND (@CertificationType IS NULL OR P.Certification=@CertificationType) AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize) AND (@Gender IS NULL OR Gender=@Gender) 
		ORDER By p.CertificationStatusDate desc
		
		IF @CertificationType='Silver'
		BEGIN
			SELECT ISNULL([2],0)+ISNULL([8],0) NotStarted, ISNULL([3],0)+ISNULL([13],0)+ISNULL([9],0) InProgress, ISNULL([5],0)+ISNULL([15],0) Qc, ISNULL([4],0)+ISNULL([14],0) Nc, ISNULL([7],0)+ISNULL([17],0) Rj FROM 
			(SELECT CertificationStatus, Count(*) Cnt FROM MsmeCertifications WHERE Certification=@CertificationType and DesktopAccepted=1 GROUP BY CertificationStatus) src
			PIVOT
			(max(cnt) for CertificationStatus in ([2],[3],[4],[5],[7],[8],[9],[13],[14],[15],[17])) pvt
		END
		ELSE
		BEGIN
			SELECT ISNULL([2],0)+ISNULL([8],0) NotStarted, ISNULL([3],0)+ISNULL([13],0)+ISNULL([9],0) InProgress, ISNULL([5],0)+ISNULL([15],0) Qc, ISNULL([4],0)+ISNULL([14],0) Nc, ISNULL([7],0)+ISNULL([17],0) Rj FROM 
			(SELECT CertificationStatus, Count(*) Cnt FROM MsmeCertifications WHERE Certification=@CertificationType and DesktopAccepted=1 GROUP BY CertificationStatus) src
			PIVOT
			(max(cnt) for CertificationStatus in ([2],[3],[4],[5],[7],[8],[9],[13],[14],[15],[17])) pvt
		END
			
	END

	ELSE IF @RoleId=2
	BEGIN
		SELECT P.Id,M.ZedId,Certification,AuditsConducted,DomesticCustomers,InternationalCustomers,RawMaterialImported,OutsourcedProcesses,EnergySources,EvidenceSubmissionDate,CertificationBodyUserId,
		AcceptOrRejectDate,P.ReasonForRejection,DesktopAssessorId,SiteAssessorId,ModeOfAssessment,FORMAT(AssessmentDate, 'MMMM d, yyyy') SaAssessmentDate,DesktopAccepted,DesktopAcceptOrRejectDate,DesktopReasonForRejection,NcCount,CertificationStatus,
		case when CertificationStatus>2 then FORMAT(CertificationStatusDate, 'MMMM d, yyyy') else null end as CertificationStatusDate,
		DaCertificateNo,SaCertificateNo,
		CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress,
		P.Certification, P.CertificationBodyUserId,P.ReasonForRejection,P.DesktopReasonForRejection, UamNumber,PCity,PStateName,PDistrictName,PPin,PUnitName, M.EnterpriseName , U.UserName AgencyName,
		PV.BasicInfoStatus, PV.DocVerifiAllot, PV.DesktopVerification DesktopVerificationCompleted,PV.ScheduledOn, PV.Completed SaCompletedOn,
		UA.UserName as DesktopAssessorName,
		UL.UserName as SiteAssessorName,
		UC.UserName as CoAssessorName,
		--UT.UserName as 
		TechExpertName,
		CoAssessorId,TechExpert,
		CASE when DesktopAssessorId=@UserId then 'D' else '' end as DeskAssessment, 
		CASE when SiteAssessorId=@UserId then 'S' else '' end as SiteAssessment,
		M.OwnerName as UnitSpocName, M.MobileNo as UnitSpocMobileNo, M.EmailId as UnitSpocEmailId,
		FORMAT(BdsFromDate, 'MMMM d, yyyy') BdsFromDate,FORMAT(BdsToDate, 'MMMM d, yyyy') BdsToDate,
		FORMAT(HapFromDate, 'MMMM d, yyyy') HapFromDate,FORMAT(HapToDate, 'MMMM d, yyyy') HapToDate, B.UdyogAadharNo,TuStatus,

		case when (IsBronzePaymentDone is null and IsSilverPaymentDone is null and IsGoldPaymentDone is null) then 'Payment Pending By MSME'			
			when CertificationStatus=1 then 'Payment done By MSME'
			when CertificationStatus=2 then 'Evidence upload done by MSME'
			when CertificationStatus=3 then 'DA Verification in progress'
			when CertificationStatus=4 then 'DA Verification done with errors'
			when CertificationStatus=5 then 'DA Verification done without errors'
			when CertificationStatus=6 then 'Agency Final submit done for DA'
			when CertificationStatus=7 then 'Failed in NC'
			when CertificationStatus=8 then 'SA Allocation Done'
			when CertificationStatus=9 then 'SA is ready to start'
			when CertificationStatus=13 then 'SA Verification in progress'
			when CertificationStatus=14 then 'SA Verification done with errors'
			when CertificationStatus=15 then 'SA verification done without errors'
			when CertificationStatus=16 then 'Agency Final submit for SA' 
			when (IsBronzePaymentDone=1 or IsSilverPaymentDone=1 or IsGoldPaymentDone=1) then 'Payment Done By MSME'
		end as AssessmentStatus,
		ROW_NUMBER() OVER (order by p.CertificationStatusDate desc) as RowNumber, NcStatus, FORMAT(P.NcFinalClosureDt, 'MMMM d, yyyy') NcFinalClosureDt
		,1 DisplayRecTech
		FROM MsmeCertifications P
		inner join Msme M on (replace(P.ZedId,'_D','')=M.ZedId)
		LEFT JOIN Users U on (P.CertificationBodyUserId=U.UserId)
		
		LEFT JOIN Users UA on (P.DesktopAssessorId=UA.UserId)
		LEFT JOIN Users UL on (P.SiteAssessorId=UL.UserId)
		LEFT JOIN Users UC on (P.CoAssessorId=UC.UserId)
		--LEFT JOIN Users UT on (P.TechExpert=UT.UserId)

		OUTER APPLY (
		SELECT STRING_AGG(U_TE.UserName, ', ') AS TechExpertName
		FROM STRING_SPLIT(P.TechExpert, ',') s
		INNER JOIN Users U_TE ON LTRIM(RTRIM(s.value)) = U_TE.UserId
		) UT

		LEFT JOIN
		(select * from 
		(
		  select ZedId, StatusType, FORMAT(CreatedDate, 'MMMM d, yyyy') CreatedOn,CertificationType
		  from MsmeHistory where CertificationType is not null and StatusType is not null
		) src
		pivot
		(
		  max(CreatedOn)
		  for StatusType in ([BasicInfoStatus], [DocVerifiAllot], [DesktopVerification],[ScheduledOn],[Completed])
		) piv) PV
		on (P.ZedId=PV.ZedId and P.Certification=PV.CertificationType and PV.CertificationType=@CertificationType)
		LEFT JOIN MsmeBasicInformation B on (M.ZedId=B.ZedId)

		WHERE ((CertificationStatus=ISNULL(@Status,0) and @Status!=6) OR (@Status=3 AND CertificationStatus=13 AND P.ModeOfAssessment!='Remote Assessment')  OR (@Status=3 AND CertificationStatus=9 AND P.ModeOfAssessment!='Remote Assessment')  OR (@Status=3 AND CertificationStatus=9 AND JoinRoomStatus=1 AND P.ModeOfAssessment='Remote Assessment') OR (@Status=2 AND CertificationStatus=8) OR (@Status=7 AND CertificationStatus=7) OR (@Status=7 AND CertificationStatus=17) OR (@Status=99 AND CertificationStatus=99) OR (@Status=2 AND P.ModeOfAssessment='Remote Assessment' AND CertificationStatus=9 AND JoinRoomStatus=0) OR (@Status=5 AND CertificationStatus=15) OR (@Status=4 AND CertificationStatus=14) OR (@Status=6 AND ((P.Certification='Bronze' and CertificationStatus=6) OR ( P.Certification!='Bronze' and CertificationStatus in (16,100)))))
		--WHERE (CertificationStatus=ISNULL(@Status,0)  OR (@Status=3 AND CertificationStatus=9 AND P.ModeOfAssessment!='<redacted>')  OR (@Status=3 AND CertificationStatus=9 AND JoinRoomStatus=1 AND P.ModeOfAssessment='<redacted>') OR (@Status=2 AND CertificationStatus=8) OR (@Status=2 AND P.ModeOfAssessment='<redacted>' AND CertificationStatus=9 AND JoinRoomStatus=0) OR (@Status=5 AND CertificationStatus=15) OR (@Status=4 AND CertificationStatus=14) OR (@Status=6 AND CertificationStatus=16))
		 and CertificationBodyUserId=@UserId AND (@ZedId IS NULL OR p.ZedId=@ZedId)
		and DesktopAccepted=1
		and (@State is null or M.StateId=@State) AND (@CertificationType IS NULL OR P.Certification=@CertificationType) AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize) AND (@Gender IS NULL OR Gender=@Gender) 
		ORDER By p.CertificationStatusDate desc


		IF @CertificationType='Silver'
		BEGIN
			--SELECT ISNULL([2],0)+ISNULL([8],0) NotStarted, ISNULL([3],0)+ISNULL([13],0)+ISNULL([9],0) InProgress, ISNULL([5],0)+ISNULL([15],0) Qc, ISNULL([4],0)+ISNULL([14],0) Nc, ISNULL([7],0)+ISNULL([17],0) Rj FROM
			--(SELECT CertificationStatus, Count(*) Cnt FROM 
			--(select CASE WHEN JoinRoomStatus=0 and CertificationStatus=9 then 8 else CertificationStatus end as CertificationStatus from MsmeCertifications 
			--WHERE Certification=@CertificationType and CertificationBodyUserId=@UserId and DesktopAccepted=1)
			--MsmeCertifications  GROUP BY CertificationStatus) src
			--PIVOT
			--(max(cnt) for CertificationStatus in ([2],[3],[4],[5],[7],[8],[9],[13],[14],[15],[17])) pvt

			SELECT ISNULL([2],0)+ISNULL([8],0) NotStarted, ISNULL([3],0)+ISNULL([13],0)+ISNULL([9],0) InProgress, ISNULL([5],0)+ISNULL([15],0) Qc, ISNULL([4],0)+ISNULL([14],0) Nc, ISNULL([7],0)+ISNULL([17],0) Rj FROM
			(SELECT CertificationStatus, Count(*) Cnt FROM MsmeCertifications WHERE Certification=@CertificationType and CertificationBodyUserId=@UserId and DesktopAccepted=1 GROUP BY CertificationStatus) src
			PIVOT
			(max(cnt) for CertificationStatus in ([2],[3],[4],[5],[7],[8],[9],[13],[14],[15],[17])) pvt
		END

		ELSE
		BEGIN
			SELECT ISNULL([2],0)+ISNULL([8],0) NotStarted, ISNULL([3],0)+ISNULL([13],0)+ISNULL([9],0) InProgress, ISNULL([5],0)+ISNULL([15],0) Qc, ISNULL([4],0)+ISNULL([14],0) Nc, ISNULL([7],0)+ISNULL([17],0) Rj FROM
			(SELECT CertificationStatus, Count(*) Cnt FROM MsmeCertifications WHERE Certification=@CertificationType and CertificationBodyUserId=@UserId and DesktopAccepted=1 GROUP BY CertificationStatus) src
			PIVOT
			(max(cnt) for CertificationStatus in ([2],[3],[4],[5],[7],[8],[9],[13],[14],[15],[17])) pvt
		END
	END

	ELSE IF @RoleId=3
	BEGIN
		SELECT P.Id,M.ZedId,Certification,AuditsConducted,DomesticCustomers,InternationalCustomers,RawMaterialImported,OutsourcedProcesses,EnergySources,EvidenceSubmissionDate,CertificationBodyUserId,
		AcceptOrRejectDate,P.ReasonForRejection,DesktopAssessorId,SiteAssessorId,ModeOfAssessment,FORMAT(AssessmentDate, 'MMMM d, yyyy') SaAssessmentDate,DesktopAccepted,DesktopAcceptOrRejectDate,DesktopReasonForRejection,NcCount,CertificationStatus,
		case when CertificationStatus>2 then FORMAT(CertificationStatusDate, 'MMMM d, yyyy') else null end as CertificationStatusDate,
		DaCertificateNo,SaCertificateNo,
		CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress,
		P.Certification, P.CertificationBodyUserId,P.ReasonForRejection,P.DesktopReasonForRejection, UamNumber,PCity,PStateName,PDistrictName,PPin,PUnitName, M.EnterpriseName , U.UserName AgencyName,
		PV.BasicInfoStatus, PV.DocVerifiAllot, PV.DesktopVerification DesktopVerificationCompleted,PV.ScheduledOn, PV.Completed SaCompletedOn,
		UA.UserName as DesktopAssessorName,
		UL.UserName as SiteAssessorName,
		UC.UserName as CoAssessorName,
		--UT.UserName as 
		TechExpertName,
		CoAssessorId,TechExpert,
		CASE when DesktopAssessorId=@UserId then 'D' else '' end as DeskAssessment, 
		CASE when SiteAssessorId=@UserId then 'S' else '' end as SiteAssessment,
		M.OwnerName as UnitSpocName, M.MobileNo as UnitSpocMobileNo, M.EmailId as UnitSpocEmailId,
		FORMAT(BdsFromDate, 'MMMM d, yyyy') BdsFromDate,FORMAT(BdsToDate, 'MMMM d, yyyy') BdsToDate,
		FORMAT(HapFromDate, 'MMMM d, yyyy') HapFromDate,FORMAT(HapToDate, 'MMMM d, yyyy') HapToDate, B.UdyogAadharNo,TuStatus,

		case when (IsBronzePaymentDone is null and IsSilverPaymentDone is null and IsGoldPaymentDone is null) then 'Payment Pending By MSME'			
			when CertificationStatus=1 then 'Payment done By MSME'
			when CertificationStatus=2 then 'Evidence upload done by MSME'
			when CertificationStatus=3 then 'DA Verification in progress'
			when CertificationStatus=4 then 'DA Verification done with errors'
			when CertificationStatus=5 then 'DA Verification done without errors'
			when CertificationStatus=6 then 'Agency Final submit done for DA'
			when CertificationStatus=7 then 'Failed in NC'
			when CertificationStatus=8 then 'SA Allocation Done'
			when CertificationStatus=9 then 'SA is ready to start'
			when CertificationStatus=13 then 'SA Verification in progress'
			when CertificationStatus=14 then 'SA Verification done with errors'
			when CertificationStatus=15 then 'SA verification done without errors'
			when CertificationStatus=16 then 'Agency Final submit for SA' 
			when (IsBronzePaymentDone=1 or IsSilverPaymentDone=1 or IsGoldPaymentDone=1) then 'Payment Done By MSME'
		end as AssessmentStatus,
		ROW_NUMBER() OVER (order by p.CertificationStatusDate desc) as RowNumber, NcStatus, FORMAT(P.NcFinalClosureDt, 'MMMM d, yyyy') NcFinalClosureDt
		,case when @UserId=P.SiteAssessorId then 1 else 0 end as DisplayRecTech
		FROM MsmeCertifications P
		inner join Msme M on (replace(P.ZedId,'_D','')=M.ZedId)
		LEFT JOIN Users U on (P.CertificationBodyUserId=U.UserId)
		
		LEFT JOIN Users UA on (P.DesktopAssessorId=UA.UserId)
		LEFT JOIN Users UL on (P.SiteAssessorId=UL.UserId)
		LEFT JOIN Users UC on (P.CoAssessorId=UC.UserId)
		--LEFT JOIN Users UT on (P.TechExpert=UT.UserId)

		OUTER APPLY (
		SELECT STRING_AGG(U_TE.UserName, ', ') AS TechExpertName
		FROM STRING_SPLIT(P.TechExpert, ',') s
		INNER JOIN Users U_TE ON LTRIM(RTRIM(s.value)) = U_TE.UserId
		) UT

		LEFT JOIN
		(select * from 
		(
		  select ZedId, StatusType, FORMAT(CreatedDate, 'MMMM d, yyyy') CreatedOn,CertificationType
		  from MsmeHistory where CertificationType is not null and StatusType is not null
		) src
		pivot
		(
		  max(CreatedOn)
		  for StatusType in ([BasicInfoStatus], [DocVerifiAllot], [DesktopVerification],[ScheduledOn],[Completed])
		) piv) PV
		on (P.ZedId=PV.ZedId and P.Certification=PV.CertificationType and PV.CertificationType=@CertificationType)
		LEFT JOIN MsmeBasicInformation B on (M.ZedId=B.ZedId)

		WHERE ((CertificationStatus=ISNULL(@Status,0) and @Status!=6)  OR (@Status=3 AND CertificationStatus=9 AND P.ModeOfAssessment!='Remote Assessment')  OR (@Status=3 AND CertificationStatus=9 AND JoinRoomStatus=1 AND P.ModeOfAssessment='Remote Assessment') OR (@Status=2 AND CertificationStatus=8) OR (@Status=7 AND CertificationStatus=7) OR (@Status=7 AND CertificationStatus=17) OR (@Status=99 AND CertificationStatus=99) OR (@Status=2 AND P.ModeOfAssessment='Remote Assessment' AND CertificationStatus=9 AND JoinRoomStatus=0) OR (@Status=5 AND CertificationStatus=15) OR (@Status=4 AND CertificationStatus=14) OR (@Status=6 AND ((P.Certification='Bronze' and CertificationStatus IN (5,6)) OR ( P.Certification!='Bronze' and CertificationStatus IN (15,16,100)))))
		--WHERE (CertificationStatus=ISNULL(@Status,0)  OR (@Status=3 AND CertificationStatus=9 AND P.ModeOfAssessment!='<redacted>')  OR (@Status=3 AND CertificationStatus=9 AND JoinRoomStatus=1 AND P.ModeOfAssessment='<redacted>') OR (@Status=2 AND CertificationStatus=8) OR (@Status=2 AND P.ModeOfAssessment='<redacted>' AND CertificationStatus=9 AND JoinRoomStatus=0) OR (@Status=5 AND CertificationStatus=15) OR (@Status=4 AND CertificationStatus=14) OR (@Status=6 AND CertificationStatus IN (5,15,16)))
		and ((DesktopAssessorId=@UserId OR SiteAssessorId=@UserId)) AND (@ZedId IS NULL OR p.ZedId=@ZedId)
		and DesktopAccepted=1 
		and (@State is null or M.StateId=@State) AND (@CertificationType IS NULL OR P.Certification=@CertificationType) AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize) AND (@Gender IS NULL OR Gender=@Gender) 
		--and NcCount=@NcCount
		ORDER By p.CertificationStatusDate desc


		IF @CertificationType='Silver'
		BEGIN
			SELECT ISNULL([2],0)+ISNULL([8],0) NotStarted, ISNULL([3],0)+ISNULL([13],0)+ISNULL([9],0) InProgress, ISNULL([5],0)+ISNULL([15],0) Qc, ISNULL([4],0)+ISNULL([14],0) Nc, ISNULL([7],0)+ISNULL([17],0) Rj FROM
			(SELECT CertificationStatus, Count(*) Cnt FROM 
			(select CASE WHEN JoinRoomStatus=0 and CertificationStatus=9 then 8 else CertificationStatus end as CertificationStatus from MsmeCertifications 
			WHERE Certification=@CertificationType and CertificationBodyUserId=@UserId and DesktopAccepted=1)
			MsmeCertifications  GROUP BY CertificationStatus) src
			PIVOT
			(max(cnt) for CertificationStatus in ([2],[3],[4],[5],[7],[8],[9],[13],[14],[15],[17])) pvt
		END

		ELSE
		BEGIN
			SELECT ISNULL([2],0)+ISNULL([8],0) NotStarted, ISNULL([3],0)+ISNULL([13],0)+ISNULL([9],0) InProgress, ISNULL([5],0)+ISNULL([15],0) Qc, ISNULL([4],0)+ISNULL([14],0) Nc,ISNULL([7],0)+ISNULL([17],0) Rj FROM
			(SELECT CertificationStatus, Count(*) Cnt FROM MsmeCertifications WHERE Certification=@CertificationType and CertificationBodyUserId=@UserId and DesktopAccepted=1 GROUP BY CertificationStatus) src
			PIVOT
			(max(cnt) for CertificationStatus in ([2],[3],[4],[5],[7],[8],[9],[13],[14],[15],[17])) pvt
		END
	END

END







