CREATE PROC [dbo].[SP_MONITORING_RA_UPDATE_AGENCY_REMARKS]
(
	@UserId varchar(50) = NULL,
	@ZedId varchar(50) = NULL,
	@CertificationType varchar(50) = NULL,
	@TableName varchar(50) = NULL,
	@Id varchar(50) = NULL,
	@Remarks varchar(5000) = NULL
)
AS
BEGIN

	IF @TableName='MsmeProducts'
	BEGIN
		UPDATE MsmeProducts 
		SET SaAssessorRemarks=@Remarks, UpdatedDate=getdate()
		where  Id=@Id AND ZedId=@ZedId AND Certification=@CertificationType
	END

	IF @TableName='MsmeRequirements'
	BEGIN
		UPDATE MsmeRequirements 
		SET SaAssessorRemarks=@Remarks, UpdatedDate=getdate()
		where  Id=@Id AND ZedId=@ZedId AND SectionType=@CertificationType
	END

	IF @TableName='MsmeCertifications'
	BEGIN
		UPDATE AssessorComments 
		SET SaAssessorRemarks=@Remarks
		where  ZedId=@ZedId AND Certification=@CertificationType AND NcCount=0 AND AssessmentType='SA'
	END
	IF @TableName='Meetings'
	BEGIN
		UPDATE Meetings 
		SET Comments=@Remarks,FieldComments=@Remarks
		where  Id=@Id AND ZedId=@ZedId AND CertificationType=@CertificationType
	END
	IF @TableName='SaPhotos'
	BEGIN
		UPDATE SaPhotos 
		SET AssessorRemarks=@Remarks
		where  Id=@Id AND ZedId=@ZedId AND Certification=@CertificationType
	END
	IF @TableName='AssessorComments'
	BEGIN
		UPDATE AssessorComments 
		SET SaAssessorRemarks=@Remarks
		where  Id=@Id AND ZedId=@ZedId AND Certification=@CertificationType
	END
END

