CREATE PROC [dbo].[SP_MONITORING_SEND_BACK_TO_ASSESSOR]
(
	@ZedId varchar(100) = NULL,
	@UserId varchar(50) = NULL,
	@RoleId	varchar(50) = NULL,
	@CertificationType varchar(50) = NULL,
	@SendBackRemarks varchar(2000) = NULL
    
	
)
AS
BEGIN

	DECLARE @NcCount varchar(50) = NULL

	SELECT top 1 @NcCount=NcCount FROM MsmeCertifications WHERE ZedId=@ZedId and Certification=@CertificationType and CertificationStatus=15 order by Id Desc

	IF EXISTS(SELECT * FROM MsmeCertifications WHERE ZedId=@ZedId and Certification=@CertificationType and CertificationStatus=15)
	BEGIN
		UPDATE MsmeCertifications set CertificationStatus=13, SendBackStatus=1, CertificationStatusDate=getdate() where ZedId=@ZedId and Certification=@CertificationType and CertificationStatus=15
	END
	ELSE
	BEGIN
		select 0 Status, 'Check the details' ErrorMessage
	END

	INSERT INTO AssessorComments (ZedId,Certification,NcCount,AssessorRemarks,CertificationStatusDate,AssessmentType)
	VALUES (@ZedId,@CertificationType,@NcCount,@SendBackRemarks,GETDATE(),concat('Milestone ',@NcCount))

	insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
	values (@ZedId,concat('CO send back to Consultant On ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@CertificationType,'CO Send back to Consultant' )

END




