CREATE PROC [dbo].[SP_MOVING_MILESTONE_1_TO_PAYMENT_COMPLETION_STAGE]
(
	@ZedId varchar(100) = NULL,
	@Certification varchar(50) = NULL,
	@NcCount int = 1
    
	
)
AS
BEGIN			

				IF @NcCount <> 1
				BEGIN
					PRINT 'Execution skipped as NcCount is not 1.'
					RETURN;
				END

			    DECLARE @NewZedId VARCHAR(60) = CONCAT(@ZedId, '_RESET')
			
				update ZED_CONSULTANT.dbo.SaRequirementPhotos set ZedId=@NewZedId where ZedId=@ZedId AND certification=@Certification and NcCount=1

				update ZED_CONSULTANT.dbo.MsmeCertifications set CertificationBodyUserId=null,SiteAssessorId=null,
				CoAssessorId=null,	ModeOfAssessment=null,	AssessmentDate=null,certificationstatus=6,issaverified=null,BdsFromDate=null,
				BdsToDate=null,	HapFromDate=null,	HapToDate=null
				where ZedId=@ZedId AND certification=@Certification and NcCount=1

				update ZED_CONSULTANT.dbo.SaRawMaterials set ZedId=@NewZedId where ZedId=@ZedId AND certification=@Certification and NcCount=1
				update ZED_CONSULTANT.dbo.AssessorComments set ZedId=@NewZedId where ZedId=@ZedId AND certification=@Certification and NcCount=1
				update ZED_CONSULTANT.dbo.MsmeLocations set ZedId=@NewZedId where ZedId=@ZedId AND certification=@Certification --and NcCount=1
				update ZED_CONSULTANT.dbo.ScreenshotPhotos set ZedId=@NewZedId where ZedId=@ZedId AND certification=@Certification and NcCount=1
				update ZED_CONSULTANT.dbo.MsmeRawMaterials set ZedId=@NewZedId where ZedId=@ZedId AND certification=@Certification and NcCount=1
				
				update ZED_CONSULTANT.dbo.MsmeSections set AssessorId=null where ZedId=@ZedId AND SectionType=@Certification and NcCount=1
				
				update ZED_CONSULTANT.dbo.MsmePhotos set ZedId=@NewZedId where ZedId=@ZedId AND certification=@Certification and NcCount=1
				update ZED_CONSULTANT.dbo.MsmeProducts set ZedId=@NewZedId where ZedId=@ZedId AND certification=@Certification and NcCount=1
				update ZED_CONSULTANT.dbo.SaPhotos set ZedId=@NewZedId where ZedId=@ZedId AND certification=@Certification and NcCount=1
				update ZED_CONSULTANT.dbo.SaProducts set ZedId=@NewZedId where ZedId=@ZedId AND certification=@Certification and NcCount=1
				
				update ZED_CONSULTANT.dbo.MeetingParticipants set ZedId=@NewZedId where ZedId=@ZedId AND CertificationType=@Certification and NcCount=1
				update ZED_CONSULTANT.dbo.Meetings set ZedId=@NewZedId where ZedId=@ZedId AND CertificationType=@Certification and NcCount=1
				update ZED_CONSULTANT.dbo.msmerequirementbullets set ZedId=@NewZedId where ZedId=@ZedId AND CertificationType=@Certification and NcCount=1
				update ZED_CONSULTANT.dbo.AllotedCoAssessors set ZedId=@NewZedId where ZedId=@ZedId AND certification=@Certification and NcCount=1


				insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType,NcCount)
				values (@ZedId,'Data reset on request of QCI',getdate(),@Certification,null,1 )


END




