CREATE PROCEDURE [dbo].[SP_MSME_INSERT_UDYAM_DETAILS] --'<redacted>', '<redacted>'
(
	@MsmeId	varchar(50)	= NULL,
	@ZedId	varchar(50)	= NULL,
	@StateId	varchar(50)	= NULL,
	@StateName	varchar(100)	= NULL,
	@DistrictId	varchar(50)	= NULL,
	@DistrictName	varchar(100)	= NULL,
	@OwnerName	varchar(200)	= NULL,
	@EnterpriseName	varchar(250)	= NULL,
	@OrganisationType	varchar(50)	= NULL,
	@OrganisationTypeName	varchar(50)	= NULL,
	@EnterpriseType	varchar(50)	= NULL,
	@EnterpriseTypee	varchar(50)	= NULL,
	@MobileNo	varchar(50)	= NULL,
	@EmailId	varchar(200)	= NULL,
	@PledgeEmailId	varchar(200)	= NULL,
	@ApplicationId	varchar(50)	= NULL,
	@PFlat	varchar(200)	= NULL,
	@PBuilding	varchar(200)	= NULL,
	@PRoad	varchar(200)	= NULL,
	@PArea	varchar(200)	= NULL,
	@PCity	varchar(200)	= NULL,
	@PPin	varchar(50)	= NULL,
	@PStateId	varchar(50)	= NULL,
	@PStateName	varchar(100)	= NULL,
	@PLgDistrictCode	varchar(50)	= NULL,
	@PDistrictName	varchar(100)	= NULL,
	@PPlantDetailId	varchar(50)	= NULL,
	@Activity	varchar(100)	= NULL,
	@TwoDigitActivity	varchar(2000)	= NULL,
	@FourDigitActivity	varchar(2000)	= NULL,
	@FiveDigitActivity	varchar(2000)	= NULL,
	@ActivityDetailId	varchar(50)	= NULL,
	@UdyogAadharNo	varchar(50)	= NULL,
	@SocialCategory	varchar(50)	= NULL,
	@SocialCategoryName	varchar(50)	= NULL,
	@Gender	varchar(50)	= NULL,
	@PH	varchar(50)	= NULL,
	@PanNo	varchar(50)	= NULL,
	@Address	varchar(max)	= NULL,
	@MajorActivity	varchar(50)	= NULL,
	@MajorActivityName	varchar(50)	= NULL,
	@CommmenceDate	varchar(50)	= NULL,	
	@LgDistrictCode	varchar(50)	= NULL,
	@Pincode	varchar(50)	= NULL,
	@PreviousEMType	varchar(50)	= NULL,
	@PreviousEMNumber	varchar(50)	= NULL,
	@TotalEmp	varchar(50)	= NULL,
	@InvestmentCost	varchar(50)	= NULL,
	@DicName	varchar(50)	= NULL,
	@AppliedDate varchar(50)	= NULL,
	@Password varchar(50) = NULL,
	@IpAddress varchar(50) = NULL,
	@PAddress varchar(2000) = NULL,
	@UamNumber varchar(50) = NULL,
	@IncorporationDate varchar(50) = NULL,
	@WhetherProdCommenced varchar(50) = NULL,
	@PlantIdNo varchar(50) = NULL,
	@UnitName varchar(500) = NULL,
	@UnitIdNo varchar(50) = NULL,
	@RegistrationFrom varchar(50) = NULL,
	@ZedCertified  bit = NULL,
	@QrCodeNo varchar(50) = NULL
)
AS
BEGIN
	  
	SET @MsmeId = Next Value For MsmeIdSequence; 
	SET @ZedId = CONCAT('ZEDMSME',RIGHT(concat('00000',convert(varchar(50),@MsmeId)),6)); 

	Declare @CertificateNo varchar(50)= NULL
	select @CertificateNo=concat('ZED_',replace(convert(varchar, getdate(),103),'/',''),'_',@MsmeId), @QrCodeNo=concat(@PlantIdNo,'1',UPPER(@Password))

	DECLARE @CurrentUrl varchar(100) = NULL
	SELECT @CurrentUrl=UrlName from UrlsMasterData

	
	IF @Password IS NULL 
	BEGIN
		SET @Password=@ZedId
	END

	IF @StateId IS NULL 
	BEGIN
		select @StateId=StateCode from Districts where DistrictCode=@PLgDistrictCode
	END


	INSERT INTO Msme (MsmeId, ZedId, StateId, StateName, DistrictId, DistrictName, OwnerName, EnterpriseName, OrganisationTypeName, EnterpriseTypee, EnterpriseType, MobileNo, EmailId,PledgeEmailId,
		ApplicationId,UamNumber, PFlat, PBuilding, PRoad, PArea, PCity,PAddress, PPin, PStateId, PStateName, PLgDistrictCode, PDistrictName, PPlantDetailId, Activity, TwoDigitActivity, FourDigitActivity,
		FiveDigitActivity, ActivityDetailId,PledgeCertificateNo,RegistrationType,IncorporationDate, WhetherProdCommenced,PlantIdNo,PUnitName,PUnitIdNo,RegistrationFrom,QrCodeNo
	)
	VALUES(@MsmeId, @ZedId, @StateId, @StateName, @DistrictId, @DistrictName, @OwnerName, @EnterpriseName, @OrganisationType, 
		@EnterpriseType, @EnterpriseType, @MobileNo, @PledgeEmailId, @PledgeEmailId, @ApplicationId,@UamNumber, @PFlat, @PBuilding, @PRoad, @PArea, @PCity,@PAddress, @PPin, @PStateId, @PStateName, @PLgDistrictCode, 
		@PDistrictName, @PPlantDetailId, @Activity, @TwoDigitActivity, @FourDigitActivity, @FiveDigitActivity, @ActivityDetailId, @CertificateNo,'UDYAM', @IncorporationDate, @WhetherProdCommenced,@PlantIdNo,
		@UnitName,@UnitIdNo,@RegistrationFrom,@QrCodeNo
	)


	INSERT INTO MsmeBasicInformation(MsmeId,ZedId, ApplicationId, UdyogAadharNo, OwnerName, EnterpriseName, OrganisationTypeName, SocialCategoryName, Gender, PH, PanNo, Address, 
		StateName, DistrictName, LgDistrictCode, Pincode, MobileNo, EmailId, MajorActivityName, EnterpriseTypee, CommmenceDate, PreviousEMType, PreviousEMNumber, 
		TotalEmp, InvestmentCost, DicName, AppliedDate
	)
	VALUES(@MsmeId,@ZedId,@ApplicationId,@UdyogAadharNo,@OwnerName,@EnterpriseName,@OrganisationType,@SocialCategory,@Gender,@PH,@PanNo,@Address,
		@StateName,@DistrictName,@LgDistrictCode,@Pincode,@MobileNo,@PledgeEmailId,@MajorActivity,@EnterpriseType,@CommmenceDate,@PreviousEMType,@PreviousEMNumber,
		@TotalEmp,@InvestmentCost,@DicName,@AppliedDate	
	)


	INSERT INTO USERS(UserId, Password,	UserName, RoleId, IsActive, Email, MobileNo, CreatedBy, CreatedDate, StateCode,	DistrictCode)
	VALUES(@ZedId, @Password, @UnitName, 5, 1, @PledgeEmailId, @MobileNo, null, getdate(), @StateId, @PLgDistrictCode)
	

    SELECT M.[MsmeId]
      ,M.[ZedId]
      ,M.[StateId]
      ,M.[StateName]
      ,M.[DistrictId]
      ,M.[DistrictName]
      ,M.[OwnerName]
      ,M.[EnterpriseName]
      ,M.[OrganisationType]
      ,M.[OrganisationTypeName]
      ,M.[EnterpriseType]
      ,M.[EnterpriseTypee]
      ,M.[MobileNo]
      ,M.[EmailId]
      ,M.[ApplicationId]
      ,[UamNumber]
      ,[PFlat]
      ,[PBuilding]
      ,[PRoad]
      ,[PArea]
      ,[PCity]
      ,[PAddress]
      ,[PPin]
      ,[PStateId]
      ,[PStateName]
      ,[PLgDistrictCode]
      ,[PDistrictName]
      ,[PPlantDetailId]
      ,[Activity]
      ,[TwoDigitActivity]
      ,[FourDigitActivity]
      ,[FiveDigitActivity]
      ,[ActivityDetailId]
      ,[PledgeEmailId]
      ,[IsBronzePaymentDone]
      ,[IsSilverPaymentDone]
      ,[IsGoldPaymentDone]
      ,[IsCouponUsed]
      ,[PledgeCertificateNo]
      ,[RegistrationType]
      ,[IncorporationDate]
      ,[WhetherProdCommenced], @Password Password, FORMAT(GETDATE(), 'MMMM d, yyyy') DateOfPledge, @CertificateNo CertificateNo, 
	  case when RegistrationType='UAM' THEN B.Address ELSE concat(PAddress,', ',PDistrictName,', ',PStateName,'-',PPin) end as Address,
	  concat(@CurrentUrl,'/Verify/PC/',QrCodeNo) QrCodeNo
	  FROM Msme M
		inner join MsmeBasicInformation B on (M.ZedId=B.ZedId)
	  Where M.MsmeId=@MsmeId

	Insert into MsmeHistory (ZedId,Descrip,CreatedDate,CertificationType,StatusType)
	values (@ZedId,concat('Registered from UDYAM via ',@RegistrationFrom),getdate(),NULL,NULL)


	update msme set PDistrictName=replace(PDistrictName,'(','') where PDistrictName like '%(%' and ZedId=@ZedId
	update msme set PDistrictName=replace(PDistrictName,')','') where PDistrictName like '%)%' and ZedId=@ZedId

END
