/****** Object:  StoredProcedure [dbo].[SP_MSME_ZERO_PAYMENT_DETAILS]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_MSME_ZERO_PAYMENT_DETAILS] --'<redacted>', '<redacted>'
(
	@ZedId	varchar(50)	= NULL,
	@Certification	varchar(50)	= NULL,
	@UseCoupon	varchar(100)	= NULL,
	@UnitGstin	varchar(50)	= NULL,
	@Gstin	varchar(100)	= NULL,
	@TdsDeductible	varchar(200)	= NULL,
	@Tds	varchar(250)	= NULL,
	@Tan	varchar(50)	= NULL,
	@PaymentRefId	varchar(50)	= NULL
)
AS
BEGIN

	DECLARE @StateCode varchar(50) = NULL,
	@UdyamNo varchar(50) = NULL
	select @StateCode=StateCode from ZED_CONSULTANT.dbo.Districts where DistrictCode in (select PLgDistrictCode from ZED_CONSULTANT.dbo.Msme where ZedId=@ZedId)
	

	DECLARE @NcCount int = NULL
	SELECT @NcCount=isnull(max(NcCount),0)+1 FROM ZED_CONSULTANT.dbo.MsmeCertifications where ZedId=@ZedId and Certification= @Certification
	
		declare @CertificationTblId int = NULL

		declare @CertificationLevel varchar(100) = NULL
	
		declare @Agency varchar(100) = NULL

		select @Agency=CertificationBodyUserId from ZED_CONSULTANT.dbo.MsmeCertifications where zedid=@ZedId and CertificationStatus=100 and Certification=@Certification and @NcCount>1 order by id desc

		IF NOT EXISTS (select * from ZED_CONSULTANT.dbo.Users where UserId=@Agency and IsActive=1 and RoleId=2)
		BEGIN
		set @Agency=NULL
		END


	IF @Certification = 'Bronze'
		UPDATE Msme SET IsBronzePaymentDone=1 WHERE ZEDId=@ZedId
	ELSE IF @Certification = 'Silver'
		UPDATE Msme SET IsSilverPaymentDone=1 WHERE ZEDId=@ZedId
	ELSE IF @Certification = 'Gold'
		UPDATE Msme SET IsGoldPaymentDone=1 WHERE ZEDId=@ZedId

	
	IF @UseCoupon = 'Yes'
		UPDATE Msme SET IsCouponUsed = 1 WHERE ZEDId=@ZedId


			DECLARE @NewInvoiceNumber VARCHAR(50);
			EXEC ZEDCS_V2_LIVE.DBO.[SP_GENERATE_NEXT_ZED_INVOICE_NO] 
			@NewTADAInvoiceNo = @NewInvoiceNumber OUTPUT; 

		select @CertificationLevel=LastestCertification,@UdyamNo=UdyogAadharNo from MsmeBasicInformation where ZedId=@ZedId
	
	
	  --IF @UdyamNo='<redacted>' AND (@NcCount=1 OR EXISTS (SELECT 1 FROM ZED_CONSULTANT.dbo.StateHandholdingPaymentDates WHERE ZedId=@ZedId AND CertificationLevel = @Certification and MileStoneNum=1))
	 -- AND NOT EXISTS (SELECT 1 FROM ZED_CONSULTANT.dbo.StateHandholdingPaymentDates WHERE ZedId = @ZedId AND CertificationLevel <> @Certification)
	  IF @StateCode=28 AND (@NcCount=1 OR EXISTS (SELECT 1 FROM ZED_CONSULTANT.dbo.StateHandholdingPaymentDates WHERE ZedId=@ZedId AND CertificationLevel = @Certification and MileStoneNum=1))
		AND NOT EXISTS (SELECT 1 FROM ZED_CONSULTANT.dbo.StateHandholdingPaymentDates WHERE ZedId = @ZedId AND CertificationLevel <> @Certification)
	
	  BEGIN

	INSERT INTO MsmePaymentInfo ([ZedId], [EnterpriseTypee], [Certification], [UseCoupon], [UnitGstin], [GstinNumber], [TdsDeductible], [Tds], [TanNumber], 
		[PaymentRefId], [AssessmentFee], [Gst], [Total], [Coupon], [AssessmentFeeAfterCoupon], [GstAfterCoupon], [TotalAfterCoupon], [SubsidyPer], 
		[SubsidyAmount], [GstAfterSubsidy], [ApplicantContributionAfterSubsidy], [Tds15], [Tds75], [NetPaybleTds15], [NetPaybleTds75], [SpecialCategory], [SubsidyPercentage],
		MileStoneNum, TaDaInvoiceNo,StateContributionAfterSubsidy,StateSubsidyPercentage
	)
	SELECT @ZedId, [EnterpriseTypee], @Certification, @UseCoupon, @UnitGstin, @Gstin, @TdsDeductible, @Tds, @Tan, 
		@PaymentRefId, [AssessmentFee], [Gst], [Total], [Coupon], [AssessmentFeeAfterCoupon], [GstAfterCoupon], [TotalAfterCoupon], [SubsidyPer], 
		[SubsidyAmount], [GstAfterSubsidy], [ApplicantContributionAfterSubsidy], [Tds15], [Tds75], [NetPaybleTds15], [NetPaybleTds75], [SpecialCategory], [SubsidyPercentage],
		@NcCount, @NewInvoiceNumber,StateContributionAfterSubsidy,StateSubsidyPercentage
	FROM StateAssessmentFee 
	WHERE Id=@PaymentRefId

	END

	--IF @StateCode=28 AND @NcCount=1
	 IF @UdyamNo='UDYAM-UP-29-0003915' AND @NcCount=1

	BEGIN
		insert into ZED_CONSULTANT.dbo.StateHandholdingPaymentDates (zedid,PaymentDate,CertificationLevel,MileStoneNum)
		select @ZedId,getdate(),@Certification,@NcCount
	END

	

	Insert into MsmeHistory (ZedId,Descrip,CreatedDate,CertificationType,StatusType)
	values (@ZedId,concat('Payment of Rs. 0 successfully received on ',FORMAT(getdate(), 'MMMM d, yyyy'),' after adjustment of  subsidy/reward as applicable.'),getdate(),@Certification,'ApplicationReceived')

		---blocking the old id here---
					UPDATE ZED_CONSULTANT.dbo.MsmeCertifications set IdDisabled='Yes' where ZedId=@ZedId and Certification= @Certification and CertificationStatus<16

					INSERT INTO ZED_CONSULTANT.dbo.MsmeCertifications (ZedId, Certification, NcCount, NcStatus, CertificationBodyUserId, CertificationLevel)
					SELECT top 1 ZedId,Certification,@NcCount,1, @Agency, @CertificationLevel FROM ZED_CONSULTANT.dbo.MsmePaymentInfo WHERE ZedId=@ZedId and Certification=@Certification order by id desc

					select @CertificationTblId=Id from ZED_CONSULTANT.dbo.MsmeCertifications where ZedId=@ZedId and Certification=@Certification and NcCount=@NcCount


					--INSERTION OF ELEMENTS DATA
					INSERT INTO ZED_CONSULTANT.dbo.MsmeSections (SectionId,ZedId,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType,NcCount, SecCertId)
					SELECT Id,@ZedId,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType,@NcCount,@CertificationTblId FROM ZEDCS_V2_LIVE.DBO.Sections WHERE SectionType=@Certification ORDER BY SectionCode

					INSERT INTO ZED_CONSULTANT.dbo.MsmeRequirements (RequirementId,ZedId,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode,RequirementName,OrderNo,SectionType,NcCount, ReqCertId)
					SELECT Id,@ZedId,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode,RequirementName,OrderNo,SectionType,@NcCount,@CertificationTblId FROM ZEDCS_V2_LIVE.DBO.Requirements WHERE SectionType=@Certification ORDER BY SectionCode, RequirementCode

					INSERT INTO ZED_CONSULTANT.dbo.MsmeOptions (OptionId,ZedId,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType,NcCount,OptCertId)
					SELECT Id,@ZedId,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType,@NcCount,@CertificationTblId FROM ZEDCS_V2_LIVE.DBO.Options WHERE SectionType=@Certification ORDER BY SectionCode, RequirementCode, OptionCode

					INSERT INTO ZED_CONSULTANT.dbo.MsmeSubOptions (SubOptionId,ZedId,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType,NcCount,SubCertId)
					SELECT Id,@ZedId,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType,@NcCount,@CertificationTblId FROM ZEDCS_V2_LIVE.DBO.SubOptions WHERE SectionType=@Certification ORDER BY SectionCode, RequirementCode, OptionCode, SubOptionCode

					INSERT INTO ZED_CONSULTANT.dbo.MsmeEvidences (EvidenceId,ZedId,SectionCode,RequirementCode,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired,EvidenceHelpText,NcCount,EviCertId)
					SELECT Id,@ZedId,SectionCode,RequirementCode,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired,HelpText,@NcCount,@CertificationTblId FROM ZEDCS_V2_LIVE.DBO.Evidences WHERE SectionType=@Certification ORDER BY SectionCode, RequirementCode, EvidenceCode

					UPDATE ZED_CONSULTANT.dbo.MsmeRequirements SET OpenedFlag=1 where ZedId=@ZedId and SectionType=@Certification and NcCount=@NcCount and concat(sectioncode,'_',RequirementCode) not in 
					(SELECT DISTINCT CONCAT(SectionCode,'_',RequirementCode)  from ZED_CONSULTANT.dbo.MsmeEvidences where ZedId=@ZedId and SectionType=@Certification and NcCount=@NcCount)

					UPDATE ZED_CONSULTANT.dbo.MsmePaymentInfo SET MsmePmtCertId=@CertificationTblId where ZedId=@ZedId and Certification=@Certification and MsmePmtCertId is null and MileStoneNum=@NcCount

		
END
GO
/****** Object:  StoredProcedure [dbo].[SP_NEFT_TRANSACTIONS_BY_STATUS]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_NEFT_TRANSACTIONS_BY_STATUS] --0
(
	@Status varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

 --   SELECT M.*, 
	--	B.UdyogAadharNo, B.TotalEmp, B.Gender, B.SocialCategoryName,
	--	P.GstinNumber, P.TanNumber, P.UtrNumber, P.Id TransactionId,P.AmountPaid, P.TransactionStatus, Convert(varchar,P.ApproverDateOfReceiptOfPayment,106) ApproverDateOfReceiptOfPayment, P.ApproverReferenceNo, P.ApproverAmount, P.Comments
	--FROM MsmePaymentInfo P, Msme M, MsmeBasicInformation B
	--WHERE P.PaymentType='<redacted>' AND P.ZedId=M.ZedId AND M.ZedId=B.ZedId AND TransactionStatus=@Status
	--ORDER By CreatedDate
	IF @Status=1
	BEGIN
		--SELECT M.*, 
		--	B.UdyogAadharNo, B.TotalEmp, B.Gender, B.SocialCategoryName,
		--	F.*, F.Id TransactionId
		--FROM  Msme M, MsmeBasicInformation B, FinancialAssistance F
		--WHERE M.ZedId=B.ZedId AND B.ZedId=F.ZedId AND F.VerificationStatus=6
		--ORDER By F.CreatedDate

		SELECT 
    M.*, B.UdyogAadharNo, B.TotalEmp, B.Gender, B.SocialCategoryName, F.*, F.Id AS TransactionId, TUP.TechnologyName, TUP.InvoiceBillDate,
	TUP.NameOfTheManufacturer, TUP.MakeOrModelName,TUP.AgencyOrSupplier, TUP.InvoiceBillDate
	FROM Msme M
INNER JOIN MsmeBasicInformation B 
    ON M.ZedId = B.ZedId
INNER JOIN FinancialAssistance F 
    ON B.ZedId = F.ZedId
INNER JOIN (
    SELECT 
        ZedId,CertificationType,CertId,FinancialAssistanceId,
        STUFF((SELECT ', ' + concat(TechnologyCode,'-',technologyname)
               FROM technologyupgradation 
               WHERE zedid = TU.zedid
               FOR XML PATH('')), 1, 2, '') AS TechnologyName,

		STUFF((SELECT ', ' + CONVERT(VARCHAR, NameOfTheManufaturer)
           FROM technologyupgradation 
           WHERE zedid = TU.zedid
           FOR XML PATH('')), 1, 2, '') AS NameOfTheManufacturer,

		STUFF((SELECT ', ' + CONVERT(VARCHAR, MakeOrModelName)
           FROM technologyupgradation 
           WHERE zedid = TU.zedid
           FOR XML PATH('')), 1, 2, '') AS MakeOrModelName,

		STUFF((SELECT ', ' + CONVERT(VARCHAR, AgencyOrSupplier)
           FROM technologyupgradation 
           WHERE zedid = TU.zedid
           FOR XML PATH('')), 1, 2, '') AS AgencyOrSupplier,

        STUFF((SELECT ', ' + CONVERT(VARCHAR, invoicebilldate, 23)
               FROM technologyupgradation 
               WHERE zedid = TU.zedid
               FOR XML PATH('')), 1, 2, '') AS InvoiceBillDate
        --STUFF((SELECT '<redacted>' + CONVERT(VARCHAR, amountpaid)
        --       FROM technologyupgradation 
        --       WHERE zedid = TU.zedid
        --       FOR XML PATH('')), 1, 2, '') AS AmountPaid,
        --STUFF((SELECT '<redacted>' + CONVERT(VARCHAR, eligibleamount)
        --       FROM technologyupgradation 
        --       WHERE zedid = TU.zedid
        --       FOR XML PATH('')), 1, 2, '') AS EligibleAmount
    FROM technologyupgradation TU
    WHERE IsEligible = 1
    GROUP BY ZedId,CertificationType,CertId,FinancialAssistanceId
) TUP 
    ON (F.ZedId = TUP.ZedId AND F.certificationType=TUP.CertificationType AND F.CertId=TUP.CertId AND F.FinancialAssistanceId=TUP.FinancialAssistanceId)
WHERE F.VerificationStatus = 6
ORDER BY F.CreatedDate

	END

	ELSE
	BEGIN
		-- SELECT M.*, 
		--	B.UdyogAadharNo, B.TotalEmp, B.Gender, B.SocialCategoryName,
		--	F.*, F.Id TransactionId
		--FROM  Msme M, MsmeBasicInformation B, FinancialAssistance F
		--WHERE M.ZedId=B.ZedId AND B.ZedId=F.ZedId AND F.VerificationStatus=4
		--ORDER By F.CreatedDate

		SELECT 
    M.*, B.UdyogAadharNo, B.TotalEmp, B.Gender, B.SocialCategoryName, F.*, F.Id AS TransactionId, TUP.TechnologyName, TUP.InvoiceBillDate,
	TUP.NameOfTheManufacturer, TUP.MakeOrModelName,TUP.AgencyOrSupplier, TUP.InvoiceBillDate
	FROM Msme M
INNER JOIN MsmeBasicInformation B 
    ON M.ZedId = B.ZedId
INNER JOIN FinancialAssistance F 
    ON B.ZedId = F.ZedId
INNER JOIN (
    SELECT 
        ZedId,CertificationType,CertId,FinancialAssistanceId,
        STUFF((SELECT ', ' + concat(TechnologyCode,'-',technologyname)
               FROM technologyupgradation 
               WHERE zedid = TU.zedid
               FOR XML PATH('')), 1, 2, '') AS TechnologyName,
		STUFF((SELECT ', ' + CONVERT(VARCHAR, NameOfTheManufaturer)
           FROM technologyupgradation 
           WHERE zedid = TU.zedid
           FOR XML PATH('')), 1, 2, '') AS NameOfTheManufacturer,

		STUFF((SELECT ', ' + CONVERT(VARCHAR, MakeOrModelName)
           FROM technologyupgradation 
           WHERE zedid = TU.zedid
           FOR XML PATH('')), 1, 2, '') AS MakeOrModelName,

		STUFF((SELECT ', ' + CONVERT(VARCHAR, AgencyOrSupplier)
           FROM technologyupgradation 
           WHERE zedid = TU.zedid
           FOR XML PATH('')), 1, 2, '') AS AgencyOrSupplier,
        STUFF((SELECT ', ' + CONVERT(VARCHAR, invoicebilldate, 23)
               FROM technologyupgradation 
               WHERE zedid = TU.zedid
               FOR XML PATH('')), 1, 2, '') AS InvoiceBillDate
        --STUFF((SELECT '<redacted>' + CONVERT(VARCHAR, amountpaid)
        --       FROM technologyupgradation 
        --       WHERE zedid = TU.zedid
        --       FOR XML PATH('')), 1, 2, '') AS AmountPaid,
        --STUFF((SELECT '<redacted>' + CONVERT(VARCHAR, eligibleamount)
        --       FROM technologyupgradation 
        --       WHERE zedid = TU.zedid
        --       FOR XML PATH('')), 1, 2, '') AS EligibleAmount
    FROM technologyupgradation TU
    WHERE IsEligible = 1
    GROUP BY ZedId,CertificationType,CertId,FinancialAssistanceId
) TUP 
    ON (F.ZedId = TUP.ZedId AND F.certificationType=TUP.CertificationType AND F.CertId=TUP.CertId AND F.FinancialAssistanceId=TUP.FinancialAssistanceId)
WHERE F.VerificationStatus = 4
ORDER BY F.CreatedDate

	END

END

GO
/****** Object:  StoredProcedure [dbo].[SP_NEFT_UPDATE_TRANSACTION_STATUS]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
