-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_NEFT_UPDATE_TRANSACTION_STATUS]
(
	@Status varchar(50) = NULL,
	@TransactionId varchar(50) = NULL,
	@ZedId varchar(50) = NULL,
	@DateOfReceiptOfPayment varchar(50) = NULL,
	@ApproverReferenceNo varchar(100) = NULL,
	@ApproverAmount varchar(50) = NULL,
	@Comments varchar(2000) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

    UPDATE FinancialAssistance SET TransactionStatus=@Status, ApproverDateOfReceiptOfPayment=@DateOfReceiptOfPayment, ApproverReferenceNo=@ApproverReferenceNo, 
	ApproverAmount=@ApproverAmount, Comments=@Comments WHERE Id=@TransactionId

	--IF @Status = 1
	--BEGIN
	--	INSERT INTO MsmeCertifications ([ZedId], [Certification])
	--	SELECT ZedId, Certification FROM MsmePaymentInfo WHERE Id=@TransactionId
	--END


	IF @Status=1 
	BEGIN
		
		DECLARE @Certification varchar(50) = NULL
		select @Certification=CertificationType from FinancialAssistance where ZedId=@ZedId and Id=@TransactionId

		update FinancialAssistance set VerificationStatus=6 where ZedId=@ZedId and Id=@TransactionId

		UPDATE ZED_CONSULTANT.DBO.FinancialAssistance SET TechUpgradeStatus=16 where ZedId=@ZedId and Id=@TransactionId


		Insert into MsmeHistory (ZedId,Descrip,CreatedDate,CertificationType,StatusType)
		values (@ZedId,'Payment approved by Neft admin ',getdate(),@Certification,'PaymentApprovedByNeftAdmin')

			--INSERTION OF ELEMENTS DATA
		--INSERT INTO MsmeSections (SectionId,ZedId,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType)
		--SELECT Id,@ZedId,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType FROM Sections WHERE SectionType=@Certification ORDER BY SectionCode

		--INSERT INTO MsmeRequirements (RequirementId,ZedId,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode,RequirementName,OrderNo,SectionType)
		--SELECT Id,@ZedId,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode,RequirementName,OrderNo,SectionType FROM Requirements WHERE SectionType=@Certification ORDER BY SectionCode, RequirementCode

		--INSERT INTO MsmeOptions (OptionId,ZedId,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType)
		--SELECT Id,@ZedId,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType FROM Options WHERE SectionType=@Certification ORDER BY SectionCode, RequirementCode, OptionCode

		--INSERT INTO MsmeSubOptions (SubOptionId,ZedId,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType)
		--SELECT Id,@ZedId,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType FROM SubOptions WHERE SectionType=@Certification ORDER BY SectionCode, RequirementCode, OptionCode, SubOptionCode

		--INSERT INTO MsmeEvidences (EvidenceId,ZedId,SectionCode,RequirementCode,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired,EvidenceHelpText)
		--SELECT Id,@ZedId,SectionCode,RequirementCode,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired, HelpText FROM Evidences WHERE SectionType=@Certification ORDER BY SectionCode, RequirementCode, EvidenceCode


		--UPDATE MsmeRequirements SET OpenedFlag=1 where ZedId=@ZedId and SectionType=@Certification and NcCount=0 and concat(sectioncode,'<redacted>',RequirementCode) not in 
		--(SELECT DISTINCT CONCAT(SectionCode,'<redacted>',RequirementCode)  from MsmeEvidences where ZedId=@ZedId and SectionType=@Certification and NcCount=0)



	END
	ELSE  
	BEGIN
		Insert into MsmeHistory (ZedId,Descrip,CreatedDate,CertificationType,StatusType)
		values (@ZedId,'Payment Rejected by Neft admin',getdate(),@Certification,'PaymentRejectedByNeftAdmin')

		UPDATE ZED_CONSULTANT.DBO.FinancialAssistance SET TechUpgradeStatus=17 where ZedId=@ZedId and Id=@TransactionId
	END


END

GO
/****** Object:  StoredProcedure [dbo].[SP_RA_GET_CERTIFICATE_DETAILS]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_RA_GET_CERTIFICATE_DETAILS]  --'<redacted>','<redacted>'
(
	@ZedId Varchar(100) =NULL,
	@CertificationType Varchar(100) =NULL
)
AS
BEGIN

	DECLARE @CurrentUrl varchar(100) = NULL
	SELECT @CurrentUrl=UrlName from UrlsMasterData
	
	SET NOCOUNT ON;

	SELECT  M.EnterpriseName,SaCertificateNo,FORMAT(CertificationStatusDate, 'MMMM d, yyyy') DateOfCertification,
	case when RegistrationType='UAM' THEN B.Address ELSE concat(PAddress,', ',PDistrictName,', ',PStateName,'-',PPin) end as Address ,	
	B.UdyogAadharNo,M.MobileNo,M.EmailId,M.EnterpriseName EstablishmentName, TwoDigitActivity NicCode, case when Certification='Bronze' then '' else U.UserName end as AssessmentAgency,
	CASE WHEN Certification='Silver' then concat(@CurrentUrl,'/Verify/SC/',QrCodeSeqNo) else concat(@CurrentUrl,'/Verify/GC/',QrCodeSeqNo) end as QrCodeSeqNo,
	PUnitName, NcCount
	from Msme M inner join MsmeCertifications C on (M.ZedId=C.ZedId)
	inner join MsmeBasicInformation B on (M.ZedId=B.ZedId)
	left join Users U on (U.UserId=C.CertificationBodyUserId)
	where Certification=@CertificationType and C.ZedId=@ZedId
	order by C.id desc

	--select * from MsmeBasicInformation

END


GO
/****** Object:  StoredProcedure [dbo].[SP_REPORT_GET_DETAILS]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
-- [SP_REPORT_GET_DETAILS] '<redacted>', '<redacted>'
CREATE PROCEDURE [dbo].[SP_REPORT_GET_DETAILS]
(
	@Certification Varchar(50) = NULL,
	@ZedId Varchar(100) =NULL,
	@UserId varchar(50) = NULL,
	@NcCount int = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	DECLARE @CurrentUrl varchar(100) = NULL
	SELECT @CurrentUrl=UrlName from UrlsMasterData

	--DECLARE @NcCount int = NULL
	IF @NcCount IS NULL 
	BEGIN
		SELECT @NcCount=isnull(max(NcCount),0) FROM MsmeCertifications where ZedId=@ZedId and Certification= @Certification
	END
	
	IF @Certification='Bronze'
	BEGIN
		SELECT C.ZedId, C.Certification, M.EnterpriseName,M.PUnitName, UdyogAadharNo, M.EnterpriseTypee, CONCAT(PAddress,' ', PDistrictName,' ',PStateName,'-', PPin) PlantAddress, PDistrictName, PStateName, TwoDigitActivity,
			C.DesktopAssessorId, U.UserName DesktopAssessorName, C.AuditsConducted, C.DomesticCustomers, C.InternationalCustomers, C.RawMaterialImported, C.OutsourcedProcesses, REPLACE(C.EnergySources,',',', ') EnergySources,
			C.AssessorRemarks, FORMAT(CertificationStatusDate, 'MMMM d, yyyy') AssessmentDate,
			C.IsSaVerified, C.SaAssessorRemarks, FORMAT(CertificationStatusDate, 'MMMM d, yyyy') AssessmentDate, Certification,CertificationStatus,
			FORMAT(BdsFromDate, 'MMMM d, yyyy') BdsFromDate,FORMAT(BdsToDate, 'MMMM d, yyyy') BdsToDate,
			FORMAT(HapFromDate, 'MMMM d, yyyy') HapFromDate,FORMAT(HapToDate, 'MMMM d, yyyy') HapToDate,
			LastestCertification
		FROM MsmeCertifications C, Msme M, MsmeBasicInformation B, Users U
		WHERE C.ZedId=M.ZedId 
			AND M.ZedId=B.ZedId 
			AND C.DesktopAssessorId=U.UserId
			AND Certification=@Certification
			AND C.ZedId=@ZedId
	END
	ELSE
	BEGIN
	SELECT C.ZedId, C.Certification, M.EnterpriseName,M.PUnitName, UdyogAadharNo, M.EnterpriseTypee, CONCAT(PAddress,' ', PDistrictName,' ',PStateName,'-', PPin) PlantAddress, PDistrictName, PStateName, TwoDigitActivity,
			C.DesktopAssessorId, U.UserName DesktopAssessorName, C.AuditsConducted, C.SaDomesticCustomers DomesticCustomers, C.SaInternationalCustomers InternationalCustomers, C.RawMaterialImported, C.SaOutsourcedProcesses OutsourcedProcesses, REPLACE(C.SaEnergySources,',',', ') EnergySources,
			C.AssessorRemarks, FORMAT(CertificationStatusDate, 'MMMM d, yyyy') AssessmentDate,
			C.IsSaVerified, C.SaAssessorRemarks, FORMAT(CertificationStatusDate, 'MMMM d, yyyy') AssessmentDate, Certification,CertificationStatus,
			FORMAT(BdsFromDate, 'MMMM d, yyyy') BdsFromDate,FORMAT(BdsToDate, 'MMMM d, yyyy') BdsToDate,
			FORMAT(HapFromDate, 'MMMM d, yyyy') HapFromDate,FORMAT(HapToDate, 'MMMM d, yyyy') HapToDate,
			LastestCertification,NcCount

		FROM MsmeCertifications C, Msme M, MsmeBasicInformation B, Users U
		WHERE C.ZedId=M.ZedId 
			AND M.ZedId=B.ZedId 
			AND C.SiteAssessorId=U.UserId
			AND Certification=@Certification
			AND C.ZedId=@ZedId
			AND C.NcCount=@NcCount
	END
	
	IF @Certification='Bronze'
	BEGIN
		SELECT * FROM MsmeProducts WHERE Certification=@Certification AND ZedId=@ZedId	AND NcCount=1
		SELECT * FROM MsmeRawMaterials WHERE Certification=@Certification AND ZedId=@ZedId
	END
	ELSE IF @Certification='Silver'
	BEGIN
		SELECT Id,ZedId,Certification,ProductName,Exported,IsVerified,AssessorRemarks,UpdatedDate,NcCount,MsmeRemarks,SaProductPhoto ProductPhoto,SaProductDescriptionPhoto ProductDescriptionPhoto
		,IsSaVerified,SaAssessorRemarks,SaUpdatedDate,ProductOpenedTime,ProductDescOpenedTime,ProductParentId,PreviousAssessorRemarks,PreviousAssessorUpdatedDate,MsmeUpdatedDate FROM MsmeProducts WHERE Certification=@Certification AND ZedId=@ZedId	AND NcCount=1
		SELECT * FROM MsmeRawMaterials WHERE Certification=@Certification AND ZedId=@ZedId AND NcCount=@NcCount
	END
	ELSE
	BEGIN
		SELECT Id,ZedId,Certification,ProductName,Exported,IsVerified,AssessorRemarks,UpdatedDate,NcCount,MsmeRemarks, ProductPhoto, ProductDescriptionPhoto
		,'' IsSaVerified,'' SaAssessorRemarks,'' SaUpdatedDate,ProductOpenedTime,ProductDescOpenedTime,'' ProductParentId,'' PreviousAssessorRemarks,'' PreviousAssessorUpdatedDate,MsmeUpdatedDate FROM SaProducts WHERE Certification=@Certification AND ZedId=@ZedId	AND NcCount=1
		SELECT * FROM MsmeRawMaterials WHERE Certification=@Certification AND ZedId=@ZedId AND NcCount=@NcCount
	END

	IF @Certification='Bronze'
	BEGIN
   		SELECT Id,ZedId,SectionType Certification,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType,'' OfiComments,'' IsAssessmentExcempted  FROM MsmeSections S 	WHERE SectionType=@Certification AND ZedId=@ZedId AND NcCount=1 ORDER BY cast(SectionCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode, RequirementId,RequirementName,OrderNo,SectionType,Conformance,AssessorRemarks,'MsmeRequirements' TableName,OpenedFlag, SaConformance,SaAssessorRemarks FROM MsmeRequirements WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=1 ORDER BY cast(SectionCode as int), cast(RequirementCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType FROM MsmeOptions WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=1 ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(OptionCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType FROM MsmeSubOptions WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=1 ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(OptionCode as int), cast(SubOptionCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,RequirementCode,EvidenceId,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired, IsVerified, SourceOfValidation, AssessorRemarks, 'MsmeEvidences' TableName, DocumentOpenedTime,'.pdf' as Pdf FROM MsmeEvidences WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=1 ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(EvidenceCode as int)
	END
	ELSE
	BEGIN
   		SELECT Id,ZedId,SectionType Certification,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType,OfiComments,IsAssessmentExcempted FROM MsmeSections S 	WHERE SectionType=@Certification AND ZedId=@ZedId AND NcCount=@NcCount ORDER BY cast(SectionCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode, RequirementId,RequirementName,OrderNo,SectionType,SaConformance Conformance,SaAssessorRemarks AssessorRemarks,'MsmeRequirements' TableName,OpenedFlag,  SaConformance,'' SaAssessorRemarks,
		EstimatedTimeInDays,	Intervention,	BaselineDate,	InterventionDate,	HActionPlanDate,	BaselineRemarks,	InterventionRemarks,	HActionPlanRemarks,
		IntConformance, IsProposedActivityCompleted, ProgressReviewRemarks, ProgressReviewDate, IsProposedActivityCompleted2, ProgressReviewRemarks2, ProgressReviewDate2
		FROM MsmeRequirements WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=1 ORDER BY cast(SectionCode as int), cast(RequirementCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType FROM MsmeOptions WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=@NcCount ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(OptionCode as int)
		SELECT Id,ZedId,SectionType Certification,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType FROM MsmeSubOptions WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=@NcCount ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(OptionCode as int), cast(SubOptionCode as int)
		--SELECT Id,ZedId,SectionType Certification,SectionCode,RequirementCode,EvidenceId,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired, IsVerified, SourceOfValidation, AssessorRemarks, '<redacted>' TableName, DocumentOpenedTime,'<redacted>' as Pdf FROM MsmeEvidences WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=1 ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(EvidenceCode as int)
		SELECT 
			R.Id ,	R.ZedId,	Certification,	M.SectionCode,M.RequirementCode, EvidenceId, '' EvidenceCode,Name EvidenceName,Certification SectionType,'' EvidenceType,'' ValidationRequired, IsVerified, '' SourceOfValidation,R.AssessorRemarks,'SaPhotos' TableName,'' DocumentOpenedTime,PhotoExtension as Pdf,	PhotoType,	R.RequirementId,  	
			Photo,CreatedDate	
			,Photo src,FORMAT(CreatedDate, 'MMMM dd, yyyy HH:mm tt') GeneratedTime,PhotoId
			FROM SaPhotos R inner join MsmeRequirements M on (R.RequirementId=M.RequirementId and r.NcCount=m.NcCount and r.ZedId=m.ZedId and r.Certification=m.SectionType) WHERE  (PhotoType in ('Evidence Photo')) and Certification=@Certification AND R.ZedId=@ZedId	AND R.NcCount=@NcCount
			union
			SELECT 
			R.Id,	R.ZedId,	R.Certification, M.SectionCode, M.RequirementCode,null EvidenceId,'' EvidenceCode,R.Name EvidenceName,Certification SectionType,'' EvidenceType,'' ValidationRequired,null IsVerified,'' SourceOfValidation,null AssessorRemarks,'SaPhotos' TableName,'' DocumentOpenedTime,null Pdf,R.PhotoType,M.RequirementId,		
			case when R.PhotoType='Evidences' then isnull(R.Photo,CONCAT(@CurrentUrl,'/mobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/Evidences/',R.PhotoId,'.jpg')) else
			isnull(R.Photo,CONCAT(@CurrentUrl,'/mobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/SiteTour/',R.PhotoId,'.jpg')) end as Photo,R.CreatedDate,	
			R.Photo src,FORMAT(CreatedDate, 'MMMM dd, yyyy HH:mm tt') GeneratedTime,PhotoId
			FROM  SaRequirementPhotos R	inner join MsmeRequirements M on (R.RequirementId=M.Id)
			WHERE  R.Certification=@Certification AND R.ZedId=@ZedId	AND R.NcCount=@NcCount and (R.PhotoType='Evidence Photo')
	END
		
	IF @Certification='Bronze'
	BEGIN
		SELECT * FROM MsmePhotos WHERE Certification=@Certification AND ZedId=@ZedId AND PhotoType='SiteExteriorPhotos' AND NcCount=1
	END
	ELSE
	BEGIN
		SELECT Id,ZedId,Certification,PhotoId,Name,TimeStamp,Latitude,Longitude,PhotoType,EvidenceId,IsVerified,AssessorId,AssessorRemarks,
		UpdatedDate,NcCount,PhotoExtension,RequirementId,CONCAT(@CurrentUrl,'/consultancymobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/',Name,'_',PhotoId,'.jpg') Photo,
		CreatedDate,ProductId,DocumentOpenedTime,MsmeRemarks  FROM SaPhotos 
		WHERE Certification=@Certification AND ZedId=@ZedId AND (name in ('Site Exterior Photo','Site Interior Photo') or (PhotoType='SiteExteriorPhotos')) AND NcCount=@NcCount
	END
	-- Lat Longs
	SELECT TOP 1 Latitude, Longitude FROM SaPhotos WHERE Certification=@Certification AND ZedId=@ZedId AND PhotoType='Open Meeting' AND NcCount=@NcCount

	SELECT *,'Meetings' TableName FROM Meetings WHERE MeetingType='Open Meeting' AND ZedId=@ZedId AND CertificationType=@Certification AND NcCount=@NcCount
	SELECT *,concat(ROW_NUMBER() over(partition by zedid order by id),'. ',name) as ParticipantName,'MeetingParticipants' TableName FROM MeetingParticipants WHERE MeetingType='Open Meeting' AND ZedId=@ZedId AND CertificationType=@Certification AND NcCount=@NcCount
	SELECT *,'Meetings' TableName FROM Meetings WHERE MeetingType='Close Meeting' AND ZedId=@ZedId AND CertificationType=@Certification AND NcCount=@NcCount
	SELECT *,concat(ROW_NUMBER() over(partition by zedid order by id),'. ',name) as ParticipantName,'MeetingParticipants' TableName FROM MeetingParticipants WHERE MeetingType='Close Meeting' AND ZedId=@ZedId AND CertificationType=@Certification AND NcCount=@NcCount

	SELECT Id,ZedId,Certification,PhotoId,TimeStamp,Latitude,Longitude,PhotoType,EvidenceId,IsVerified,AssessorId,AssessorRemarks,UpdatedDate,NcCount,PhotoExtension,RequirementId,Photo,CreatedDate,'SaPhotos' TableName,CONCAT(@CurrentUrl,'/consultancymobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/Opening Meeting Photo_',PhotoId,'.jpg') as PhotoPath, name  FROM SaPhotos WHERE Name in ('Opening Meeting Photo') AND ZedId=@ZedId AND Certification=@Certification AND NcCount=@NcCount	
	SELECT Id,ZedId,Certification,PhotoId,TimeStamp,Latitude,Longitude,PhotoType,EvidenceId,IsVerified,AssessorId,AssessorRemarks,UpdatedDate,NcCount,PhotoExtension,RequirementId,Photo,CreatedDate,'SaPhotos' TableName,CONCAT(@CurrentUrl,'/consultancymobileapi/','SaPhotos/',@ZedId,'/',@Certification,'/Closing Meeting Photo_',PhotoId,'.jpg') as PhotoPath, name  FROM SaPhotos WHERE Name in ('Closing Meeting Photo') AND ZedId=@ZedId AND Certification=@Certification AND NcCount=@NcCount	 

	SELECT * FROM MsmeRequirementBullets WHERE CertificationType=@Certification AND ZedId=@ZedId  AND NcCount=@NcCount order by Id

END


GO
/****** Object:  StoredProcedure [dbo].[SP_REPORT_GET_DETAILS_NC]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_REPORT_GET_DETAILS_NC] --'<redacted>', '<redacted>'
(
	@Certification Varchar(50) = NULL,
	@ZedId Varchar(100) =NULL,
	@NcCount int = NULL,
	@UserId varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;
		
	SELECT * FROM MsmeProducts WHERE Certification=@Certification AND ZedId=@ZedId	AND NcCount=@NcCount

   	SELECT Id,ZedId,SectionType Certification,SectionCode,SectionName,OrderNo,iButton,SectionImage,SectionType FROM MsmeSections S 	WHERE SectionType=@Certification AND ZedId=@ZedId AND NcCount=@NcCount ORDER BY cast(SectionCode as int)

	SELECT Id,ZedId,SectionType Certification,SectionCode,SectionName,QuestionCode,QuestionName,RequirementCode, RequirementId,RequirementName,OrderNo,SectionType,Conformance,AssessorRemarks,'MsmeRequirements' TableName,OpenedFlag, SaConformance,SaAssessorRemarks FROM MsmeRequirements WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=@NcCount ORDER BY cast(SectionCode as int), cast(RequirementCode as int)
	
	SELECT Id,ZedId,SectionType Certification,SectionCode,QuestionCode,OptionCode,OptionName,OptionImage,RequirementCode,SectionType FROM MsmeOptions WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=@NcCount ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(OptionCode as int)
	
	SELECT Id,ZedId,SectionType Certification,SectionCode,QuestionCode,OptionCode,SubOptionCode,SubOptionName,RequirementCode,SubOptionImage,SectionType FROM MsmeSubOptions WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=@NcCount ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(OptionCode as int), cast(SubOptionCode as int)
	
	SELECT Id,ZedId,SectionType Certification,SectionCode,RequirementCode,EvidenceId,EvidenceCode,EvidenceName,SectionType,EvidenceType,ValidationRequired, IsVerified, SourceOfValidation, AssessorRemarks, 'MsmeEvidences' TableName, DocumentOpenedTime,'.pdf' as Pdf FROM MsmeEvidences WHERE SectionType=@Certification AND ZedId=@ZedId  AND NcCount=@NcCount ORDER BY cast(SectionCode as int), cast(RequirementCode as int), cast(EvidenceCode as int)

		
	SELECT *,'.jpg' as Jpg FROM MsmePhotos WHERE Certification=@Certification AND ZedId=@ZedId AND PhotoType='SiteExteriorPhotos' AND NcCount=@NcCount
END


GO
/****** Object:  StoredProcedure [dbo].[SP_REPORT_GET_TECHNOLOGY_UPGRADATION_DETAILS]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
-- [SP_REPORT_GET_TECHNOLOGY_UPGRADATION_DETAILS] '<redacted>', '<redacted>'
CREATE PROCEDURE [dbo].[SP_REPORT_GET_TECHNOLOGY_UPGRADATION_DETAILS]
(
	@Certification Varchar(50) = NULL,
	@ZedId Varchar(100) =NULL,
	@UserId varchar(50) = NULL,
	@NcCount int = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	DECLARE @CurrentUrl varchar(100) = NULL
	SELECT @CurrentUrl=UrlName from UrlsMasterData

	Declare @DateOfVerification datetime = NULL
	SELECT top 1 @DateOfVerification=CreatedDate FROM FinancialAssistanceScreenshotPhotos WHERE ZedId=@ZedId and Certification= @Certification order by id desc


		SELECT @NcCount=isnull(max(NcCount),0) FROM MsmeCertifications where ZedId=@ZedId and Certification= @Certification


	SELECT C.ZedId, C.CertificationType, M.EnterpriseName,M.PUnitName, UdyogAadharNo, M.EnterpriseTypee, CONCAT(PAddress,' ', PDistrictName,' ',PStateName,'-', PPin) PlantAddress, PDistrictName, PStateName, TwoDigitActivity,
		   CategoryOfCertificate,AccountNo,IfscCode,BranchAddress,C.CreatedDate,SubmittedFrom,BankName,EligibleAmount,
		   CertificationType,VerificationStatus,CertificationBodyUserId,FinancialAssessorId,C.ReasonForRejection,IsApproved,
		   FinancialAssistanceId,ReasonForRejectionAgency,TransactionStatus,ApproverDateOfReceiptOfPayment,ApproverReferenceNo,
		   ApproverAmount,Comments,TechUpgradeStatus,CertId,TotalPaidAfterQc,FinancialStatusDate,ApproveOrRejectDate,
		   FORMAT(@DateOfVerification, 'MMMM d, yyyy') DateOfVerification,
		   U.UserName as [MSMEDFOOffice],UU.UserName as [ApproverOfficialName]

		FROM Msme M inner join MsmeBasicInformation B on (M.ZedId=B.ZedId)
		INNER JOIN FinancialAssistance C ON (M.ZedId=C.ZedId)
		INNER JOIN Users U on (C.CertificationBodyUserid=U.UserId)
		INNER JOIN Users UU on (C.FinancialAssessorId=UU.UserId)
		WHERE CertificationType=@Certification AND C.ZedId=@ZedId and TechUpgradeStatus!=7

		----SITE EXTERIOR AND INTERIOR PICTURES------
	SELECT M.*,concat(@CurrentUrl,'/consultancy/Uploads/TechnologyUpgradation/',@ZedId,'/',CertificationType,'/OpenMeeting/',Name,'_',PhotoId,'.jpg') as src 
	FROM FinancialAssistance F inner join TuMeetingPhotos M on (F.FinancialAssistanceId=M.FinancialAssistanceId) 
	WHERE M.ZedId=@ZedId and F.CertificationType=@Certification and TechUpgradeStatus!=7
	and Name in ('Site Exterior Photo','Site Interior Photo')
	order by M.Id


	-----LIST OF RECOMMENDED TECHNOLOGIES BY CONSULTANT--------------
	select TechnologyCode,TechnologyName from FinancialAssistance F 
	inner join RecommandedTechnologies R on (F.ZedId=R.ZedId and F.CertificationType=R.Certification and F.CertId=R.CertId) 
	where F.ZedId=@ZedId and Certification=@Certification and TechUpgradeStatus!=7
	order by cast(TechnologyCode as int)


		-----LIST OF PURCHASED TECHNOLOGIES BY MSME--------------
		SELECT R.*, row_number() over(partition by R.Zedid,R.CertificationType,R.FinancialAssistanceId order by TechnologyCode) as techCount FROM FinancialAssistance F 
		Inner join TechnologyUpgradation R on (F.ZedId=R.ZedId and F.CertificationType=R.CertificationType and F.CertId=R.CertId AND F.FinancialAssistanceId=R.FinancialAssistanceId) 
		WHERE F.ZedId=@ZedId AND F.CertificationType=@Certification and IsEligible=1 and TechUpgradeStatus!=7 order by cast(TechnologyCode as int)

			----OPENING MEETING PICTURES------
	SELECT M.* FROM FinancialAssistance F inner join TuMeetings M on (F.FinancialAssistanceId=M.FinancialAssistanceId) WHERE M.ZedId=@ZedId order by M.Id
	SELECT M.Id,
		M.RefId,
		M.ZedId,
		M.CertificationType,
		M.Name,
		CASE WHEN M.Designation='Lead Consultant' THEN 'MSME-DFO Officer' ELSE M.Designation end  Designation,
		M.MeetingType,
		M.FinancialAssistanceId,
		M.CertId FROM FinancialAssistance F inner join TuMeetingParticipants M on (F.FinancialAssistanceId=M.FinancialAssistanceId)  WHERE M.ZedId=@ZedId order by M.Id

	SELECT M.*,concat(@CurrentUrl,'/consultancy/Uploads/TechnologyUpgradation/',@ZedId,'/',CertificationType,'/OpenMeeting/',Name,'_',PhotoId,'.jpg') as src 
	FROM FinancialAssistance F inner join TuMeetingPhotos M on (F.FinancialAssistanceId=M.FinancialAssistanceId) 
	WHERE M.ZedId=@ZedId and F.CertificationType=@Certification and TechUpgradeStatus!=7
	and Name in ('Opening Meeting Photo')
	order by M.Id

	select T.ZedId,T.TechnologyCode,T.TechnologyName,P.PhotoType,S.FileName,P.AssessorRemarks, S.CreatedDate,techCount,
	concat(@CurrentUrl,'/consultancy/Uploads/TechnologyUpgradation/',@ZedId,'/',P.CertificationType,'/Screenshots/',FileName) as src
	from FinancialAssistance F 
	inner join 
	(select *,row_number() over(partition by Zedid,CertificationType,FinancialAssistanceId order by TechnologyCode) as techCount from TechnologyUpgradation where ZedId=@Zedid and CertificationType=@Certification and IsEligible=1) T 
	on (F.ZedId=T.ZedId and F.certificationType=F.CertificationType and F.CertId=T.CertId)
	inner join FinancialAssistancePhotos P ON (P.FinancialAssistanceId=F.FinancialAssistanceId AND P.ZedId=F.ZedId AND P.CertificationType=F.CertificationType AND P.TechnologyCode=T.TechnologyCode)
	inner join FinancialAssistanceScreenshotPhotos S on (P.Id=S.PhotoId)
	WHERE IsEligible=1 and P.PhotoType in ('Purchased Technology','Copy of Invoice') AND P.ZedId=@ZedId and P.CertificationType=@Certification and TechUpgradeStatus!=7
	order by cast(T.TechnologyCode as int)
	
END


GO
