/****** Object:  StoredProcedure [dbo].[SP_RESET_TECHNOLOGY_UPGRADATION_ID]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_RESET_TECHNOLOGY_UPGRADATION_ID] -- '<redacted>','<redacted>'
(
    @ZedId VARCHAR(100) =NULL,
    @Certification VARCHAR(100)

)
	
AS
BEGIN
    SET NOCOUNT ON;
	BEGIN TRANSACTION

    DECLARE @DeletedZedId  VARCHAR(100);
    SET @DeletedZedId  = CONCAT(@ZedId, '_DEL');

	UPDATE ZED_CONSULTANT.dbo.FinancialAssistance SET ZedId = @DeletedZedId  WHERE ZedId = @ZedId and  CertificationType = @Certification;
	UPDATE ZED_CONSULTANT.dbo.RecommandedTechnologies SET ZedId = @DeletedZedId  WHERE ZedId = @ZedId AND Certification = @Certification;
	UPDATE ZED_CONSULTANT.dbo.technologyupgradation SET ZedId = @DeletedZedId  WHERE ZedId = @ZedId AND CertificationType = @Certification;
	UPDATE ZED_CONSULTANT.dbo.FinancialAssistancephotos SET ZedId = @DeletedZedId  WHERE ZedId = @ZedId and  CertificationType = @Certification;
	UPDATE ZED_CONSULTANT.dbo.financialassistancescreenshotphotos SET ZedId = @DeletedZedId  WHERE ZedId = @ZedId AND Certification = @Certification;
	UPDATE ZED_CONSULTANT.dbo.tumeetings SET ZedId = @DeletedZedId  WHERE ZedId = @ZedId AND CertificationType = @Certification;
	UPDATE ZED_CONSULTANT.dbo.tumeetingparticipants SET ZedId = @DeletedZedId  WHERE ZedId = @ZedId AND CertificationType = @Certification;
	UPDATE ZED_CONSULTANT.dbo.ConsultantDailyAttendance SET ZedId = @DeletedZedId  WHERE ZedId = @ZedId AND Certification = @Certification and MileStoneNo is null;
	UPDATE ZED_CONSULTANT.dbo.TuMeetingPhotos SET ZedId = @DeletedZedId  WHERE ZedId = @ZedId AND Certification = @Certification;


	UPDATE ZED_CONSULTANT.dbo.msmehistory set  zedid = @DeletedZedId where  ZedId = @ZedId and CertificationType = @Certification and nccount = 3 
	and statustype in ('TechnologiesRecommended','ApplicationOfTUDoneByMSME','AgencyAutoAlloted','ConsultantforTUAlloted',
    'ConsultantApprovedTU','CORejectedTU','MasterAdminRejectedTU');


	UPDATE ZED_CONSULTANT.dbo.msme SET technologyupgradation = 1 WHERE ZedId = @ZedId;

	--added new update 
	UPDATE ZED_CONSULTANT.dbo.MsmeCertifications  SET TuStatus = 0  where ZedId = @ZedId and ncCount = 3  AND TuStatus = 1;

	print 'Sucessfully reset technologyupgradation.'
	
	COMMIT;
END;
GO
/****** Object:  StoredProcedure [dbo].[SP_RESET_TECHNOLOGY_UPGRADATION_TILL_MSME_SUBMISSION]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_RESET_TECHNOLOGY_UPGRADATION_TILL_MSME_SUBMISSION] -- '<redacted>','<redacted>'
(
    @ZedId VARCHAR(100) =NULL,
    @Certification VARCHAR(100)

)
	
AS
BEGIN
    SET NOCOUNT ON;
	BEGIN TRANSACTION

    DECLARE @DeletedZedId  VARCHAR(100);
    SET @DeletedZedId  = CONCAT(@ZedId, '_DEL');

	UPDATE ZED_CONSULTANT.dbo.FinancialAssistance SET ZedId = @DeletedZedId  WHERE ZedId = @ZedId and  CertificationType = @Certification;
	UPDATE ZED_CONSULTANT.dbo.technologyupgradation SET ZedId = @DeletedZedId  WHERE ZedId = @ZedId AND CertificationType = @Certification;
	UPDATE ZED_CONSULTANT.dbo.FinancialAssistancephotos SET ZedId = @DeletedZedId  WHERE ZedId = @ZedId and  CertificationType = @Certification;
	UPDATE ZED_CONSULTANT.dbo.financialassistancescreenshotphotos SET ZedId = @DeletedZedId  WHERE ZedId = @ZedId AND Certification = @Certification;
	UPDATE ZED_CONSULTANT.dbo.tumeetings SET ZedId = @DeletedZedId  WHERE ZedId = @ZedId AND CertificationType = @Certification;
	UPDATE ZED_CONSULTANT.dbo.tumeetingparticipants SET ZedId = @DeletedZedId  WHERE ZedId = @ZedId AND CertificationType = @Certification;
	UPDATE ZED_CONSULTANT.dbo.ConsultantDailyAttendance SET ZedId = @DeletedZedId  WHERE ZedId = @ZedId AND Certification = @Certification;;
	UPDATE ZED_CONSULTANT.dbo.TuMeetingPhotos SET ZedId = @DeletedZedId  WHERE ZedId = @ZedId AND Certification = @Certification;


	UPDATE ZED_CONSULTANT.dbo.msme SET technologyupgradation = 1 WHERE ZedId = @ZedId;

	--added new update 
	UPDATE ZED_CONSULTANT.dbo.MsmeCertifications  SET TuStatus = 0  where ZedId = @ZedId and ncCount = 3  AND TuStatus = 1;

	print 'MSME uploaded data cleared Sucessfully for technologyupgradation.'
	
	COMMIT;
END;
GO
