CREATE PROCEDURE [dbo].[SP_RESETTING_CERTIFICATION] --'<redacted>','<redacted>'
(
	@ZedId varchar(50) = NULL,
	@CertificationType varchar(50) = NULL
)
AS
BEGIN

	SET NOCOUNT ON;

				update ZED_CONSULTANT.dbo.SaRequirementPhotos set ZedId=concat(ZedId,'_RESET') where ZedId=@ZedId AND certification=@CertificationType
				update ZED_CONSULTANT.dbo.MsmeCertifications set ZedId=concat(ZedId,'_RESET') where ZedId=@ZedId AND certification=@CertificationType
				update ZED_CONSULTANT.dbo.SaRawMaterials set ZedId=concat(ZedId,'_RESET') where ZedId=@ZedId AND certification=@CertificationType
				update ZED_CONSULTANT.dbo.AssessorComments set ZedId=concat(ZedId,'_RESET') where ZedId=@ZedId AND certification=@CertificationType
				update ZED_CONSULTANT.dbo.MsmeLocations set ZedId=concat(ZedId,'_RESET') where ZedId=@ZedId AND certification=@CertificationType
				update ZED_CONSULTANT.dbo.ScreenshotPhotos set ZedId=concat(ZedId,'_RESET') where ZedId=@ZedId AND certification=@CertificationType
				update ZED_CONSULTANT.dbo.MsmeRawMaterials set ZedId=concat(ZedId,'_RESET') where ZedId=@ZedId AND certification=@CertificationType
				update ZED_CONSULTANT.dbo.PaymentGateWayTransactions set ZedId=concat(ZedId,'_RESET') where ZedId=@ZedId AND certification=@CertificationType
				update ZED_CONSULTANT.dbo.MsmePaymentInfo set ZedId=concat(ZedId,'_RESET') where ZedId=@ZedId AND certification=@CertificationType
				update ZED_CONSULTANT.dbo.MsmeSections set ZedId=concat(ZedId,'_RESET') where ZedId=@ZedId AND SectionType=@CertificationType
				update ZED_CONSULTANT.dbo.MsmeRequirements set ZedId=concat(ZedId,'_RESET') where ZedId=@ZedId AND SectionType=@CertificationType
				update ZED_CONSULTANT.dbo.MsmeOptions set ZedId=concat(ZedId,'_RESET') where ZedId=@ZedId AND SectionType=@CertificationType
				update ZED_CONSULTANT.dbo.MsmeSubOptions set ZedId=concat(ZedId,'_RESET') where ZedId=@ZedId AND SectionType=@CertificationType
				update ZED_CONSULTANT.dbo.MsmeEvidences set ZedId=concat(ZedId,'_RESET') where ZedId=@ZedId AND SectionType=@CertificationType
				update ZED_CONSULTANT.dbo.MsmePhotos set ZedId=concat(ZedId,'_RESET') where ZedId=@ZedId AND certification=@CertificationType
				update ZED_CONSULTANT.dbo.MsmeProducts set ZedId=concat(ZedId,'_RESET') where ZedId=@ZedId AND certification=@CertificationType
				update ZED_CONSULTANT.dbo.SaPhotos set ZedId=concat(ZedId,'_RESET') where ZedId=@ZedId AND certification=@CertificationType
				update ZED_CONSULTANT.dbo.SaProducts set ZedId=concat(ZedId,'_RESET') where ZedId=@ZedId AND certification=@CertificationType
				update ZED_CONSULTANT.dbo.MsmeSelfies set ZedId=concat(ZedId,'_RESET') where ZedId=@ZedId AND certification=@CertificationType
				update ZED_CONSULTANT.dbo.MsmeHistory set ZedId=concat(ZedId,'_RESET') where ZedId=@ZedId AND CertificationType=@CertificationType
				update ZED_CONSULTANT.dbo.MeetingParticipants set ZedId=concat(ZedId,'_RESET') where ZedId=@ZedId AND CertificationType=@CertificationType
				update ZED_CONSULTANT.dbo.Meetings set ZedId=concat(ZedId,'_RESET') where ZedId=@ZedId AND CertificationType=@CertificationType
				update ZED_CONSULTANT.dbo.msmerequirementbullets set ZedId=concat(ZedId,'_RESET') where ZedId=@ZedId AND CertificationType=@CertificationType

				IF @CertificationType='Gold'
				BEGIN
				update ZED_CONSULTANT.dbo.msme set IsGoldPaymentDone=null where ZedId=@ZedId 
				END

				IF @CertificationType='Silver'
				BEGIN
				update ZED_CONSULTANT.dbo.msme set IsSilverPaymentDone=null where ZedId=@ZedId 
				END


	

END

