/****** Object:  StoredProcedure [dbo].[SP_SA_APP_CHECK_STATUS]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_SA_APP_CHECK_STATUS] --'<redacted>', '<redacted>', '<redacted>'
(
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL,
	@AssessorId varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	DECLARE @LeadAssessor varchar(50) = NULL,
			@CoAssessor   varchar(50) = NULL,
			@True bit = 1,
			@False bit = 0,
			@NoOfCoAssessors int = 0,
			@NoOfFinalSubmitsByCo int = 0

			DECLARE @NcCount int = NULL
			SELECT @NcCount=isnull(max(NcCount),0) FROM MsmeCertifications where ZedId=@ZedId and Certification= @Certification


			SELECT @LeadAssessor=SiteAssessorId,@CoAssessor=CoAssessorId FROM MsmeCertifications WHERE ZedId=@ZedId and Certification=@Certification and NcCount=@NcCount

			--select @NoOfCoAssessors=count(*) from AllotedCoAssessors WHERE ZedId=@ZedId and Certification=@Certification and NcCount=@NcCount

			select @NoOfFinalSubmitsByCo=count(*) from Meetings WHERE ZedId=@ZedId and CertificationType=@Certification and MeetingType='Final Submit' and NcCount=@NcCount


	SELECT 
		1 SaStatus,
		CASE WHEN 
		(select count(*) from Meetings  where zedid=@ZedId and certificationtype=@Certification and AssessorId=@LeadAssessor and MeetingType='Open Meeting' and NcCount=@NcCount)>0 THEN @True ELSE @False end as OpenMeetingSubmitted, 

		--CASE WHEN
		--(select  count(*) from MsmeRequirements E inner join MsmeSections S on (S.SectionCode=E.SectionCode and S.ZedId=E.ZedId and S.NcCount=E.NcCount and E.NcCount=0)
		--left join SaRequirementPhotos P on (E.Id=P.RequirementId and E.ZedId=P.ZedId and E.NcCount=P.NcCount and E.NcCount=0)
		--where E.zedid=@ZedId and E.sectiontype=@Certification and (IsAssessmentExcempted='<redacted>' OR IsAssessmentExcempted IS NULL) and E.BaselineDate is not null
		--and AssessorId=@LeadAssessor and P.RequirementId is null)=0 THEN @True ELSE @False end as AllParametersSyncedByLead,

		CASE WHEN
		(select count(*) from MsmeSections S inner join MsmeRequirements R on (S.SectionCode=R.SectionCode and S.SectionType=R.SectionType and S.ZedId=R.ZedId and S.NcCount=@NcCount AND R.NcCount=1)
		where S.ZedId=@ZedId and S.SectionType=@Certification and S.NcCount=@NcCount AND
		((@NcCount=1 and BaselineDate is null) OR (@NcCount=2 and ProgressReviewDate is null) OR (@NcCount=3 and ProgressReviewDate2 is null))
		and S.AssessorId=@LeadAssessor)=0 THEN @True ELSE @False end as AllParametersSyncedByLead,

		--CASE WHEN
		--(select  count(*) from MsmeRequirements E inner join MsmeSections S on (S.SectionCode=E.SectionCode and S.ZedId=E.ZedId and S.NcCount=E.NcCount and E.NcCount=0)
		--left join SaRequirementPhotos P on (E.Id=P.RequirementId and E.ZedId=P.ZedId and E.NcCount=P.NcCount and E.NcCount=0) 
		--where E.zedid=@ZedId and E.sectiontype=@Certification and (IsAssessmentExcempted='<redacted>' OR IsAssessmentExcempted IS NULL) and E.SaConformance='<redacted>'
		--and AssessorId=@CoAssessor and P.RequirementId is null)=0 THEN @True ELSE @False end as AllParametersSyncedByCo,

		CASE WHEN
		(select count(*) from MsmeSections S inner join MsmeRequirements R on (S.SectionCode=R.SectionCode and S.SectionType=R.SectionType and S.ZedId=R.ZedId and S.NcCount=@NcCount AND R.NcCount=1)
		where S.ZedId=@ZedId and S.SectionType=@Certification and S.NcCount=@NcCount AND
		((@NcCount=1 and BaselineDate is null) OR (@NcCount=2 and ProgressReviewDate is null) OR (@NcCount=3 and ProgressReviewDate2 is null))
		and S.AssessorId=@CoAssessor)=0 THEN @True ELSE @False end as AllParametersSyncedByCo,

		CASE
		WHEN @CoAssessor IS NULL THEN @True
		--WHEN (select count(*) from Meetings  where zedid=@ZedId and certificationtype=@Certification and AssessorId=@CoAssessor and MeetingType='<redacted>')>0 THEN @True ELSE @False end as FinalSubmissionDone,
		WHEN
		(select count(*) from MsmeSections S 
		inner join AllotedCoAssessors A on (S.AssessorId=A.CoAssessorId and S.NcCount=A.NcCount and S.ZedId=A.ZedId and s.SectionType=a.Certification) 
		left join Meetings M on (M.AssessorId=S.AssessorId and M.ZedId=S.ZedId and M.NcCount=S.NcCount and M.CertificationType=S.SectionType)
		where S.ZedId=@ZedId and S.SectionType=@Certification and M.AssessorId is null AND S.NcCount=@NcCount)=0 THEN @True ELSE @False end as FinalSubmissionDone,

		CASE WHEN
		(select count(*) from Meetings  where zedid=@ZedId and certificationtype=@Certification and NcCount=@NcCount and AssessorId=@LeadAssessor and MeetingType='Close Meeting')>0 THEN @True ELSE @False end as ClosingMeetingSubmitted,

		CASE WHEN
		(SELECT count(*) FROM MsmeCertifications WHERE ZedId=@ZedId and Certification=@Certification and NcCount=@NcCount and SiteAssessorId=@AssessorId)>0 THEN @True ELSE @False end as LeadAssessor



	--select 1 SaStatus, 
	--	1 OpenMeetingSubmitted, 
	--	1 AllParametersSyncedByLead, 
	--	1 AllParametersSyncedByCo,
	--	1 FinalSubmissionDone, 
	--	1 ClosingMeetingSubmitted,
	--	1 LeadAssessor

	--from MsmeCertifications 
	--where ZedId=@ZedId 
	--	and Certification=@Certification
	
END






GO
/****** Object:  StoredProcedure [dbo].[SP_SA_APP_INSERT_CLOSE_MEETING]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_SA_APP_INSERT_CLOSE_MEETING] 
(
	@RefId                    VarChar(50)			= NULL,
	@RegistrationNumber       VarChar(200)			= NULL,
	@AssessorId               VarChar(200)			= NULL,
	@Latitude                 VarChar(200)			= NULL,
	@Longitude                VarChar(200)			= NULL,
	@Comments                 VarChar(5000)			= NULL,
	@ParticipantsList   DynamicParticipants  READONLY
)
AS
BEGIN
	      
	SET NOCOUNT ON;
	
	
	DELETE FROM Meetings where MeetingType='CLOSE' and RegistrationNumber=@RegistrationNumber

	INSERT INTO Meetings(RefId,RegistrationNumber,AssessorId,Latitude,Longitude,Comments,FieldComments,MeetingType)
	values(@RefId,@RegistrationNumber,@AssessorId,@Latitude,@Longitude,@Comments,@Comments,'CLOSE')

	DELETE FROM MeetingParticipants where MeetingType='CLOSE' and RegistrationNumber=@RegistrationNumber

	INSERT INTO MeetingParticipants (RefId,RegistrationNumber,Name,Designation,MeetingType)
	select @RefId,@RegistrationNumber,Name,Designation,'CLOSE' from @ParticipantsList

	Update SelfAssessments set SaStatus=2,SaLastSyncTime=getdate() where RegistrationNumber=@RegistrationNumber 

	
END



GO
