CREATE PROCEDURE [dbo].[SP_SA_APP_INSERT_OPEN_MEETING] 
(
	@RefId                  VarChar(50)			= NULL,
	@ZedId				    VarChar(200)		= NULL,
	@AssessorId             VarChar(200)		= NULL,
	@CertificationType      VarChar(200)		= NULL,
	@PhotoType			    VarChar(200)		= NULL,
	@Latitude               VarChar(200)		= NULL,
	@Longitude              VarChar(200)		= NULL,
	@Comments               VarChar(5000)		= NULL,
	@ParticipantsList		DynamicParticipants READONLY,
	@PhotoList				DynamicPhotoList2	READONLY
)
AS
BEGIN
	      
	SET NOCOUNT ON;

	DECLARE @NcCount int = NULL
	SELECT @NcCount=NcCount FROM MsmeCertifications WHERE ZedId=@ZedId and Certification=@CertificationType and  SiteAssessorId is not null and SaCertificateNo is null

	IF @PhotoType='Open Meeting'
	BEGIN
		
		INSERT INTO Meetings(RefId,ZedId,AssessorId,Latitude,Longitude,Comments,FieldComments,MeetingType,CertificationType, NcCount)
		values(@RefId,@ZedId,@AssessorId,@Latitude,@Longitude,@Comments,@Comments,@PhotoType,@CertificationType, @NcCount)

		INSERT INTO MeetingParticipants (RefId,ZedId,Name,Designation,MeetingType,CertificationType, NcCount)
		select @RefId,@ZedId,Name,Designation,@PhotoType,@CertificationType, @NcCount from @ParticipantsList 

		INSERT INTO SaPhotos (ZedId,AssessorId,  Certification, PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoExtension, NcCount)
		SELECT @ZedId, @AssessorId,  @CertificationType, @PhotoType, PhotoId, Name, TimeStamp, Latitude, Longitude, PhotoType,@NcCount FROM @PhotoList

		update MsmeCertifications set IsSaVerified='Yes' where ZedId=@ZedId and Certification=@CertificationType and NcCount=@NcCount

		insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType)
		values (@ZedId,concat('Open Meeting Done by ',@AssessorId, 'for',  @CertificationType),getdate(),@CertificationType,NULL)

		update MeetingParticipants set Designation=replace(Designation,'Assessor','Consultant') where Designation like '%Assessor%'

	END

	IF @PhotoType='Final Submit'
	BEGIN
		
		INSERT INTO Meetings(RefId,ZedId,AssessorId,Latitude,Longitude,Comments,FieldComments,MeetingType,CertificationType,NcCount)
		values(@RefId,@ZedId,@AssessorId,@Latitude,@Longitude,@Comments,@Comments,@PhotoType,@CertificationType,@NcCount)

