-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_SA_GET_CERTIFICATE_DETAILS] --'<redacted>', '<redacted>'
(
	@RegistrationNumber Varchar(100) =NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	SELECT    [StateName]
		, [DistrictName]
		, [RespondentName]
		, S.[MobileNo]
		, [EmailId]
		, [Gender]
		, [RespondentAge]
		, [EstablishmentType]
		, UPPER([EstablishmentName]) EstablishmentName
		, [EstablishmentAddress]
		, [EstablishmentPinCode]
		, [EstablishmentPhoneNo]
		, [EstablishmentFaxNo]
		, [EstablishmentCity]
		, [EstablishmentWebsite]
		, [Acommodationtype]
		, [TotalRooms]
		, [RegistrationNumber]
		, [Category]
		, [RestaurantType]
		, REPLACE(UPPER(case when EstablishmentCity is null or EstablishmentCity = '' then '' else EstablishmentCity + ', ' end + case when DistrictName is null or DistrictName='' then '' else DistrictName + ', ' end + StateName),'*','') EstablishmentFullAddress
		, [SaCertificateNo]
		, FORMAT(FinalSaDate, 'MMMM d, yyyy') [FinalSaDate]
		, [CertificationBodyUserId]
		, UPPER(U.UserName) AgencyName
		, ModeOfAssessment
	FROM SelfAssessments S LEFT JOIN Users U on (S.CertificationBodyUserId=U.UserId)
	WHERE RegistrationNumber=@RegistrationNumber AND SaStatus in (2,3)

END


