/****** Object:  StoredProcedure [dbo].[SP_SA_GET_LIST]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_SA_GET_LIST] --'<redacted>', '<redacted>'
(
	@UserId varchar(50) = NULL,
	@RoleId varchar(50) = NULL,
	@State varchar(50) = NULL,
	@Category varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	IF @RoleId=1
	BEGIN
		SELECT  ROW_NUMBER() OVER(ORDER BY PaymentDate desc) SNo
		  , S.[Id]
		  , S.[StateCode]
		  , [StateName]
		  , S.[DistrictCode]
		  , [DistrictName]
		  , [RespondentName]
		  , S.[MobileNo]
		  , [EmailId]
		  , S.[CreatedDate]
		  , [Gender]
		  , [RespondentAge]
		  , [Service]
		  , [Experience]
		  , S.[Email]
		  , [Status]
		  , [IsTerminated]
		  , [FinalSubmitDate]
		  , [EstablishmentType]
		  , [RespondentMobileNo]
		  , UPPER([EstablishmentName]) EstablishmentName
		  , [EstablishmentAddress]
		  , [EstablishmentPinCode]
		  , [EstablishmentPhoneNo]
		  , [EstablishmentFaxNo]
		  , [IsDeclarationAccepted]
		  , [CurrentQuestion]
		  , [CertificateNo]
		  , [Name]
		  , [IssuedOn]
		  , FORMAT(FinalSubmitDate, 'MMMM d, yyyy h:mm tt') [FinalSubmittedDate]
		  , [EstablishmentCity]
		  , [EstablishmentWebsite]
		  , S.[Acommodationtype]
		  , [TotalRooms]
		  , [RegistrationNumber]
		  , [Category]
		  , [CertificateNo]
		  , [RestaurantType]
		  , REPLACE(UPPER(case when EstablishmentCity is null or EstablishmentCity = '' then '' else EstablishmentCity + ', ' end + case when DistrictName is null or DistrictName='' then '' else DistrictName + ', ' end + StateName),'*','') EstablishmentFullAddress
		  , FORMAT(SaDate, 'MMMM d, yyyy') [SaDate]
		  , FORMAT(FinalSaDate, 'MMMM d, yyyy') [FinalSaDate]
		  , [CertificationBodyUserId]
		  , [AssessorUserId]
		  , [ReasonForRejection]
		  , U.UserName
		  , ModeOfAssessment
		  , UA.UserName as AssessorName
		  , S.SaStatus
		  , S.UtrNumber
		  , S.AmountPaid
		  , QuestionnaireName
		FROM SelfAssessments S LEFT JOIN Users U on (S.CertificationBodyUserId=U.UserId)
		LEFT JOIN Users UA on (S.AssessorUserId=UA.UserId)
		LEFT JOIN AcommodationTypes A on (S.Acommodationtype=A.Acommodationtype)
		WHERE SaDate IS NOT NULL AND PaymentDate IS NOT NULL--and RegistrationNumber not in ('<redacted>','<redacted>','<redacted>','<redacted>')
			AND StateName = ISNULL(@State, StateName) AND Category = ISNULL(@Category, Category)
		ORDER BY PaymentDate desc

		SELECT UserId, UserName FROM Users WHERE RoleId=2 AND IsActive = 1 ORDER BY UserName
	END
	ELSE IF @RoleId=2
	BEGIN
		SELECT  ROW_NUMBER() OVER(ORDER BY SaStatus,AcceptOrRejectDate) SNo
		  , S.[Id]
		  , S.[StateCode]
		  , [StateName]
		  , S.[DistrictCode]
		  , [DistrictName]
		  , [RespondentName]
		  , S.[MobileNo]
		  , [EmailId]
		  , S.[CreatedDate]
		  , [Gender]
		  , [RespondentAge]
		  , [Service]
		  , [Experience]
		  , S.[Email]
		  , [Status]
		  , [IsTerminated]
		  , [FinalSubmitDate]
		  , [EstablishmentType]
		  , [RespondentMobileNo]
		  , UPPER([EstablishmentName]) EstablishmentName
		  , [EstablishmentAddress]
		  , [EstablishmentPinCode]
		  , [EstablishmentPhoneNo]
		  , [EstablishmentFaxNo]
		  , [IsDeclarationAccepted]
		  , [CurrentQuestion]
		  , [CertificateNo]
		  , [Name]
		  , [IssuedOn]
		  , FORMAT(FinalSubmitDate, 'MMMM d, yyyy h:mm tt') [FinalSubmittedDate]
		  , [EstablishmentCity]
		  , [EstablishmentWebsite]
		  , S.[Acommodationtype]
		  , [TotalRooms]
		  , [RegistrationNumber]
		  , [Category]
		  , [CertificateNo]
		  , [RestaurantType]
		  , REPLACE(UPPER(case when EstablishmentCity is null or EstablishmentCity = '' then '' else EstablishmentCity + ', ' end + case when DistrictName is null or DistrictName='' then '' else DistrictName + ', ' end + StateName),'*','') EstablishmentFullAddress
		  , FORMAT(SaDate, 'MMMM d, yyyy') [SaDate]
		  , FORMAT(FinalSaDate, 'MMMM d, yyyy') [FinalSaDate]
		  , [CertificationBodyUserId]
		  , [AssessorUserId]
		  , [ReasonForRejection]
		  , UserName
		  , ModeOfAssessment
		  , S.SaStatus
		  ,NULL UtrNumber
		  ,NULL AmountPaid
		  ,QuestionnaireName
		FROM SelfAssessments S LEFT JOIN Users U on (S.AssessorUserId=U.UserId) LEFT JOIN AcommodationTypes A on (S.Acommodationtype=A.Acommodationtype)
		WHERE SaDate IS NOT NULL AND PaymentDate IS NOT NULL AND CertificationBodyUserId=@UserId --and RegistrationNumber not in ('<redacted>','<redacted>','<redacted>','<redacted>')
			AND StateName = ISNULL(@State, StateName) AND Category = ISNULL(@Category, Category)
		ORDER BY SaStatus,AcceptOrRejectDate

		SELECT UserId, UserName FROM Users WHERE RoleId=3 AND CreatedBy=@UserId AND IsActive = 1 ORDER BY UserName
	END
END



GO
