		  , [RespondentMobileNo]
		  , UPPER([EstablishmentName]) EstablishmentName
		  , [EstablishmentAddress]
		  , [EstablishmentPinCode]
		  , [EstablishmentPhoneNo]
		  , [EstablishmentFaxNo]
		  , [IsDeclarationAccepted]
		  , [CurrentQuestion]
		  , [CertificateNo]
		  , [Name]
		  , [IssuedOn]
		  , FORMAT(FinalSubmitDate, 'MMMM d, yyyy h:mm tt') [FinalSubmittedDate]
		  , [EstablishmentCity]
		  , [EstablishmentWebsite]
		  , S.[Acommodationtype]
		  , [TotalRooms]
		  , [RegistrationNumber]
		  , [Category]
		  , [CertificateNo]
		  , [RestaurantType]
		  , REPLACE(UPPER(case when EstablishmentCity is null or EstablishmentCity = '' then '' else EstablishmentCity + ', ' end + case when DistrictName is null or DistrictName='' then '' else DistrictName + ', ' end + StateName),'*','') EstablishmentFullAddress
		  , FORMAT(SaDate, 'MMMM d, yyyy') [SaDate]
		  , FORMAT(ISNULL(SaDate,getdate()+7), 'MM/dd/yyyy') [SaDateForm1]
		  , FORMAT(PaymentDate, 'MMMM d, yyyy') [PaymentDate]
		  , FORMAT(FinalSaDate, 'MMMM d, yyyy') [FinalSaDate]
		  , CASE WHEN SaStatus=2 and SaCertificateNo is null then 'Completed' 
		    WHEN SaStatus=2 and SaCertificateNo is not null then 'Report and Certificate Generated'
			else 'In process' end SaStatusDisplay
		  , [CertificationBodyUserId]
		  , [AssessorUserId]
		  , [ReasonForRejection] 
		  , [IsSaDeclarationAccepted]
		  , [UtrNumber]
		  , [GstNumber]
		  , U1.[Email] CbEmail
		  , U1.[MobileNo] CbMobileNo
		  , U1.UserName CbName
		  , U1.SpocName CbSpocName
		  , U2.[Email] AssessorEmail
		  , U2.[MobileNo] AssessorMobileNo
		  , U2.UserName AssessorName
		  , U2.Password AssessorPassword
		  ,ModeOfAssessment
	FROM SelfAssessments S 
		LEFT JOIN Users U1 on (S.CertificationBodyUserId=U1.UserId)
		LEFT JOIN Users U2 on (S.AssessorUserId=U2.UserId)
	WHERE RegistrationNumber=@RegistrationNo 
		AND IsSaDeclarationAccepted IS NOT NULL


	--SELECT '<redacted>' Amount, '<redacted>' Gst, '<redacted>' Total
	SELECT Amount,Gst,Total, FORMAT(getdate()+7, 'MM/dd/yyyy') [SaDateForm1] from SaPaymentCases where @NoofRooms>=MinNumOfRooms and @NoofRooms<= Isnull(MaxNumOfRooms,@NoofRooms)

END


