CREATE PROC [dbo].[SP_SA_SUBMIT_NEFT]
(
	@RegistrationNumber varchar(50) = NULL,
	@UtrNumber varchar(100) = NULL,
	@Gst varchar(100) = NULL,
	@AmountPaid varchar(50) = NULL
)
AS
BEGIN

	DECLARE @NoofRooms int = NULL
	SELECT @NoofRooms=TotalRooms from SelfAssessments where RegistrationNumber=@RegistrationNumber
	SELECT @AmountPaid=Total from SaPaymentCases where @NoofRooms>=MinNumOfRooms and @NoofRooms<= Isnull(MaxNumOfRooms,@NoofRooms)
	
	UPDATE SelfAssessments SET UtrNumber=@UtrNumber,PaymentDate=getdate(),AmountPaid=@AmountPaid,GstNumber=@Gst where  RegistrationNumber=@RegistrationNumber

END

