/****** Object:  StoredProcedure [dbo].[SP_SEND_BACK_TO_AGENCY_FOR_RE_ALLOCATION]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_SEND_BACK_TO_AGENCY_FOR_RE_ALLOCATION] --'<redacted>','<redacted>','<redacted>'
(
	@ZedId varchar(100) = NULL,
	@Certification varchar(50) = NULL,
	@NcCount int = NULL
    
	
)
AS
BEGIN			
				DECLARE @NewZedId VARCHAR(60) = CONCAT(@ZedId, '_RESET')

				insert into MsmeCertifications_Moveback
				select * from MsmeCertifications where zedid=@ZedId AND certification=@Certification and NcCount=@NcCount

				update ZED_CONSULTANT.dbo.SaRequirementPhotos set zedid=@NewZedId where zedid=@ZedId AND certification=@Certification and NcCount=@NcCount

				update ZED_CONSULTANT.dbo.MsmeCertifications set SiteAssessorId=null,
				CoAssessorId=null,TechExpert=null,	ModeOfAssessment=null,	AssessmentDate=null,certificationstatus=6,issaverified=null,BdsFromDate=null,
				BdsToDate=null,	HapFromDate=null,	HapToDate=null, sacertificateno=null,CertificationStatusDate=null
				where zedid=@ZedId AND certification=@Certification and NcCount=@NcCount

				update ZED_CONSULTANT.dbo.SaRawMaterials set zedid=@NewZedId where zedid=@ZedId AND certification=@Certification and NcCount=@NcCount
				update ZED_CONSULTANT.dbo.AssessorComments set zedid=@NewZedId where zedid=@ZedId AND certification=@Certification and NcCount=@NcCount

				update ZED_CONSULTANT.dbo.ScreenshotPhotos set zedid=@NewZedId where zedid=@ZedId AND certification=@Certification and NcCount=@NcCount
				update ZED_CONSULTANT.dbo.MsmeRawMaterials set zedid=@NewZedId where zedid=@ZedId AND certification=@Certification and NcCount=@NcCount
				
				update ZED_CONSULTANT.dbo.MsmeSections set AssessorId=null where zedid=@ZedId AND SectionType=@Certification and NcCount=@NcCount
				
				update ZED_CONSULTANT.dbo.MsmePhotos set zedid=@NewZedId where zedid=@ZedId AND certification=@Certification and NcCount=@NcCount
				update ZED_CONSULTANT.dbo.MsmeProducts set zedid=@NewZedId where zedid=@ZedId AND certification=@Certification and NcCount=@NcCount
				update ZED_CONSULTANT.dbo.SaPhotos set zedid=@NewZedId where zedid=@ZedId AND certification=@Certification and NcCount=@NcCount
				update ZED_CONSULTANT.dbo.SaProducts set zedid=@NewZedId where zedid=@ZedId AND certification=@Certification and NcCount=@NcCount
				 
				update ZED_CONSULTANT.dbo.MeetingParticipants set zedid=@NewZedId where zedid=@ZedId AND CertificationType=@Certification and NcCount=@NcCount
				update ZED_CONSULTANT.dbo.Meetings set zedid=@NewZedId where zedid=@ZedId AND CertificationType=@Certification and NcCount=@NcCount
				update ZED_CONSULTANT.dbo.msmerequirementbullets set zedid=@NewZedId where zedid=@ZedId AND CertificationType=@Certification and NcCount=@NcCount
				update ZED_CONSULTANT.dbo.AllotedCoAssessors set zedid=@NewZedId where zedid=@ZedId AND certification=@Certification and NcCount=@NcCount
				update ZED_CONSULTANT.dbo.AllotedTechExperts set zedid=@NewZedId where zedid=@ZedId AND certification=@Certification and NcCount=@NcCount
				update ZED_CONSULTANT.dbo.TrainingInfo set zedid=@NewZedId where zedid=@ZedId AND CertificationType=@Certification and NcCount=@NcCount
				update ZED_CONSULTANT.dbo.TrainingPhotos set zedid=@NewZedId where zedid=@ZedId AND Certification=@Certification and NcCount=@NcCount
				update ZED_CONSULTANT.dbo.ConsultancyBasicInformation set zedid=@NewZedId where zedid=@ZedId AND CertificationType=@Certification and NcCount=@NcCount

				update ZED_CONSULTANT.dbo.MsmeHistory set zedid=@NewZedId where zedid=@ZedId AND CertificationType=@Certification and NcCount=@NcCount and StatusType != 'ApplicationReceived'

				--Clear recomdation 

				IF @NcCount=3
				Begin

				EXEC ZED_CONSULTANT.dbo.[SP_RESET_TECHNOLOGY_UPGRADATION_ID] @ZedId,@Certification;
				END

				IF @NcCount=1
				BEGIN					

					insert into ZED_CONSULTANT.dbo.MsmeRequirements_Moveback
					select * from ZED_CONSULTANT.dbo.MsmeRequirements where zedid=@ZedId AND SectionType=@Certification and NcCount=@NcCount

					update ZED_CONSULTANT.dbo.MsmeRequirements set SaConformance=null,estimatedtimeindays=null,Intervention=null,IntConformance=null,IsProposedActivityCompleted=null,IsProposedActivityCompleted2=null	where zedid=@ZedId AND SectionType=@Certification and NcCount=@NcCount 
				END


				insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType,NcCount)
				values (@ZedId,'Send back to agency for allocation request of QCI',getdate(),@Certification,null,@NcCount )


END




GO
