/****** Object:  StoredProcedure [dbo].[SP_TECHNOLOGIES_GET_LIST]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
--[SP_TECHNOLOGIES_GET_LIST] '<redacted>','<redacted>','<redacted>'
--[SP_TECHNOLOGIES_GET_LIST] '<redacted>','<redacted>','<redacted>'
CREATE PROCEDURE [dbo].[SP_TECHNOLOGIES_GET_LIST] --'<redacted>','<redacted>','<redacted>'
(
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL,
	@CertId varchar(50) = NULL,
	@UserId varchar(50) = NULL,
	@Roleid varchar(50) = NULL
)
AS
BEGIN
	
	Declare @TuStatus int = null

	select @TuStatus=TuStatus from MsmeCertifications where ZedId=@ZedId and Certification=@Certification and Id=@CertId

	SET NOCOUNT ON;

	IF @Roleid=3
	BEGIN
		select T.Id, T.TechnologyCode,T.TechnologyName,T.Description,T.Sectors,T.Categories,T.OrderNo,
		CASE WHEN R.TechnologyCode is not null THEN 'Yes' ELSE 'No'END AS IsSelected
		from ZEDCS_V2_LIVE.dbo.Technologies T
		LEFT join RecommandedTechnologies R on (T.TechnologyCode=R.TechnologyCode and R.CertId=@CertId and R.ZedId=@ZedId and R.Certification=@Certification) 
		INNER JOIN Msme M on M.ZedId=@ZedId
		WHERE (T.Sectors IS NULL OR CHARINDEX(M.TwoDigitActivity, T.Sectors) > 0) and IsActive=1
		order by T.TechnologyCode

		IF EXISTS (select * from FinancialAssistance where ZedId=@ZedId and CertificationType!=@Certification and TechUpgradeStatus not in (16,17) )
		BEGIN
			select 'Previous recommendations are in progress. Please try later.' PreviousRecomInProgress
		END
		ELSE 
		BEGIN
			select '' PreviousRecomInProgress
		END

	END
	ELSE
	BEGIN
		select T.Id, T.TechnologyCode,T.TechnologyName,T.Description,T.Sectors,T.Categories,T.OrderNo,
		CASE WHEN R.TechnologyCode is not null THEN 'Yes' ELSE 'No'END AS IsSelected
		from ZEDCS_V2_LIVE.dbo.Technologies T
		LEFT join RecommandedTechnologies R on (T.TechnologyCode=R.TechnologyCode and R.CertId=@CertId and R.ZedId=@ZedId and R.Certification=@Certification) 
		INNER JOIN Msme M on M.ZedId=@ZedId
		WHERE (T.Sectors IS NULL OR CHARINDEX(M.TwoDigitActivity, T.Sectors) > 0) and IsActive=1 and @TuStatus=1
		order by T.TechnologyCode

			IF EXISTS (select * from FinancialAssistance where ZedId=@ZedId and CertificationType!=@Certification and TechUpgradeStatus not in (16,17) )
		BEGIN
			select 'Previous recommendations are in progress. Please try later.' PreviousRecomInProgress
		END
		ELSE 
		BEGIN
			select '' PreviousRecomInProgress
		END

	END

END

GO
/****** Object:  StoredProcedure [dbo].[SP_TECHNOLOGIES_INSERT_TECHNOLOGIES_FOR_UNIT]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_TECHNOLOGIES_INSERT_TECHNOLOGIES_FOR_UNIT] --'<redacted>','<redacted>','<redacted>'
(
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL,
	@CertId varchar(50) = NULL,
	@SelectedCode varchar(500) = NULL,
	@UserId varchar(50) = NULL,
	@Roleid varchar(50) = NULL
	
)
AS
BEGIN
	
	SET NOCOUNT ON;

	DECLARE @TechnologyCodeTable TABLE (TechnologyCode varchar(50));

    INSERT INTO @TechnologyCodeTable
    SELECT value 
    FROM STRING_SPLIT(@SelectedCode, ',');

	--SELECT * FROM @TechnologyCodeTable

	delete from RecommandedTechnologies where ZedId=@ZedId and Certification=@Certification and CertId=@CertId
	insert into RecommandedTechnologies (ZedId,Certification,TechnologyCode,TechnologyName,Description,Sectors,Categories,OrderNo,CertId,CreatedDate)
    select @ZedId,@Certification,TechnologyCode,TechnologyName,Description,Sectors,Categories,OrderNo,@CertId,GETDATE() from ZEDCS_V2_LIVE.dbo.Technologies 
	WHERE TechnologyCode IN (SELECT TechnologyCode FROM @TechnologyCodeTable)

	IF EXISTS (SELECT * FROM RecommandedTechnologies WHERE ZedId=@ZedId AND Certification=@Certification AND CertId=@CertId)
			BEGIN
				UPDATE Msme SET TechnologyUpgradation=1 WHERE ZedId=@ZedId and TechnologyUpgradation is null
			END

	UPDATE MsmeCertifications SET TuStatus=1 where ZedId=@ZedId and Certification=@Certification and Id=@CertId

	insert into MsmeHistory(ZedId,Descrip,CreatedDate,CertificationType,StatusType, NcCount)
	values (@ZedId,concat('Consultant Recommended Technologies for Unit on ',FORMAT(getdate(), 'MMMM d, yyyy')),getdate(),@Certification,'TechnologiesRecommended','3')

	  EXEC [SP_SEND_AUTO_MAIL_TO_UNIT_FOR_TECHNOLOGY_UPGRADATIONS] @ZedId, @Certification

END
