-- =============================================
--[SP_TECHNOLOGIES_GET_LIST] '<redacted>','<redacted>','<redacted>'
--[SP_TECHNOLOGIES_GET_LIST] '<redacted>','<redacted>','<redacted>'
CREATE PROCEDURE [dbo].[SP_TECHNOLOGY_UPGRADATION_GET_LIST_NOT_USING] --'<redacted>','<redacted>','<redacted>'
(
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL,
	@CertId varchar(50) = NULL,
	@UserId varchar(50) = NULL,
	@Roleid varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

    select T.Id, T.TechnologyCode,T.TechnologyName,T.Description,T.Sectors,T.Categories,T.OrderNo,
	CASE WHEN R.TechnologyCode is not null THEN 'Yes' ELSE 'No'END AS IsSelected
	from ZEDCS_V2_LIVE.dbo.Technologies T
	INNER join RecommandedTechnologies R on (T.TechnologyCode=R.TechnologyCode) 
	WHERE R.CertId=@CertId and R.ZedId=@ZedId and R.Certification=@Certification
	order by T.TechnologyCode

END

