/****** Object:  StoredProcedure [dbo].[SP_UNDO__AGENCY_TO_REVERT]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_UNDO__AGENCY_TO_REVERT] --'<redacted>', '<redacted>'
(
	@ZedId varchar(50) = NULL,
	@Certification varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	BEGIN
		
			-- A. Restore MsmeCertifications data from Moveback table
			-- Note: We assume Id, ZedId, and Certification are the primary keys/unique identifiers
			UPDATE T1
			SET
				T1.CertificationStatus = T2.CertificationStatus,
				T1.SiteAssessorId = T2.SiteAssessorId,
				T1.CoAssessorId = T2.CoAssessorId,
				T1.ModeOfAssessment = T2.ModeOfAssessment,
				T1.AssessmentDate = T2.AssessmentDate,
				T1.SaAuditsConducted = T2.SaAuditsConducted,
				T1.SaDomesticCustomers = T2.SaDomesticCustomers,
				T1.SaInternationalCustomers = T2.SaInternationalCustomers,
				T1.SaRawMaterialImported = T2.SaOutsourcedProcesses, -- Assuming a typo in original SP, matching column to column
				T1.SaOutsourcedProcesses = T2.SaOutsourcedProcesses,
				T1.SaEnergySources = T2.SaEnergySources,
				T1.certificationstatusdate = T2.certificationstatusdate,
				T1.bdsfromdate = T2.bdsfromdate,
				T1.bdstodate = T2.bdstodate,
				T1.hapfromdate = T2.hapfromdate,
				T1.haptodate = T2.haptodate

			FROM ZED_CONSULTANT.dbo.MsmeCertifications AS T1
			INNER JOIN ZED_CONSULTANT.dbo.MsmeCertifications_Moveback AS T2 
				ON T1.Id = T2.Id 
				AND T1.ZedId = @ZedId 
				AND T1.Certification = @Certification;

			
			--UPDATE T1
			--SET 
			--	T1.SaConformance = T2.SaConformance,
			--	T1.SaUpdatedDate = T2.SaUpdatedDate,
			--	T1.SaAssessorRemarks = T2.SaAssessorRemarks
			--FROM ZED_CONSULTANT.dbo.MsmeRequirements AS T1
			--INNER JOIN ZED_CONSULTANT.dbo.MsmeRequirementsMoveback AS T2
			--	ON T1.Id = T2.Id
			--WHERE T1.ZedId = @ZedId 
			--AND T1.SectionType = @Certification;		



			DECLARE @SiteAssessorId varchar(50) = NULL
			SELECT  @SiteAssessorId=SiteAssessorId FROM MsmeCertifications where ZedId=@ZedId and certification = @Certification

			UPDATE ZED_CONSULTANT.dbo.SaRequirementPhotos SET zedid = @ZedId 
            WHERE zedid = @ZedId + '_RESET' AND certification = @Certification;

			UPDATE ZED_CONSULTANT.dbo.SaRawMaterials SET zedid = @ZedId 
            WHERE zedid = @ZedId + '_RESET' AND certification = @Certification;

			UPDATE ZED_CONSULTANT.dbo.AssessorComments SET zedid = @ZedId 
            WHERE zedid = @ZedId + '_RESET' AND certification = @Certification AND AssessmentType = 'SA';

			UPDATE ZED_CONSULTANT.dbo.MsmeLocations SET zedid = @ZedId 
            WHERE zedid = @ZedId + '_RESET' AND certification = @Certification;

			UPDATE ZED_CONSULTANT.dbo.ScreenshotPhotos SET zedid = @ZedId 
            WHERE zedid = @ZedId + '_RESET' AND certification = @Certification;

			UPDATE ZED_CONSULTANT.dbo.MsmeRawMaterials SET zedid = @ZedId 
            WHERE zedid = @ZedId + '_RESET' AND certification = @Certification;			
            
			UPDATE ZED_CONSULTANT.dbo.SaPhotos SET zedid = @ZedId 
            WHERE zedid = @ZedId + '_RESET' AND certification = @Certification;

			UPDATE ZED_CONSULTANT.dbo.SaProducts SET zedid = @ZedId 
            WHERE zedid = @ZedId + '_RESET' AND certification = @Certification;

			UPDATE ZED_CONSULTANT.dbo.MsmeSelfies SET zedid = @ZedId 
            WHERE zedid = @ZedId + '_RESET' AND certification = @Certification;

			UPDATE ZED_CONSULTANT.dbo.MeetingParticipants SET zedid = @ZedId 
            WHERE zedid = @ZedId + '_RESET' AND CertificationType = @Certification;

			UPDATE ZED_CONSULTANT.dbo.Meetings SET zedid = @ZedId 
            WHERE zedid = @ZedId + '_RESET' AND CertificationType = @Certification;

			UPDATE ZED_CONSULTANT.dbo.MsmeSections SET AssessorId=@SiteAssessorId
            WHERE zedid = @ZedId AND SectionType = @Certification;


			UPDATE ZED_CONSULTANT.dbo.msmerequirementbullets SET zedid = @ZedId 
            WHERE zedid = @ZedId + '_RESET' AND CertificationType = @Certification;
			UPDATE ZED_CONSULTANT.dbo.AllotedCoAssessors SET zedid = @ZedId 
            WHERE zedid = @ZedId + '_RESET' AND certification = @Certification;
			UPDATE ZED_CONSULTANT.dbo.AllotedTechExperts SET zedid = @ZedId 
            WHERE zedid = @ZedId + '_RESET' AND certification = @Certification;
			UPDATE ZED_CONSULTANT.dbo.TrainingInfo SET zedid = @ZedId 
            WHERE zedid = @ZedId + '_RESET' AND CertificationType = @Certification;
			UPDATE ZED_CONSULTANT.dbo.TrainingPhotos SET zedid = @ZedId 
            WHERE zedid = @ZedId + '_RESET' AND Certification = @Certification;
			UPDATE ZED_CONSULTANT.dbo.ConsultancyBasicInformation SET zedid = @ZedId 
            WHERE zedid = @ZedId + '_RESET' AND CertificationType = @Certification;






	END
            

END
