/****** Object:  StoredProcedure [dbo].[SP_UPDATE_USER]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[SP_UPDATE_USER] 
(
	 @UserId varchar(200)=NULL
	,@UserName varchar(200)
	,@Password varchar(200)=NULL
	,@RoleId int = NULL
	,@Email varchar(200) = NULL
	,@MobileNo varchar(15) = NULL
	,@CreatedBy varchar(50) = NULL
	,@SpocName varchar(200) = NULL
	,@Address varchar(2000) = NULL
	,@PinCode varchar(50) = NULL
	,@PreferredStates varchar(2000) = NULL
	,@NicSectors varchar(4000) = NULL
	,@AreaOfknowledge varchar(4000) = NULL
	,@IdProofType varchar(50) = NULL
	,@IdProofNumber varchar(50) = NULL
	,@GstNumber varchar(50) = NULL
	,@DesktopVerification varchar(50) = NULL
	,@SiteVerification varchar(50) = NULL
	,@FinancialVerification varchar(50) = NULL,
	 @ReasonForRejection varchar(2000) = NULL,
	 @TuPreferredState varchar(2000) = NULL,
	 @TuPreferredDistricts varchar(2000) = NULL
	 --,@AssessorType varchar(50) = NULL
	,@CertificateNo varchar(50) = NULL
	,@ProfessionalEmail varchar(50) = NULL
)
AS
BEGIN
     
	 IF @RoleId=2
	  Begin

	  IF EXISTS(select * from Users where UserId=@UserId and ((SiteVerification=1 and SiteVerification=@SiteVerification) OR (FinancialVerification=1 and FinancialVerification=@FinancialVerification)))
	  BEGIN
		UPDATE Users set UserName=@UserName,Email=@Email, MobileNo=@MobileNo,SpocName=@SpocName,Address=@Address,Pincode=@PinCode, AgencyGstNumber=@GstNumber, DesktopVerification=@DesktopVerification, SiteVerification=@SiteVerification,FinancialVerification=@FinancialVerification,ReasonForRejection=@ReasonForRejection,TuPreferredState=@TuPreferredState  where UserId=@UserId

		Delete from AgencyUserStates where UserId=@UserId
		Delete from UserNicSectors where UserId=@UserId
		Delete from TuAgencyUserDistricts where UserId=@UserId

		INSERT INTO AgencyUserStates (UserId,RoleId,States,IsActive)
	    select @UserId, @RoleId, value, 1 from string_split(@PreferredStates,',')

		INSERT INTO UserNicSectors (UserId,RoleId,NicSectorCode,IsActive)
	    select @UserId, @RoleId, value, 1 from string_split(@NicSectors,',')
		update U set NicSector=SectorName from Sectors S inner join UserNicSectors U on (S.SectorCode=U.NicSectorCode) where NicSector is null

		INSERT INTO TuAgencyUserDistricts (UserId,RoleId,Districts,IsActive)
	    select @UserId, @RoleId, value, 1 from string_split(@TuPreferredDistricts,',')

		update users set DesktopVerification=@DesktopVerification, SiteVerification=@SiteVerification,FinancialVerification=@FinancialVerification where RoleId=3 AND CreatedBy=@UserId
		update users set DesktopVerification=1 where SiteVerification=1 and RoleId=3 AND CreatedBy=@UserId
		END
		ELSE
		BEGIN
			UPDATE DummyUsersForError SET IsActive='CANNOT CHANGE THE USER ROLE NOW' where UserId='ZEDMSME000112'
		END


			
	  End

	 IF   (@RoleId=3 OR @RoleId=33)
	  Begin

	  IF EXISTS(select * from Users where UserId=@UserId and RoleId=@RoleId)
	  BEGIN
		UPDATE Users set UserName=@UserName,Email=@Email, MobileNo=@MobileNo,IdProofType=@IdProofType,IdProofNumber=@IdProofNumber,ReasonForRejection=@ReasonForRejection,Address=@Address,Pincode=@PinCode
		--,DesktopVerification=@DesktopVerification, SiteVerification=@SiteVerification,FinancialVerification=@FinancialVerification 
		where UserId=@UserId

		Delete from AgencyUserStates where UserId=@UserId
		Delete from UserNicSectors where UserId=@UserId
		Delete from UserAreaOfKnowledge where UserId=@UserId

		INSERT INTO AgencyUserStates (UserId,RoleId,States,IsActive)
	    select @UserId, @RoleId, value, 1 from string_split(@PreferredStates,',')

		INSERT INTO UserNicSectors (UserId,RoleId,NicSectorCode,IsActive)
	    select @UserId, @RoleId, value, 1 from string_split(@NicSectors,',')
		update U set NicSector=SectorName from Sectors S inner join UserNicSectors U on (S.SectorCode=U.NicSectorCode) where NicSector is null

		INSERT INTO UserAreaOfKnowledge (UserId,RoleId,AreaOfKnowledge,IsActive)
	    select @UserId, @RoleId, value, 1 from string_split(@AreaOfknowledge,',')
		END
		ELSE
		BEGIN
		UPDATE DummyUsersForError SET IsActive='CANNOT CHANGE THE ROLE NOW' where UserId='ZEDMSME000112'
		END
			
	  End
END



