/****** Object:  StoredProcedure [dbo].[SP_VERIFY_QR_CODE]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_VERIFY_QR_CODE]  --'<redacted>','<redacted>'
(
	@QrCodeNo VARCHAR(50) = NULL,
	@CertificationType VARCHAR(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;

	IF @CertificationType='Pledge'
	BEGIN
	SELECT M.PUnitName EnterpriseName,	concat(PAddress,', ',PDistrictName,', ',PStateName,'-',PPin)  as Address,
	b.UdyogAadharNo,
	FORMAT(CreatedDate, 'MMMM d, yyyy') DateOfPledge,PledgeCertificateNo CertificateNo
	FROM Msme M	inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) WHERE QrCodeNo=@QrCodeNo
	END
	ELSE 
	select 
		M.PUnitName EnterpriseName,
		case when @CertificationType='Bronze' then DaCertificateNo else SaCertificateNo end as CertificateNo,
		FORMAT(CertificationStatusDate, 'MMMM d, yyyy') DateOfCertification,
		FORMAT(convert(date,dateadd(yy,3,CertificationStatusDate)), 'MMMM d, yyyy') DateOfExpiry,
		concat(PAddress,', ',PDistrictName,', ',PStateName,'-',PPin) as Address ,	
		B.UdyogAadharNo,
		M.MobileNo,
		M.EmailId
	    from Msme M inner join MsmeCertifications C on (M.ZedId=C.ZedId)
	inner join MsmeBasicInformation B on (M.ZedId=B.ZedId) where QrCodeSeqNo=@QrCodeNo and Certification=@CertificationType

END


GO
/****** Object:  StoredProcedure [dbo].[SP_WEB_SITE_COUNTS]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<for the counts showing in website dashboard --https://zed.msme.gov.in/>
-- =============================================
CREATE PROCEDURE [dbo].[SP_WEB_SITE_COUNTS] --null,null,null,'<redacted>'
(

	
	@CertificationType varchar(50) = NULL,
	@State varchar(100) = NULL,
	@MsmeSize varchar(50) = NULL,
	@Sector varchar(2000) = NULL
)
AS
BEGIN
	
	------  LIST OF REGISTERED MSME

	SET NOCOUNT ON;
		
		--SELECT * FROM MsmeCertifications
		SELECT
		(SELECT count(*) FROM Msme) MsmeRegistered, 
		(SELECT count(*) FROM Msme) Pledge, 
		(SELECT count(*) FROM MsmeCertifications C inner join MsmeBasicInformation B on (C.ZedId=B.ZedId) where Certification='Bronze' and CertificationStatus=6 and DaCertificateNo is not null and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915')) BronzeCertified, 
		(SELECT count(*) FROM MsmeCertifications C inner join MsmeBasicInformation B on (C.ZedId=B.ZedId) where Certification='Silver' and CertificationStatus=16 and SaCertificateNo is not null and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915')) SilverCertified, 
		(SELECT count(*) FROM MsmeCertifications C inner join MsmeBasicInformation B on (C.ZedId=B.ZedId) where Certification='Gold' and CertificationStatus=16 and SaCertificateNo is not null and UdyogAadharNo not in ('UDYAM-GJ-01-0013310','UDYAM-MH-23-0006117','UDYAM-UP-29-0003915')) GoldCertified,
	

		(select 
		(select sum(10000-ISNULL(T.Amount,0))
		from msme M inner join MsmeCertifications C  on (M.ZedId=replace(C.ZedId,'_D','')) 
		inner join 
		(select distinct zedid,certification,paymentrefid from MsmePaymentInfo) P on (replace(C.ZedId,'_D','')=replace(P.ZedId,'_D','') and C.Certification=p.Certification)
		left join 
		PaymentGateWayTransactions T on (replace(C.ZedId,'_D','')=replace(T.ZedId,'_D','') and C.Certification=T.Certification and PaymentStatus='Success' )
		where P.Certification='Bronze' and CertificationStatus>=2) 
		+
			(select sum(40000-ISNULL(T.Amount,0))
		from msme M inner join MsmeCertifications C  on (M.ZedId=replace(C.ZedId,'_D','')) 
		inner join 
		(select distinct zedid,certification,paymentrefid from MsmePaymentInfo) P on (replace(C.ZedId,'_D','')=replace(P.ZedId,'_D','') and C.Certification=p.Certification)
		left join 
		PaymentGateWayTransactions T on (replace(C.ZedId,'_D','')=replace(T.ZedId,'_D','') and C.Certification=T.Certification and PaymentStatus='Success' )
		where P.Certification='Silver' and CertificationStatus>=2)
		+
		(select sum(90000-ISNULL(T.Amount,0))
		from msme M inner join MsmeCertifications C  on (M.ZedId=replace(C.ZedId,'_D','')) 
		inner join 
		(select distinct zedid,certification,paymentrefid from MsmePaymentInfo) P on (replace(C.ZedId,'_D','')=replace(P.ZedId,'_D','') and C.Certification=p.Certification)
		left join 
		PaymentGateWayTransactions T on (replace(C.ZedId,'_D','')=replace(T.ZedId,'_D','') and C.Certification=T.Certification and PaymentStatus='Success' )
		where P.Certification='Gold' and CertificationStatus>=2)

		--+
		--(select sum(6175) from KAWACH.dbo.MsmeCertifications where CertificationStatus>=2)

		+

		isnull((select sum(ApproverAmount) from FinancialAssistance where ApproverAmount is not null),0)
		)  FinancialSupport

END


GO
/****** Object:  StoredProcedure [dbo].[SP_WEB_SITE_LIST_OF_CERTIFIED_MSME]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_WEB_SITE_LIST_OF_CERTIFIED_MSME] --null,null,null,'<redacted>'
(
	  
	
	@CertificationType varchar(50) = NULL,
	@State varchar(100) = NULL,
	@MsmeSize varchar(50) = NULL,
	@Sector varchar(2000) = NULL
)
AS
BEGIN
	
	------  LIST OF REGISTERED MSME

	SET NOCOUNT ON;
		
		SELECT 
		ROW_NUMBER() OVER(order by MsmeId) as Sno,
		M.EnterpriseName,
		TwoDigitActivity,
			CONCAT(PAddress, ', ', PDistrictName, ', ', PStateName, ', ', PPin) UnitAddress,PStateName StateName,EnterpriseTypee,Certification
			--M.CreatedDate ReigstrationDate,
			-- U.UserName AS AgencyName,P.CertificationBodyUserId AgencyId,
			--UA.UserName as DesktopAsssessor, p.DesktopAssessorId,
			--Us.UserName as SiteAssessor, P.SiteAssessorId,
			--UC.UserName as coAssessor, P.CoAssessorId,
		
			--PDistrictName DistrictName,  EnterpriseName, ModeOfAssessment,FORMAT(AssessmentDate, '<redacted>') SaAssessmentDate,
			--DaCertificateNo,SaCertificateNo,
		--	CertificationStatusDate CertificationDate
		

		FROM Msme M
		INNER join MsmeCertifications P on (P.ZedId=M.ZedId)
		WHERE CertificationStatus in (6,16)
		AND (DaCertificateNo is not null OR SaCertificateNo is not null)
		AND (@State is null or M.StateId=@State)
		AND (@CertificationType IS NULL OR Certification=@CertificationType) AND (@MsmeSize IS NULL OR M.EnterpriseTypee=@MsmeSize) AND (@Sector IS NULL OR left(TwoDigitActivity,2)=@Sector)
		ORDER By MsmeId 	
	
END


GO
