/****** Object:  StoredProcedure [dbo].[SP_WEBINAR_GET_CERTIFICATE_DETAILS]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_WEBINAR_GET_CERTIFICATE_DETAILS] --'<redacted>'
(
	@Id varchar(50) = NULL
)
AS
BEGIN

	Declare @CertificateNo varchar(50)= NULL,
			@SerialNo bigint,
		    @ExistingCertificateNo varchar(100)

	 SELECT @ExistingCertificateNo=WebinarCertificateNo FROM WebinarRegistrations WHERE Id=@Id
	
	SET NOCOUNT ON;
	IF (@ExistingCertificateNo IS NULL) 
	BEGIN
	SET  @SerialNo = Next Value For WebinarCertificateSequence; 
	select @CertificateNo=concat('ZEDCS_V2_WB_',replace(convert(varchar, getdate(),103),'/',''),'_',@SerialNo)
	--print @CertificateNo
	UPDATE WebinarRegistrations SET IsSentCertificate=1, CertificateDate=ISNULL(CertificateDate,getdate()), WebinarCertificateNo=@CertificateNo,WebinarCertificateId=concat(WebinarId,'W',Id) WHERE Id=@Id
	END
    
	SELECT FORMAT(WebinarStartTime, 'MMMM d, yyyy h:mm tt') WebinarStartTime, FORMAT(WebinarEndTime, 'MMMM d, yyyy h:mm tt') WebinarEndTime, W.WebinarUrl, W.WebinarUrl, 
		R.Title, R.FirstName, R.LastName, UPPER(R.Title + ' ' + R.FirstName) FullName, R.MobileNo, R.Email, R.WebinarCertificateNo, FORMAT(WebinarEndTime, 'MMMM d, yyyy') CertificateDate,
		UPPER(S.EstablishmentName) EstablishmentName, S.RegistrationNumber, S.EmailId, S.StateName,WebinarCertificateId,
		REPLACE(UPPER(case when EstablishmentCity is null or EstablishmentCity = '' then '' else EstablishmentCity + ', ' end + case when DistrictName is null or DistrictName='' then '' else DistrictName + ', ' end + StateName),'*','') EstablishmentFullAddress

	FROM WebinarRegistrations R
	INNER JOIN Webinars W on (R.WebinarId=W.Id)
	--INNER JOIN SelfAssessments S on (S.WebinarId=W.Id AND R.RegistrationNumber=S.RegistrationNumber)
	INNER JOIN SelfAssessments S on (R.RegistrationNumber=S.RegistrationNumber)
	WHERE R.Id=@Id

END


