CREATE PROCEDURE [dbo].[SP_WEBINAR_GET_DETAILS_BY_EMAIL] --'<redacted>'
(
	@RegistrationNumber varchar(50) = NULL,
	@ParticipantEmail varchar(200) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;
    
	SELECT TOP 1 FORMAT(WebinarStartTime, 'MMMM d, yyyy h:mm tt') WebinarStartTime, FORMAT(WebinarEndTime, 'MMMM d, yyyy h:mm tt') WebinarEndTime, 
		W.WebinarUrl, W.WebinarUrl, R.FirstName, R.Title, R.LastName, R.MobileNo, R.Email, S.EstablishmentName, S.RegistrationNumber, S.EmailId
	FROM WebinarRegistrations R
	INNER JOIN Webinars W on (R.WebinarId=W.Id)
	INNER JOIN SelfAssessments S on (S.RegistrationNumber=r.RegistrationNumber)
	WHERE R.RegistrationNumber=@RegistrationNumber AND R.Email=@ParticipantEmail
	ORDER BY R.Id desc

END


