/****** Object:  StoredProcedure [dbo].[SP_WEBINAR_GET_LIST]    Script Date: 9/19/2026 4:28:40 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_WEBINAR_GET_LIST]
AS
BEGIN
	
	SET NOCOUNT ON;
    
	SELECT Id, FORMAT(WebinarStartTime, 'MMM d, yyyy h:mm tt') WebinarStartTime, FORMAT(WebinarEndTime, 'MMM d, yyyy h:mm tt') WebinarEndTime, 
		WebinarUrl, FeedbackUrl, RegistrationCount, RegistrationCount RegistrationCountNew,  ISNULL(NoOfRegistrations,0) NoOfRegistrations,  ISNULL(NoOfUniqueRegistrations,0) NoOfUniqueRegistrations, CreatedDate, 
		CASE WHEN WebinarStartTime < GETDATE() THEN 'Closed' 
			WHEN IsRegistrationsClosed=1 THEN 'ReOpen' 
			ELSE 'Open' END AS RegistrationStatus, 
		CASE WHEN WebinarStartTime < GETDATE() OR IsRegistrationsClosed=1 THEN 'Closed' 
			ELSE 'Open' END AS RegistrationStatusDisplay, 
		CASE WHEN WebinarStartTime > GETDATE() THEN '1' 
			ELSE '0' END AS SendReminder,
		CASE WHEN WebinarEndTime < GETDATE() THEN 'Conducted' 
			ELSE '' END AS WebinarConductedStatusDisplay
	FROM Webinars W 
	left join 
	(select WebinarId,count(*) [NoOfRegistrations], count(distinct RegistrationNumber) [NoOfUniqueRegistrations] from WebinarRegistrations group by WebinarId) B 
	on (W.Id=B.WebinarId)
	ORDER BY WebinarDate DESC

END


