-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_WEBINAR_GET_REGISTRATIONS] --7
(
	@WebinarId varchar(50) = NULL
)
AS
BEGIN
	
	SET NOCOUNT ON;
    
	SELECT W.*, S.EstablishmentName, S.EstablishmentPinCode, FORMAT(S.FinalSubmitDate, 'MMMM d, yyyy h:mm tt') SelfCertificateDate, FORMAT(W.CreatedDate, 'MMMM d, yyyy h:mm tt') WebinarRegistrationDate,
		REPLACE(UPPER(case when S.EstablishmentCity is null or S.EstablishmentCity = '' then '' else EstablishmentCity + ', ' end + case when S.DistrictName is null or S.DistrictName='' then '' else DistrictName + ', ' end + S.StateName),'*','') EstablishmentFullAddress,
		S.Acommodationtype, S.TotalRooms
	FROM WebinarRegistrations W, SelfAssessments S 
	--WHERE W.WebinarId=s.WebinarId and w.RegistrationNumber=s.RegistrationNumber and W.WebinarId=@WebinarId
	WHERE w.RegistrationNumber=s.RegistrationNumber and W.WebinarId=@WebinarId
	ORDER BY W.CreatedDate

	SELECT FORMAT(WebinarStartTime, 'MMM d, yyyy h:mm tt') WebinarStartTime, FORMAT(WebinarEndTime, 'MMM d, yyyy h:mm tt') WebinarEndTime, 
		WebinarUrl, FeedbackUrl, RegistrationCount, RegistrationCount RegistrationCountNew, CreatedDate,IsRegistrationsClosed 
	FROM Webinars WHERE Id=@WebinarId

END


